window.COURSE={"id": "latyshova_gl5_par17-20", "title": "Выделение коллекторов и оценка их продуктивности по каротажу", "book": "Латышова М. Г. Практическое руководство по интерпретации диаграмм ГИС, 1991, гл. V §17–20", "generated_by": "claude_code/sonnet", "parts": [{"title": "Задачи ГИС и влияние раствора на разрез", "nodes": ["latyshova.goals_of_log_interpretation", "latyshova.mud_effects_on_borehole", "latyshova.water_loss_and_mud_density", "latyshova.filtrate_salinity", "latyshova.water_and_nonfiltering_muds"]}, {"title": "Типы разрезов и комплекс методов", "nodes": ["latyshova.section_and_collector_types", "latyshova.four_method_groups", "latyshova.productivity_pn", "latyshova.methods_overlap"]}, {"title": "Литологическая колонка по комплексу ГИС", "nodes": ["latyshova.build_litho_column", "latyshova.table21_clays_sands_gas", "latyshova.table21_carbonates_salts", "latyshova.mixed_section_practice"]}, {"title": "Выделение межзерновых коллекторов в терригенном разрезе", "nodes": ["latyshova.direct_signs_of_collector", "latyshova.radial_gradient_and_dynamic", "latyshova.critical_permeability", "latyshova.debit_to_critical_perm", "latyshova.permeability_threshold_on_logs", "latyshova.nmr_and_method_choice"]}, {"title": "Характер насыщения коллектора", "nodes": ["latyshova.saturation_from_resistivity", "latyshova.compare_resistivity_porosity", "latyshova.rho_kp_palette", "latyshova.reading_palette", "latyshova.critical_pn_kv", "latyshova.phase_permeability_zones", "latyshova.critical_values_examples", "latyshova.clay_classes_critical", "latyshova.saturation_examples_tasks"]}, {"title": "Эффективная толщина продуктивного коллектора", "nodes": ["latyshova.effective_thickness_basic", "latyshova.vnk_transition_zone", "latyshova.gnk_by_neutron", "latyshova.nonreservoir_interlayers", "latyshova.thin_layers_resistivity", "latyshova.thin_layers_sp", "latyshova.thickness_practice", "latyshova.ggm_ak_collectors"]}, {"title": "Карбонатный разрез", "nodes": ["latyshova.carbonate_features", "latyshova.normalization_overlay", "latyshova.example_54", "latyshova.kp_star_graph", "latyshova.kp_star_table"]}, {"title": "Сложные коллекторы", "nodes": ["latyshova.complex_collectors", "latyshova.fracture_matrix", "latyshova.fracture_detection"]}], "steps": [{"title": "Какие задачи решают данные ГИС при построении разреза и оценке коллекторов", "short_title": "Задачи ГИС в разрезе скважины", "why_here": {"text": "Открывает главу: задаёт цели (литология, коллекторы, насыщение, толщина, пористость), к которым далее подводят все остальные шаги.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Н"}, "threshold": true, "pages": [90], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход — диаграммы главных методов геофизического комплекса по скважине. Выход — литологический разрез, коллекторы с характером насыщения, эффективная толщина, коэффициенты пористости, нефтегазонасыщения, проницаемости и глинистости. Для эксплуатационных скважин выходом также служит положение ВНК и ГЖК по ходу разработки.", "by_model": true}, "breaks": {"text": "Качественной интерпретации достаточно лишь для простейшего случая коллекторов с межзерновой пористостью. Для более сложных коллекторов она недостаточна, нужна количественная.", "by_model": true}, "hypotheses": []}, "it_analogy": {"text": "Качественная интерпретация похожа на быстрый просмотр логов по шаблонным признакам, количественная — на расчёт метрик по этим логам.", "breaks_where": "В ГИС вывод об объекте делают косвенно по физическому отклику породы, а не по явным записям. Простая и сложная ситуации отличаются свойствами породы, а не объёмом данных.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["эффективная толщина", "качественная интерпретация", "количественная интерпретация", "ВНК", "ГЖК"], "links": [], "needs_scan": [], "claims": [{"page_print": null, "text": "Данные ГИС поисковых, разведочных и эксплуатационных скважин на нефть и газ используются для составления литологического разреза скважины.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.06", "quote": "Данные геофизических исследований поисковых, разведочных и эксплуатационных скважин на нефть и газ используются для составления литологического разреза скважины", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c1"}, {"page_print": null, "text": "Данные ГИС используются для выделения коллекторов в разрезе и оценки характера их насыщения.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.06", "quote": "выделения и оценки характера насыщения коллекторов в разрезе", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c2"}, {"page_print": null, "text": "Данные ГИС используются для определения эффективной толщины, коэффициентов пористости и нефтегазонасыщения.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.06", "quote": "определения эффективной толщины, коэффициентов пористости и нефтегазонасыщения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c3"}, {"page_print": null, "text": "Данные ГИС используются также для оценки коэффициентов проницаемости и глинистости продуктивных коллекторов.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.06", "quote": "а также оценки коэффициентов проницаемости и глинистости продуктивных коллекторов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c4"}, {"page_print": null, "text": "Литологический разрез обычно строят методами качественной интерпретации, применяя признаки основных типов пород на главных диаграммах геофизического комплекса.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.07", "quote": "Первая из перечисленных задач решается обычно методами качественной интерпретации путем применения признаков основных типов пород на главных диаграммах геофизического комплекса.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c5"}, {"page_print": null, "text": "Для простейшего случая коллекторов с межзерновой пористостью выделение, оценка характера насыщения и определение эффективной толщины также проводятся качественной интерпретацией.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.07", "quote": "Выделение, оценка характера насыщения коллекторов и определение их эффективной толщины проводятся для простейшего случая коллекторов с межзерновой пористостью также на основании качественной интерпретации", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c6"}, {"page_print": null, "text": "Для более сложных коллекторов применяют количественную интерпретацию через оценку коэффициентов пористости, глинистости, нефтегазонасыщения либо параметра насыщения Pп.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.07", "quote": "а для более сложных — методами количественной интерпретации через оценку коэффициентов пористости, глинистости, нефтегазонасыщения, либо параметра насыщения $P_п$.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c7"}, {"page_print": null, "text": "Промышленная оценка коллекторов основана на количественных определениях пористости, нефтегазонасыщения и проницаемости.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.07", "quote": "Промышленная оценка коллекторов базируется на количественных определениях пористости, нефтегазонасыщения, проницаемости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c8"}, {"page_print": null, "text": "Эти количественные определения используются при подсчёте запасов и проектировании разработки месторождений.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.07", "quote": "используемых при проведении подсчетов запасов и проектировании разработки месторождений.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c9"}, {"page_print": null, "text": "По данным эксплуатационных скважин, кроме перечисленных задач, по геофизическим материалам устанавливают характер продвижения ВНК и ГЖК в процессе разработки месторождения.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.08", "quote": "По данным, полученным в эксплуатационных скважинах, кроме указанных задач, по геофизическим материалам устанавливается характер продвижения водонефтяного (ВНК) и газожидкостного (ГЖК) контактов в процессе разработки месторождения.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.goals_of_log_interpretation#c10"}], "id": "latyshova.goals_of_log_interpretation", "order": 1, "minutes": 2, "essence": "Данные ГИС используются для литологического разреза, выделения коллекторов и оценки их насыщения. Они же дают эффективную толщину, пористость, нефтегазонасыщение, проницаемость и глинистость. Простые задачи решают качественно, сложные и промышленную оценку — количественно.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Качественная интерпретация — это работа по признакам на диаграммах без расчёта численных параметров. Количественная интерпретация — это расчёт числовых параметров коллектора. Литологический разрез строят качественно: применяют признаки основных типов пород на главных диаграммах комплекса.", "pages": [90]}, {"text": "Для простейших коллекторов с межзерновой пористостью качественно же выделяют коллектор, оценивают насыщение и находят эффективную толщину. Для более сложных коллекторов считают пористость, глинистость и нефтегазонасыщение либо параметр насыщения Pп. Как именно считают, в этой части главы не сказано.", "pages": [90]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок работы виден из текста: сначала литологический разрез, затем выделение коллекторов и оценка насыщения. Способ зависит от сложности коллектора. Для промышленной оценки нужны пористость, нефтегазонасыщение и проницаемость: их используют при подсчёте запасов и проектировании разработки.", "pages": [90]}, {"text": "В эксплуатационных скважинах по ГИС дополнительно следят за продвижением контактов ВНК и ГЖК. ВНК — водонефтяной контакт, граница между водой и нефтью. ГЖК — газожидкостной контакт, граница между газом и жидкостью.", "pages": [90]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Эффективная толщина — толщина той части пласта, которая работает как коллектор. Автор в этой части главы её не определяет. Граница между простым и сложным коллектором задана только примером: простейший случай — межзерновая пористость.", "pages": [90]}, {"text": "Критерии «сложности» в этой части главы не раскрыты. Пороговые значения для выделения коллектора здесь не приводятся.", "pages": [90]}]}], "deeper": [], "glossary": [{"term": "эффективная толщина", "definition": "Толщина части пласта, которая работает как коллектор. Определяется по данным ГИС; в главе в этой части главы не раскрыта."}, {"term": "качественная интерпретация", "definition": "Анализ диаграмм ГИС по признакам типов пород и коллекторов без расчёта числовых параметров."}, {"term": "количественная интерпретация", "definition": "Расчёт числовых параметров коллектора по данным ГИС: пористости, глинистости, нефтегазонасыщения или параметра насыщения Pп."}, {"term": "ВНК", "definition": "Водонефтяной контакт — граница между водой и нефтью в пласте."}, {"term": "ГЖК", "definition": "Газожидкостной контакт — граница между газом и жидкостью в пласте."}], "format": "карточки", "tasks": [{"id": "latyshova.goals_of_log_interpretation.t1", "type": "multiple", "step_id": "latyshova.goals_of_log_interpretation", "claim_ids": ["latyshova.goals_of_log_interpretation#c1", "latyshova.goals_of_log_interpretation#c2", "latyshova.goals_of_log_interpretation#c3"], "prompt": "Какие из перечисленных задач решают по данным ГИС нефтяных и газовых скважин? Выберите все верные варианты.", "options": [{"id": "a", "text": "Составление литологического разреза скважины", "misconception": null}, {"id": "b", "text": "Выделение коллекторов и оценка характера их насыщения", "misconception": null}, {"id": "c", "text": "Определение эффективной толщины и коэффициентов пористости", "misconception": null}, {"id": "d", "text": "Измерение минерализации раствора на поверхности буровой", "misconception": "misc.gis_tasks_confusion"}], "answer": ["a", "b", "c"], "tolerance": null, "unit": null, "explanation": "Литологический разрез, выделение коллекторов с оценкой насыщения, эффективная толщина и пористость названы задачами ГИС, а минерализацию раствора на поверхности ГИС не определяют.", "kind": "recall"}, {"id": "latyshova.goals_of_log_interpretation.t2", "type": "single", "step_id": "latyshova.goals_of_log_interpretation", "claim_ids": ["latyshova.goals_of_log_interpretation#c6", "latyshova.goals_of_log_interpretation#c7"], "prompt": "Геофизик изучает простейший коллектор с межзерновой пористостью. Как для него выделяют коллектор, оценивают насыщение и находят эффективную толщину?", "options": [{"id": "a", "text": "Только количественно: расчётом пористости, глинистости и нефтегазонасыщения по формулам", "misconception": "misc.always_quantitative"}, {"id": "b", "text": "Качественно: по признакам на диаграммах, без расчёта параметров", "misconception": null}, {"id": "c", "text": "Только по керну, потому что ГИС для выделения коллекторов не применяют", "misconception": "misc.gis_not_for_collectors"}, {"id": "d", "text": "Количественно, через параметр насыщения Pп, так как качественных признаков коллектора нет", "misconception": "misc.always_quantitative"}], "answer": "b", "tolerance": null, "unit": null, "explanation": "Для простейшего межзернового коллектора выделение, оценка насыщения и эффективная толщина определяются качественной интерпретацией, а количественная нужна для более сложных коллекторов.", "kind": "understanding"}], "pictures": [{"id": "latyshova.goals_of_log_interpretation.i1", "step_id": "latyshova.goals_of_log_interpretation", "node_id": "latyshova.goals_of_log_interpretation", "file": "pictures/goals_of_log_interpretation_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Сравните, какие задачи по ГИС решают по признакам на диаграммах, а какие требуют расчёта параметров.", "alt": "Таблица из двух столбцов: качественная интерпретация работает по признакам и решает литологию и простые коллекторы, количественная считает пористость, глинистость и насыщение.", "source": "построено кодом по утверждениям главы, стр. 90", "claim_ids": ["latyshova.goals_of_log_interpretation#c5", "latyshova.goals_of_log_interpretation#c6", "latyshova.goals_of_log_interpretation#c7", "latyshova.goals_of_log_interpretation#c8"], "prompt": null}]}, {"title": "Как глинистый раствор образует корку и зону проникновения и меняет диаметр скважины", "short_title": "Раствор, корка и диаметр скважины", "why_here": {"text": "Опирается на общие задачи ГИС; все признаки коллектора далее строятся на следах раствора в стенке скважины.", "by_model": true}, "difficulty": {"primary": "М", "secondary": "И"}, "threshold": true, "pages": [90], "misconception": {"ref": null, "text": "Диаметр скважины всегда равен диаметру долота. На деле в коллекторе он меньше из-за корки, а в глинах, трещиноватых породах, карсте и солях может быть больше.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Диаметр скважины d_c сравнивают с номинальным d_a. Значение d_c меньше d_a указывает на межзерновой коллектор с коркой, d_c равен d_a — на плотную сцементированную породу, d_c больше d_a — на глины, сланцы, аргиллиты, трещиноватые породы, карст или растворимые соли.", "by_model": false}, "breaks": {"text": "Правило относится к скважинам на глинистом растворе. Для технической воды и нефильтрующихся растворов в единицах правил нет. Увеличение диаметра неоднозначно: оно бывает в разных породах.", "by_model": true}, "hypotheses": [{"text": "Диаметр скважины определяют кавернометрией, то есть кавернометр даёт кривую d_c по глубине; в этой части главы метод не назван.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Корка похожа на кэш на входе в сервис: слой, который образуется при обращении к проницаемому ресурсу и сужает канал.", "breaks_where": "Корка физическая, она не ускоряет работу и не очищается сама. Кэш не создаёт зону изменённой среды вокруг канала.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["d_c < d_a", "d_c = d_a", "d_c > d_a"], "rule": "На глинистом растворе: d_c < d_a — межзерновой коллектор с коркой; d_c = d_a — плотная сцементированная порода; d_c > d_a — глины, сланцы, аргиллиты, трещиноватые породы, карст или соли.", "conclusion": "Сопоставление d_c с d_a даёт предварительный признак типа породы в интервале.", "counterexample": "Увеличенный d_c не отличает глину от карста или соли, поэтому по диаметру одному вывод неоднозначен."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["промывочная жидкость", "глинистый раствор", "фильтрат", "глинистая корка", "зона проникновения", "номинальный диаметр d_a", "диаметр скважины d_c"], "links": [{"type": "prerequisite", "target": "latyshova.goals_of_log_interpretation"}], "needs_scan": [], "claims": [{"page_print": null, "text": "В данном районе и в пределах изучаемого геологического объекта должен применяться оптимальный комплекс геофизических исследований, соответствующий условиям района.", "kind": "assumption", "page_pdf": 90, "unit_id": "p090.10", "quote": "должен применяться оптимальный, соответствующий условиям района комплекс геофизических исследований", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c1"}, {"page_print": null, "text": "Состав методов оптимального комплекса зависит от особенностей разреза: терригенный, карбонатный, гидрохимический и др.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.11", "quote": "Состав методов оптимального комплекса зависит от особенностей разреза (терригенный, карбонатный, гидрохимический и др.)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c2"}, {"page_print": null, "text": "На комплекс методов и способы их интерпретации существенно влияют условия бурения, в первую очередь тип и параметры промывочной жидкости.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.11", "quote": "На комплекс применяемых методов и способы их интерпретации также существенно влияют условия бурения скважин и в первую очередь тип и параметры промывочной жидкости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c3"}, {"page_print": null, "text": "Тип и параметры промывочной жидкости в значительной степени определяют достоверность и качество информации, получаемой по геофизическим данным.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.11", "quote": "которые в значительной степени определяют достоверность и качество получаемой по геофизическим данным информации", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c4"}, {"page_print": null, "text": "Промывочными жидкостями являются глинистые растворы, техническая вода и нефильтрующиеся растворы.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.11", "quote": "Промывочными жидкостями являются глинистые растворы, техническая вода и нефильтрующиеся растворы.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c5"}, {"page_print": null, "text": "Глинистый раствор — наиболее широко применяемая в настоящее время промывочная жидкость.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.12", "quote": "Глинистый раствор — наиболее широко применяемая в настоящее время промывочная жидкость", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c6"}, {"page_print": null, "text": "Основные признаки выделения литологических разностей, в том числе коллекторов, формулируются в расчёте на применение глинистого раствора.", "kind": "inference", "page_pdf": 90, "unit_id": "p090.12", "quote": "основные признаки выделения в разрезе литологических разностей, в том числе коллекторов, по геофизическим данным формулируются в расчете на применение глинистого раствора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c7"}, {"page_print": null, "text": "В межзерновых коллекторах при вскрытии на глинистом растворе образуются зоны проникновения фильтрата раствора и глинистые корки на стенках скважины, при этом d_c < d_a.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.13", "quote": "образование в межзерновых коллекторах зон проникновения фильтрата раствора и глинистых корок на стенках скважины $d_c < d_a$", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c8"}, {"page_print": null, "text": "В плотных сцементированных породах диаметр скважины остаётся равным номинальному (d_c = d_a).", "kind": "observation", "page_pdf": 90, "unit_id": "p090.13", "quote": "В плотных, сцементированных породах диаметр скважины остается равным номинальному ($d_c = d_a$).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c9"}, {"page_print": null, "text": "В глинах, глинистых сланцах, аргиллитах диаметр скважины увеличивается за счёт разбухания глинистых частиц и вымывания их струей бурового раствора.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.13", "quote": "за счет разбухания глинистых частиц и вымывания их струей бурового раствора диаметр скважины увеличивается", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c10"}, {"page_print": null, "text": "В трещиноватых разрушенных породах, зонах карста и растворимых каменных и калийных солях диаметр скважины также может увеличиваться (d_c > d_a).", "kind": "observation", "page_pdf": 90, "unit_id": "p090.13", "quote": "диаметр скважины также может увеличиваться ($d_c > d_a$)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mud_effects_on_borehole#c11"}], "id": "latyshova.mud_effects_on_borehole", "order": 2, "minutes": 3, "essence": "Глинистый раствор — самая распространённая промывочная жидкость, поэтому признаки коллекторов в главе сформулированы для него. В проницаемых межзерновых породах он образует зону проникновения фильтрата и глинистую корку, и диаметр скважины становится меньше номинального. В плотных породах диаметр равен номинальному, а в глинах, трещиноватых породах, карсте и солях он может быть больше.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Промывочная жидкость — жидкость, которой промывают скважину при бурении. Глинистый раствор — один из её видов. Фильтрат — жидкая часть раствора, которая входит в пласт.", "pages": [90]}, {"text": "Зона проникновения — часть пласта около стенки скважины, куда вошёл фильтрат. Глинистая корка — слой глинистых частиц на стенке скважины. В главе корка и зона проникновения названы особенностями вскрытия межзерновых коллекторов.", "pages": [90]}, {"text": "Номинальный диаметр d_a — исходный диаметр скважины, заданный долотом (это пояснение модели). Диаметр скважины d_c — фактический диаметр. Из-за корки в коллекторе d_c меньше d_a.", "pages": [90]}, {"text": "В плотных сцементированных породах d_c равен d_a. В глинах, сланцах и аргиллитах диаметр растёт: частицы разбухают, а струя раствора вымывает их. В трещиноватых разрушенных породах, карсте, растворимых каменных и калийных солях d_c тоже может быть больше d_a.", "pages": [90]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Комплекс методов ГИС должен быть оптимальным для района и изучаемого объекта. Его состав зависит от типа разреза: терригенный, карбонатный, гидрохимический и другие. На выбор методов и способы интерпретации влияют условия бурения, прежде всего тип и параметры промывочной жидкости.", "pages": [90]}, {"text": "Они определяют достоверность и качество информации. Признаки выделения литологических разностей и коллекторов в главе даны в расчёте на глинистый раствор.", "pages": [90]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Промывочные жидкости бывают разные: глинистые растворы, техническая вода и нефильтрующиеся растворы. Признаки коллектора, построенные для глинистого раствора, к другим жидкостям переносить нельзя без оговорок (вывод модели). Корка и зона проникновения указаны для межзерновых коллекторов.", "pages": [90]}, {"text": "Увеличение диаметра бывает в разных породах по разным причинам: набухание и вымыв в глинах, разрушение в трещиноватых породах, растворение в солях и карсте. Поэтому один лишь увеличенный диаметр не указывает на конкретную породу (вывод модели).", "pages": [90]}]}], "deeper": [], "glossary": [{"term": "промывочная жидкость", "definition": "Жидкость, применяемая при бурении скважины; в главе это глинистые растворы, техническая вода и нефильтрующиеся растворы."}, {"term": "глинистый раствор", "definition": "Наиболее широко применяемая промывочная жидкость, на которую рассчитаны основные признаки выделения пород и коллекторов."}, {"term": "фильтрат", "definition": "Жидкая часть глинистого раствора, проникающая в межзерновой коллектор."}, {"term": "глинистая корка", "definition": "Слой, образующийся на стенках скважины против межзерновых коллекторов при бурении на глинистом растворе."}, {"term": "зона проникновения", "definition": "Область межзернового коллектора вокруг скважины, в которую проник фильтрат раствора."}, {"term": "номинальный диаметр d_a", "definition": "Исходный (номинальный) диаметр скважины, с которым сравнивают фактический диаметр."}, {"term": "диаметр скважины d_c", "definition": "Фактический диаметр скважины, который может быть меньше, равен или больше номинального."}], "format": "длинное видео", "tasks": [{"id": "latyshova.mud_effects_on_borehole.t1", "type": "single", "step_id": "latyshova.mud_effects_on_borehole", "claim_ids": ["latyshova.mud_effects_on_borehole#c10", "latyshova.mud_effects_on_borehole#c11"], "prompt": "Скважину бурят на глинистом растворе. В некотором интервале фактический диаметр скважины d_c больше номинального d_a. Что можно заключить только по этому признаку?", "options": [{"id": "a", "text": "Это обязательно глина, потому что только глины разбухают и размываются струёй раствора", "misconception": "misc.enlarged_diameter_is_clay"}, {"id": "b", "text": "Это проницаемый межзерновой коллектор, на стенке которого нарос слой глинистой корки", "misconception": "misc.crust_increases_diameter"}, {"id": "c", "text": "Это плотная сцементированная порода, у которой диаметр совпадает с номинальным", "misconception": "misc.dense_rock_enlarged"}, {"id": "d", "text": "Любая из пород: глина, трещиноватая порода, карст, соль, диаметром их не различить", "misconception": null}], "answer": "d", "tolerance": null, "unit": null, "explanation": "Увеличение диаметра возникает в глинах, трещиноватых породах, карсте и солях по разным причинам, поэтому один диаметр не указывает на конкретную породу.", "kind": "transfer"}, {"id": "latyshova.mud_effects_on_borehole.t2", "type": "gap", "step_id": "latyshova.mud_effects_on_borehole", "claim_ids": ["latyshova.mud_effects_on_borehole#c8", "latyshova.mud_effects_on_borehole#c9"], "prompt": "При бурении на глинистом растворе диаметр скважины в плотных сцементированных породах {{1}} номинальному, а в межзерновом коллекторе из-за глинистой корки он {{2}} номинального. Вставьте пропущенные слова (равен / меньше / больше).", "options": [], "answer": ["равен", "меньше"], "tolerance": null, "unit": null, "explanation": "В плотных породах d_c = d_a, а корка в коллекторе даёт d_c < d_a.", "kind": "recall"}], "pictures": [{"id": "latyshova.mud_effects_on_borehole.i1", "step_id": "latyshova.mud_effects_on_borehole", "node_id": "latyshova.mud_effects_on_borehole", "file": "pictures/mud_effects_on_borehole_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Смотрите, как диаметр скважины d_c соотносится с номинальным d_a в разных породах при глинистом растворе.", "alt": "Таблица: в межзерновом коллекторе диаметр скважины меньше номинального, в плотной породе равен ему, в глинах, трещиноватых породах, карсте и солях больше.", "source": "построено кодом по утверждениям главы, стр. 90", "claim_ids": ["latyshova.mud_effects_on_borehole#c8", "latyshova.mud_effects_on_borehole#c9", "latyshova.mud_effects_on_borehole#c10", "latyshova.mud_effects_on_borehole#c11"], "prompt": null}]}, {"title": "Водоотдача и плотность раствора определяют глубину проникновения и доступность коллектора для методов", "short_title": "Водоотдача, плотность, репрессия", "why_here": {"text": "Опирается на корку и проникновение; объясняет, при каких условиях разные методы вообще видят коллектор.", "by_model": true}, "difficulty": {"primary": "М", "secondary": "Н"}, "threshold": false, "pages": [90, 91], "misconception": null, "data_meaning": {"from_chapter": {"text": "Глава связывает параметры раствора с доступностью коллектора для методов. Водоотдача 4—8 см³/ч даёт минимальные проникновение и корку, а 20 см³/ч — глубокое проникновение и толстую корку. Глубинные методы электрометрии (индукционный зонд, большие потенциал- и градиент-зонды) страдают от проникновения. Малоглубинные ГГМ, МБК, ЯМР страдают от толстой корки. Табличных столбцов и кривых в этой части главы нет.", "by_model": true}, "breaks": {"text": "При высокой водоотдаче (20 см³/ч) глубокое проникновение не позволяет оценить продуктивность глубинными методами электрометрии. Толстая корка закрывает коллектор от малоглубинных методов. Рост плотности раствора, а значит и Δp, ухудшает условия аналогично.", "by_model": true}, "hypotheses": [{"text": "Если по замерам видно разное влияние на глубинные и малоглубинные методы, это может указывать на водоотдачу или репрессию как причину. Глава этого прямо не утверждает.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Репрессия похожа на перепад напора между двумя системами. Чем больше перепад, тем дальше «просачивается» содержимое из одной системы в другую, а корка играет роль буферного слоя на границе.", "breaks_where": "В скважине просачивание зависит ещё от проницаемости породы и свойств корки. Проникновение нельзя свести к одному перепаду, как в простой сетевой модели.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["водоотдача раствора (см³/ч)", "плотность раствора и репрессия Δp = p_c − p_пл", "набор методов: глубинные (индукционный зонд, большие потенциал- и градиент-зонды) и малоглубинные (ГГМ, МБК, ЯМР)"], "rule": "Водоотдача 4—8 см³/ч и Δp ≈ 0 дают минимальные проникновение и корку, и коллектор доступен обеим группам методов. Высокая водоотдача (20 см³/ч) или большая репрессия делают проникновение глубоким и корку толстой.", "conclusion": "При высокой водоотдаче продуктивность нельзя оценивать наиболее глубинными методами электрометрии, а малоглубинные методы коллектор не изучают. Условия лучше всего при бурении на равновесии.", "counterexample": "В главе не приведён."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["водоотдача", "репрессия Δp", "бурение на равновесии"], "links": [{"type": "prerequisite", "target": "latyshova.goals_of_log_interpretation"}, {"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Проявление особенностей (корка, проникновение) зависит от параметров раствора: водоотдачи, плотности и минерализации фильтрата.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.14", "quote": "Проявление этих особенностей зависит от параметров раствора: водоотдачи, плотности, минерализации фильтрата.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c1"}, {"page_print": null, "text": "Водоотдача — основной показатель качества глинистого раствора; чем ниже водоотдача, тем лучше раствор.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.14", "quote": "Водоотдача - основной показатель качества глинистого раствора; чем ниже водоотдача, тем лучше раствор.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c2"}, {"page_print": null, "text": "При оптимальной водоотдаче (4—8 см³/ч) условия изучения разреза геофизическими методами наиболее благоприятны.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.14", "quote": "При оптимальной водоотдаче (4—8 см³/ч) условия изучения разреза геофизическими методами наиболее благоприятны", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c3"}, {"page_print": null, "text": "Причина благоприятных условий: при оптимальной водоотдаче глубина проникновения и толщина глинистой корки в коллекторах минимальны.", "kind": "inference", "page_pdf": 90, "unit_id": "p090.14", "quote": "поскольку в этом случае глубина проникновения и толщина глинистой корки в коллекторах являются минимальными.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c4"}, {"page_print": null, "text": "Оптимальная водоотдача обеспечивает надёжное определение параметров неизменённой части коллектора методами электрометрии.", "kind": "inference", "page_pdf": 90, "unit_id": "p090.14", "quote": "Это обеспечивает надежное определение параметров неизмененной части коллектора методами электрометрии", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c5"}, {"page_print": null, "text": "Оптимальная водоотдача обеспечивает надёжное определение коллекторских свойств пласта методами с высокой вертикальной разрешающей способностью и малой глубинностью (ГГМ, МБК, ЯМР).", "kind": "inference", "page_pdf": 90, "unit_id": "p090.14", "quote": "коллекторских свойств пласта методами с высокой вертикальной разрешающей способностью и малой глубинностью (ГГМ, МБК, ЯМР)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c6"}, {"page_print": null, "text": "При высокой водоотдаче (20 см³/ч) условия изучения разреза, прежде всего коллекторов, становятся крайне неблагоприятными.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.14", "quote": "При высокой водоотдаче (20 см³/ч) условия изучения разреза и прежде всего коллекторов геофизическими методами становятся крайне неблагоприятными", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c7"}, {"page_print": null, "text": "При высокой водоотдаче глубокое проникновение не позволяет оценивать продуктивность коллектора наиболее глубинными методами электрометрии (индукционный зонд, большие потенциал- и градиент-зонды).", "kind": "inference", "page_pdf": 90, "unit_id": "p090.14", "quote": "глубокое проникновение не позволяет оценивать продуктивность коллектора наиболее глубинными методами электрометрии (индукционный зонд, большие потенциал- и градиент-зонды)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c8"}, {"page_print": null, "text": "При высокой водоотдаче толстая глинистая корка делает коллектор недоступным для изучения методами с малой глубинностью (ГГМ, МБК, ЯМР).", "kind": "inference", "page_pdf": 90, "unit_id": "p090.14", "quote": "а толстая глинистая корка делает коллектор недоступным для изучения методами с малой глубинностью (ГГМ, МБК, ЯМР)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c9"}, {"page_print": null, "text": "Плотность глинистого раствора определяет давление в скважине и его превышение (репрессию Δp) над пластовым давлением на заданной глубине.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.15", "quote": "определяет величину давления в скважине $p$ и превышение его (репрессию) $\\Delta p$ над пластовым $p_{пл}$", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c10"}, {"page_print": null, "text": "Репрессия определяется формулой Δp = p_c − p_пл (давление в скважине минус пластовое) на заданной глубине.", "kind": "assumption", "page_pdf": 90, "unit_id": "p090.15", "quote": "на заданной глубине ($\\Delta p = p_c - p_{пл}$)", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c11"}, {"page_print": null, "text": "Чем больше плотность раствора, тем больше давление в скважине и репрессия, и тем глубже фильтрат проникает в коллекторы.", "kind": "inference", "page_pdf": 90, "unit_id": "p090.15", "quote": "Чем больше $\\delta_p$, тем больше $p_c$ и $\\Delta p$, и тем глубже происходит проникновение фильтрата глинистого раствора в коллекторы.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c12"}, {"page_print": null, "text": "Для промысловой геофизики увеличение плотности раствора означает примерно то же, что увеличение водоотдачи.", "kind": "inference", "page_pdf": 91, "unit_id": "p091.01", "quote": "Следовательно, увеличение $\\delta_p$ раствора для промысловой геофизики означает примерно то же, что увеличение водоотдачи.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c13"}, {"page_print": null, "text": "Оптимальные условия для геофизических исследований — бурение с минимальной репрессией или «на равновесии», когда Δp ≈ 0.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.01", "quote": "Оптимальные условия для проведения геофизических исследований - бурение с минимальным $\\Delta p$ или \"на равновесии\", когда $\\Delta p \\approx 0$.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_loss_and_mud_density#c14"}], "id": "latyshova.water_loss_and_mud_density", "order": 3, "minutes": 3, "essence": "Водоотдача — главный показатель качества раствора, и чем она ниже, тем лучше условия для каротажа. При оптимальной водоотдаче проникновение и корка минимальны, поэтому доступны и глубинные, и малоглубинные методы. Плотность раствора задаёт давление в скважине и репрессию Δp: чем она больше, тем глубже проникает фильтрат, так что рост плотности для геофизики почти равен росту водоотдачи.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Фильтрат уходит из раствора в проницаемый пласт и формирует зону проникновения, а на стенке скважины остаётся глинистая корка. Водоотдача показывает, как легко раствор отдаёт фильтрат. Чем она выше, тем глубже проникновение и тем толще корка.", "pages": [90]}, {"text": "Давление в скважине создаётся плотностью раствора. Репрессия Δp — это превышение давления в скважине p_c над пластовым p_пл на заданной глубине: Δp = p_c − p_пл. Чем больше плотность, тем больше p_c и Δp, и тем глубже фильтрат проникает в коллектор.", "pages": [90]}, {"text": "Поэтому увеличение плотности действует на условия каротажа примерно так же, как увеличение водоотдачи. Параметрами раствора, от которых зависят эти особенности, названы водоотдача, плотность и минерализация фильтрата. Влияние минерализации фильтрата в этой части главы не раскрыто.", "pages": [90]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "При оптимальной водоотдаче 4—8 см³/ч глубина проникновения и корка минимальны. Тогда электрометрия надёжно определяет параметры неизменённой части коллектора. Методы с высокой вертикальной разрешающей способностью и малой глубинностью (ГГМ, МБК, ЯМР) надёжно оценивают коллекторские свойства.", "pages": [90]}, {"text": "При высокой водоотдаче 20 см³/ч глубокое проникновение мешает оценивать продуктивность самыми глубинными методами электрометрии: индукционным зондом, большими потенциал- и градиент-зондами. Толстая корка делает коллектор недоступным для малоглубинных методов ГГМ, МБК и ЯМР. Лучшие условия для исследований дают бурение с минимальным Δp, или «на равновесии», когда Δp ≈ 0.", "pages": [90]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Водоотдача в тексте дана в см³/ч, как у автора; единицу и числа 4—8 и 20 мы не пересчитывали. Вывод об эквивалентности плотности и водоотдачи сформулирован как «примерно то же», то есть не как точное равенство. В тексте давление в скважине обозначено то p, то p_c; в формуле репрессии используется p_c.", "pages": [90, 91]}, {"text": "Для значений водоотдачи между 8 и 20 см³/ч глава оценок не даёт.", "pages": [90, 91]}]}], "deeper": [], "glossary": [{"term": "водоотдача", "definition": "Показатель качества глинистого раствора: чем ниже водоотдача, тем лучше раствор. Оптимальная — 4—8 см³/ч, высокая — 20 см³/ч. От неё зависят глубина проникновения и толщина глинистой корки."}, {"term": "репрессия Δp", "definition": "Превышение давления в скважине p_c над пластовым p_пл на заданной глубине: Δp = p_c − p_пл. Она растёт с плотностью раствора, и чем она больше, тем глубже проникает фильтрат."}, {"term": "бурение на равновесии", "definition": "Бурение с минимальной репрессией, когда Δp ≈ 0. Такие условия оптимальны для проведения геофизических исследований."}], "format": "шортс", "tasks": [{"id": "latyshova.water_loss_and_mud_density.t1", "type": "calc", "step_id": "latyshova.water_loss_and_mud_density", "claim_ids": ["latyshova.water_loss_and_mud_density#c10", "latyshova.water_loss_and_mud_density#c11"], "prompt": "На некоторой глубине давление в скважине p_c = 31,5 МПа, пластовое давление p_пл = 28,0 МПа. Найдите репрессию Δp на этой глубине (ответ в МПа).", "options": [], "answer": 3.5, "tolerance": 0.05, "unit": "МПа", "explanation": "Репрессия равна разности давления в скважине и пластового: Δp = 31,5 − 28,0 = 3,5 МПа.", "kind": "data"}, {"id": "latyshova.water_loss_and_mud_density.t2", "type": "order", "step_id": "latyshova.water_loss_and_mud_density", "claim_ids": ["latyshova.water_loss_and_mud_density#c10", "latyshova.water_loss_and_mud_density#c12"], "prompt": "Расположите звенья цепочки в порядке причинной связи: от увеличения плотности раствора до последствия для коллектора.", "options": [{"id": "d", "text": "Фильтрат глубже проникает в коллектор", "misconception": null}, {"id": "b", "text": "Растёт давление в скважине p_c", "misconception": null}, {"id": "a", "text": "Растёт плотность глинистого раствора", "misconception": null}, {"id": "c", "text": "Растёт репрессия Δp", "misconception": null}], "answer": ["a", "b", "c", "d"], "tolerance": null, "unit": null, "explanation": "Плотность задаёт давление в скважине, оно увеличивает репрессию, а большая репрессия углубляет проникновение фильтрата.", "kind": "understanding"}], "pictures": [{"id": "latyshova.water_loss_and_mud_density.i1", "step_id": "latyshova.water_loss_and_mud_density", "node_id": "latyshova.water_loss_and_mud_density", "file": "pictures/water_loss_and_mud_density_1.svg", "frame_class": "A", "origin": "code_from_data", "label": "схема", "caption": "Оптимальная водоотдача 4–8 см³/ч даёт минимальные проникновение и корку, при 20 см³/ч условия крайне неблагоприятны.", "alt": "Столбчатая диаграмма: оптимальная водоотдача раствора лежит в диапазоне от 4 до 8 кубических сантиметров в час, высокая равна 20.", "source": "построено кодом по утверждениям главы, стр. 90", "claim_ids": ["latyshova.water_loss_and_mud_density#c3", "latyshova.water_loss_and_mud_density#c7"], "prompt": null}]}, {"title": "Как минерализация фильтрата влияет на выделение коллектора и на оценку продуктивности", "short_title": "Минерализация фильтрата", "why_here": {"text": "Продолжает тему параметров раствора; готовит понимание повышающего и понижающего проникновения.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "Н"}, "threshold": false, "pages": [91], "misconception": null, "data_meaning": {"from_chapter": {"text": "Входные данные: сопротивление фильтрата ρф и величина ρп. Выход: насколько эффективны СП, микрозонды и индукционный метод для выделения коллектора. Ещё выход: какие зоны проникновения (понижающие или нет) видны по разноглубинной электрометрии. Диаграммы СП и микрозондов выделяют коллектор отрицательной аномалией СП и положительным приращением микрозондов.", "by_model": true}, "breaks": {"text": "Когда ρф приближается к ρп, СП и микрозонды плохо выделяют коллектор. Индукционный метод тоже теряет эффективность.", "by_model": true}, "hypotheses": [{"text": "Вероятно, ρп — сопротивление, с которым сравнивают ρф, а ρпп — сопротивление, измеряемое более глубоким методом. В этой части главы символы не расшифрованы.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на контраст подсветки при разметке объектов на изображении. Когда цвет метки близок к фону, границы не разглядеть. Но близость цветов упрощает сравнение по другому признаку.", "breaks_where": "У фильтрата нет цвета. Это физическое сопротивление, и разные методы реагируют на него по разным законам, а не по одному признаку.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["ρф > ρп (пресный раствор) или ρф близко к ρп", "аномалия СП", "приращения на микрозондах", "соотношение ρп и ρпп по разноглубинным методам"], "rule": "Если ρф > ρп, коллектор выделяют по отрицательной аномалии СП и положительному приращению микрозондов. Если ρф ≈ ρп, СП и микрозонды малоэффективны, но по разноглубинным методам продуктивный коллектор показывает ρп < ρпп, а водоносный — ρп ≈ ρпп.", "conclusion": "Метод выбирают по соотношению ρф и ρп: выделение коллектора и оценка продуктивности требуют разных условий.", "counterexample": "В главе в этой части главы контрпример не приведён."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["удельное сопротивление фильтрата ρф", "пресный раствор", "повышающее проникновение", "понижающее проникновение"], "links": [{"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.water_loss_and_mud_density"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Минерализацию фильтрата глинистого раствора геофизики обычно связывают с удельным сопротивлением фильтрата ρф.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.02", "quote": "Минерализация С фильтрата глинистого раствора, которую геофизики обычно связывают с удельным сопротивлением фильтрата $\\rho_ф$", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c1"}, {"page_print": null, "text": "Минерализация фильтрата неоднозначно влияет на эффективность различных геофизических методов.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.02", "quote": "неоднозначно влияет на эффективность различных геофизических методов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c2"}, {"page_print": null, "text": "Для большинства районов наиболее типично бурение на пресном глинистом растворе, для которого ρф > ρп.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.02", "quote": "Наиболее типично для большинства районов бурение на пресном глинистом растворе ($\\rho_ф > \\rho_п$)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c3"}, {"page_print": null, "text": "При пресном растворе коллекторы и породы с низкой глинистостью выделяются отрицательными аномалиями на диаграмме СП.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.02", "quote": "для которого характерно выделение коллекторов и пород с низкой глинистостью отрицательными аномалиями на диаграмме СП", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c4"}, {"page_print": null, "text": "При пресном растворе коллекторы выделяются по положительным приращениям на диаграммах микрозондов.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.02", "quote": "и выделение коллекторов по положительным приращениям на диаграммах микрозондов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c5"}, {"page_print": null, "text": "С ростом минерализации раствора и приближением ρф к ρп эффективность методов СП и микрозондов как средств выделения коллектора резко снижается.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.02", "quote": "С ростом минерализации глинистого раствора и приближением величины $\\rho_ф$ к величине $\\rho_п$ резко снижается эффективность методов СП и микрозондов как средств выделения коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c6"}, {"page_print": null, "text": "При этом существенно уменьшается эффективность индукционного метода для изучения разреза в целом.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.02", "quote": "а также существенно уменьшается эффективность индукционного метода для изучения разреза в целом", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c7"}, {"page_print": null, "text": "Одновременно приближение ρф к ρп создаёт более благоприятные условия для оценки продуктивности коллектора по комплексу разноглубинных методов электрометрии.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.03", "quote": "Одновременно приближение $\\rho_ф$, к $\\rho_п$ создает более благоприятные условия для оценки продуктивности коллектора по комплексу разноглубинных методов электрометрии", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c8"}, {"page_print": null, "text": "При ρф = ρп в продуктивных коллекторах формируются зоны только понижающего проникновения (ρп < ρпп).", "kind": "observation", "page_pdf": 91, "unit_id": "p091.03", "quote": "поскольку при $\\rho_ф = \\rho_п$ в продуктивных коллекторах формируются зоны только понижающего проникновения ($\\rho_п < \\rho_пп$)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c9"}, {"page_print": null, "text": "При ρф = ρп в водоносных коллекторах ρп ≈ ρпп.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.03", "quote": "а в водоносных — $\\rho_п \\approx \\rho_пп$", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.filtrate_salinity#c10"}], "id": "latyshova.filtrate_salinity", "order": 4, "minutes": 2, "essence": "Минерализация фильтрата влияет на методы ГИС неоднозначно. Для одних задач она помогает, для других мешает. Чем ближе ρф к ρп, тем хуже работают СП, микрозонды и индукционный метод. Но тем лучше оценивается продуктивность по разноглубинной электрометрии.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Минерализацию фильтрата геофизики обычно выражают через удельное сопротивление фильтрата ρф. Чем выше минерализация, тем меньше сопротивление. Обычный случай — пресный раствор, у которого ρф больше ρп.", "pages": [91]}, {"text": "Тогда коллекторы и малоглинистые породы дают отрицательные аномалии на диаграмме СП. По микрозондам коллектор виден как положительное приращение. С ростом минерализации ρф приближается к ρп.", "pages": [91]}, {"text": "Эффективность СП и микрозондов резко падает, а индукционного метода заметно уменьшается. При ρф = ρп в продуктивных коллекторах возникают зоны только понижающего проникновения (ρп < ρпп). В водоносных коллекторах ρп ≈ ρпп.", "pages": [91]}, {"text": "Эта разница и позволяет судить о продуктивности.", "pages": [91]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Практический вывод в главе один: метод подбирают по соотношению ρф и ρп. Для выделения коллектора, пока раствор пресный, используют СП и микрозонды. Для оценки продуктивности при ρф около ρп используют комплекс разноглубинных методов электрометрии.", "pages": [91]}, {"text": "Пошаговой процедуры в этой части главы нет.", "pages": [91]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Влияние минерализации неоднозначно. Один и тот же сдвиг ρф ухудшает выделение коллектора, но улучшает оценку его продуктивности. Пресный раствор здесь определяется условием ρф > ρп.", "pages": [91]}, {"text": "Об ухудшении индукционного метода сказано только «для изучения разреза в целом». Символы ρп и ρпп в абзацах не расшифрованы. Их смысл надо уточнять по соседним параграфам главы.", "pages": [91]}]}], "deeper": [], "glossary": [{"term": "удельное сопротивление фильтрата ρф", "definition": "Электрическое сопротивление фильтрата глинистого раствора. Геофизики обычно связывают его с минерализацией фильтрата."}, {"term": "пресный раствор", "definition": "Глинистый раствор, у которого сопротивление фильтрата больше ρп (ρф > ρп). Для большинства районов это наиболее типичный случай."}, {"term": "повышающее проникновение", "definition": "Термин в этой части главы не раскрыт. Он противопоставлен понижающему проникновению, при котором ρп < ρпп."}, {"term": "понижающее проникновение", "definition": "Тип зоны проникновения, который по главе характеризуется условием ρп < ρпп. При ρф = ρп такие зоны формируются в продуктивных коллекторах."}], "format": "интерактив", "tasks": [{"id": "latyshova.filtrate_salinity.t1", "type": "single", "step_id": "latyshova.filtrate_salinity", "claim_ids": ["latyshova.filtrate_salinity#c6", "latyshova.filtrate_salinity#c8"], "prompt": "Скважину бурят на растворе, минерализация которого выросла настолько, что ρф стало близко к ρп. СП и микрозонды почти не выделяют коллектор. Чем оценивать продуктивность?", "options": [{"id": "a", "text": "Комплексом разноглубинных методов электрометрии", "misconception": null}, {"id": "b", "text": "Диаграммой СП: отрицательная аномалия при высокой минерализации становится контрастнее", "misconception": "misc.sp_improves_with_salinity"}, {"id": "c", "text": "Микрозондами: положительное приращение при ρф ≈ ρп проявляется заметнее", "misconception": "misc.microprobe_improves_with_salinity"}, {"id": "d", "text": "Одним индукционным методом: его эффективность при ρф ≈ ρп растёт", "misconception": "misc.induction_improves_with_salinity"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "При ρф ≈ ρп СП и микрозонды теряют эффективность, зато условия для оценки продуктивности по разноглубинной электрометрии лучше.", "kind": "transfer"}, {"id": "latyshova.filtrate_salinity.t2", "type": "multiple", "step_id": "latyshova.filtrate_salinity", "claim_ids": ["latyshova.filtrate_salinity#c9", "latyshova.filtrate_salinity#c10"], "prompt": "Скважина пробурена на растворе с ρф = ρп. По разноглубинной электрометрии в интервале A получено ρп < ρпп, а в интервале B ρп ≈ ρпп. Какие выводы верны? Выберите все верные варианты.", "options": [{"id": "a", "text": "Интервал A — продуктивный коллектор с зоной понижающего проникновения", "misconception": null}, {"id": "b", "text": "Интервал B — водоносный коллектор", "misconception": null}, {"id": "c", "text": "В интервале A проникновение только повышающее (ρп > ρпп)", "misconception": "misc.inverse_invasion"}, {"id": "d", "text": "Разделить A и B можно только по уверенной аномалии СП", "misconception": "misc.sp_needed_at_equal_resistivity"}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "При ρф = ρп продуктивный коллектор даёт ρп < ρпп, а водоносный ρп ≈ ρпп, и по этой разнице судят о продуктивности.", "kind": "data"}], "pictures": [{"id": "latyshova.filtrate_salinity.i1", "step_id": "latyshova.filtrate_salinity", "node_id": "latyshova.filtrate_salinity", "file": "pictures/filtrate_salinity_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Слева пресный раствор, справа ρф близко к ρп: одни методы теряют эффективность, а оценка продуктивности улучшается.", "alt": "Таблица: при пресном растворе СП и микрозонды выделяют коллекторы, при сближении ρф и ρп они теряют эффективность, зато продуктивность оценивается лучше.", "source": "построено кодом по утверждениям главы, стр. 91", "claim_ids": ["latyshova.filtrate_salinity#c3", "latyshova.filtrate_salinity#c4", "latyshova.filtrate_salinity#c5", "latyshova.filtrate_salinity#c6", "latyshova.filtrate_salinity#c7", "latyshova.filtrate_salinity#c8"], "prompt": null}]}, {"title": "Техническая вода и нефильтрующиеся растворы: чем они ограничивают набор методов", "short_title": "Вода и нефильтрующиеся растворы", "why_here": {"text": "Завершает обзор типов промывочных жидкостей и показывает, как тип раствора выбирает комплекс методов.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "М"}, "threshold": false, "pages": [91], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход: тип промывочной жидкости (вода или нефильтрующийся раствор) и состав разреза. Выход: допустимый набор методов ГИС. Для воды с глинами оценка насыщения, как правило, исключена. Для нефильтрующегося раствора применим индукционный зонд, ядерные и акустические методы. Столбцы и кривые в главе здесь не названы.", "by_model": true}, "breaks": {"text": "Вода: в глинистом разрезе из-за глубоких зон проникновения оценка насыщения исключена, микрозонд и каверномер малоэффективны. Нефильтрующийся раствор: нет глинистой корки, поэтому традиционные способы выделения коллектора не работают, а методы с электрическим контактом неприменимы.", "by_model": true}, "hypotheses": [{"text": "Вероятно, при выборе раствора заранее стоит определить, какие методы потребуются, и сверить их с типом раствора. В главе это прямо не сказано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Тип раствора похож на выбор формата хранилища: он определяет, какие запросы к данным вообще возможны. Нефильтрующийся раствор — как закрытый API без прямого доступа к базе: работают только запросы через разрешённый интерфейс.", "breaks_where": "В ИТ ограничение можно снять настройкой. Здесь тип раствора задан при бурении, и потерянную информацию задним числом не восстановить.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["тип промывочной жидкости: техническая вода или нефильтрующийся раствор", "наличие глин в разрезе", "наличие мощных пластов каменных и калийных солей"], "rule": "Вода при глинах в разрезе: оценка насыщения, как правило, исключена. Нефильтрующийся раствор: применимы только методы без электрического контакта, из электрометрии — индукционный зонд. Вода высокой минерализации оправдана только при мощных солях.", "conclusion": "Набор методов определяется типом раствора. При воде с глинами возможны невосполнимые потери информации о коллекторах.", "counterexample": "Бурение на воде не всегда вредно: при мощных пластах каменных и калийных солей воду высокой минерализации применяют, чтобы не растворять соли и не получать каверны."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["техническая вода как раствор", "нефильтрующийся раствор", "ИБР", "ВИЭР"], "links": [{"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.water_loss_and_mud_density"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Скважины, где большая часть разреза — плотные породы, бурят на воде. Её минерализация в зависимости от условий района меняется от низкой до минерализации пластовой воды.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.04", "quote": "Скважины, где большая часть разреза представлена плотными породами, бурятся на воде, минерализация которой в зависимости от конкретных условий района изменяется от низкой до минерализации пластовой воды.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c1"}, {"page_print": null, "text": "Если в разрезе есть глины и глинистые породы, при бурении на воде возникает подобие глинистого раствора с очень высокой водоотдачей.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.04", "quote": "Если в разрезе есть глины и глинистые породы, при бурении на воде возникает подобие глинистого раствора с очень высокой водоотдачей.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c2"}, {"page_print": null, "text": "Из-за образования глубоких зон проникновения оценка характера насыщения коллекторов геофизическими методами, как правило, исключена.", "kind": "inference", "page_pdf": 91, "unit_id": "p091.04", "quote": "В этом случае в связи с образованием глубоких зон проникновения оценка характера насыщения коллекторов геофизическими методами, как правило, исключена", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c3"}, {"page_print": null, "text": "Эффективность микрозондов и каверномера как средств выделения коллектора при бурении на воде крайне низка.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.04", "quote": "а эффективность микрозондов и каверномера как средств выделения коллектора крайне низка", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c4"}, {"page_print": null, "text": "Условия бурения на воде чрезвычайно неблагоприятны для изучения разреза геофизическими методами и могут привести к невосполнимым потерям информации, прежде всего о коллекторах.", "kind": "inference", "page_pdf": 91, "unit_id": "p091.04", "quote": "Очевидно, что такие условия бурения чрезвычайно неблагоприятны для изучения разреза геофизическими методами и могут привести к невосполнимым потерям информации, прежде всего о коллекторах.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c5"}, {"page_print": null, "text": "Бурение на воде высокой минерализации, близкой к насыщенному раствору, оправдано только при разрезе с мощными пластами каменных и калийных солей.", "kind": "inference", "page_pdf": 91, "unit_id": "p091.04", "quote": "Бурение на воде высокой минерализации, близкой к минерализации насыщенного раствора, оправдано только при наличии разреза с мощными пластами каменных и калийных солей", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c6"}, {"page_print": null, "text": "В этом случае предотвращается растворение солей и интенсивное кавернообразование, которое существенно снижает проходимость скважины геофизическими приборами.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.04", "quote": "поскольку в этом случае предотвращается растворение последних и интенсивное кавернообразование, существенно снижающее проходимость скважины геофизическими приборами.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c7"}, {"page_print": null, "text": "В последние годы при бурении всё чаще применяют нефильтрующиеся растворы в качестве промывочной жидкости.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.05", "quote": "Последние годы при бурении скважин все чаще применяют в качестве промывочной жидкости нефильтрующиеся растворы.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c8"}, {"page_print": null, "text": "Наиболее широко применяют растворы на непроводящей углеводородной основе: известково-битумные (ИБР) и инвертные водоэмульсионные (ВИЭР).", "kind": "observation", "page_pdf": 91, "unit_id": "p091.05", "quote": "Наиболее широкое применение получили растворы на непроводящей — углеводородной — основе: известково-битумные (ИБР) и инвертные водоэмульсионные (ВИЭР).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c9"}, {"page_print": null, "text": "Важнейшие особенности нефильтрующихся растворов для ГИС: огромное удельное сопротивление и отсутствие (или очень малое) проникновения в коллекторы.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.05", "quote": "Для ГИС важнейшими их особенностями являются огромное удельное сопротивление ($\\rho_п \\rightarrow \\infty$, $\\delta_p = 0$) и отсутствие (или очень малое) проникновения в коллекторы.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c10"}, {"page_print": null, "text": "Из этих особенностей вытекает ограничение: используют только те методы комплекса, где не требуется прямого электрического контакта с породой.", "kind": "inference", "page_pdf": 91, "unit_id": "p091.05", "quote": "Из этих особенностей растворов вытекают ограничения использования геофизического комплекса методов только теми, где не требуется прямого электрического контакта с породой.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c11"}, {"page_print": null, "text": "Из методов электрометрии при нефильтрующемся растворе применим только индукционный зонд.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.05", "quote": "Из методов электрометрии применим только индукционный зонд.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c12"}, {"page_print": null, "text": "Из-за отсутствия глинистых корок традиционные методы выделения коллекторов использовать нельзя.", "kind": "inference", "page_pdf": 91, "unit_id": "p091.05", "quote": "Отсутствие глинистых корок не позволяет использовать традиционные методы выделения коллекторов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c13"}, {"page_print": null, "text": "При нефильтрующемся растворе благоприятны условия для изучения характера насыщения коллекторов методами средней и малой глубинности, например ядерными и акустическими.", "kind": "inference", "page_pdf": 91, "unit_id": "p091.05", "quote": "В то же время создаются благоприятные условия для изучения характера насыщения последних геофизическими методами средней и малой глубинности (например, ядерными и акустическими).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.water_and_nonfiltering_muds#c14"}], "id": "latyshova.water_and_nonfiltering_muds", "order": 5, "minutes": 3, "essence": "Бурение на технической воде при наличии глин даёт глубокие зоны проникновения. Из-за этого характер насыщения коллекторов по ГИС, как правило, оценить нельзя. Нефильтрующиеся растворы на углеводородной основе не дают проникновения, но они не проводят ток. Поэтому остаются методы без электрического контакта с породой, а выделять коллекторы по глинистой корке нельзя.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Техническая вода в глинистом разрезе ведёт себя как глинистый раствор с очень высокой водоотдачей. Водоотдача — это количество жидкости, уходящее из раствора в пласт. Фильтрат уходит глубоко, и зона проникновения становится глубокой.", "pages": [91]}, {"text": "Нефильтрующийся раствор устроен иначе. Его сопротивление стремится к бесконечности, а проникновение в коллектор равно нулю или очень мало. Корка не образуется, потому что нечему фильтроваться.", "pages": [91]}, {"text": "Раствор не проводит ток, поэтому методы, которым нужен электрический контакт со стенкой, не работают.", "pages": [91]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Скважину на воде бурят, если большая часть разреза — плотные породы. Минерализация воды зависит от района: от низкой до минерализации пластовой воды. Воду высокой минерализации, близкой к насыщенному раствору, берут только при мощных пластах каменной и калийной соли.", "pages": [91]}, {"text": "Так соль не растворяется, и каверн меньше. При нефильтрующемся растворе из электрометрии остаётся индукционный зонд. Насыщение изучают методами средней и малой глубинности, например ядерными и акустическими.", "pages": [91]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Вода не всегда плоха: на ней бурят там, где разрез плотный, и воду высокой минерализации выбирают ради солей. Но при глинах потери информации о коллекторах могут быть невосполнимыми. Микрозонд — прибор с малой глубиной исследования, он ищет коллектор по глинистой корке.", "pages": [91]}, {"text": "Каверномер измеряет диаметр скважины. В воде оба метода почти бесполезны, а в нефильтрующемся растворе корки нет совсем. Индукционный зонд работает без контакта с породой, поэтому остаётся применимым.", "pages": [91]}, {"text": "Нефильтрующийся раствор плох для одних задач и хорош для других: выделение коллектора затруднено, изучение насыщения облегчено.", "pages": [91]}]}], "deeper": [{"text": "В тексте отдельно названы две разновидности нефильтрующихся растворов: ИБР и ВИЭР. Обе на углеводородной основе. Для ГИС важны две их особенности: огромное сопротивление и отсутствие проникновения. Из них автор выводит ограничения комплекса. Сопротивление фильтрата для таких растворов не вводится, так как фильтрата нет.", "pages": [91]}], "glossary": [{"term": "техническая вода как раствор", "definition": "Вода, которую используют вместо глинистого раствора как промывочную жидкость. Её минерализация меняется от низкой до минерализации пластовой воды. При глинах в разрезе она ведёт себя как раствор с очень высокой водоотдачей."}, {"term": "нефильтрующийся раствор", "definition": "Промывочная жидкость с огромным удельным сопротивлением, которая не проникает (или почти не проникает) в коллекторы и не образует глинистой корки."}, {"term": "ИБР", "definition": "Известково-битумный раствор: нефильтрующийся раствор на непроводящей углеводородной основе."}, {"term": "ВИЭР", "definition": "Инвертный водоэмульсионный раствор: нефильтрующийся раствор на непроводящей углеводородной основе."}], "format": "карточки", "tasks": [{"id": "latyshova.water_and_nonfiltering_muds.t1", "type": "single", "step_id": "latyshova.water_and_nonfiltering_muds", "claim_ids": ["latyshova.water_and_nonfiltering_muds#c2", "latyshova.water_and_nonfiltering_muds#c3"], "prompt": "Скважину в разрезе с глинами бурят на технической воде. Почему по данным ГИС, как правило, нельзя оценить характер насыщения коллекторов?", "options": [{"id": "a", "text": "Вода с глинами даёт раствор с очень высокой водоотдачей, и возникают глубокие зоны проникновения", "misconception": null}, {"id": "b", "text": "Вода образует толстую глинистую корку, которая экранирует пласт от приборов", "misconception": "misc.water_crust"}, {"id": "c", "text": "Вода имеет бесконечно большое сопротивление и не пропускает ток к породе", "misconception": "misc.water_nonconductive"}, {"id": "d", "text": "Вода растворяет соли и даёт каверны, из-за которых приборы не проходят", "misconception": "misc.water_salt_caverns"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "В глинистом разрезе техническая вода ведёт себя как раствор с очень высокой водоотдачей, фильтрат уходит глубоко и зона проникновения становится глубокой.", "kind": "understanding"}, {"id": "latyshova.water_and_nonfiltering_muds.t2", "type": "multiple", "step_id": "latyshova.water_and_nonfiltering_muds", "claim_ids": ["latyshova.water_and_nonfiltering_muds#c10", "latyshova.water_and_nonfiltering_muds#c12", "latyshova.water_and_nonfiltering_muds#c13"], "prompt": "Скважина пробурена на нефильтрующемся растворе на углеводородной основе. Какие утверждения верны?", "options": [{"id": "a", "text": "Из электрометрии применим индукционный зонд", "misconception": null}, {"id": "b", "text": "Коллекторы нельзя выделять по глинистой корке, потому что корки нет", "misconception": null}, {"id": "c", "text": "Микрозонды работают лучше, чем на глинистом растворе, так как проникновения нет", "misconception": "misc.microprobe_nonfilter"}, {"id": "d", "text": "Любые методы электрометрии применимы, поскольку раствор имеет огромное сопротивление", "misconception": "misc.high_resistivity_any_method"}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "Раствор не проводит ток и не образует корку, поэтому остаются методы без электрического контакта, например индукционный зонд.", "kind": "understanding"}, {"id": "latyshova.water_and_nonfiltering_muds.t3", "type": "gap", "step_id": "latyshova.water_and_nonfiltering_muds", "claim_ids": ["latyshova.water_and_nonfiltering_muds#c6", "latyshova.water_and_nonfiltering_muds#c7"], "prompt": "Воду высокой минерализации, близкой к насыщенному раствору, применяют только при {{1}} пластах каменных и калийных солей: так соли не {{2}}, и меньше образуется каверн.", "options": [], "answer": ["мощных", "растворяются"], "tolerance": null, "unit": null, "explanation": "Насыщенная вода не растворяет соль, что предотвращает кавернообразование, поэтому она оправдана лишь при мощных солях.", "kind": "recall"}], "pictures": [{"id": "latyshova.water_and_nonfiltering_muds.i1", "step_id": "latyshova.water_and_nonfiltering_muds", "node_id": "latyshova.water_and_nonfiltering_muds", "file": "pictures/water_and_nonfiltering_muds_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Два типа промывки рядом: в воде фильтрат уходит глубоко и мешает оценке, нефильтрующийся раствор почти не проникает, но корки нет.", "alt": "Таблица из двух столбцов: бурение на воде и нефильтрующийся раствор. Сравниваются проникновение, выделение коллекторов и оценка характера насыщения.", "source": "построено кодом по утверждениям главы, стр. 91", "claim_ids": ["latyshova.water_and_nonfiltering_muds#c3", "latyshova.water_and_nonfiltering_muds#c4", "latyshova.water_and_nonfiltering_muds#c10", "latyshova.water_and_nonfiltering_muds#c13", "latyshova.water_and_nonfiltering_muds#c14"], "prompt": null}]}, {"title": "Типы разрезов и типы коллекторов по составу и строению порового пространства", "short_title": "Типы разрезов и коллекторов", "why_here": {"text": "После условий бурения вводит классификацию объектов; дальше признаки и методы привязываются к типу разреза и коллектора.", "by_model": true}, "difficulty": {"primary": "Р", "secondary": "П"}, "threshold": true, "pages": [91], "misconception": {"ref": "misc.reservoir_void", "text": "Шаг показывает, что коллектор — это порода с порами разного строения: межзерновыми, трещинами, кавернами. Только в карстовых коллекторах встречаются крупные пустоты и полости выщелачивания.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "В этой части главы нет данных, кривых и столбцов. Дана только словесная классификация разрезов и коллекторов.", "by_model": true}, "breaks": {"text": "Классификация неоднозначна для смешанных разрезов и смешанных коллекторов: один объект может сочетать несколько типов. Вулканогенные породы по составу похожи на терригенные, а по порам — на карбонатные.", "by_model": true}, "hypotheses": [{"text": "Тип разреза и коллектора, видимо, задаёт набор признаков и методов, которые применяют к объекту. В этой части главы это не показано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это как классификация хранилищ данных: сначала тип системы, затем схема таблиц внутри неё. Тип разреза — тип системы, тип коллектора — схема хранения.", "breaks_where": "Типы пород не исключают друг друга: смешанные разрезы и коллекторы сочетают несколько типов сразу, а типы системы обычно чётко разделены.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["терригенный разрез", "карбонатный разрез", "гидрохимический разрез", "межзерновой коллектор", "трещинный коллектор", "кавернозно-трещинный коллектор", "рассеянная глинистость", "слоистая глинистость", "гнездовидная глинистость"], "links": [{"type": "prerequisite", "target": "latyshova.goals_of_log_interpretation"}, {"type": "refutes_misconception", "target": "misc.reservoir_void"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Основными типами разреза считают терригенный, карбонатный и гидрохимический.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.07", "quote": "В качестве основных типов разреза рассматривают терригенный, карбонатный и гидрохимический.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c1"}, {"page_print": null, "text": "Встречаются разрезы смешанного типа: терригенно-карбонатные, карбонатно-гидрохимические, терригенно-гидрохимические.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.07", "quote": "Кроме того, встречаются разрезы смешанного типа: терригенно-карбонатные; карбонатно-гидрохимические; терригенно-гидрохимические;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c2"}, {"page_print": null, "text": "Вулканогенные разрезы по вещественному составу близки к терригенным, а по структуре порового пространства коллекторов — к карбонатным, за исключением карстовых образований.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.07", "quote": "вулканогенные, которые по вещественному составу близки к терригенным, а по структуре порового пространства коллекторов — к карбонатным (за исключением карстовых образований).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c3"}, {"page_print": null, "text": "По морфологии порового пространства коллекторы делят на межзерновые, трещинные, кавернозно-трещинные и смешанные типы.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.08", "quote": "По морфологии порового пространства коллекторы разделяют на межзерновые, трещинные, кавернозно-трещинные и смешанные типы.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c4"}, {"page_print": null, "text": "Среди смешанных коллекторов выделяют трещинно-межзерновые, кавернозно-межзерново-трещинные, карстово-кавернозные и другие.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.08", "quote": "В последнем в свою очередь, выделяют трещинно-межзерновые, кавернозно-межзерново-трещинные, карстово-кавернозные и т.д.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c5"}, {"page_print": null, "text": "В терригенном разрезе преобладают межзерновые коллекторы. В карбонатном наряду с межзерновыми преобладают кавернозно-трещинные и смешанные.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.08", "quote": "В терригенном разрезе преобладают межзерновые коллекторы, в карбонатном наряду с межзерновыми - кавернозно-трещинные и смешанные.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c6"}, {"page_print": null, "text": "С геофизической точки зрения межзерновые коллекторы терригенного разреза делят на высокопористые и низкопористые, а также на чистые (слабоглинистые) и глинистые.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.09", "quote": "С геофизической точки зрения в терригенном разрезе среди межзерновых коллекторов выделяют высокопористые и низкопористые; чистые (слабоглинистые) и глинистые.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c7"}, {"page_print": null, "text": "Глинистые коллекторы делят по характеру распределения глинистого материала на коллекторы с рассеянной, слоистой и гнездовидной глинистостью.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.09", "quote": "Последние в свою очередь разделяют по характеру распределения глинистого материала на коллекторы с рассеянной, слоистой и гнездовидной глинистостью.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c8"}, {"page_print": null, "text": "Особую группу межзерновых коллекторов составляют породы с неактивным (карбонатным или силикатным) цементом.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.09", "quote": "Особую группу межзерновых коллекторов составляют породы с неактивным (карбонатным или силикатным) цементом.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c9"}, {"page_print": null, "text": "В карбонатном разрезе различают высокопористые и низкопористые межзерновые коллекторы.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.09", "quote": "В карбонатном разрезе различают высокопористые и низкопористые межзерновые коллекторы.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c10"}, {"page_print": null, "text": "Высокопористые карбонатные коллекторы часто бывают смешанного типа, со значительной долей вторичных пор выщелачивания, перекристаллизации и т.д.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.09", "quote": "Высокопористые коллекторы часто бывают смешанного типа с присутствием значительной доли вторичных пор выщелачивания, перекристаллизации и т.д.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c11"}, {"page_print": null, "text": "Особую группу составляют высокопродуктивные трещинно-кавернозно-межзерновые коллекторы с крупными пустотами и полостями выщелачивания карстового типа.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.09", "quote": "Особую группу составляют высокопродуктивные трещинно-кавернозно-межзерновые коллекторы с наличием крупных пустот и полостей выщелачивания карстового типа.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c12"}, {"page_print": null, "text": "Трещинные коллекторы встречаются в карбонатных, терригенных и вулканогенных породах.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.09", "quote": "Трещинные коллекторы встречаются в карбонатных, терригенных и вулканогенных породах.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.section_and_collector_types#c13"}], "id": "latyshova.section_and_collector_types", "order": 6, "minutes": 2, "essence": "Разрезы делят на терригенный, карбонатный и гидрохимический, а также на смешанные типы. Коллекторы делят по морфологии пор: межзерновые, трещинные, кавернозно-трещинные и смешанные. В терригенном разрезе преобладают межзерновые коллекторы, в карбонатном рядом с ними часто встречаются кавернозно-трещинные и смешанные.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Классификация идёт в два шага. Сначала определяют тип разреза по составу пород. Затем внутри разреза определяют тип коллектора по тому, как устроены его пустоты.", "pages": [91]}, {"text": "Межзерновые коллекторы делят дальше по пористости и глинистости. Глинистые коллекторы делят по распределению глины: рассеянная, слоистая или гнездовидная. Для карбонатного разреза в главе различают высоко- и низкопористые межзерновые коллекторы.", "pages": [91]}, {"text": "Высокопористые из них часто смешанные: к первичным порам добавляются вторичные поры выщелачивания и перекристаллизации.", "pages": [91]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "В этих параграфах способов определения типа по диаграммам нет, дана только классификация. Её нужно знать, чтобы по типу разреза и коллектора выбирать признаки выделения коллекторов и методы оценки.", "pages": [91]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Вулканогенные разрезы по составу близки к терригенным, а по строению пор коллекторов — к карбонатным, кроме карстовых образований. Трещинные коллекторы встречаются не только в карбонатных, но и в терригенных и вулканогенных породах. Отдельную группу межзерновых коллекторов образуют породы с неактивным цементом, карбонатным или силикатным.", "pages": [91]}, {"text": "Отдельную группу составляют и высокопродуктивные трещинно-кавернозно-межзерновые коллекторы с крупными карстовыми полостями.", "pages": [91]}]}], "deeper": [{"text": "Глава называет типы глинистости, но не объясняет, чем они различаются по влиянию на диаграммы. Гидрохимический разрез в этой части главы тоже не расшифрован. Для него в глоссарии дано пояснение модели.", "pages": [91]}], "glossary": [{"term": "терригенный разрезе", "definition": "Разрез, сложенный обломочными породами (пески, песчаники, алевролиты, глины). В нём преобладают межзерновые коллекторы."}, {"term": "карбонатный разрез", "definition": "Разрез из карбонатных пород, таких как известняки и доломиты. В нём наряду с межзерновыми коллекторами преобладают кавернозно-трещинные и смешанные."}, {"term": "гидрохимический разрез", "definition": "Разрез из химических осадков, например солей и ангидритов. Пояснение модели: в главе термин не раскрыт."}, {"term": "межзерновой коллектор", "definition": "Коллектор, у которого поровое пространство — промежутки между зёрнами породы."}, {"term": "трещинный коллектор", "definition": "Коллектор, у которого поровое пространство образовано трещинами. Встречается в карбонатных, терригенных и вулканогенных породах."}, {"term": "кавернозно-трещинный коллектор", "definition": "Коллектор с пустотами двух видов — кавернами и трещинами. Встречается в карбонатном разрезе наряду с межзерновыми."}, {"term": "рассеянная глинистость", "definition": "Тип глинистого коллектора, где глинистый материал распределён по породе рассеянно. Пояснение модели по названию: в главе не раскрыто."}, {"term": "слоистая глинистость", "definition": "Тип глинистого коллектора, где глинистый материал образует слои. Пояснение модели по названию: в главе не раскрыто."}, {"term": "гнездовидная глинистость", "definition": "Тип глинистого коллектора, где глинистый материал собран в гнёзда. Пояснение модели по названию: в главе не раскрыто."}], "format": "карточки", "tasks": [{"id": "latyshova.section_and_collector_types.t1", "type": "single", "step_id": "latyshova.section_and_collector_types", "claim_ids": ["latyshova.section_and_collector_types#c6", "latyshova.section_and_collector_types#c4"], "prompt": "В каком разрезе наряду с межзерновыми коллекторами преобладают кавернозно-трещинные и смешанные?", "options": [{"id": "a", "text": "В карбонатном", "misconception": null}, {"id": "b", "text": "В терригенном", "misconception": "misc.terrigenous_cavern"}, {"id": "c", "text": "Только в гидрохимическом", "misconception": "misc.hydrochemical"}, {"id": "d", "text": "В любом разрезе в равной мере", "misconception": "misc.all_equal"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "В терригенном разрезе преобладают межзерновые коллекторы, а в карбонатном к ним добавляются кавернозно-трещинные и смешанные.", "kind": "recall"}, {"id": "latyshova.section_and_collector_types.t2", "type": "order", "step_id": "latyshova.section_and_collector_types", "claim_ids": ["latyshova.section_and_collector_types#c1", "latyshova.section_and_collector_types#c4", "latyshova.section_and_collector_types#c7", "latyshova.section_and_collector_types#c8"], "prompt": "Расположите шаги классификации терригенного коллектора в порядке от общего к частному.", "options": [{"id": "a", "text": "Глинистый коллектор делят по распределению глины: рассеянная, слоистая, гнездовидная", "misconception": null}, {"id": "b", "text": "Межзерновой коллектор делят на высоко- и низкопористые, чистые и глинистые", "misconception": null}, {"id": "c", "text": "Определяют тип разреза по составу пород: терригенный", "misconception": null}, {"id": "d", "text": "Определяют тип коллектора по морфологии пор: межзерновой", "misconception": null}], "answer": ["c", "d", "b", "a"], "tolerance": null, "unit": null, "explanation": "Сначала определяют тип разреза, затем тип коллектора по порам, затем делят межзерновые по пористости и глинистости, а глинистые по распределению глины.", "kind": "understanding"}], "pictures": [{"id": "latyshova.section_and_collector_types.i1", "step_id": "latyshova.section_and_collector_types", "node_id": "latyshova.section_and_collector_types", "file": "pictures/section_and_collector_types_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Сравнение терригенного и карбонатного разрезов по типам коллекторов: смотрите, какие поры преобладают в каждом.", "alt": "Таблица сравнения терригенного и карбонатного разрезов: преобладающие типы коллекторов, деление межзерновых коллекторов и особенности высокопористых.", "source": "построено кодом по утверждениям главы, стр. 91", "claim_ids": ["latyshova.section_and_collector_types#c6", "latyshova.section_and_collector_types#c7", "latyshova.section_and_collector_types#c10", "latyshova.section_and_collector_types#c11"], "prompt": null}]}, {"title": "Четыре группы методов комплекса: выделение коллекторов, пористость, глинистость, продуктивность", "short_title": "Четыре группы методов", "why_here": {"text": "Опирается на типы коллекторов и корку; разделяет методы по решаемым задачам, чтобы потом сопоставлять их диаграммы.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "Р"}, "threshold": true, "pages": [91, 92], "misconception": {"ref": "misc.gr_measures_clay", "text": "В главе ГМ отнесён к методам глинистости: он дифференцирует разрез по kг и kн. Это не значит, что прибор напрямую измеряет глинистость. Метод даёт отклик по естественной радиоактивности, а kг выводят из него. Этот вывод — пояснение модели, в этой части главы прямо не сказан.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Каждая группа методов отвечает на свой вопрос. Группа коллекторов выделяет фильтрующие интервалы или породы с эффективной пористостью. Группа пористости определяет пористость. Группа глинистости различает пласты по ηг, ηн, kг, kн. Какие именно кривые и столбцы получаются, в этой части главы не сказано.", "by_model": true}, "breaks": {"text": "СП ограничен глинистым раствором или водой при ρф > ρн. Методы выделения коллекторов по корке привязаны к глинистому раствору. ГМ и методы пористости работают в более широком наборе условий.", "by_model": true}, "hypotheses": [{"text": "Если глинистой корки нет (например, при нефильтрующемся растворе), признак корки для первой группы, видимо, недоступен. В единицах это прямо не сказано.", "by_model": true, "hypothesis": true}, {"text": "ρн, вероятно, — удельное сопротивление пластовой воды. В единицах обозначение не расшифровано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это набор проверок в CI-пайплайне: у каждой группы свой вопрос (есть ли коллектор, какая пористость, какая глинистость), и часть проверок запускается только в подходящем окружении.", "breaks_where": "Проверки в CI дают чёткий результат «прошёл/не прошёл». Методы ГИС дают косвенные измерения, и результат зависит от среды (раствор, обсадка, ρф и ρн).", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["тип промывочной жидкости (глинистый раствор, техническая вода, нефильтрующийся раствор)", "соотношение ρф и ρн", "скважина обсаженная или необсаженная", "тип разреза (терригенный или карбонатный)"], "rule": "ГМ применим во всех скважинах. Методы пористости применимы при любом из трёх типов раствора. СП применим на глинистом растворе или воде при ρф > ρн. Микрозонды и каверномер выделяют коллекторы по глинистой корке, которая образуется при бурении на глинистом растворе.", "conclusion": "Набор методов зависит от условий скважины. Нужно сначала проверить тип раствора и соотношение ρф и ρн, а потом выбирать метод. Для терригенного разреза мера — глинистость, для карбонатного — нерастворимый остаток.", "counterexample": "Если условие ρф > ρн не выполнено, в главе нет гарантии применимости СП. ГМ при этом остаётся применимым, поскольку не зависит от типа раствора."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["микрозонды", "каверномер", "ядерно-магнитный метод (ЯМ)", "относительная глинистость ηг", "объёмная глинистость kг", "нерастворимый остаток"], "links": [{"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.water_and_nonfiltering_muds"}, {"type": "prerequisite", "target": "latyshova.filtrate_salinity"}, {"type": "refutes_misconception", "target": "misc.gr_measures_clay"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Современный стандартный комплекс геофизических методов для изучения разрезов скважин включает методы очень разной физической сущности.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.10", "quote": "Современный стандартный комплекс геофизических методов, используемых для изучения разрезов скважин при большом разнообразии их физической сущности", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c1"}, {"page_print": null, "text": "По характеру решаемых задач методы комплекса делятся на четыре группы: выделение коллекторов (межзерновых), определение пористости, определение глинистости, оценка продуктивности.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.10", "quote": "по характеру решаемых задач можно разделить на группы методов: 1) выделения коллекторов (межзерновых); 2) определения пористости; 3) определения глинистости; 4) оценки продуктивности.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c2"}, {"page_print": null, "text": "В группу выделения коллекторов входят микрозонды и каверномер; они позволяют установить в разрезе фильтрующие интервалы.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.10", "quote": "В первую группу входят микрозонды и каверномер, позволяющие установить в разрезах скважин фильтрующие интервалы", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c3"}, {"page_print": null, "text": "Фильтрующие интервалы — это коллекторы с межзерновой пористостью, на которых при бурении на глинистом растворе образуется глинистая корка.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.10", "quote": "коллекторы с межзерновой пористостью, на которых образуется глинистая корка при бурении на глинистом растворе", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c4"}, {"page_print": null, "text": "К группе выделения коллекторов относится и ядерно-магнитный метод, который выделяет в разрезе породы с эффективной пористостью.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.10", "quote": "К этой же группе относится ядерно-магнитный метод, выделяющий в разрезе породы с эффективной пористостью.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c5"}, {"page_print": null, "text": "Группу методов пористости составляют гамма-гамма-метод, акустический и нейтронные методы.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.10", "quote": "Группу методов пористости составляют гамма-гамма-метод, акустический и нейтронные методы", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c6"}, {"page_print": null, "text": "Методы пористости в одинаковой степени применимы в скважинах на глинистом растворе, технической воде и нефильтрующихся растворах.", "kind": "observation", "page_pdf": 91, "unit_id": "p091.10", "quote": "они в одинаковой степени применимы в скважинах, бурящихся на глинистом растворе, технической воде и нефильтрующихся растворах.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c7"}, {"page_print": null, "text": "К методам глинистости относятся методы собственных потенциалов (СП) и естественной радиоактивности (ГМ).", "kind": "observation", "page_pdf": 91, "unit_id": "p091.10", "quote": "К методам глинистости относятся методы собственных потенциалов (СП) и естественной радиоактивности (ГМ).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c8"}, {"page_print": null, "text": "Метод СП дифференцирует терригенный разрез по относительной глинистости ηг, а карбонатный — по относительному содержанию нерастворимого остатка ηн.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.01", "quote": "Метод СП дифференцирует терригенный разрез по относительной глинистости ηг, карбонатный – по относительному содержанию нерастворимого остатка ηн;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c9"}, {"page_print": null, "text": "Метод СП применим в скважинах, бурящихся на глинистом растворе и на воде, при условии ρф > ρн.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.01", "quote": "он применим в скважинах, бурящихся на глинистом растворе и воде при ρф > ρн.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c10"}, {"page_print": null, "text": "Гамма-метод дифференцирует терригенный разрез по объёмной глинистости kг, а карбонатный — по объёмному содержанию нерастворимого остатка kн.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.02", "quote": "Гамма-метод дифференцирует терригенный разрез по объемной глинистости kг, карбонатный - по объемному содержанию нерастворимого остатка kн;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c11"}, {"page_print": null, "text": "ГМ применим во всех скважинах независимо от типа раствора, как в обсаженных, так и в необсаженных.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.02", "quote": "ГМ применим во всех скважинах, независимо от типа раствора, обсаженных и необсаженных.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.four_method_groups#c12"}], "id": "latyshova.four_method_groups", "order": 7, "minutes": 3, "essence": "Методы комплекса делятся на четыре группы: выделение межзерновых коллекторов, определение пористости, определение глинистости и оценка продуктивности. Первая группа — микрозонды, каверномер и ядерно-магнитный метод. Группа пористости — гамма-гамма, акустический и нейтронные методы. Группа глинистости — СП и ГМ. Группы различаются и по условиям применимости: тип раствора, обсадка, соотношение ρф и ρн.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Микрозонды и каверномер ищут фильтрующие интервалы: на межзерновых коллекторах при бурении на глинистом растворе образуется глинистая корка. Это признак проницаемого пласта. Ядерно-магнитный метод выделяет породы с эффективной пористостью.", "pages": [91]}, {"text": "Методы пористости (гамма-гамма, акустический, нейтронные) не привязаны к корке и работают при любом из трёх типов раствора. Методы глинистости различают пласты по составу: СП даёт относительные величины ηг и ηн, ГМ — объёмные kг и kн. Как именно прибор получает отклик, в этой части главы не описано.", "pages": [91]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "На практике метод выбирают по условиям скважины. Для выделения коллекторов нужен глинистый раствор, при котором образуется корка. Для пористости подходят глинистый раствор, техническая вода и нефильтрующиеся растворы.", "pages": [91, 92]}, {"text": "СП требует глинистого раствора или воды при ρф > ρн. ГМ можно использовать в любой скважине: с любым раствором, обсаженной или необсаженной.", "pages": [91, 92]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Четвёртая группа, оценка продуктивности, названа, но её методы в этой части главы не перечислены. СП и ГМ дифференцируют разрез по двум разным мерам: относительной (ηг, ηн) и объёмной (kг, kн). Для терригенного разреза мера — глинистость, для карбонатного — нерастворимый остаток.", "pages": [92]}, {"text": "Условие ρф > ρн относится к СП, у ГМ такого ограничения нет. Расшифровка ρн в этой части главы не дана.", "pages": [91, 92]}]}], "deeper": [{"text": "Автор подчёркивает, что методы комплекса очень разнообразны по физической сущности. Объединяет их решаемая задача, а не физический принцип. Поэтому в одной группе соседствуют разные приборы: в первой — микрозонды, каверномер и ядерно-магнитный метод. Первая группа относится именно к межзерновым коллекторам.", "pages": [91]}], "glossary": [{"term": "микрозонды", "definition": "Методы, которые вместе с каверномером позволяют выделить в разрезе фильтрующие интервалы — межзерновые коллекторы, на которых при бурении на глинистом растворе образуется глинистая корка. Устройство прибора в главе здесь не описано."}, {"term": "каверномер", "definition": "Прибор из группы выделения коллекторов; вместе с микрозондами помогает установить фильтрующие интервалы. Он измеряет диаметр скважины."}, {"term": "ядерно-магнитный метод (ЯМ)", "definition": "Метод из группы выделения коллекторов, который выделяет в разрезе породы с эффективной пористостью."}, {"term": "относительная глинистость ηг", "definition": "Мера глинистости терригенного разреза, по которой метод СП разделяет пласты. Это относительная величина; для карбонатного разреза аналог — ηн."}, {"term": "объёмная глинистость kг", "definition": "Мера глинистости терригенного разреза, по которой ГМ разделяет пласты. Это доля глины по объёму; для карбонатного разреза аналог — kн."}, {"term": "нерастворимый остаток", "definition": "Часть карбонатной породы, не растворяющаяся в кислоте. Служит мерой «неочищенности» карбонатного разреза: в относительной форме ηн (СП), в объёмной kн (ГМ)."}], "format": "карточки", "tasks": [{"id": "latyshova.four_method_groups.t1", "type": "single", "step_id": "latyshova.four_method_groups", "claim_ids": ["latyshova.four_method_groups#c3", "latyshova.four_method_groups#c4"], "prompt": "Скважину бурят на нефильтрующемся растворе. Почему микрозонды и каверномер здесь не позволят выделить фильтрующие интервалы?", "options": [{"id": "a", "text": "Корка образуется только при бурении на глинистом растворе, а нефильтрующийся раствор её не даёт", "misconception": null}, {"id": "b", "text": "Эти методы применимы только в обсаженных скважинах", "misconception": "misc.cased_only"}, {"id": "c", "text": "Эти методы определяют глинистость, а не фильтрацию", "misconception": "misc.wrong_group"}, {"id": "d", "text": "Они работают только при условии ρф > ρн", "misconception": "misc.rho_condition"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Микрозонды и каверномер находят фильтрующие интервалы по глинистой корке, которая возникает на глинистом растворе.", "kind": "transfer"}, {"id": "latyshova.four_method_groups.t2", "type": "multiple", "step_id": "latyshova.four_method_groups", "claim_ids": ["latyshova.four_method_groups#c7", "latyshova.four_method_groups#c10", "latyshova.four_method_groups#c12"], "prompt": "Скважина пробурена на нефильтрующемся растворе, обсадки нет. Какие методы по описанным условиям применимы?", "options": [{"id": "a", "text": "Гамма-метод (ГМ)", "misconception": null}, {"id": "b", "text": "Акустический метод пористости", "misconception": null}, {"id": "c", "text": "Метод СП", "misconception": "misc.sp_any_mud"}, {"id": "d", "text": "Микрозонды для выделения коллекторов по корке", "misconception": "misc.microprobe_nonfilter"}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "ГМ применим в любой скважине, методы пористости работают при любом растворе, а СП требует глинистого раствора или воды.", "kind": "transfer"}, {"id": "latyshova.four_method_groups.t3", "type": "gap", "step_id": "latyshova.four_method_groups", "claim_ids": ["latyshova.four_method_groups#c9", "latyshova.four_method_groups#c11"], "prompt": "Метод СП дифференцирует терригенный разрез по относительной глинистости {{1}}, а гамма-метод — по объёмной глинистости {{2}}.", "options": [], "answer": ["ηг", "kг"], "tolerance": null, "unit": null, "explanation": "СП даёт относительные величины ηг и ηн, а ГМ даёт объёмные kг и kн.", "kind": "recall"}], "pictures": [{"id": "latyshova.four_method_groups.i1", "step_id": "latyshova.four_method_groups", "node_id": "latyshova.four_method_groups", "file": "pictures/four_method_groups_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Три из четырёх групп методов и условия их применимости. Четвёртая группа, оценка продуктивности, здесь не показана.", "alt": "Таблица: группы методов выделения коллекторов, пористости и глинистости, их методы и условия применения.", "source": "построено кодом по утверждениям главы, стр. 91, 92", "claim_ids": ["latyshova.four_method_groups#c2", "latyshova.four_method_groups#c3", "latyshova.four_method_groups#c4", "latyshova.four_method_groups#c5", "latyshova.four_method_groups#c6", "latyshova.four_method_groups#c7", "latyshova.four_method_groups#c8", "latyshova.four_method_groups#c10", "latyshova.four_method_groups#c12"], "prompt": null}]}, {"title": "Параметр насыщения Pн как главный петрофизический признак продуктивности", "short_title": "Параметр насыщения Pн", "why_here": {"text": "Опирается на методы сопротивления и пористости; на Pн строятся все дальнейшие оценки характера насыщения.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "И"}, "threshold": true, "pages": [92], "misconception": {"ref": "misc.high_res_oil", "text": "Высокое сопротивление само по себе не означает нефть. Признаком служит отношение сопротивления неизменённой части пласта к сопротивлению того же пласта при водонасыщении: нефтегазоносной считается порода с Pн больше единицы.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: сопротивление неизменённой части пласта ρп по зондам с разными радиусами исследования, данные пористости и удельное сопротивление воды. Выход: Pн как отношение ρп к сопротивлению водонасыщенного пласта; значение больше единицы указывает на нефте- или газосодержащую породу.", "by_model": true}, "breaks": {"text": "Если ρп только оценивается при качественной интерпретации, Pн получается приблизительным. Pн нельзя оценить без пористости и без известного сопротивления воды.", "by_model": true}, "hypotheses": [{"text": "Вероятно, ρвп растёт при уменьшении пористости или при пресной пластовой воде, и тогда Pн меняется при том же ρп. В главе это не разобрано.", "by_model": true, "hypothesis": true}, {"text": "Вероятно, значение Pн чуть выше единицы можно спутать с водонасыщенным пластом из-за погрешностей ρп и ρвп. Пороги в главе не даны.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Pн похож на коэффициент аномальности в мониторинге: наблюдаемое значение делят на базовое значение для здорового состояния. Значение больше единицы сигнализирует об отклонении.", "breaks_where": "Базовый уровень в каротаже не измеряют напрямую, а вычисляют по пористости и сопротивлению воды. Его ошибки входят в итог, чего нет у простого базового значения.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["ρп — удельное сопротивление неизменённой части пласта по зондам с разными радиусами исследования", "ρвп — сопротивление водонасыщенного пласта по данным пористости и сопротивления воды", "Pн как отношение ρп к ρвп"], "rule": "Если Pн больше единицы, порода нефте- или газосодержащая.", "conclusion": "Пласт с Pн больше единицы считают продуктивным по характеру насыщения.", "counterexample": "В единице контрпример не приведён. Из определения Pн следует, что высокое ρп при столь же высоком ρвп, например из-за низкой пористости, не даёт Pн больше единицы."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["параметр насыщения Pн", "сопротивление неизменённой части пласта ρп", "сопротивление водонасыщенного пласта ρвп"], "links": [{"type": "prerequisite", "target": "latyshova.four_method_groups"}, {"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.filtrate_salinity"}, {"type": "prerequisite", "target": "latyshova.goals_of_log_interpretation"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [{"page": 92, "what": "Обозначения в формулах Pн, ρп, ρвп искажены распознаванием (ρн/ρн, Рнρ, Рн ρн = ρн). Нужно сверить с оригиналом и формулами (10), (11)."}], "claims": [{"page_print": null, "text": "Оценку продуктивности можно выполнить фактически по всем методам комплекса.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.03", "quote": "Оценку продуктивности можно осуществить фактически по всем методам комплекса", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.productivity_pn#c1"}, {"page_print": null, "text": "Это вытекает из главного петрофизического параметра Pн, который связывает геофизические свойства с коэффициентом нефтегазонасыщения порового пространства коллектора.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.03", "quote": "главного петрофизического параметра Pн, связывающего геофизические свойства с коэффициентом нефтегазонасыщения порового пространства коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.productivity_pn#c2"}, {"page_print": null, "text": "Из формул (10), (11) следует, что нефте- или газосодержащая порода — та, в которой Pн больше единицы.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.03", "quote": "Из формул (10), (11) следует, что нефте-, газосодержащей является порода, в которой Pн = ρн/ρн > 1.", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.productivity_pn#c3"}, {"page_print": null, "text": "Pн оценивают методами сопротивления, которые дают числитель выражения, и методами пористости при известном удельном сопротивлении воды, от которых зависит знаменатель.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.03", "quote": "Оценка величины Pн = ρн/Рнρ, должна проводиться методами сопротивления (ρн - числитель выражения) и пористости при известном удельном сопротивлении воды (Рн ρн = ρн - знаменатель выражения).", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.productivity_pn#c4"}, {"page_print": null, "text": "Методами оценки продуктивности являются боковое электрическое зондирование, а также экранированные и индукционные зонды с разными радиусами исследования.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.03", "quote": "методами оценки продуктивности являются боковое электрическое зондирование, экранированные и индукционные зонды с разными радиусами исследования", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.productivity_pn#c5"}, {"page_print": null, "text": "Эти методы позволяют определить удельное сопротивление неизменённой части пласта, а при качественной интерпретации — оценить его.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.03", "quote": "позволяющие определить или при качественной интерпретации оценить удельное сопротивление неизмененной части пласта", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.productivity_pn#c6"}, {"page_print": null, "text": "Методы сопротивления должны комплексироваться с методами пористости для определения или оценки сопротивления водонасыщенного пласта.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.03", "quote": "Методы сопротивления должны комплексироваться с методами пористости для определения (или оценки) ρн.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.productivity_pn#c7"}, {"page_print": null, "text": "Всё это должно сочетаться с электрическими методами, которые устанавливают изменение удельного сопротивления в пласте по радиусу и характер проникновения фильтрата в коллектор.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.03", "quote": "Все это также должно сочетаться с электрическими методами, позволяющими установить изменение удельного сопротивления в пласте по радиусу и характер проникновения фильтрата в коллектор.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.productivity_pn#c8"}], "id": "latyshova.productivity_pn", "order": 8, "minutes": 2, "essence": "Продуктивность можно оценивать почти по всем методам комплекса через главный петрофизический параметр Pн. Он связывает геофизические свойства с коэффициентом нефтегазонасыщения порового пространства. Порода нефте- или газосодержащая, если Pн больше единицы.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Pн — отношение двух сопротивлений. В числителе стоит сопротивление неизменённой части пласта ρп, то есть части за зоной проникновения фильтрата. В знаменателе стоит сопротивление того же пласта, если бы он был полностью водонасыщенным, — ρвп.", "pages": [92]}, {"text": "Числитель находят методами сопротивления. Знаменатель находят методами пористости при известном удельном сопротивлении воды. Поэтому один параметр объединяет обе группы методов.", "pages": [92]}, {"text": "Если Pн больше единицы, порода нефте- или газосодержащая. В тексте главы обозначения в формулах искажены распознаванием, поэтому смысл числителя и знаменателя взят из пояснений автора в скобках.", "pages": [92]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "ρп определяют боковым электрическим зондированием, а также экранированными и индукционными зондами с разными радиусами исследования. При качественной интерпретации ρп только оценивают. Для знаменателя методы сопротивления комплексируют с методами пористости.", "pages": [92]}, {"text": "Дополнительно нужны электрические методы, показывающие изменение сопротивления по радиусу пласта и характер проникновения фильтрата в коллектор.", "pages": [92]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Сам по себе большой ρп не доказывает продуктивность: его нужно сравнить с сопротивлением водонасыщенного пласта. Знаменатель зависит от пористости и от сопротивления воды, поэтому ошибка в любом из них меняет Pн. Проникновение фильтрата искажает измерения вблизи скважины, поэтому нужны зонды с разными радиусами исследования.", "pages": [92]}, {"text": "Автор говорит о методах, которые определяют или оценивают ρп, и пороги Pн для разных коллекторов здесь не приводит. Формулы (10), (11), на которые ссылается автор, в шаге не даны.", "pages": [92]}]}], "deeper": [], "glossary": [{"term": "параметр насыщения Pн", "definition": "Главный петрофизический параметр, связывающий геофизические свойства с нефтегазонасыщением коллектора; это отношение сопротивления неизменённой части пласта к сопротивлению водонасыщенного пласта. Pн больше единицы означает нефте- или газосодержащую породу."}, {"term": "сопротивление неизменённой части пласта ρп", "definition": "Удельное сопротивление части пласта, которую не изменило проникновение фильтрата. Это числитель Pн; его определяют боковым зондированием, экранированными и индукционными зондами, а при качественной интерпретации оценивают."}, {"term": "сопротивление водонасыщенного пласта ρвп", "definition": "Сопротивление пласта при полном заполнении пор водой. Это знаменатель Pн; его находят комплексом методов сопротивления и пористости при известном удельном сопротивлении воды."}], "format": "интерактив", "tasks": [{"id": "latyshova.productivity_pn.t1", "type": "single", "step_id": "latyshova.productivity_pn", "claim_ids": ["latyshova.productivity_pn#c3", "latyshova.productivity_pn#c4"], "prompt": "Пласт имеет очень высокое сопротивление неизменённой части ρп, но и сопротивление того же пласта при полном водонасыщении ρвп столь же высокое, например из-за низкой пористости. Что можно сказать о его продуктивности?", "options": [{"id": "a", "text": "Pн близок к единице, поэтому высокое ρп не доказывает нефтегазонасыщение", "misconception": null}, {"id": "b", "text": "Пласт продуктивен, так как высокое сопротивление всегда означает нефть", "misconception": "misc.high_res_oil"}, {"id": "c", "text": "Пласт непродуктивен, так как Pн меньше нуля", "misconception": "misc.pn_negative"}, {"id": "d", "text": "Оценить нельзя, поскольку Pн зависит только от ρвп", "misconception": "misc.pn_only_denominator"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Pн равен отношению ρп к ρвп, и при близких значениях он около единицы, а порода считается нефтегазосодержащей только при Pн больше единицы.", "kind": "transfer"}, {"id": "latyshova.productivity_pn.t2", "type": "calc", "step_id": "latyshova.productivity_pn", "claim_ids": ["latyshova.productivity_pn#c3", "latyshova.productivity_pn#c4"], "prompt": "Для пласта по зондам с разными радиусами исследования найдено удельное сопротивление неизменённой части ρп = 60 Ом·м, а сопротивление того же пласта при полном водонасыщении, оценённое по пористости и сопротивлению воды, ρвп = 12 Ом·м. Чему равен параметр насыщения Pн (отношение ρп к ρвп)?", "options": [], "answer": 5, "tolerance": 0.05, "unit": "безразм.", "explanation": "Pн = ρп / ρвп = 60 / 12 = 5, что больше единицы, значит порода нефте- или газосодержащая.", "kind": "data"}], "pictures": [{"id": "latyshova.productivity_pn.i1", "step_id": "latyshova.productivity_pn", "node_id": "latyshova.productivity_pn", "file": "pictures/productivity_pn_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Pн собирается из двух групп методов; если Pн больше единицы, порода содержит нефть или газ.", "alt": "Схема: методы сопротивления и методы пористости дают числитель и знаменатель параметра Pн. Если Pн больше единицы, порода нефте- или газосодержащая.", "source": "построено кодом по утверждениям главы, стр. 92", "claim_ids": ["latyshova.productivity_pn#c3", "latyshova.productivity_pn#c4"], "prompt": null}]}, {"title": "Каждый метод несёт больше информации, чем его группа, поэтому нужен полный комплекс", "short_title": "Перекрытие информации методов", "why_here": {"text": "Подводит итог разделу о комплексе: связывает группы методов, условия бурения и полноту исследований.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "Пр"}, "threshold": false, "pages": [92], "misconception": {"ref": "misc.log_is_rock", "text": "Каротажная кривая — не сама порода, а косвенный отклик. Поэтому один метод не даёт однозначного ответа, его сведения дополняют другими методами комплекса.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Входом служат диаграммы методов комплекса: ЯМР, СП, ГМ, ГГМ, НМ, АК, микрозонды. Выход — сведения о пористости, глинистости, коллекторе, продуктивности и газонасыщенности. Один метод даёт сведения сразу о нескольких свойствах. Таблиц и числовых столбцов в шаге нет.", "by_model": true}, "breaks": {"text": "Сведения микрозондов о продуктивности и сведения ГГМ и НМ о газонасыщенности верны при неглубоком проникновении. При глубоком проникновении нейтронные методы повторяют после обсадки. Сведения о глинистости от ГГМ, НМ и АК надёжнее при комплексном использовании диаграмм. Сведения о пористости от СП и ГМ автор относит только к терригенному разрезу.", "by_model": true}, "hypotheses": [{"text": "Если комплекс неполон, коллектор и насыщение могут быть определены неоднозначно из-за перекрытия откликов разных свойств.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Метод похож на датчик мониторинга, который косвенно показывает не только свою метрику. Загрузка CPU частично говорит и о памяти, и о сети. Надёжный диагноз ставят по нескольким метрикам сразу.", "breaks_where": "У метрик сервера причинные связи программно известны. У методов ГИС перекрытие зависит от породы, раствора и глубины проникновения.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["глубокое проникновение фильтрата в пласт", "нужно найти газонасыщенные интервалы нейтронными методами"], "rule": "При глубоких проникновениях нейтронные измерения проводят повторно после обсадки скважины, когда зона проникновения расформировывается.", "conclusion": "По повторным замерам можно установить газонасыщенные интервалы по мере расформирования зоны проникновения.", "counterexample": "При неглубоком проникновении по тексту автора ГГМ и НМ дают сведения о газонасыщенности, а микрозонды — о продуктивности без повторных замеров (вывод модели, что повтор здесь не обязателен)."}, "worked_examples": [], "book_tasks": [{"number": "86", "page_pdf": 92, "text": "Диаграммы каких методов геофизических исследований необходимо иметь, чтобы дать заключение о продуктивности коллекторов, выделяемых на основании рис. 14?", "figure": "рис. 14"}, {"number": "87", "page_pdf": 92, "text": "Какими геофизическими методами желательно дополнить комплекс диаграмм, приведенных на рис. 24 и 74? Какие задачи должны решать эти методы?", "figure": "рис. 24 и 74"}, {"number": "88", "page_pdf": 92, "text": "Какие методы геофизического комплекса требуется использовать, чтобы дать однозначное заключение об участке разреза, представленного на рис. 47?", "figure": "рис. 47"}, {"number": "89", "page_pdf": 92, "text": "Какими методами необходимо дополнить комплекс диаграмм, представленных на рис. 58, для однозначной характеристики выделенного участка разреза?", "figure": "рис. 58"}], "terms_introduced": ["повторные исследования после обсадки"], "links": [{"type": "prerequisite", "target": "latyshova.four_method_groups"}, {"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.water_loss_and_mud_density"}, {"type": "prerequisite", "target": "latyshova.water_and_nonfiltering_muds"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "refutes_misconception", "target": "misc.log_is_rock"}], "needs_scan": [{"page": 92, "what": "Рисунки 14, 24, 74, 47, 58 нужны для решения задач 86–89; в единицах их содержимого нет."}], "claims": [{"page_print": null, "text": "Сфера применения каждого из перечисленных методов шире, чем это предусмотрено классификацией по группам.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.04", "quote": "Сфера применения каждого из перечисленных методов шире, чем это предусмотрено данной классификацией.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c1"}, {"page_print": null, "text": "Диаграмма ЯМР в терригенном и карбонатном разрезах, а также диаграммы СП и ГМ в терригенном разрезе несут информацию о пористости.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.04", "quote": "диаграмма ЯМР в терригенном и карбонатном разрезах, диаграммы СП, ГМ - в терригенном, несут информацию о пористости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c2"}, {"page_print": null, "text": "Методы пористости ГГМ, НМ, АК содержат сведения о глинистости, особенно при комплексном использовании их диаграмм.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.04", "quote": "методы пористости ГГМ, НМ, АК содержат сведения о глинистости, особенно при комплексном использовании диаграмм этих методов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c3"}, {"page_print": null, "text": "Практически все методы пористости и глинистости несут косвенную информацию о коллекторе.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.04", "quote": "практически все методы пористости и глинистости несут косвенную информацию о коллекторе", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c4"}, {"page_print": null, "text": "В условиях неглубокого проникновения диаграммы микрозондов дают сведения о продуктивности, а диаграммы ГГМ и НМ — о газонасыщенности породы.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.04", "quote": "(в условиях неглубокого проникновения диаграммы микрозондов дают сведения о продуктивности, диаграммы ГГМ и НМ - о газонасыщенности породы)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c5"}, {"page_print": null, "text": "При глубоких проникновениях измерения нейтронными методами проводят в виде повторных исследований после обсадки скважины.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.04", "quote": "При наличии глубоких проникновений геофизические измерения нейтронными методами проводят в виде повторных исследований после обсадки скважины.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c6"}, {"page_print": null, "text": "Повторные измерения после обсадки позволяют установить газонасыщенные интервалы по мере расформирования в них зоны проникновения.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.04", "quote": "Это позволяет установить газонасыщенные интервалы по мере расформирования в них зоны проникновения.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c7"}, {"page_print": null, "text": "Для надёжного построения литологического разреза по геофизическим данным требуется соблюдать оптимальные параметры промывочной жидкости и репрессии на пласты при бурении.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.05", "quote": "для надежного построения литологического разреза по геофизическим данным требуется соблюдение оптимальных параметров промывочной жидкости, репрессий на пласты в процессе бурения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c8"}, {"page_print": null, "text": "Для надёжного разреза нужен полный комплекс геофизических исследований, соответствующий изучаемому разрезу и типу бурового раствора.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.05", "quote": "проведение в скважинах полного комплекса геофизических исследований, соответствующего изучаемому разрезу и типу бурового раствора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.methods_overlap#c9"}, {"page_print": null, "text": "Задачи 86–89 требуют по рисункам комплексов (рис. 14, 24, 74, 47, 58) назвать методы, необходимые для заключения о продуктивности или однозначной характеристики разреза.", "kind": "assumption", "page_pdf": 92, "unit_id": "p092.07", "quote": "86. Диаграммы каких методов геофизических исследований необходимо иметь, чтобы дать заключение о продуктивности коллекторов, выделяемых на основании рис. 14?", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.methods_overlap#c10"}], "id": "latyshova.methods_overlap", "order": 9, "minutes": 3, "essence": "Классификация методов по четырём группам условна: сфера применения каждого метода шире своей группы. Методы пористости несут сведения о глинистости, а методы пористости и глинистости — косвенно о коллекторе. Поэтому для надёжного разреза нужны оптимальные параметры раствора, подходящие репрессии и полный комплекс исследований.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Группа метода — это лишь основное назначение. Один и тот же прибор откликается на несколько свойств породы сразу. ЯМР в терригенных и карбонатных разрезах, а также СП и ГМ в терригенных несут сведения о пористости.", "pages": [92]}, {"text": "ГГМ, НМ и АК дают сведения о глинистости, особенно если сопоставлять их диаграммы. Практически все методы пористости и глинистости косвенно говорят о коллекторе. При неглубоком проникновении микрозонды дают сведения о продуктивности, а ГГМ и НМ — о газонасыщенности.", "pages": [92]}, {"text": "Когда проникновение глубокое, зона проникновения скрывает газ от нейтронных методов. Тогда измерения повторяют после обсадки скважины: зона проникновения со временем расформировывается, и газонасыщенные интервалы становятся видны.", "pages": [92]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Практический вывод автора: надёжный литологический разрез требует оптимальных параметров промывочной жидкости и подходящих репрессий на пласты при бурении. Нужен также полный комплекс ГИС, соответствующий изучаемому разрезу и типу бурового раствора. При глубоком проникновении нейтронные методы повторяют после обсадки.", "pages": [92]}, {"text": "Задачи 86–89 тренируют подбор недостающих методов по готовым рисункам комплексов.", "pages": [92]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Информация «чужих» методов косвенная и зависит от условий. Сведения микрозондов о продуктивности относятся к неглубокому проникновению. Сведения ГГМ и НМ о газонасыщенности тоже зависят от проникновения.", "pages": [92]}, {"text": "Сведения о глинистости от ГГМ, НМ и АК лучше при комплексном использовании диаграмм. Повторные замеры после обсадки нужны именно для нейтронных методов при глубоких проникновениях. Одна диаграмма не даёт однозначного ответа, поэтому в задачах просят дополнить комплекс.", "pages": [92]}]}], "deeper": [], "glossary": [{"term": "повторные исследования после обсадки", "definition": "Повторные нейтронные измерения, которые проводят в обсаженной скважине при глубоких проникновениях. Со временем зона проникновения расформировывается, и становятся видны газонасыщенные интервалы."}], "format": "карточки", "tasks": [{"id": "latyshova.methods_overlap.t1", "type": "single", "step_id": "latyshova.methods_overlap", "claim_ids": ["latyshova.methods_overlap#c6", "latyshova.methods_overlap#c7"], "prompt": "При бурении фильтрат бурового раствора глубоко проник в пласты, и нейтронные методы не показали газонасыщенные интервалы. Что делают, чтобы их выделить?", "options": [{"id": "a", "text": "Повторяют нейтронные измерения после обсадки скважины", "misconception": null}, {"id": "b", "text": "Заменяют нейтронные методы микрозондами, они покажут газ при любом проникновении", "misconception": "misc.log_is_rock"}, {"id": "c", "text": "Увеличивают репрессию на пласт, чтобы вытеснить фильтрат", "misconception": null}, {"id": "d", "text": "Считают такие интервалы водоносными, раз газ не виден", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Со временем зона проникновения расформировывается, и после обсадки газонасыщенные интервалы становятся видны нейтронным методам.", "kind": "understanding"}, {"id": "latyshova.methods_overlap.t2", "type": "multiple", "step_id": "latyshova.methods_overlap", "claim_ids": ["latyshova.methods_overlap#c3"], "prompt": "Какие из методов пористости содержат сведения о глинистости, особенно если сопоставлять их диаграммы? Выберите все верные.", "options": [{"id": "a", "text": "ГГМ", "misconception": null}, {"id": "b", "text": "НМ", "misconception": null}, {"id": "c", "text": "АК", "misconception": null}, {"id": "d", "text": "ЯМР", "misconception": "misc.log_is_rock"}, {"id": "e", "text": "Микрозонды", "misconception": null}], "answer": ["a", "b", "c"], "tolerance": null, "unit": null, "explanation": "Глинистость несут диаграммы ГГМ, НМ и АК, а ЯМР даёт сведения о пористости, микрозонды — о продуктивности.", "kind": "recall"}], "pictures": [{"id": "latyshova.methods_overlap.i1", "step_id": "latyshova.methods_overlap", "node_id": "latyshova.methods_overlap", "file": "pictures/methods_overlap_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Методы выходят за рамки своей группы: слева метод, справа, какие ещё сведения он даёт и при каком условии.", "alt": "Таблица из пяти строк: какие методы дают сведения о пористости, глинистости, коллекторе, продуктивности и газонасыщенности помимо своего основного назначения.", "source": "построено кодом по утверждениям главы, стр. 92", "claim_ids": ["latyshova.methods_overlap#c1", "latyshova.methods_overlap#c2", "latyshova.methods_overlap#c3", "latyshova.methods_overlap#c4", "latyshova.methods_overlap#c5"], "prompt": null}]}, {"title": "Построение литологической колонки: границы пластов и оценка пород по сумме признаков", "short_title": "Как строят литологическую колонку", "why_here": {"text": "Опирается на комплекс методов; открывает работу с таблицей признаков пород.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Н"}, "threshold": false, "pages": [92], "misconception": {"ref": "misc.log_is_rock", "text": "Шаг исправляет представление, что каротажная кривая и есть порода. Диаграмма даёт лишь физический признак, часто общий для разных отложений. Поэтому породу оценивают по сумме признаков и уточняют по образцам.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: диаграммы разных геофизических методов по скважине и данные петрофизических исследований образцов. Выход: границы и толщины пластов и литологическая характеристика однородных интервалов, а при неизвестном составе условная колонка по физическим признакам.", "by_model": false}, "breaks": {"text": "Правило ломается, когда признаки общие для разных отложений, а состав неизвестен: тогда колонка остаётся условной, пока её не уточнят по образцам.", "by_model": false}, "hypotheses": [{"text": "Возможно, при расхождении колонки и образцов приоритет имеют образцы, так как колонку «уточняют» по ним. В главе это прямо не сказано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Похоже на определение типа файла без расширения по нескольким признакам: размеру, заголовку, содержимому. Чем больше признаков совпало, тем увереннее вывод, а проверка по образцу даёт окончательный ответ.", "breaks_where": "Признаки файла дискретны и точны, а геофизические признаки косвенные, неоднозначные и зависят от условий в скважине.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы разных методов ГИС по скважине, образцы породы, полученные при бурении или боковым грунтоносом.", "manual_steps": "Определить границы и толщины пластов по диаграммам, собрать признаки по каждому интервалу, оценить литологию, при неизвестном составе построить условную колонку и уточнить её по образцам.", "judgment_points": "Решать, достаточно ли признаков для определения породы и когда нужна условная колонка с уточнением по образцам.", "time": "в главе не указано", "typical_errors": "Опора на один метод при том, что признаки у разных отложений общие; принятие условной колонки за окончательную.", "by_model": true}, "decision_on_data": {"features": ["состав пород неизвестен", "физические признаки с разных диаграмм", "число установленных признаков", "наличие образцов"], "rule": "Литологию оценивают по сумме признаков; если минералогический состав и литология неизвестны, строят условную колонку по физическим признакам и уточняют её по петрофизике образцов.", "conclusion": "Чем больше признаков установлено, тем точнее определена порода; колонка по физическим признакам предварительна до уточнения по образцам.", "counterexample": "Физические признаки часто общие для разных отложений, поэтому даже сумма признаков может не различить породы без образцов."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["условная колонка по физическим признакам", "боковой грунтонос"], "links": [{"type": "prerequisite", "target": "latyshova.four_method_groups"}, {"type": "prerequisite", "target": "latyshova.methods_overlap"}, {"type": "refutes_misconception", "target": "misc.log_is_rock"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Для построения разрезов скважин используется комплекс диаграмм различных геофизических методов.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.09", "quote": "Для построения разрезов скважин используется комплекс диаграмм различных геофизических методов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.build_litho_column#c1"}, {"page_print": null, "text": "Построение разреза включает две операции: определение границ и толщин отдельных пластов и оценку литологической характеристики выделенных однородных интервалов.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.09", "quote": "Построение разреза включает две операции: определение границ и толщин отдельных пластов и оценку литологической характеристики выделенных однородных интервалов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.build_litho_column#c2"}, {"page_print": null, "text": "Границы и толщины пластов определяют способами, рассмотренными выше, по диаграммам отдельных методов.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.10", "quote": "Для определения границ и толщин пластов используются способы, рассмотренные выше, по диаграммам отдельных методов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.build_litho_column#c3"}, {"page_print": null, "text": "Литологическую характеристику пород оценивают по сумме признаков, выявленных на диаграммах различных методов.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.10", "quote": "Литологическую характеристику пород оценивают по сумме признаков, выявленных на диаграммах различных методов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.build_litho_column#c4"}, {"page_print": null, "text": "Чем больше число признаков, характеризующих породу, установлено, тем точнее она может быть определена.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.10", "quote": "Чем больше число признаков, характеризующих породу, установлено, тем точнее она может быть определена.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.build_litho_column#c5"}, {"page_print": null, "text": "При комплексной интерпретации нужно учитывать, что методы дают физические признаки пород, часто общие для разных отложений.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.11", "quote": "существующие методы дают физические признаки пород, часто являющиеся общими для разных отложений.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.build_litho_column#c6"}, {"page_print": null, "text": "Если неизвестны ни минералогический состав, ни литологическая характеристика пород, следует строить условную колонку расчленения разреза по физическим признакам.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.11", "quote": "следует строить условную колонку расчленения разреза по физическим признакам", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.build_litho_column#c7"}, {"page_print": null, "text": "Условную колонку затем уточняют по данным петрофизических исследований образцов, извлечённых в процессе бурения скважины или боковым грунтоносом.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.11", "quote": "которую затем уточняют по данным петрофизических исследований образцов, извлеченных в процессе бурения скважины или боковым грунтоносом.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.build_litho_column#c8"}], "id": "latyshova.build_litho_column", "order": 10, "minutes": 2, "essence": "Построение разреза состоит из двух операций: определения границ и толщин пластов и оценки литологии выделенных однородных интервалов. Литологию оценивают по сумме признаков с диаграмм разных методов: чем признаков больше, тем точнее определение. Если состав пород совсем неизвестен, строят условную колонку по физическим признакам и уточняют её по образцам.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Сначала разрез делят на пласты. Границы и толщины находят по диаграммам отдельных методов, теми способами, что рассмотрены выше в книге. Затем каждый однородный интервал описывают по признакам с диаграмм разных методов.", "pages": [92]}, {"text": "Один метод даёт физический признак, например отклик на какое-то свойство породы. Такие признаки часто одинаковы у разных отложений, поэтому по одному методу породу не определить. Сумма признаков сужает круг возможных пород.", "pages": [92]}, {"text": "Чем признаков больше, тем точнее оценка.", "pages": [92]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Если минеральный состав и литология совсем неизвестны, строят условную колонку расчленения разреза по физическим признакам. Это разбиение разреза на интервалы по физическим признакам, ещё без названий пород. Затем колонку уточняют петрофизическими исследованиями образцов, то есть измерением свойств пород в лаборатории.", "pages": [92]}, {"text": "Образцы берут двумя путями: извлекают в процессе бурения скважины или отбирают боковым грунтоносом. Боковой грунтонос — прибор для отбора образцов породы из стенки скважины. В главе он назван только как источник образцов, без описания конструкции.", "pages": [92]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Главная трудность в том, что физические признаки пород часто общие для разных отложений. Поэтому комплексная интерпретация не должна опираться на один метод. Условная колонка — промежуточный вариант, а не окончательный ответ.", "pages": [92]}, {"text": "Окончательное уточнение даёт изучение образцов. Подробностей о том, какие признаки нужны для каждой породы, в этой части главы нет.", "pages": [92]}]}], "deeper": [], "glossary": [{"term": "условная колонка по физическим признакам", "definition": "Предварительное расчленение разреза на интервалы по физическим признакам, когда состав и литология пород неизвестны; затем её уточняют по образцам."}, {"term": "боковой грунтонос", "definition": "Прибор для отбора образцов породы из стенки скважины; образцы затем исследуют петрофизически."}], "format": "практикум на данных", "tasks": [{"id": "latyshova.build_litho_column.t1", "type": "order", "step_id": "latyshova.build_litho_column", "claim_ids": ["latyshova.build_litho_column#c2", "latyshova.build_litho_column#c7", "latyshova.build_litho_column#c8"], "prompt": "Расположите в порядке действия при построении литологической колонки, если состав пород неизвестен.", "options": [{"id": "a", "text": "Уточнить колонку по петрофизическим исследованиям образцов", "misconception": null}, {"id": "b", "text": "Определить границы и толщины пластов", "misconception": null}, {"id": "c", "text": "Составить условную колонку по физическим признакам однородных интервалов", "misconception": null}], "answer": ["b", "c", "a"], "tolerance": null, "unit": null, "explanation": "Сначала находят границы пластов, затем строят условную колонку по физическим признакам и в конце уточняют её по образцам.", "kind": "recall"}, {"id": "latyshova.build_litho_column.t2", "type": "single", "step_id": "latyshova.build_litho_column", "claim_ids": ["latyshova.build_litho_column#c4", "latyshova.build_litho_column#c6"], "prompt": "Почему литологию нельзя уверенно определить по диаграмме одного метода?", "options": [{"id": "a", "text": "Физические признаки часто одинаковы у разных отложений", "misconception": null}, {"id": "b", "text": "Один метод не позволяет найти границы пластов", "misconception": null}, {"id": "c", "text": "Диаграмма отражает только свойства бурового раствора", "misconception": null}, {"id": "d", "text": "Кривая и есть порода, но она искажена", "misconception": "misc.log_is_rock"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Метод даёт физический признак, общий для разных пород, поэтому породу оценивают по сумме признаков.", "kind": "understanding"}], "pictures": [{"id": "latyshova.build_litho_column.i1", "step_id": "latyshova.build_litho_column", "node_id": "latyshova.build_litho_column", "file": "pictures/build_litho_column_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Сначала делят разрез на пласты, затем оценивают литологию по сумме признаков. Если состав неизвестен, колонку строят условно и уточняют.", "alt": "Схема: диаграммы методов дают границы пластов, затем признаки интервалов, из них строится колонка. Если состав неизвестен, строят условную колонку и уточняют по образцам.", "source": "построено кодом по утверждениям главы, стр. 92", "claim_ids": ["latyshova.build_litho_column#c2", "latyshova.build_litho_column#c3", "latyshova.build_litho_column#c4", "latyshova.build_litho_column#c5", "latyshova.build_litho_column#c7", "latyshova.build_litho_column#c8"], "prompt": null}]}, {"title": "Таблица 21: как выглядят глины, водоносные, нефтяные, газовые и пресноводные коллекторы", "short_title": "Таблица признаков: глины и коллекторы", "why_here": {"text": "Применяет знания о корке, СП, микрозондах и нейтронных методах; даёт образцы для опознавания пород по кривым.", "by_model": true}, "difficulty": {"primary": "Р", "secondary": "И"}, "threshold": false, "pages": [92, 93], "misconception": {"ref": "misc.high_res_oil", "text": "По таблице 21 нефтяной коллектор имеет среднее ρп, как и газовый и пресноводный. Высокое сопротивление само по себе нефть не доказывает, нужен комплекс признаков.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: кривые сопротивления, СП, кавернограмма, микрозонды, гамма-метод и нейтронные методы по интервалу при глинистом растворе. Выход: отнесение интервала к глине или к типу коллектора по уровню показаний каждой кривой.", "by_model": false}, "breaks": {"text": "Признаки даны только для ясно выраженных типов и межзерновых коллекторов. Переходные разности (песчанистая или пластичная глина, глинистый нефтеносный песчаник) таблице не соответствуют. Таблица относится к глинистому раствору.", "by_model": false}, "hypotheses": [{"text": "Если несколько признаков указывают на разные типы пород, интервал, вероятно, переходный или глинистый, и решение надёжнее принимать по сумме кривых.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Таблица похожа на справочник сигнатур: набор признаков (кривых) сопоставляют с эталонными профилями и выбирают ближайший.", "breaks_where": "Эталоны даны для чистых типов, а реальные породы смешанные. Нет точного совпадения хеша, поэтому получается лишь приближённое соответствие, и разные причины могут давать схожий набор признаков.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["СП: максимум (глина) или минимум (минерализованная вода)", "d_c относительно d_n", "совпадение показаний микрозондов разной длины", "ГК и нейтронные методы", "наличие проникновения"], "rule": "Глина: максимальные СП и ГК, d_c > d_n, нет проникновения, микрозонды совпадают. Проницаемый коллектор: d_c < d_n, микрозонды расходятся, есть проникновение. Среди коллекторов газ отличается максимумом нейтронных показаний.", "conclusion": "Интервал можно отнести к глине, к водоносному, нефтяному или газовому коллектору, к пресноводному коллектору или к низкопористому карбонату. Нефть и газ почти не различимы по сопротивлению и зоне проникновения.", "counterexample": "Глинистый нефтенасыщенный песчаник: амплитуда СП уменьшена и сопротивление заметно снижено, поэтому по таблице его можно принять за другой тип породы."}, "worked_examples": [], "book_tasks": [], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.filtrate_salinity"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.four_method_groups"}, {"type": "prerequisite", "target": "latyshova.build_litho_column"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [{"page": 93, "what": "Последняя строка таблицы 21 (низкопористые карбонатные коллекторы) обрезана: нет конца описания насыщения и уточнения значений."}, {"page": 93, "what": "Проверить по скану обозначения (ρп, ρр, ρм, U_сп, d_n) и соотношения сопротивлений зоны проникновения в ячейках таблицы."}], "claims": [{"page_print": null, "text": "Для оценки наиболее распространённых осадочных пород можно использовать ориентировочные данные таблицы 21.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.12", "quote": "Для оценки наиболее распространенных осадочных пород можно использовать ориентировочные данные (табл. 21).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c1"}, {"page_print": null, "text": "В таблице 21 даны признаки только наиболее ясно выраженных типов пород и коллекторов межзернового типа.", "kind": "assumption", "page_pdf": 92, "unit_id": "p092.12", "quote": "При этом необходимо учитывать, что в этой таблице даны признаки лишь наиболее ясно выраженных типов пород и коллекторов межзернового типа.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c2"}, {"page_print": null, "text": "В природных условиях могут встречаться переходные разности от одного типа породы к другому.", "kind": "observation", "page_pdf": 92, "unit_id": "p092.12", "quote": "В природных условиях могут встречаться также переходные разности от одного типа к другому.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c3"}, {"page_print": null, "text": "Увеличение песчанистости глины может уменьшить её пористость и вероятность образования против неё каверны, а также увеличить сопротивление.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.12", "quote": "Например, увеличение песчанистости глины может привести к уменьшению ее пористости и вероятности образования против нее каверны, увеличению сопротивления", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c4"}, {"page_print": null, "text": "Увеличение пластичности глины может привести к тому, что вместо каверны против неё создаётся сужение диаметра скважины.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.12", "quote": "а увеличение пластичности - к тому, что вместо каверны против глины создается сужение диаметра скважины", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c5"}, {"page_print": null, "text": "Повышение содержания глинистого материала в нефтенасыщенном песчанике уменьшает амплитуду СП и значительно снижает сопротивление.", "kind": "inference", "page_pdf": 92, "unit_id": "p092.12", "quote": "Повышение содержания глинистого материала в нефтенасыщенном песчанике приводит к уменьшению амплитуды СП и значительному снижению сопротивления.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c6"}, {"page_print": null, "text": "Таблица 21 даёт основные признаки некоторых осадочных пород и коллекторов по геофизическим методам для случая глинистого раствора.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.02", "quote": "Основные признаки некоторых осадочных пород и коллекторов по данным геофизических методов (глинистый раствор).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c7"}, {"page_print": null, "text": "Колонки таблицы: методы сопротивления (ρп и характер зоны проникновения), СП, кавернограмма, микрозонды, гамма-метод и нейтронные методы.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "Метод СП | Кавернограмма | Микрозонды | Гамма-метод | Нейтронные методы", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c8"}, {"page_print": null, "text": "Измеряемые величины в колонках: U_сп для СП, d_c для кавернограммы, ρп для микрозондов, Iγ для гамма-метода, Inγ и Inn для нейтронных методов.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "$$U_{cn}$$ | $$d_c$$ | $$\\rho_n$$ | $$I\\gamma$$ | $$In\\gamma, Inn$$", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c9"}, {"page_print": null, "text": "Глины: низкое ρп, проникновения нет, максимальные показания СП, диаметр скважины больше номинального (d_c > d_n).", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "Глины | низкое | Отсутствие проникновения | максимальные | $$d_c > d_n$$", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c10"}, {"page_print": null, "text": "Глины: микрозонды дают низкие показания, совпадающие для зондов разной длины; гамма-метод максимальный, нейтронные методы минимальные.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "Низкие, совпадающие для микрозондов разной длины | максимальные | Минимальные", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c11"}, {"page_print": null, "text": "Пески, песчаники и высокопористые карбонатные коллекторы с межзерновой пористостью, насыщенные высокоминерализованной водой: минимальное ρп, минимальные показания СП, d_c < d_n.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "насыщенные высокоминерализованной водой | минимальное | $$\\rho_p < \\rho_m \\geq \\rho_n$$ | минимальные | $$d_c < d_n$$", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c12"}, {"page_print": null, "text": "У водоносных коллекторов с высокоминерализованной водой микрозонды дают средние показания, не совпадающие для зондов разной длины; гамма-метод и нейтронные методы средние.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "Средние, не совпадающие для микрозондов разной длины | средние | средние", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c13"}, {"page_print": null, "text": "Нефтенасыщенные межзерновые коллекторы с небольшим содержанием связанной воды имеют среднее ρп; для зоны проникновения в таблице приведены три варианта соотношений сопротивлений.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "насыщенные нефтью с небольшим содержанием связанной воды | среднее | $$\\rho_p < \\rho_m > \\rho_n$$ $$\\rho_p < \\rho_m < \\rho_n$$ $$\\rho_p < \\rho_m = \\rho_n$$", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c14"}, {"page_print": null, "text": "Для нефтяных коллекторов показания СП, кавернограммы, микрозондов, гамма-метода и нейтронных методов указаны «то же», то есть как у водоносных коллекторов с высокоминерализованной водой выше в таблице.", "kind": "inference", "page_pdf": 93, "unit_id": "p093.03", "quote": "| То же | То же | То же | То же | То же  |", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c15"}, {"page_print": null, "text": "Газонасыщенные межзерновые коллекторы с небольшим содержанием связанной воды: сопротивление и характер зоны проникновения те же, что у нефтяных; нейтронные методы показывают максимум.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "насыщенные газом с небольшим содержанием связанной воды | То же | То же | - | - | - | - | максимальные", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c16"}, {"page_print": null, "text": "Для газовых коллекторов в таблице нет значений по СП, кавернограмме, микрозондам и гамма-методу (стоят прочерки).", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "То же | То же | - | - | - | - | максимальные", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c17"}, {"page_print": null, "text": "Коллекторы, насыщенные водой более пресной или такой же, как фильтрат бурового раствора, имеют среднее ρп; зона проникновения записана двумя вариантами соотношений.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "насыщенные водой более пресной или такой же, как фильтрат бурового раствора | Среднее | $$\\rho_p < \\rho_m < \\rho_n$$ $$\\rho_p < \\rho_m = \\rho_n$$", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c18"}, {"page_print": null, "text": "У пресноводных коллекторов показания СП выше, чем в глинах, или как в глинах; диаметр скважины равен номинальному (d_c = d_n); нейтронные методы средние.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "Показания СП выше, чем в глинах или как в глинах; $$\\rho_p \\leq \\rho_n$$ | $$d_c = d_n$$ | - | - | средние", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_clays_sands_gas#c19"}, {"page_print": null, "text": "Низкопористые коллекторы в чистых карбонатных разностях выделены в отдельную строку; описание характера насыщения порового пространства в тексте обрезано.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "Низкопористые коллекторы в чистых карбонатных разностях. Характер насыщения порового про-", "source_kind": "table", "by_model": false, "needs_scan": true, "id": "latyshova.table21_clays_sands_gas#c20"}, {"page_print": null, "text": "У низкопористых карбонатных коллекторов проникновение глубокое; СП минимален, либо показания фильтрата дают кажущееся отсутствие проникновения.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "Глубокое проникновение | Минимальные или фильтрата, кажущееся отсутствие проникновения", "source_kind": "table", "by_model": false, "needs_scan": true, "id": "latyshova.table21_clays_sands_gas#c21"}, {"page_print": null, "text": "У низкопористых карбонатных коллекторов гамма-метод минимальный; нейтронные показания те же, но выше, чем в песчаных коллекторах.", "kind": "observation", "page_pdf": 93, "unit_id": "p093.03", "quote": "минимальные | То же, но выше, чем в песчаных коллекторах", "source_kind": "table", "by_model": false, "needs_scan": true, "id": "latyshova.table21_clays_sands_gas#c22"}], "id": "latyshova.table21_clays_sands_gas", "order": 11, "minutes": 4, "essence": "Таблица 21 даёт образцы для опознавания породы по набору кривых: сопротивление, зона проникновения, СП, каверномер, микрозонды, ГК, нейтронные методы. Глины и коллекторы различаются по СП, диаметру скважины и проникновению. Нефтяной и газовый коллекторы почти не различаются по большинству методов, газ выделяется максимальными показаниями нейтронных методов. Признаки даны только для ясно выраженных типов и межзерновых коллекторов, переходные разности возможны.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Глина не пропускает фильтрат, поэтому зоны проникновения нет, а скважина против неё обычно расширена (d_c > d_n). Это глинистая порода, и СП и ГК в ней максимальны. В проницаемом коллекторе фильтрат проникает в пласт и образует корку, поэтому d_c < d_n.", "pages": [93]}, {"text": "Показания микрозондов разной длины в коллекторе расходятся, а в глине совпадают. Сопротивление коллектора зависит от насыщения. Высокоминерализованная вода даёт минимальное сопротивление, нефть и газ со связанной водой дают среднее.", "pages": [93]}, {"text": "Нейтронные показания у глин минимальные, у обычных коллекторов средние, у газоносных максимальные. Автор отдельно описывает, как меняется картина у переходных пород. Песчанистая глина менее пористая, в ней реже возникает каверна, а сопротивление растёт.", "pages": [92, 93]}, {"text": "Более пластичная глина вместо каверны даёт сужение ствола. Глинистый материал в нефтенасыщенном песчанике снижает амплитуду СП и заметно снижает сопротивление.", "pages": [92]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Таблицу используют как ориентир при качественной интерпретации. Сравнивают наблюдаемые кривые с колонками таблицы и выбирают наиболее подходящий тип породы или коллектора. Сначала смотрят на СП, кавернограмму и микрозонды, чтобы отделить глину от проницаемого пласта.", "pages": [92, 93]}, {"text": "Затем по сопротивлению и нейтронным методам оценивают характер насыщения. Результат нужно проверять с учётом переходных разностей, которые таблица не описывает.", "pages": [93]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Таблица относится к глинистому раствору и к ясно выраженным типам пород и межзерновым коллекторам. Нефтяной и газовый коллекторы в ней записаны одинаково по сопротивлению и зоне проникновения. Для газа в таблице нет данных по СП, каверномеру, микрозондам и ГК, отличается только максимум нейтронных методов.", "pages": [92, 93]}, {"text": "Пресноводный коллектор тоже имеет среднее сопротивление, поэтому одного сопротивления для вывода о нефти недостаточно. У глин и у низкопористых карбонатов признаки частично пересекаются: у обоих низкое или минимальное значение отдельных методов. Последняя строка таблицы в распознанном тексте обрезана, поэтому описание насыщения для чистых карбонатов неполное.", "pages": [93]}, {"text": "Обозначения ρп, ρр, ρм и U_сп в этой части главы не расшифрованы. Их смысл берётся из предыдущих шагов.", "pages": [92, 93]}]}], "deeper": [], "glossary": [], "format": "карточки", "tasks": [{"id": "latyshova.table21_clays_sands_gas.t1", "type": "single", "step_id": "latyshova.table21_clays_sands_gas", "claim_ids": ["latyshova.table21_clays_sands_gas#c16", "latyshova.table21_clays_sands_gas#c12", "latyshova.table21_clays_sands_gas#c15"], "prompt": "При глинистом растворе интервал имеет: среднее сопротивление ρп, диаметр скважины меньше номинального (d_c < d_n), расходящиеся показания микрозондов разной длины и максимальные показания нейтронных методов. К какому типу относится интервал?", "options": [{"id": "a", "text": "Газонасыщенный коллектор", "misconception": null}, {"id": "b", "text": "Нефтенасыщенный коллектор", "misconception": "misc.high_res_oil"}, {"id": "c", "text": "Глина", "misconception": null}, {"id": "d", "text": "Водоносный коллектор с высокоминерализованной водой", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Признаки проницаемого коллектора со средним сопротивлением плюс максимум нейтронных показаний отличают газ от нефти.", "kind": "data"}, {"id": "latyshova.table21_clays_sands_gas.t2", "type": "gap", "step_id": "latyshova.table21_clays_sands_gas", "claim_ids": ["latyshova.table21_clays_sands_gas#c10"], "prompt": "Глина не пропускает фильтрат, поэтому зоны проникновения в ней {{1}}, а диаметр скважины против неё обычно {{2}} номинального.", "options": [], "answer": ["нет", "больше"], "tolerance": null, "unit": null, "explanation": "Для глин в таблице 21 указано отсутствие проникновения и d_c > d_n.", "kind": "recall"}], "pictures": [{"id": "latyshova.table21_clays_sands_gas.i1", "step_id": "latyshova.table21_clays_sands_gas", "node_id": "latyshova.table21_clays_sands_gas", "file": "pictures/table21_clays_sands_gas_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Глины и водоносный коллектор с высокоминерализованной водой различаются по СП, диаметру скважины и микрозондам.", "alt": "Сравнение глин и водоносного коллектора с высокоминерализованной водой по СП, диаметру скважины, микрозондам, гамма-методу и нейтронным методам.", "source": "построено кодом по утверждениям главы, стр. 93", "claim_ids": ["latyshova.table21_clays_sands_gas#c10", "latyshova.table21_clays_sands_gas#c11", "latyshova.table21_clays_sands_gas#c12", "latyshova.table21_clays_sands_gas#c13"], "prompt": null}]}, {"title": "Таблица 21 (продолжение): карбонаты, ангидриты, гипсы и соли, особенности и ограничения", "short_title": "Таблица признаков: карбонаты и соли", "why_here": {"text": "Дополняет первую часть таблицы породами других типов и показывает, когда хватает нескольких методов.", "by_model": true}, "difficulty": {"primary": "Р", "secondary": "Н"}, "threshold": false, "pages": [94, 95], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход: показания методов по пласту и состояние ствола (отсутствие проникновения, d_c относительно d_a). Выход: тип породы — глинистый известняк, мергель, ангидрит, плотный известняк, гипс, галит или калийная соль. Названия столбцов таблицы в этой части главы не даны.", "by_model": true}, "breaks": {"text": "Правило ломается при высокой глинистости: показания других методов резко меняются. Оно же ломается при загипсованности: показания НГМ снижаются. У галита значения зависят от диаметра скважины, если раствор не насыщен солью.", "by_model": true}, "hypotheses": [{"text": "Различие гипса и ангидрита по последнему столбцу, вероятно, связано со свойством, чувствительным к связанной воде в гипсе; в главе это не сказано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Таблица похожа на справочник правил классификации, как дерево решений. Строка — класс, столбцы — признаки, «то же» — унаследованное значение.", "breaks_where": "У таблицы качественные значения («максимальные», «средние») без порогов. Признаки зависят от состояния скважины и глинистости, поэтому правила не жёсткие.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Кривые методов по интервалу и сведения о растворе и диаметре скважины.", "manual_steps": "Специалист сопоставляет показания с каждой строкой таблицы 21. Для гидрохимических разрезов он сверяет их с константами из табл. 14, 16, 19.", "judgment_points": "Хватает ли небольшого числа методов; не исказили ли глинистость или загипсованность показания других методов.", "time": "в главе не указано", "typical_errors": "Не учесть влияние глинистости или загипсованности (снижение НГМ). Не учесть, что у соли показания зависят от диаметра скважины.", "by_model": true}, "decision_on_data": {"features": ["отсутствие проникновения", "d_c = d_a", "значение в последнем столбце таблицы (максимальное или минимальное)", "насыщенность раствора солью (для соли)"], "rule": "Гипсы и ангидриты в таблице совпадают по большинству столбцов и различаются последним: у гипсов минимальные значения, у ангидритов максимальные. Для галита и калийных солей d_c = d_a только при предельном насыщении раствора солью. Калийные соли отличает аномально высокое значение в одном из столбцов.", "conclusion": "Для гидрохимического разреза породы выделяют по константам методов рассеянного гамма-излучения и акустического (табл. 14, 16, 19).", "counterexample": "При большом содержании глинистого материала показания резко меняются, а загипсованность снижает показания НГМ; такой пласт не сводится к строке таблицы."}, "worked_examples": [{"page_pdf": 95, "condition": "Терригенный разрез, в котором плотные слабоглинистые карбонатные породы имеют подчиненное значение.", "steps": ["Сопоставить свойства пород с таблицей 21.", "Убедиться, что свойства пород ясно выражены.", "Оценить, сколько методов нужно для колонки."], "result": "Задача может быть достаточно хорошо решена с помощью одних лишь электрических методов.", "figure": null}], "book_tasks": [], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.table21_clays_sands_gas"}, {"type": "prerequisite", "target": "latyshova.build_litho_column"}, {"type": "prerequisite", "target": "latyshova.methods_overlap"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}], "needs_scan": [{"page": 94, "what": "Заголовки столбцов таблицы 21 и начало обрезанной первой строки («…странства»): в единице они не переданы."}], "claims": [{"page_print": null, "text": "В обрывке предыдущей строки сказано, что что-то (окончание слова «…странства») установить трудно из-за глубокого проникновения.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "странства установить трудно из-за глубокого проникновения", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c1"}, {"page_print": null, "text": "Порода из обрывка предыдущей строки может обладать как межзерновой, так и трещинной пористостью.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "Могут обладать как межзерновой, так и трещиной пористостью", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c2"}, {"page_print": null, "text": "Глинистые известняки и мергели могут обладать как межзерновой, так и трещинной пористостью.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "Глинистые известняки, мергели. Могут обладать как межзерновой, так и трещиной пористостью", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c3"}, {"page_print": null, "text": "Для глинистых известняков и мергелей в таблице указаны: отсутствие проникновения, максимальные значения, в одном столбце максимальные и резко меняющиеся, затем средние или максимальные. В последнем столбце значения средние, но выше, чем в песчаных коллекторах.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "- | Отсутствие проникновения | максимальные | - | максимальные, резко меняющиеся | Средние или максимальные | Средние, но выше, чем в песчаных коллекторах", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c4"}, {"page_print": null, "text": "Для ангидритов и чистых плотных кристаллических известняков в таблице указаны: максимальное значение в первом столбце, отсутствие проникновения и минимальные значения в следующем.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "Ангидриты, чистые плотные кристаллические известняки | максимальное | Отсутствие проникновения | минимальные", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c5"}, {"page_print": null, "text": "У ангидритов и чистых плотных кристаллических известняков диаметр скважины равен номинальному (d_c = d_a). В последнем столбце значения максимальные.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "d_{c} = d_{a} | То же | минимальные | Максимальные", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c6"}, {"page_print": null, "text": "Для гипсов и сильно загипсованных пород все значения те же, что у ангидритов. Исключение — последний столбец, где значения минимальные.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "Гипсы, сильно загипсованные породы | То же | То же | То же | То же | То же | То же | Минимальные", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c7"}, {"page_print": null, "text": "У галита (каменной соли) d_c = d_a выполняется при предельном насыщении раствора солью. В другом столбце значения минимальные при d_c » d_a.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "d_{c} = d_{a} при предельном насыщении раствора солью | минимальные при d_{c} » d_{a}.", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c8"}, {"page_print": null, "text": "Для галита один из столбцов имеет очень низкие значения. В последнем столбце показания меняются с изменением диаметра скважины от средних до очень высоких.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "Очень низкие | Показания меняются с изменением диаметра скважины от средних до очень высоких", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c9"}, {"page_print": null, "text": "Для калийных солей значения те же, что у галита, кроме одного столбца, где они аномально высокие.", "kind": "observation", "page_pdf": 94, "unit_id": "p094.01", "quote": "Калийные соли | - | - | - | То же | То же | Аномально высокие | То же", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c10"}, {"page_print": null, "text": "Если содержание глинистого материала велико, показания и других методов могут резко измениться.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.01", "quote": "если содержание глинистого материала велико, то могут резко измениться показания и других методов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c11"}, {"page_print": null, "text": "Резкое изменение показаний при высокой глинистости затрудняет выделение такого коллектора.", "kind": "inference", "page_pdf": 95, "unit_id": "p095.01", "quote": "что вызовет затруднение в выделении такого коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c12"}, {"page_print": null, "text": "Загипсованность пород приводит к уменьшению показаний НГМ.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.01", "quote": "Загипсованность пород приводит к уменьшению показаний НГМ.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c13"}, {"page_print": null, "text": "Всё перечисленное (высокая глинистость, загипсованность) в значительной степени затрудняет построение разреза.", "kind": "inference", "page_pdf": 95, "unit_id": "p095.01", "quote": "Все это в значительной степени затруднит построение разреза.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c14"}, {"page_print": null, "text": "Из таблицы 21 следует: если разрезы представлены породами с ясно выраженными свойствами, литологическую колонку в некоторых случаях можно удовлетворительно составить по данным небольшого числа методов.", "kind": "inference", "page_pdf": 95, "unit_id": "p095.02", "quote": "в некоторых случаях, когда разрезы представлены породами с ясно выраженными свойствами, литологическая колонка может быть вполне удовлетворительно составлена на основании данных небольшого числа методов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c15"}, {"page_print": null, "text": "Для терригенного разреза, где плотные слабоглинистые карбонатные породы имеют подчиненное значение, задачу можно достаточно хорошо решить одними электрическими методами.", "kind": "inference", "page_pdf": 95, "unit_id": "p095.02", "quote": "Например для терригенного разреза, в котором плотные, слабоглинистые карбонатные разности пород имеют подчиненное значение, задача может быть достаточно хорошо решена с помощью одних лишь электрических методов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c16"}, {"page_print": null, "text": "При построении разрезов скважин в гидрохимических отложениях большую роль играют методы рассеянного гамма-излучения и акустический.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.06", "quote": "При построении разрезов скважин, вскрывающих гидрохимические отложения, большую роль играют методы рассеянного гамма-излучения и акустический", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c17"}, {"page_print": null, "text": "Эти методы позволяют выделить гипсы, ангидриты, известняки и соли по характерным для них константам, приведенным в табл. 14, 16, 19.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.06", "quote": "которые позволяют выделить гипсы, ангидриты, известняки и соли по характерным для них константам (см. табл. 14, 16, 19)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.table21_carbonates_salts#c18"}], "id": "latyshova.table21_carbonates_salts", "order": 12, "minutes": 3, "essence": "Таблица 21 продолжается строками для глинистых известняков и мергелей, ангидритов, плотных известняков, гипсов, галита и калийных солей. Литологическую колонку можно составить по немногим методам, если породы разреза выражены ясно. В гидрохимических разрезах главную роль играют методы рассеянного гамма-излучения и акустический.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Каждая строка таблицы описывает породу набором значений по методам. Названия столбцов стоят на предыдущей странице и в этой части главы не даны. Поэтому здесь значения читаются только по порядку столбцов.", "pages": [94]}, {"text": "Глинистые известняки и мергели: отсутствие проникновения, максимальные и резко меняющиеся значения. Ангидриты и чистые плотные кристаллические известняки: отсутствие проникновения и d_c = d_a. Диаметр скважины d_c равен номинальному d_a, то есть каверн нет.", "pages": [94]}, {"text": "У гипсов почти все значения «то же», что у ангидритов. Различает их последний столбец: у гипсов «минимальные», у ангидритов «максимальные». У галита d_c = d_a только при предельном насыщении раствора солью.", "pages": [94]}, {"text": "Показания по галиту меняются с диаметром скважины от средних до очень высоких. У калийных солей одно значение названо аномально высоким, остальные такие же, как у галита.", "pages": [94]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Если разрез состоит из пород с ясно выраженными свойствами, колонку можно составить по небольшому числу методов. Пример автора: терригенный разрез, где плотные слабоглинистые карбонаты подчинены. Там хватает одних электрических методов.", "pages": [95]}, {"text": "В гидрохимических разрезах гипсы, ангидриты, известняки и соли выделяют по их константам. Для этого используют методы рассеянного гамма-излучения и акустический. Константы даны в таблицах 14, 16 и 19.", "pages": [95]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Высокая глинистость может резко изменить показания других методов. Тогда коллектор труднее выделить. Загипсованность снижает показания НГМ.", "pages": [95]}, {"text": "Из-за этого построить разрез сложнее. Глинистые известняки и мергели могут иметь и межзерновую, и трещинную пористость. Для соли «таблица» зависит от диаметра скважины.", "pages": [94]}, {"text": "Если раствор не насыщен солью, d_c » d_a, и показания меняются от средних до очень высоких.", "pages": [94]}]}], "deeper": [{"text": "Таблица дает качественные признаки: «максимальные», «минимальные», «то же», прочерк. Числовых порогов в этой части главы нет. Прочерк в ячейке автор не поясняет. Первая строка таблицы на этой странице обрезана: её начало осталось на предыдущей странице.", "pages": [94]}], "glossary": [], "format": "карточки", "tasks": [{"id": "latyshova.table21_carbonates_salts.t1", "type": "single", "step_id": "latyshova.table21_carbonates_salts", "claim_ids": ["latyshova.table21_carbonates_salts#c15", "latyshova.table21_carbonates_salts#c16"], "prompt": "Разрез терригенный, плотные слабоглинистые карбонатные породы в нём подчинены, а свойства пород выражены ясно. Какого набора методов достаточно для литологической колонки?", "options": [{"id": "a", "text": "Одних электрических методов", "misconception": null}, {"id": "b", "text": "Только методов рассеянного гамма-излучения и акустического", "misconception": null}, {"id": "c", "text": "Только нейтронных методов после обсадки", "misconception": null}, {"id": "d", "text": "Полного комплекса из всех групп без исключений", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "При ясно выраженных свойствах пород колонку можно составить по небольшому числу методов, здесь по электрическим.", "kind": "transfer"}, {"id": "latyshova.table21_carbonates_salts.t2", "type": "multiple", "step_id": "latyshova.table21_carbonates_salts", "claim_ids": ["latyshova.table21_carbonates_salts#c17", "latyshova.table21_carbonates_salts#c18"], "prompt": "Какие методы играют главную роль при построении разрезов в гидрохимических отложениях (гипсы, ангидриты, известняки, соли)? Выберите все верные.", "options": [{"id": "a", "text": "Методы рассеянного гамма-излучения", "misconception": null}, {"id": "b", "text": "Акустический метод", "misconception": null}, {"id": "c", "text": "Метод СП", "misconception": null}, {"id": "d", "text": "Кавернометрия", "misconception": null}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "Эти породы выделяют по константам, полученным методами рассеянного гамма-излучения и акустическим.", "kind": "recall"}], "pictures": [{"id": "latyshova.table21_carbonates_salts.i1", "step_id": "latyshova.table21_carbonates_salts", "node_id": "latyshova.table21_carbonates_salts", "file": "pictures/table21_carbonates_salts_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Гипсы повторяют ангидриты почти во всём; различает их только последний столбец таблицы.", "alt": "Сравнение ангидритов и гипсов: проникновения нет и диаметр равен номинальному у обоих, отличается лишь последний столбец: максимум у ангидритов, минимум у гипсов.", "source": "построено кодом по утверждениям главы, стр. 94", "claim_ids": ["latyshova.table21_carbonates_salts#c5", "latyshova.table21_carbonates_salts#c6", "latyshova.table21_carbonates_salts#c7"], "prompt": null}]}, {"title": "Смешанные разрезы: когда колонку нельзя составить качественно и нужна количественная интерпретация", "short_title": "Смешанный разрез на практике", "why_here": {"text": "Закрепляет таблицу 21 на рис. 68 и объясняет границу применимости качественных признаков.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Н"}, "threshold": false, "pages": [95], "misconception": {"ref": null, "text": "Заблуждение: по любому комплексу диаграмм литологическую колонку можно однозначно построить по таблице качественных признаков. В смешанном терригенно-карбонатном разрезе с разными флюидами это не так, и задача 91 требует отметить неоднозначные интервалы.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: комплекс диаграмм ГИС по участку разреза (рис. 68; в подписи d_r=0,25m, p_p=1,2 Ом·м при температуре пласта). По описанию программы распознавания это кавернограмма, СП, микрозонды, ГМ, НГМ по глубине 2190–2250 м. Выход: литологическая колонка с отмеченными неоднозначными интервалами (задача 91).", "by_model": true}, "breaks": {"text": "Качественный подход ломается, когда есть терригенные и карбонатные породы с разными типами пор, насыщенные водой разной минерализации, нефтью или газом. Тогда колонка и коллектор определяются лишь количественной интерпретацией с геологическими сведениями.", "by_model": true}, "hypotheses": [{"text": "Неоднозначными, вероятно, окажутся интервалы, где признаки таблицы 21 для разных пород и насыщений совпадают или противоречат друг другу.", "by_model": true, "hypothesis": true}, {"text": "Выбор между литотипами, видимо, придётся подкреплять данными за пределами диаграммы, например керном или геологическим описанием.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это как классификатор на простых правилах if-else по признакам. Он годится, пока классы не пересекаются. Когда входные данные смешанные и признаки неоднозначны, нужна количественная модель плюс контекст предметной области.", "breaks_where": "У правил в коде есть заданный набор классов и чёткие условия, а в разрезе неоднозначность идёт от природы пород и флюидов, и контекст берётся из геологии.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Комплекс диаграмм ГИС по участку разреза (рис. 68), таблица 21, геологические сведения о разрезе.", "manual_steps": "Специалист вручную сопоставляет кривые по глубине, строит литологическую колонку и помечает интервалы, где интерпретация неоднозначна.", "judgment_points": "Решение, хватает ли качественных признаков или нужна количественная интерпретация; выбор литотипа и флюида в спорных интервалах; привлечение геологических сведений.", "time": "в главе не указано", "typical_errors": "В главе прямо не названы; задача 91 подразумевает риск принять неоднозначный интервал за однозначный.", "by_model": true}, "decision_on_data": {"features": ["В разрезе есть и терригенные, и карбонатные породы", "Типы порового пространства различаются", "Насыщение: вода разной минерализации, нефть или газ"], "rule": "Если эти признаки присутствуют вместе, разрез и коллектор определяют количественной интерпретацией геофизических данных с привлечением геологических сведений.", "conclusion": "Колонку по одним качественным признакам строить нельзя, интервалы с неоднозначной интерпретацией надо отмечать.", "counterexample": "В главе прямо не приведён. По противопоставлению «Однако» в разрезе без такого сочетания колонка строится по качественным признакам."}, "worked_examples": [], "book_tasks": [{"number": "90", "page_pdf": 95, "text": "Построить литологическую колонку на основании диаграмм комплекса методов, приведенных на рис. 14, 58. Дать объяснение, какие группы методов дают информацию о границах плотных пород, коллекторов, глин. Какие методы позволяют выделить интервалы повышенной пористости? Какие методы дают возможность судить о продуктивности выделенных коллекторов? Какими исследованиями необходимо располагать, чтобы точно установить, имеются ли в разрезе газоносные коллекторы?", "figure": "рис. 14, рис. 58"}, {"number": "91", "page_pdf": 95, "text": "Построить литологическую колонку на основании диаграмм комплекса методов, изображенных на рис. 68. Отметить интервалы, в которых интерпретация не является однозначной.", "figure": "рис. 68, стр. 95"}], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.build_litho_column"}, {"type": "prerequisite", "target": "latyshova.table21_clays_sands_gas"}, {"type": "prerequisite", "target": "latyshova.table21_carbonates_salts"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.four_method_groups"}], "needs_scan": [{"page": 95, "what": "Рис. 68: сам рисунок, шкалы кривых (часть нечитаема), расшифровка ГМ/НГМ и обозначений в подписи d_r, p_p; описание программы распознавания ненадёжно."}], "claims": [{"page_print": null, "text": "Если в разрезе вместе встречаются терригенные и карбонатные породы, то построение разреза и особенно выделение коллектора можно осуществить лишь на основании количественной интерпретации геофизических данных.", "kind": "inference", "page_pdf": 95, "unit_id": "p095.05", "quote": "построение разреза и особенно выделение коллектора можно осуществить лишь на основании количественной интерпретации геофизических данных с привлечением геологических сведений о характере разреза.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c1"}, {"page_print": null, "text": "Условие трудности: в разрезе встречаются и терригенные, и карбонатные породы с различными типами порового пространства.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.05", "quote": "Однако, если в разрезе встречаются как терригенные, так и карбонатные породы с различными типами порового пространства", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c2"}, {"page_print": null, "text": "Условие трудности: породы насыщены водой разной минерализации, нефтью или газом.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.05", "quote": "насыщенные водой разной минерализации, нефтью или газом", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c3"}, {"page_print": null, "text": "Количественную интерпретацию в смешанном разрезе нужно вести с привлечением геологических сведений о характере разреза.", "kind": "inference", "page_pdf": 95, "unit_id": "p095.05", "quote": "с привлечением геологических сведений о характере разреза.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c4"}, {"page_print": null, "text": "Особенно трудно в таком разрезе именно выделение коллектора, наряду с построением разреза.", "kind": "inference", "page_pdf": 95, "unit_id": "p095.05", "quote": "построение разреза и особенно выделение коллектора можно осуществить", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c5"}, {"page_print": null, "text": "Рис. 68 представляет комплекс диаграмм методов ГИС по участку терригенно-карбонатного разреза.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.04", "quote": "Комплекс диаграмм методов ГИС по участку терригенно-карбонатного разреза", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c6"}, {"page_print": null, "text": "В подписи к рис. 68 указаны d_r=0,25m и p_p=1,2 Ом·м при температуре пласта.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.04", "quote": "\\( d_{r}=0,25m \\) ;  \\( p_{p}=1,2 \\)  Ом·м при температуре пласта", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c7"}, {"page_print": null, "text": "Задача 91: построить литологическую колонку по диаграммам комплекса методов, изображённым на рис. 68.", "kind": "assumption", "page_pdf": 95, "unit_id": "p095.08", "quote": "91. Построить литологическую колонку на основании диаграмм комплекса методов, изображенных на рис. 68.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c8"}, {"page_print": null, "text": "Задача 91: отметить интервалы, в которых интерпретация не является однозначной.", "kind": "assumption", "page_pdf": 95, "unit_id": "p095.08", "quote": "Отметить интервалы, в которых интерпретация не является однозначной.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c9"}, {"page_print": null, "text": "Задача 90: построить литологическую колонку по диаграммам комплекса методов, приведённым на рис. 14 и 58.", "kind": "assumption", "page_pdf": 95, "unit_id": "p095.08", "quote": "90. Построить литологическую колонку на основании диаграмм комплекса методов, приведенных на рис. 14, 58.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c10"}, {"page_print": null, "text": "Задача 90: объяснить, какие группы методов дают информацию о границах плотных пород, коллекторов и глин.", "kind": "assumption", "page_pdf": 95, "unit_id": "p095.08", "quote": "Дать объяснение, какие группы методов дают информацию о границах плотных пород, коллекторов, глин.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c11"}, {"page_print": null, "text": "Задача 90: назвать методы, позволяющие выделить интервалы повышенной пористости, и методы, позволяющие судить о продуктивности выделенных коллекторов.", "kind": "assumption", "page_pdf": 95, "unit_id": "p095.08", "quote": "Какие методы позволяют выделить интервалы повышенной пористости? Какие методы дают возможность судить о продуктивности выделенных коллекторов?", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c12"}, {"page_print": null, "text": "Задача 90: указать, какими исследованиями необходимо располагать, чтобы точно установить наличие газоносных коллекторов в разрезе.", "kind": "assumption", "page_pdf": 95, "unit_id": "p095.08", "quote": "Какими исследованиями необходимо располагать, чтобы точно установить, имеются ли в разрезе газоносные коллекторы?", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.mixed_section_practice#c13"}, {"page_print": null, "text": "По описанию программы распознавания, диаграмма охватывает глубины 2190–2250 м, глубина увеличивается вниз.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "Глубина: 2190–2250 м; шкала глубины направлена вниз, глубина увеличивается вниз.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c14"}, {"page_print": null, "text": "По описанию программы распознавания, на диаграмме присутствует кавернограмма с кривой изменения диаметра ствола; подписи её шкалы нечитаемы.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "Кавернограмма: подписи шкалы [нрзб]; присутствует кривая изменения диаметра ствола.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c15"}, {"page_print": null, "text": "По описанию программы распознавания, кривая СП показана сплошной линией со шкалой 0, 25, 50, 75.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "СП: шкала 0, 25, 50, 75 [нрзб]; показана сплошной кривой.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c16"}, {"page_print": null, "text": "По описанию программы распознавания, микрозонды A 0,05М и A 0,025М показаны на общей шкале 48, 16, 0, 16, 48 Ом·м.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "шкала: 48, 16, 0, 16, 48 Ом·м.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c17"}, {"page_print": null, "text": "По описанию программы распознавания, на диаграмме есть кривая ГМ со шкалой 1, 3, 5.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "6. ГМ: шкала 1, 3, 5 [нрзб].", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c18"}, {"page_print": null, "text": "По описанию программы распознавания, в интервале 2190–2210 м микрозонды дают частые узкие пики, а ГМ и НГМ — широкие изменения показаний.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "ГМ и НГМ имеют широкие изменения показаний.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c19"}, {"page_print": null, "text": "По описанию программы распознавания, в интервале 2210–2230 м на ГМ и НГМ есть пунктирные участки кривых.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "На ГМ и НГМ присутствуют пунктирные участки кривых.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c20"}, {"page_print": null, "text": "По описанию программы распознавания, в интервале 2230–2250 м в нижней части микрозондов есть интенсивная пачка пиков.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "Микрозонды: в нижней части отмечается интенсивная пачка пиков.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c21"}, {"page_print": null, "text": "По описанию программы распознавания, НГМ резко отклоняется вправо вблизи 2245–2250 м.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "НГМ резко отклоняется вправо вблизи 2245–2250 м.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c22"}, {"page_print": null, "text": "По описанию программы распознавания, литология на диаграмме не показана и без легенды не определяется.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "Литология не показана; литология не определяется без легенды", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c23"}, {"page_print": null, "text": "По описанию программы распознавания, отбивки пластов и результаты интерпретации на диаграмме не подписаны.", "kind": "observation", "page_pdf": 95, "unit_id": "p095.03", "quote": "Отбивки пластов и результаты интерпретации не подписаны.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.mixed_section_practice#c24"}], "id": "latyshova.mixed_section_practice", "order": 13, "minutes": 3, "essence": "Если в разрезе вместе встречаются терригенные и карбонатные породы, колонку и особенно коллектор можно выделить лишь количественной интерпретацией. Причина в сочетании разных типов порового пространства и разных флюидов: вода разной минерализации, нефть, газ. К количественным данным добавляют геологические сведения о характере разреза. Закрепляется на рис. 68 и задаче 91, где нужно отметить неоднозначные интервалы.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Глава называет только условия, при которых качественный подход не работает. Это одновременное присутствие терригенных и карбонатных пород и различные типы порового пространства. Ещё это насыщение водой разной минерализации, нефтью или газом.", "pages": [95]}, {"text": "Причинное объяснение, почему именно так, в этой части главы не приведено. Качественная интерпретация — это оценка по виду кривых и таблице признаков. Количественная — это расчёт параметров по данным ГИС.", "pages": [95]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Сначала по комплексу диаграмм пытаются построить колонку по признакам таблицы 21. Для рис. 68 по условию задачи 91 нужно построить колонку и отметить интервалы с неоднозначной интерпретацией.", "pages": [95]}, {"text": "В задаче 90 по рис. 14 и 58 надо ещё объяснить роль групп методов. Они дают границы плотных пород, коллекторов и глин, интервалы повышенной пористости и признаки продуктивности.", "pages": [95]}, {"text": "Для газоносных коллекторов нужно назвать исследования, дающие точный ответ. Этот ответ в этой части главы не приведён.", "pages": [95]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Автор пишет «особенно выделение коллектора»: именно коллектор в смешанном разрезе труднее всего выделить. Одних геофизических данных мало: нужны ещё геологические сведения о характере разреза. Описание рисунка сделано программой распознавания, часть шкал нечитаема ([нрзб]), литология и отбивки пластов на нём не подписаны.", "pages": [95]}, {"text": "Поэтому выводы по самому рисунку требуют проверки по скану.", "pages": [95]}]}], "deeper": [{"text": "Рис. 68 в подписи назван комплексом диаграмм по участку терригенно-карбонатного разреза. В подписи заданы d_r=0,25m и p_p=1,2 Ом·м при температуре пласта. Смысл d_r и p_p в этой части главы не раскрыт. По описанию программы распознавания на диаграмме глубины 2190–2250 м и кривые: кавернограмма, СП, кривая МКЗМ 0,75А, два микрозонда, ГМ и НГМ. Обозначения ГМ и НГМ в этой части главы не расшифрованы.", "pages": [95]}], "glossary": [], "format": "практикум на данных", "tasks": [{"id": "latyshova.mixed_section_practice.t1", "type": "single", "step_id": "latyshova.mixed_section_practice", "claim_ids": ["latyshova.mixed_section_practice#c1", "latyshova.mixed_section_practice#c2", "latyshova.mixed_section_practice#c3"], "prompt": "В разрезе чередуются терригенные и карбонатные породы с разными типами порового пространства, а насыщены они водой разной минерализации, нефтью и газом. Как надо строить литологическую колонку и выделять коллектор?", "options": [{"id": "a", "text": "По одной таблице качественных признаков, сверяя вид кривых", "misconception": "misc.qualitative_always_works"}, {"id": "b", "text": "Только по кавернограмме, по сужению диаметра ствола", "misconception": null}, {"id": "c", "text": "Количественной интерпретацией с привлечением геологических сведений", "misconception": null}, {"id": "d", "text": "Колонку строить не нужно, пока нет керна по всему разрезу", "misconception": null}], "answer": "c", "tolerance": null, "unit": null, "explanation": "При сочетании разных пород, пор и флюидов качественных признаков недостаточно, нужны количественная интерпретация и геологические сведения.", "kind": "understanding"}, {"id": "latyshova.mixed_section_practice.t2", "type": "multiple", "step_id": "latyshova.mixed_section_practice", "claim_ids": ["latyshova.mixed_section_practice#c2", "latyshova.mixed_section_practice#c3"], "prompt": "Какие условия делают качественное построение колонки в смешанном разрезе невозможным? Выберите все верные.", "options": [{"id": "a", "text": "Одновременное присутствие терригенных и карбонатных пород", "misconception": null}, {"id": "b", "text": "Различные типы порового пространства", "misconception": null}, {"id": "c", "text": "Насыщение водой разной минерализации, нефтью или газом", "misconception": null}, {"id": "d", "text": "Наличие в комплексе более трёх методов ГИС", "misconception": null}], "answer": ["a", "b", "c"], "tolerance": null, "unit": null, "explanation": "Глава называет три условия: смесь терригенных и карбонатных пород, разные поры и разное насыщение.", "kind": "recall"}], "pictures": [{"id": "latyshova.mixed_section_practice.i1", "step_id": "latyshova.mixed_section_practice", "node_id": "latyshova.mixed_section_practice", "file": "pictures/mixed_section_practice_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Смешанный разрез и разные флюиды делают необходимой количественную интерпретацию: только она позволяет выделить коллектор.", "alt": "Схема: две причины трудности, смесь терригенных и карбонатных пород и разные флюиды, ведут к количественной интерпретации с геологическими сведениями, а она к построению разреза и выделению коллектора.", "source": "построено кодом по утверждениям главы, стр. 95", "claim_ids": ["latyshova.mixed_section_practice#c1", "latyshova.mixed_section_practice#c2", "latyshova.mixed_section_practice#c3", "latyshova.mixed_section_practice#c4", "latyshova.mixed_section_practice#c5"], "prompt": null}]}, {"title": "Прямые признаки коллектора в межзерновом разрезе и роль качества раствора", "short_title": "Прямые признаки коллектора", "why_here": {"text": "Опирается на корку, проникновение и микрозонды; переходит от общей картины к самому выделению коллектора.", "by_model": true}, "difficulty": {"primary": "Р", "secondary": "М"}, "threshold": true, "pages": [96], "misconception": null, "data_meaning": {"from_chapter": {"text": "Входом служат диаграммы каверномера (диаметр скважины против номинального), микрозондов (ГМЗ и ПМЗ) и БЭЗ или разноглубинных зондов. Выход — качественный вывод, коллектор перед нами или нет. Кривая сопротивления микрозондов должна давать положительное приращение при невысоких показаниях.", "by_model": true}, "breaks": {"text": "Признаки ломаются при плохом растворе: толстая корка (3-4 см) закрывает промытую зону и тонкие прослои. При росте минерализации качественных диаграмм микрозондов практически нет. На технической воде признаки по микрозондам и кавернограмме обычно отсутствуют. Зона проникновения не обязательна и у продуктивного коллектора может не проявиться.", "by_model": true}, "hypotheses": [{"text": "Числовые пороги «малой водоотдачи», «невысокой минерализации» и «невысоких показаний» в главе здесь не заданы; их нужно искать в таблице 21 или в других параграфах.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на оповещение по нескольким метрикам мониторинга: диаметр, микрозонды и зонды глубокого проникновения. Вывод «сервис работал» делают по совпадению нескольких следов, и не каждый след обязателен.", "breaks_where": "В мониторинге качество метрик обычно не зависит от состояния самого объекта. Здесь качество раствора определяет, будут ли признаки вообще видны, а при технической воде сам канал измерения теряет чувствительность.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы каверномера, микрозондов (ГМЗ, ПМЗ), БЭЗ или разноглубинных зондов, сведения о качестве раствора, табл. 21.", "manual_steps": "Сравнить диаметр скважины с номинальным, найти положительное приращение микрозондов и проверить наличие зоны проникновения по зондам разной глубины.", "judgment_points": "Оценить, достаточно ли качествен раствор для применения признаков, и учесть, что зона проникновения не обязательна. Решить, что делать при толстой корке или технической воде.", "time": "в главе не указано", "typical_errors": "Применение признаков при плохом растворе или технической воде, где они обычно отсутствуют. Требование зоны проникновения как обязательного признака. Потеря тонких прослоев под толстой коркой.", "by_model": true}, "decision_on_data": {"features": ["dᵢ < dₙ (сужение диаметра за счёт корки)", "ρₙГМЗ < ρₙПМЗ при невысоких показаниях микрозондов", "зона проникновения или радиальный градиент сопротивления по БЭЗ или разноглубинным зондам", "качественный раствор с малой водоотдачей и невысокой минерализацией"], "rule": "При качественном глинистом растворе наличие сужения диаметра и положительных приращений микрозондов указывает на проницаемый коллектор; зона проникновения подтверждает, но не обязательна.", "conclusion": "Пласт можно отнести к коллектору, если по табл. 21 совпадают прямые признаки при пригодном качестве раствора.", "counterexample": "Продуктивный коллектор может не иметь выраженной зоны проникновения (ρₘ ≈ ρₘ). При плохом растворе, высокой минерализации или технической воде признаки по микрозондам и кавернограмме могут отсутствовать, хотя пласт проницаем."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["прямые качественные признаки", "косвенные количественные признаки", "положительное приращение микрозондов", "толщина глинистой корки"], "links": [{"type": "prerequisite", "target": "latyshova.goals_of_log_interpretation"}, {"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.water_loss_and_mud_density"}, {"type": "prerequisite", "target": "latyshova.filtrate_salinity"}, {"type": "prerequisite", "target": "latyshova.water_and_nonfiltering_muds"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}], "needs_scan": [{"page": 96, "what": "Формулы в тексте (ρₘ ≈ ρₘ, hᵣₓ, dᵢ) выглядят искажёнными при распознавании; сверить индексы по скану."}], "claims": [{"page_print": null, "text": "Геофизическое выделение коллектора опирается на его отличие от вмещающих неколлекторов по проницаемости, пористости и глинистости.", "kind": "inference", "page_pdf": 96, "unit_id": "p096.03", "quote": "является его отличие от вмещающих пород-неколлекторов по проницаемости, пористости, глинистости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c1"}, {"page_print": null, "text": "Признаки коллектора делятся на прямые качественные и косвенные количественные.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.03", "quote": "Признаки коллектора делятся на прямые качественные и косвенные количественные.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c2"}, {"page_print": null, "text": "Прямые признаки указывают на возможность фильтрации в порах коллектора воды, нефти, газа и фильтрата бурового раствора.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.04", "quote": "Прямые признаки указывают на возможность фильтрации в порах коллектора воды, нефти, газа и фильтрата бурового раствора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c3"}, {"page_print": null, "text": "При бурении на качественном глинистом растворе с малой водоотдачей и невысокой минерализацией признаки коллектора устанавливают в соответствии с табл. 21.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.04", "quote": "При бурении на качественном глинистом растворе с малой водоотдачей и невысокой минерализацией признаки коллектора устанавливают в соответствии с табл. 21", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c4"}, {"page_print": null, "text": "Первый прямой признак — сужение диаметра скважины за счёт образования глинистой корки (dᵢ < dₙ).", "kind": "observation", "page_pdf": 96, "unit_id": "p096.04", "quote": "сужение диаметра за счет образования глинистой корки (dᵢ < dₙ)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c5"}, {"page_print": null, "text": "Второй прямой признак — положительные приращения на диаграмме микрозондов (ρₙГМЗ < ρₙПМЗ) при невысоких значениях их показаний.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.04", "quote": "положительные приращения на диаграмме микрозондов (ρₙГМЗ < ρₙПМЗ) при невысоких значениях их показаний", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c6"}, {"page_print": null, "text": "Третий прямой признак — наличие зоны проникновения или радиального градиента сопротивления в пласте по данным БЭЗ или диаграмм разноглубинных зондов.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.04", "quote": "наличие зоны проникновения или радиального градиента сопротивления в пласте по данным БЭЗ или диаграмм разноглубинных зондов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c7"}, {"page_print": null, "text": "Признак зоны проникновения не обязателен, поскольку в продуктивных коллекторах могут создаваться условия, при которых сопротивления в зонах примерно равны (ρₘ ≈ ρₘ в тексте).", "kind": "observation", "page_pdf": 96, "unit_id": "p096.04", "quote": "Последний признак не является обязательным, поскольку в продуктивных коллекторах могут создаваться условия, при которых ρₘ ≈ ρₘ.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c8"}, {"page_print": null, "text": "При ухудшении качества глинистого раствора с ростом его водоотдачи глинистая корка на поверхности коллектора увеличивается.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "При ухудшении качества глинистого раствора с увеличением его водоотдачи возрастает глинистая корка на поверхности коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c9"}, {"page_print": null, "text": "В хороших условиях толщина глинистой корки не превышает 1 см.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "hᵣₓ ≤ 1 см в хороших условиях", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c10"}, {"page_print": null, "text": "При плохом растворе толщина глинистой корки достигает 3-4 см.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "достигает 3-4 см при плохом растворе", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c11"}, {"page_print": null, "text": "При росте толщины корки разница в показаниях микрозондов сначала возрастает, а потом убывает.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "разница в показаниях микрозондов сначала возрастает, а потом убывает", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c12"}, {"page_print": null, "text": "При больших значениях толщины корки исключается возможность исследования промытой зоны микрометодами.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "При больших значениях толщины глинистой корки исключается возможность исследования промытой зоны микрометодами", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c13"}, {"page_print": null, "text": "При толстой корке тонкие прослои неколлекторов (глин и плотных пластов) в коллекторе перестают выделяться, так как корка покрывает и эти прослои.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "тонкие прослои неколлекторов в коллекторе (глин и плотных пластов) перестают выделяться, так как корка покрывает и эти прослои", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c14"}, {"page_print": null, "text": "При возрастании минерализации раствора корки на стенках коллекторов образуются, но качественные диаграммы микрозондов практически не получаются.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "При возрастании минерализации раствора корки на стенках коллекторов образуются, но качественные диаграммы микрозондов практически не получаются.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c15"}, {"page_print": null, "text": "При бурении на технической воде признаки коллекторов на диаграммах микрозондов и кавернограммах обычно отсутствуют.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "При бурении на технической воде признаки коллекторов на диаграммах микрозондов и кавернограммах обычно отсутствуют", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c16"}, {"page_print": null, "text": "Слабые признаки коллекторов на этих диаграммах при технической воде появляются лишь при значительном обогащении промывочной жидкости глиной из выбуренных пород.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.05", "quote": "лишь при значительном обогащении промывочной жидкости глиной из выбуренных пород появляются слабые признаки коллекторов на этих диаграммах", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c17"}, {"page_print": null, "text": "Примеры выделения межзерновых коллекторов при бурении на качественном глинистом растворе приведены на рис. 14, 58, 68, 76.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.06", "quote": "Примеры выделения межзерновых коллекторов при бурении на качественном глинистом растворе приведены на рис. 14, 58, 68, 76.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.direct_signs_of_collector#c18"}], "id": "latyshova.direct_signs_of_collector", "order": 14, "minutes": 3, "essence": "Коллектор отличается от неколлектора проницаемостью, пористостью и глинистостью. Его признаки делятся на прямые качественные и косвенные количественные. Прямые признаки показывают, что в порах возможна фильтрация воды, нефти, газа и фильтрата. При качественном растворе это сужение диаметра из-за глинистой корки, положительные приращения микрозондов и зона проникновения.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Если порода проницаема, фильтрат раствора уходит в поры, а на стенке остаётся глинистая корка. Из-за корки диаметр скважины становится меньше номинального (dᵢ < dₙ). Корка и промытая зона по-разному влияют на два микрозонда, поэтому показания ГМЗ оказываются ниже показаний ПМЗ.", "pages": [96]}, {"text": "Это и есть положительное приращение. Фильтрат, проникший в пласт, создаёт зону проникновения, то есть радиальный градиент сопротивления. Его видно по БЭЗ или по разноглубинным зондам.", "pages": [96]}, {"text": "Когда раствор ухудшается, водоотдача растёт и корка утолщается. Толщина корки hᵣₓ обычно не больше 1 см, а при плохом растворе достигает 3-4 см. Разница показаний микрозондов сначала растёт, затем убывает.", "pages": [96]}, {"text": "При толстой корке промытую зону микрометодами уже не исследовать.", "pages": [96]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "При качественном глинистом растворе с малой водоотдачей и невысокой минерализацией признаки ищут по табл. 21. Проверяют три вещи: сужение диаметра по каверномеру, положительное приращение микрозондов при невысоких показаниях и зону проникновения.", "pages": [96]}, {"text": "Примеры выделения межзерновых коллекторов автор отсылает на рис. 14, 58, 68, 76. При ухудшении раствора сначала смотрят на толщину корки.", "pages": [96]}, {"text": "При технической воде признаки по микрозондам и кавернограмме обычно отсутствуют, и надо опираться на другие методы комплекса.", "pages": [96]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Зона проникновения не обязательна для вывода о коллекторе. В продуктивных коллекторах возможны условия, при которых сопротивления в зонах сближаются. Признаки зависят от раствора.", "pages": [96]}, {"text": "При большой толщине корки тонкие прослои глин и плотных пластов в коллекторе не выделяются, потому что корка покрывает и их. При росте минерализации корки образуются, но качественных диаграмм микрозондов практически нет. При технической воде слабые признаки появляются лишь при значительном обогащении жидкости глиной из выбуренных пород.", "pages": [96]}]}], "deeper": [{"text": "В шаге названы косвенные количественные признаки, но их содержание в этой части главы не раскрыто. Рисунки 14, 58, 68, 76 в шаге не разбираются и только упомянуты. Конкретные пороги «невысоких» показаний микрозондов и минерализации в этой части главы не заданы.", "pages": [96]}], "glossary": [{"term": "прямые качественные признаки", "definition": "Признаки коллектора, указывающие на возможность фильтрации воды, нефти, газа и фильтрата в порах: сужение диаметра из-за корки, положительные приращения микрозондов, зона проникновения."}, {"term": "косвенные количественные признаки", "definition": "Вторая группа признаков коллектора, противопоставленная прямым качественным. В этой части главы названа, но не раскрыта."}, {"term": "положительное приращение микрозондов", "definition": "Ситуация, когда на диаграмме микрозондов показание ГМЗ меньше показания ПМЗ (ρₙГМЗ < ρₙПМЗ) при невысоких значениях показаний; признак коллектора."}, {"term": "толщина глинистой корки", "definition": "Толщина hᵣₓ корки на стенке против коллектора: обычно не больше 1 см, при плохом растворе достигает 3-4 см."}], "format": "карточки", "tasks": [{"id": "latyshova.direct_signs_of_collector.t1", "type": "gap", "step_id": "latyshova.direct_signs_of_collector", "claim_ids": ["latyshova.direct_signs_of_collector#c5", "latyshova.direct_signs_of_collector#c6"], "prompt": "При качественном глинистом растворе диаметр скважины против коллектора {{1}} номинального из-за образования {{2}}, а показания градиент-микрозонда ГМЗ {{3}} показаний потенциал-микрозонда ПМЗ (положительное приращение).", "options": [], "answer": ["меньше", "глинистой корки", "ниже"], "tolerance": null, "unit": null, "explanation": "Корка сужает ствол (dᵢ < dₙ), а положительное приращение означает ρГМЗ < ρПМЗ.", "kind": "recall"}, {"id": "latyshova.direct_signs_of_collector.t2", "type": "single", "step_id": "latyshova.direct_signs_of_collector", "claim_ids": ["latyshova.direct_signs_of_collector#c16", "latyshova.direct_signs_of_collector#c17"], "prompt": "Скважину бурили на технической воде. Против пласта на микрозондах нет положительных приращений, а на кавернограмме нет сужения диаметра. Какой вывод правильный?", "options": [{"id": "a", "text": "Пласт не коллектор, раз прямых признаков нет", "misconception": "misc.no_signs_no_collector"}, {"id": "b", "text": "Признаки при такой промывке обычно отсутствуют, нужны другие методы комплекса", "misconception": null}, {"id": "c", "text": "Микрозонды вышли из строя, замер надо отбраковать", "misconception": null}, {"id": "d", "text": "Пласт является коллектором, раз корка не образовалась", "misconception": null}], "answer": "b", "tolerance": null, "unit": null, "explanation": "При технической воде корки нет, поэтому признаки по микрозондам и каверномеру обычно отсутствуют и опираться надо на другие методы.", "kind": "transfer"}], "pictures": [{"id": "latyshova.direct_signs_of_collector.i1", "step_id": "latyshova.direct_signs_of_collector", "node_id": "latyshova.direct_signs_of_collector", "file": "pictures/direct_signs_of_collector_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Прямые признаки коллектора при качественном глинистом растворе: узкий ствол, положительные приращения микрозондов, зона проникновения.", "alt": "Схема: возможность фильтрации в порах проявляется прямыми признаками: сужением диаметра скважины, положительными приращениями микрозондов и зоной проникновения.", "source": "построено кодом по утверждениям главы, стр. 96", "claim_ids": ["latyshova.direct_signs_of_collector#c3", "latyshova.direct_signs_of_collector#c4", "latyshova.direct_signs_of_collector#c5", "latyshova.direct_signs_of_collector#c6", "latyshova.direct_signs_of_collector#c7"], "prompt": null}]}, {"title": "Радиальный градиент сопротивления и динамические методы выделения коллектора", "short_title": "Градиент сопротивления и повторные замеры", "why_here": {"text": "Опирается на повышающее и понижающее проникновение; даёт запасной способ, когда статические признаки не работают.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "Н"}, "threshold": false, "pages": [96], "misconception": {"ref": null, "text": "Если у зондов разной глубины сопротивление одинаковое и градиента нет, значит, это не коллектор. Глава это исправляет: отсутствие градиента коллектор не отрицает.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: диаграммы БЭЗ, разноглубинных фокусированных зондов, микро- и трёхэлектродного БК-3. Выход: наличие и знак радиального градиента (ρₙМБК больше или меньше ρₙБК). Для динамических методов — те же кривые одного метода в разные моменты или при разных растворах, а для нейтронных методов в обсаженных скважинах — расформирование зоны проникновения.", "by_model": true}, "breaks": {"text": "Отсутствие градиента не отрицает коллектор: оно может отвечать особому сочетанию насыщений и ρф/ρₙ. Когда отдельные измерения не позволяют выделить коллектор, нужны динамические методы.", "by_model": true}, "hypotheses": []}, "it_analogy": {"text": "Повторные замеры похожи на сравнение двух снимков состояния системы во времени: по изменению делают вывод, а по одному снимку нельзя. Метод двух растворов похож на A/B-тест: меняют одно условие и смотрят, как откликнулись данные.", "breaks_where": "Скважина — не воспроизводимая тестовая среда: зона проникновения со временем необратимо формируется, а повтор опыта ничего не откатывает. Условия в скважине нельзя менять произвольно.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы БЭЗ, фокусированных зондов, МБК и БК-3 из одной или нескольких съёмок, в том числе повторных.", "manual_steps": "Визуально сравнить кривые мелкого и глубокого зондов, определить знак градиента, при неясности организовать повторные замеры во времени или смену раствора и сопоставить кривые.", "judgment_points": "Считать ли отсутствие градиента отсутствием коллектора (нет, не считать). Когда переходить к динамическим методам. Какой вариант выбрать: повторные замеры или метод двух растворов.", "time": "в главе не указано", "typical_errors": "Отбраковка коллектора только из-за отсутствия градиента сопротивления.", "by_model": true}, "decision_on_data": {"features": ["ρₙМБК и ρₙБК на диаграммах экранированных зондов", "расхождение показаний разноглубинных зондов", "возможность выделить коллектор по отдельным измерениям"], "rule": "ρₙМБК больше ρₙБК — повышающее проникновение; ρₙМБК меньше ρₙБК — понижающее. Если градиента нет и по отдельным измерениям выделить коллектор нельзя, применяют повторные замеры или метод двух растворов.", "conclusion": "Наличие градиента фиксирует проникновение фильтрата. Отсутствие градиента не означает отсутствие коллектора, поэтому его проверяют динамическими методами.", "counterexample": "Отсутствие заметного градиента при определённом сочетании насыщений и отношения ρф/ρₙ, когда выполняется ρ₁₀/ρₙₙ = Pₙ₁₀ρф/Pₙρₙ: коллектор при этом есть."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["радиальный градиент сопротивления", "метод повторных замеров", "метод двух растворов"], "links": [{"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.filtrate_salinity"}, {"type": "prerequisite", "target": "latyshova.productivity_pn"}, {"type": "prerequisite", "target": "latyshova.direct_signs_of_collector"}], "needs_scan": [{"page": 96, "what": "Формула (12) и расшифровка обозначений ρ₁₀, ρₙₙ, Pₙ₁₀ не приведены в этой части главы; нужен исходный текст формулы."}], "claims": [{"page_print": null, "text": "Наличие радиального градиента сопротивления, то есть повышающего или понижающего проникновения фильтрата глинистого раствора, устанавливают при интерпретации БЭЗ и диаграмм разноглубинных фокусированных зондов.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.07", "quote": "устанавливают при интерпретации БЭЗ и диаграмм разноглубинных фокусированных зондов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c1"}, {"page_print": null, "text": "Радиальный градиент сопротивления связан с повышающим или понижающим проникновением фильтрата глинистого раствора.", "kind": "inference", "page_pdf": 96, "unit_id": "p096.07", "quote": "повышающего или понижающего проникновения фильтрата глинистого раствора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c2"}, {"page_print": null, "text": "Радиальное изменение сопротивления чётко устанавливают визуально по диаграммам экранированных зондов: микро- и трёхэлектродного БК-3.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.08", "quote": "Радиальное изменение сопротивления четко устанавливают визуально по диаграммам экранированных зондов (микро- и трехэлектродного БК-3)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c3"}, {"page_print": null, "text": "При повышающем проникновении ρₙМБК больше ρₙБК.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.08", "quote": "при повышающем проникновении ρₙМБК > ρₙБК", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c4"}, {"page_print": null, "text": "При понижающем проникновении ρₙМБК меньше ρₙБК.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.08", "quote": "при понижающем ρₙМБК < ρₙБК", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c5"}, {"page_print": null, "text": "Отсутствие заметного градиента сопротивления не является признаком, отрицающим коллектор.", "kind": "inference", "page_pdf": 96, "unit_id": "p096.09", "quote": "Отсутствие заметного градиента сопротивления не является признаком, отрицающим коллектор.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c6"}, {"page_print": null, "text": "Случай отсутствия градиента может соответствовать такому сочетанию коэффициентов насыщения в зоне проникновения и неизменной части пласта с отношением ρф/ρₙ, при котором по формуле (12) ρ₁₀/ρₙₙ = Pₙ₁₀ρф/Pₙρₙ.", "kind": "inference", "page_pdf": 96, "unit_id": "p096.09", "quote": "по формуле(12) ρ₁₀/ρₙₙ = Pₙ₁₀ρф/Pₙρₙ", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c7"}, {"page_print": null, "text": "Если выделение коллектора по отдельным измерениям невозможно, используются динамические методы его обнаружения.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.10", "quote": "Когда выделение коллектора на основании отдельных измерений по какой-либо из упомянутых выше причин оказывается невозможным, используются динамические методы их обнаружения.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c8"}, {"page_print": null, "text": "Динамические методы наблюдают процессы формирования или расформирования зоны проникновения во времени одним методом (БЭЗ или комплекс фокусированных зондов).", "kind": "observation", "page_pdf": 96, "unit_id": "p096.10", "quote": "проводят наблюдение процессов формирования или расформирования зоны проникновения во времени каким-нибудь одним методом (БЭЗ, комплекс фокусированных зондов)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c9"}, {"page_print": null, "text": "Метод повторных замеров: наблюдения во времени при неизменных условиях в скважине.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.10", "quote": "с неизменными условиями в скважине — метод повторных замеров", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c10"}, {"page_print": null, "text": "Метод двух растворов: наблюдения во времени при смене скважинных условий.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.10", "quote": "или при смене скважинных условий — метод двух растворов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c11"}, {"page_print": null, "text": "Такие наблюдения в обсаженных скважинах с нейтронными методами направлены на обнаружение газовых коллекторов в процессе расформирования зоны проникновения.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.10", "quote": "Такие наблюдения в обсаженных скважинах с использованием нейтронных методов направлены на обнаружение газовых коллекторов в процессе расформирования зоны проникновения.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c12"}, {"page_print": null, "text": "Динамические исследования широко применяются также для выявления сложных коллекторов.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.10", "quote": "Эти исследования широко применяются также и для выявления сложных коллекторов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.radial_gradient_and_dynamic#c13"}], "id": "latyshova.radial_gradient_and_dynamic", "order": 15, "minutes": 3, "essence": "Радиальный градиент сопротивления — это изменение сопротивления от стенки скважины вглубь пласта из-за проникновения фильтрата. Его видно по диаграммам БЭЗ и разноглубинных фокусированных зондов. Если сопротивление у зондов разной глубины одинаково, коллектор всё равно не исключён. Тогда применяют динамические методы: повторные замеры или метод двух растворов.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Фильтрат глинистого раствора входит в пласт и меняет сопротивление в зоне проникновения. Поэтому сопротивление вблизи скважины отличается от сопротивления неизменённой части пласта. Это и есть радиальный градиент.", "pages": [96]}, {"text": "Он бывает повышающим или понижающим. Его определяют сравнением показаний мелкого и глубокого зондов. Микро-БК (МБК) смотрит близко к стенке, трёхэлектродный БК-3 — глубже.", "pages": [96]}, {"text": "При повышающем проникновении ρₙМБК больше ρₙБК, при понижающем — меньше. Градиента может не быть из-за сочетания коэффициентов насыщения в зоне проникновения и в неизменной части пласта с отношением ρф/ρₙ. Автор связывает это с равенством ρ₁₀/ρₙₙ = Pₙ₁₀ρф/Pₙρₙ по формуле (12).", "pages": [96]}, {"text": "Обозначения этой формулы в этой части главы не расшифрованы.", "pages": [96]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Сначала смотрят БЭЗ и диаграммы разноглубинных фокусированных зондов. Для чёткого визуального вывода сравнивают кривые экранированных зондов МБК и БК-3. Если выделить коллектор по отдельным измерениям нельзя, наблюдают формирование или расформирование зоны проникновения во времени.", "pages": [96]}, {"text": "Одним методом (БЭЗ или комплексом фокусированных зондов) при неизменных условиях в скважине делают повторные замеры. При смене скважинных условий применяют метод двух растворов. В обсаженных скважинах нейтронные методы так же ищут газовые коллекторы по расформированию зоны проникновения.", "pages": [96]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Отсутствие заметного градиента не отрицает коллектор. Нельзя считать «нет градиента — нет коллектора». Динамические методы нужны, когда статические признаки не работают по перечисленным ранее причинам.", "pages": [96]}, {"text": "Они широко применяются и для выявления сложных коллекторов. Для повторных замеров условия в скважине должны оставаться неизменными. Для метода двух растворов их, наоборот, меняют.", "pages": [96]}, {"text": "Нейтронные наблюдения в обсаженных скважинах нацелены именно на газовые коллекторы.", "pages": [96]}]}], "deeper": [], "glossary": [{"term": "радиальный градиент сопротивления", "definition": "Изменение удельного сопротивления от стенки скважины вглубь пласта из-за проникновения фильтрата. Бывает повышающим и понижающим. Устанавливается по БЭЗ и разноглубинным фокусированным зондам."}, {"term": "метод повторных замеров", "definition": "Динамический метод: один и тот же метод (БЭЗ или комплекс фокусированных зондов) повторяют во времени при неизменных условиях в скважине. Так наблюдают формирование или расформирование зоны проникновения."}, {"term": "метод двух растворов", "definition": "Динамический метод: тем же методом наблюдают зону проникновения при смене скважинных условий, то есть при смене раствора."}], "format": "шортс", "tasks": [{"id": "latyshova.radial_gradient_and_dynamic.t1", "type": "single", "step_id": "latyshova.radial_gradient_and_dynamic", "claim_ids": ["latyshova.radial_gradient_and_dynamic#c4", "latyshova.radial_gradient_and_dynamic#c5"], "prompt": "Против пласта кажущееся сопротивление по микро-БК (МБК) равно 8 Ом·м, а по трёхэлектродному БК-3 равно 5 Ом·м. Что это означает?", "options": [{"id": "a", "text": "Понижающее проникновение фильтрата", "misconception": "misc.gradient_direction_swapped"}, {"id": "b", "text": "Радиального градиента нет, пласт плотный", "misconception": null}, {"id": "c", "text": "Повышающее проникновение фильтрата", "misconception": null}, {"id": "d", "text": "Зонды неисправны, так как показания различаются", "misconception": null}], "answer": "c", "tolerance": null, "unit": null, "explanation": "Если ρМБК больше ρБК, это повышающее проникновение.", "kind": "data"}, {"id": "latyshova.radial_gradient_and_dynamic.t2", "type": "order", "step_id": "latyshova.radial_gradient_and_dynamic", "claim_ids": ["latyshova.radial_gradient_and_dynamic#c1", "latyshova.radial_gradient_and_dynamic#c3", "latyshova.radial_gradient_and_dynamic#c8"], "prompt": "Расположите действия при поиске радиального градиента сопротивления в порядке их применения.", "options": [{"id": "a", "text": "Применить динамические методы: повторные замеры или метод двух растворов", "misconception": null}, {"id": "b", "text": "Посмотреть БЭЗ и диаграммы разноглубинных фокусированных зондов", "misconception": null}, {"id": "c", "text": "Сравнить кривые экранированных зондов МБК и БК-3", "misconception": null}], "answer": ["b", "c", "a"], "tolerance": null, "unit": null, "explanation": "Сначала смотрят БЭЗ и разноглубинные зонды, затем сравнивают МБК и БК-3, а если коллектор так не выделить, применяют динамические методы.", "kind": "understanding"}], "pictures": [{"id": "latyshova.radial_gradient_and_dynamic.i1", "step_id": "latyshova.radial_gradient_and_dynamic", "node_id": "latyshova.radial_gradient_and_dynamic", "file": "pictures/radial_gradient_and_dynamic_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Отсутствие градиента не отрицает коллектор; тогда прибегают к динамическим методам: повторным замерам или методу двух растворов.", "alt": "Схема: если радиального градиента сопротивления не видно, коллектор всё равно не исключён, и применяют динамические методы: повторные замеры либо метод двух растворов.", "source": "построено кодом по утверждениям главы, стр. 96", "claim_ids": ["latyshova.radial_gradient_and_dynamic#c6", "latyshova.radial_gradient_and_dynamic#c8", "latyshova.radial_gradient_and_dynamic#c9", "latyshova.radial_gradient_and_dynamic#c10", "latyshova.radial_gradient_and_dynamic#c11"], "prompt": null}]}, {"title": "Критическая проницаемость как главный критерий деления на коллектор и неколлектор", "short_title": "Критическая проницаемость", "why_here": {"text": "Вводит количественный критерий, на котором строятся пороги по пористости и глинистости.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "Ф"}, "threshold": true, "pages": [96], "misconception": {"ref": "misc.porosity_eq_perm", "text": "Главный критерий коллектора — проницаемость, а не пористость. Критическая пористость в главе названа отдельным, косвенным признаком, поэтому пористость и проницаемость не одно и то же.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Входом служит коэффициент проницаемости породы kпр, а выходом — класс «коллектор» или «неколлектор» по сравнению с k*пр. Порог k*пр свой для нефти и для газа и задан диапазонами. Связанные признаки — критические пористость и глинистость и геофизические параметры, отражающие изменение kп и kпр.", "by_model": false}, "breaks": {"text": "Правило зависит от района: порог меняется с рентабельным дебитом, то есть с экономикой и себестоимостью. Он зависит и от свойств флюидов и коллектора в пластовых условиях. Единое число для всех районов взять нельзя.", "by_model": false}, "hypotheses": [{"text": "Вероятно, граничное значение для нефти выше, чем для газа, потому что газ подвижнее нефти. В главе причина не названа.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Критическая проницаемость похожа на порог алерта в мониторинге. Метрика выше порога — событие значимо, ниже или равна — шум. Сам порог подбирают под сервис и стоимость простоя.", "breaks_where": "Порог мониторинга можно подкрутить за минуту. Критическую проницаемость определяют по геологии, экономике района и физике флюидов, и она задаёт класс породы.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["коэффициент проницаемости породы kпр", "критическое значение k*пр для флюида (нефть или газ) и района"], "rule": "Если kпр > k*пр — коллектор. Если kпр ≤ k*пр — неколлектор.", "conclusion": "Порода относится к коллекторам или неколлекторам. Для нефти k*пр лежит в пределах (1-10) · 10³ мкм², для газа в пределах (0,1-1) · 10³ мкм².", "counterexample": "Одно значение проницаемости может быть коллектором для газа и неколлектором для нефти, потому что диапазоны порогов различаются. Порог меняется и от района к району вместе с рентабельным дебитом."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["критическая проницаемость k*пр", "рентабельный дебит"], "links": [{"type": "prerequisite", "target": "latyshova.direct_signs_of_collector"}, {"type": "prerequisite", "target": "latyshova.four_method_groups"}, {"type": "refutes_misconception", "target": "misc.porosity_eq_perm"}], "needs_scan": [{"page": 96, "what": "Проверить знак степени в диапазонах критической проницаемости: в тексте записано 10³ мкм²."}, {"page": 96, "what": "Схема дальнейших определений после фразы «по следующей схеме» в выданных единицах не приведена."}], "claims": [{"page_print": null, "text": "Кроме прямых качественных признаков коллекторов используются также косвенные количественные признаки.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.11", "quote": "Кроме прямых качественных, используются также косвенные количественные признаки коллекторов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_permeability#c1"}, {"page_print": null, "text": "К косвенным количественным признакам относятся критические значения проницаемости, пористости и глинистости.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.12", "quote": "К ним относятся критические значения проницаемости (kₚₚ), пористости (kₙ), глинистости (Cᵣₓ, kᵣₓ, ηᵣₓ)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_permeability#c2"}, {"page_print": null, "text": "К косвенным количественным признакам относятся также геофизические параметры, отражающие изменение пористости и проницаемости (ΔJₙᵧ, ΔJᵧ, αCₙ и др.).", "kind": "observation", "page_pdf": 96, "unit_id": "p096.12", "quote": "и геофизические параметры, отражающие изменение kₙ и kₚₚ (ΔJₙᵧ, ΔJᵧ, αCₙ и др.).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_permeability#c3"}, {"page_print": null, "text": "Основной критерий отнесения породы к классам «коллектор» и «неколлектор» — граничное (критическое) значение коэффициента проницаемости k*пр.", "kind": "assumption", "page_pdf": 96, "unit_id": "p096.13", "quote": "Основным критерием, позволяющим относить породу к классам \"коллектор\" и \"неколлектор\", является граничное или критическое значение коэффициента проницаемости kₚₚ = k*ₚₚ.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_permeability#c4"}, {"page_print": null, "text": "Если проницаемость больше критической, породу относят к коллекторам; если меньше или равна критической, к неколлекторам.", "kind": "assumption", "page_pdf": 96, "unit_id": "p096.13", "quote": "Если kₚₚ > kₚₚ*, породу относят к классу \"коллектор\", если kₚₚ ≤ kₚₚ* - \"неколлектор\".", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_permeability#c5"}, {"page_print": null, "text": "Критическое значение проницаемости зависит от свойств флюидов и коллектора в пластовых условиях и от величины рентабельного дебита для данного района.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.13", "quote": "Критическое значение проницаемости зависит от свойств флюидов и коллектора в пластовых условиях и от величины рентабельного дебита для данного района.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_permeability#c6"}, {"page_print": null, "text": "Для нефтеносных коллекторов критическая проницаемость лежит в пределах (1-10) · 10³ мкм², для газовых в пределах (0,1-1) · 10³ мкм².", "kind": "observation", "page_pdf": 96, "unit_id": "p096.13", "quote": "Для нефтеносных коллекторов оно лежит в пределах (1-10) · 10³ мкм², для газовых - (0,1-1) · 10³ мкм².", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_permeability#c7"}, {"page_print": null, "text": "Рентабельным считают дебит нефти или газа, значение которого выше нижнего предела рентабельного дебита для данного района.", "kind": "assumption", "page_pdf": 96, "unit_id": "p096.14", "quote": "Рентабельным считают дебит нефти Qₙ или газа Qᵣ, значение которого выше нижнего предела Qₙ, Qᵣ рентабельного дебита для данного района.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_permeability#c8"}, {"page_print": null, "text": "Нижние пределы рентабельного дебита определяются особенностями геологии и экономики района и себестоимостью тонны нефти или кубометра газа.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.14", "quote": "Величины Qₙ, Qᵣ определяются особенностями геологии, экономики данного района и себестоимостью тонны нефти или кубометра газа.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_permeability#c9"}, {"page_print": null, "text": "Автор переходит к схеме дальнейших определений, но сама схема в выданных единицах не приведена.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.14", "quote": "Дальнейшие определения осуществляют по следующей схеме.", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_permeability#c10"}], "id": "latyshova.critical_permeability", "order": 16, "minutes": 2, "essence": "Порода — коллектор, если её проницаемость выше граничного значения k*пр, и неколлектор, если равна ему или ниже. Граничное значение не универсально: оно зависит от флюида, пластовых условий и рентабельного дебита района. Для нефти оно выше, чем для газа.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Проницаемость — способность породы пропускать флюид. Автор сравнивает проницаемость породы с критическим значением k*пр. Если kпр больше k*пр, это коллектор.", "pages": [96]}, {"text": "Если kпр не больше k*пр, это неколлектор. Само k*пр определяют свойства флюидов и коллектора в пластовых условиях. Его определяет и нижний предел рентабельного дебита района.", "pages": [96]}, {"text": "Дебит считается рентабельным, если он выше этого предела. Предел задают геология, экономика района и себестоимость тонны нефти или кубометра газа.", "pages": [96]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Для нефтеносных коллекторов критическая проницаемость лежит в пределах (1-10) · 10³ мкм². Для газовых она лежит в пределах (0,1-1) · 10³ мкм². Эти диапазоны даны как общие, а конкретное значение подбирают под район.", "pages": [96]}, {"text": "Схема дальнейших определений в выданных единицах не приведена.", "pages": [96]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Критерий относится к косвенным количественным признакам и дополняет прямые качественные признаки. К таким признакам автор относит и критические пористость и глинистость, и геофизические параметры. Граница нестрогая в одну сторону: значение, равное k*пр, относят к неколлекторам.", "pages": [96]}, {"text": "Пороги зависят от района и экономики, поэтому один и тот же образец в разных районах может попасть в разные классы. Степень множителя в диапазонах записана в тексте как 10³. Скан страницы стоит проверить, чтобы подтвердить знак степени.", "pages": [96]}]}], "deeper": [], "glossary": [{"term": "критическая проницаемость k*пр", "definition": "Граничное значение коэффициента проницаемости. Порода с kпр выше него — коллектор, с kпр не выше него — неколлектор. Значение зависит от флюида, пластовых условий и рентабельного дебита района."}, {"term": "рентабельный дебит", "definition": "Дебит нефти или газа выше нижнего предела, принятого для данного района. Предел определяют геология, экономика района и себестоимость тонны нефти или кубометра газа."}], "format": "карточки", "tasks": [{"id": "latyshova.critical_permeability.t1", "type": "single", "step_id": "latyshova.critical_permeability", "claim_ids": ["latyshova.critical_permeability#c5", "latyshova.critical_permeability#c6", "latyshova.critical_permeability#c7"], "prompt": "Проницаемость породы 0,5·10³ мкм². В районе критическая проницаемость для газа принята 0,3·10³ мкм², для нефти 3·10³ мкм². К какому классу относится порода?", "options": [{"id": "a", "text": "Неколлектор и для газа, и для нефти", "misconception": null}, {"id": "b", "text": "Коллектор и для газа, и для нефти", "misconception": "misc.porosity_eq_perm"}, {"id": "c", "text": "Коллектор для нефти, неколлектор для газа", "misconception": null}, {"id": "d", "text": "Коллектор для газа, неколлектор для нефти", "misconception": null}], "answer": "d", "tolerance": null, "unit": null, "explanation": "Для газа 0,5 больше порога 0,3, а для нефти 0,5 меньше порога 3.", "kind": "transfer"}, {"id": "latyshova.critical_permeability.t2", "type": "multiple", "step_id": "latyshova.critical_permeability", "claim_ids": ["latyshova.critical_permeability#c6", "latyshova.critical_permeability#c8", "latyshova.critical_permeability#c9"], "prompt": "От чего зависит критическое значение проницаемости k*пр? Выберите все верные.", "options": [{"id": "a", "text": "От свойств флюидов и коллектора в пластовых условиях", "misconception": null}, {"id": "b", "text": "От нижнего предела рентабельного дебита в районе", "misconception": null}, {"id": "c", "text": "Только от пористости породы", "misconception": "misc.porosity_eq_perm"}, {"id": "d", "text": "От цвета и крепости керна", "misconception": null}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "Порог задают свойства флюидов и коллектора в пластовых условиях и рентабельный дебит района.", "kind": "recall"}], "pictures": [{"id": "latyshova.critical_permeability.i1", "step_id": "latyshova.critical_permeability", "node_id": "latyshova.critical_permeability", "file": "pictures/critical_permeability_1.svg", "frame_class": "A", "origin": "code_from_data", "label": "схема", "caption": "Диапазоны критической проницаемости: для нефти она выше, чем для газа.", "alt": "Диаграмма диапазонов критической проницаемости: для нефтеносных коллекторов от 1 до 10, для газовых от 0,1 до 1, в единицах 10³ мкм².", "source": "построено кодом по утверждениям главы, стр. 96", "claim_ids": ["latyshova.critical_permeability#c7"], "prompt": null}]}, {"title": "От рентабельного дебита к критической проницаемости через коэффициент продуктивности", "short_title": "От дебита к проницаемости", "why_here": {"text": "Раскрывает, откуда берётся значение критической проницаемости; опирается на рентабельный дебит.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "Пр"}, "threshold": false, "pages": [96, 97], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход первого шага: минимальный рентабельный дебит, депрессия и эффективная толщина. Выход первого шага: коэффициент продуктивности η. Вход второго шага: η, вязкость флюида в пластовых условиях, радиусы скважины и контура питания. Выход: критическая проницаемость k*пр. Столбцов и кривых в этой части главы нет.", "by_model": true}, "breaks": {"text": "В главе не указано, где расчёт ломается. Единственная оговорка в сноске: второй шаг иногда пропускают и сразу связывают Qн с k*пр корреляцией.", "by_model": true}, "hypotheses": [{"text": "Результат, вероятно, чувствителен к принятому радиусу контура питания, хотя входит он только под логарифм. В главе это не обсуждается.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это как пересчёт целевой пропускной способности сервиса в требуемый размер пула соединений. Сначала из нужной нагрузки получают удельную производительность на единицу ресурса, затем по ней находят порог параметра системы.", "breaks_where": "У расчёта дебита есть физика притока: вязкость и радиальная геометрия с логарифмом радиусов. У пула соединений такой зависимости нет.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["коэффициент продуктивности η", "депрессия", "радиус контура питания"], "links": [{"type": "prerequisite", "target": "latyshova.critical_permeability"}], "needs_scan": [{"page": 96, "what": "Формула η = Qₙ/Δphₙφ: проверить вид знаменателя и смысл индекса «ₙ» и знака «φ», так как текст распознан, по-видимому, с искажением."}], "claims": [{"page_print": null, "text": "По величине минимального рентабельного дебита Q (в м³/сут) определяют коэффициент продуктивности коллектора.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.15", "quote": "По величине минимального рентабельного дебита Q (в м³/сут) определяют коэффициент продуктивности коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c1"}, {"page_print": null, "text": "Коэффициент продуктивности коллектора измеряется в м³/Па·сут·м.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.15", "quote": "коэффициент продуктивности коллектора (в м³/Па·сут·м)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c2"}, {"page_print": null, "text": "Коэффициент продуктивности η выражается через дебит Qₙ, депрессию Δp и эффективную толщину h; в тексте формула записана как η = Qₙ/Δphₙφ, возможно с искажением.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.16", "quote": "η = Qₙ/Δphₙφ,", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.debit_to_critical_perm#c3"}, {"page_print": null, "text": "Δp — депрессия в Па, при которой получен дебит Qₙ.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.17", "quote": "где Δp — депрессия в Па, при которой получен дебит Qₙ;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c4"}, {"page_print": null, "text": "h — эффективная толщина коллектора, давшего этот приток, в метрах.", "kind": "observation", "page_pdf": 96, "unit_id": "p096.17", "quote": "h - эффективная толщина коллектора, давшего этот приток (в м).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c5"}, {"page_print": null, "text": "Второй шаг: зная η, рассчитывают соответствующее значение критической проницаемости k*пр.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.01", "quote": "Зная η, рассчитывают соответствующее значение", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c6"}, {"page_print": null, "text": "Критическая проницаемость вычисляется по формуле k*пр = (μη/2π)·ln(Rк/rс).", "kind": "observation", "page_pdf": 97, "unit_id": "p097.02", "quote": "$$k^*_{\\text{пр}} = (\\mu\\eta/2\\pi)\\ln(R_\\text{к}/r_\\text{с}),$$", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c7"}, {"page_print": null, "text": "rс и Rк — соответственно радиусы скважины и контура питания скважины.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.03", "quote": "где rс, Rк - соответственно радиусы скважины и контура питания скважины;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c8"}, {"page_print": null, "text": "μ — вязкость жидкости или газа в пластовых условиях.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.03", "quote": "μ - вязкость жидкости или газа в пластовых условиях.¹", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c9"}, {"page_print": null, "text": "Этап расчёта k*пр иногда пропускают: получают корреляционную связь Qн непосредственно с k*пр.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.14", "quote": "Данный этап иногда минуют, получая корреляционную связь Qн непосредственно с kпр*.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.debit_to_critical_perm#c10"}], "id": "latyshova.debit_to_critical_perm", "order": 17, "minutes": 2, "essence": "Критическую проницаемость получают из рентабельного дебита в два шага. Сначала по дебиту находят коэффициент продуктивности η. Затем по η рассчитывают k*пр с учётом вязкости флюида и геометрии притока.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Шаг 1: минимальный рентабельный дебит Q (м³/сут) делят на депрессию Δp и эффективную толщину h. Так получают η. Депрессия — это перепад давления в Па, при котором получен дебит.", "pages": [96]}, {"text": "Толщина h — эффективная толщина коллектора, давшего приток. Шаг 2: η умножают на вязкость μ, делят на 2π и умножают на ln(Rк/rс). Rк — радиус контура питания, то есть расстояние, до которого пласт подпитывает скважину. rс — радиус скважины.", "pages": [96, 97]}, {"text": "Результат — критическая проницаемость k*пр.", "pages": [97]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Исходные данные для расчёта: рентабельный дебит, депрессия и толщина пласта, давшего приток. Нужны также вязкость флюида в пластовых условиях и оба радиуса. Второй шаг иногда пропускают и сразу строят корреляцию дебита Qн с k*пр.", "pages": [96, 97]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Вязкость берут в пластовых условиях, а не поверхностных. Это относится и к жидкости, и к газу. В тексте главы формулы η символы выглядят искажёнными: индекс «ₙ» и знак «φ».", "pages": [97]}, {"text": "Поэтому точный вид знаменателя лучше проверить по скану. Числовых примеров расчёта в этой части главы нет.", "pages": [96, 97]}]}], "deeper": [{"text": "Формула для k*пр содержит ln(Rк/rс), поэтому зависимость от отношения радиусов логарифмическая. Значения Rк и rс в этой части главы не приведены. Как их выбирать, в этом фрагменте не сказано.", "pages": [96, 97]}], "glossary": [{"term": "коэффициент продуктивности η", "definition": "Величина, которую находят по минимальному рентабельному дебиту, депрессии и эффективной толщине. Измеряется в м³/Па·сут·м. Служит для расчёта критической проницаемости."}, {"term": "депрессия", "definition": "Давление Δp в Па, при котором получен дебит Qₙ. Проще говоря, это перепад давления, под действием которого пласт отдаёт флюид в скважину."}, {"term": "радиус контура питания", "definition": "Радиус Rк, который входит в формулу критической проницаемости вместе с радиусом скважины rс. Условно это расстояние, до которого пласт подпитывает скважину."}], "format": "интерактив", "tasks": [{"id": "latyshova.debit_to_critical_perm.t1", "type": "order", "step_id": "latyshova.debit_to_critical_perm", "claim_ids": ["latyshova.debit_to_critical_perm#c1", "latyshova.debit_to_critical_perm#c3", "latyshova.debit_to_critical_perm#c6", "latyshova.debit_to_critical_perm#c7"], "prompt": "Расставьте в порядке выполнения шаги перехода от рентабельного дебита к критической проницаемости.", "options": [{"id": "a", "text": "Получить критическую проницаемость k*пр", "misconception": null}, {"id": "b", "text": "Разделить дебит на депрессию и эффективную толщину и получить коэффициент продуктивности η", "misconception": null}, {"id": "c", "text": "Взять минимальный рентабельный дебит Q", "misconception": null}, {"id": "d", "text": "Умножить η на вязкость, разделить на 2π и умножить на ln(Rк/rс)", "misconception": null}], "answer": ["c", "b", "d", "a"], "tolerance": null, "unit": null, "explanation": "Сначала по дебиту находят η, и только затем по η считают k*пр.", "kind": "recall"}, {"id": "latyshova.debit_to_critical_perm.t2", "type": "calc", "step_id": "latyshova.debit_to_critical_perm", "claim_ids": ["latyshova.debit_to_critical_perm#c7", "latyshova.debit_to_critical_perm#c8"], "prompt": "Условные данные: произведение μη = 6,283 (в согласованных единицах), отношение радиуса контура питания к радиусу скважины Rк/rс = 20, ln 20 ≈ 3,0. По формуле k*пр = (μη/2π)·ln(Rк/rс) найдите k*пр.", "options": [], "answer": 3.0, "tolerance": 0.05, "unit": "усл. ед.", "explanation": "μη/2π = 6,283/6,283 = 1, и 1 · 3,0 = 3,0.", "kind": "data"}], "pictures": [{"id": "latyshova.debit_to_critical_perm.i1", "step_id": "latyshova.debit_to_critical_perm", "node_id": "latyshova.debit_to_critical_perm", "file": "pictures/debit_to_critical_perm_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Два шага: из дебита, депрессии и толщины получают η, затем по формуле с μ, Rк и rс получают k*пр.", "alt": "Схема из двух шагов. Дебит, депрессия и эффективная толщина дают коэффициент продуктивности. Затем по формуле с вязкостью и радиусами скважины и контура питания получают критическую проницаемость.", "source": "построено кодом по утверждениям главы, стр. 96, 97", "claim_ids": ["latyshova.debit_to_critical_perm#c1", "latyshova.debit_to_critical_perm#c3", "latyshova.debit_to_critical_perm#c4", "latyshova.debit_to_critical_perm#c5", "latyshova.debit_to_critical_perm#c6", "latyshova.debit_to_critical_perm#c7", "latyshova.debit_to_critical_perm#c8", "latyshova.debit_to_critical_perm#c9"], "prompt": null}]}, {"title": "Перенос критической проницаемости на диаграммы: уровень разделения «коллектор» и «неколлектор»", "short_title": "Порог проницаемости на диаграммах", "why_here": {"text": "Завершает цепочку от дебита до практического порога на кривых, опираясь на корреляционные связи.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Ф"}, "threshold": false, "pages": [97], "misconception": null, "data_meaning": {"from_chapter": {"text": "Входом служат корреляционные связи kн с показаниями методов пористости и kпр с kгл или ηгл, а также k*пр. Выходом служит уровень критических значений ΔJнт*, ΔТ*, αСП* на диаграммах, который делит пласты на коллектор и неколлектор.", "by_model": true}, "breaks": {"text": "В главе не указано, где правило ломается.", "by_model": true}, "hypotheses": [{"text": "Если корреляционная связь построена по малой или разнородной выборке, критический уровень на диаграмме будет неточным.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это как пересчёт порога бизнес-метрики в порог технической метрики через регрессию. Порог по пропускной способности переводится в порог по загрузке CPU, и алерт ставится на графике CPU.", "breaks_where": "У регрессии в ИТ есть явная ошибка и метрики, а здесь в единицах о разбросе связей и их точности ничего не сказано.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Значение k*пр, корреляционные связи kн и ηгл с показаниями методов, диаграммы ГИС.", "manual_steps": "Найти kн* или ηгл* по связи, пересчитать в ΔJнт*, ΔТ*, αСП*, отложить значения на диаграммах и разделить пласты.", "judgment_points": "Выбор между методами пористости и глинистости; выбор связей для пересчёта.", "time": "в главе не указано", "typical_errors": "В главе не указано.", "by_model": true}, "decision_on_data": {"features": ["Показание метода на пласте (ΔJнт, ΔТ, αСП)", "Критическое значение ΔJнт*, ΔТ*, αСП* на диаграмме"], "rule": "Критическое значение получают пересчётом k*пр через корреляционные связи. Показание пласта сравнивают с этим уровнем на диаграмме.", "conclusion": "Пласт относят к классу «коллектор» или «неколлектор» по положению показания относительно уровня.", "counterexample": "В главе не приведён. По логике метода, без надёжной корреляционной связи уровень не получить."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["корреляционная связь", "критическое значение геофизического параметра", "относительная амплитуда СП αСП"], "links": [{"type": "prerequisite", "target": "latyshova.critical_permeability"}, {"type": "prerequisite", "target": "latyshova.debit_to_critical_perm"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Для определения эффективной толщины можно использовать два пути: методы пористости либо методы глинистости.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.04", "quote": "для определения эффективной толщины могут использоваться два пути - либо методы пористости, либо методы глинистости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.permeability_threshold_on_logs#c1"}, {"page_print": null, "text": "При использовании методов пористости требуются корреляционные связи вида ΔJнт = f (kн).", "kind": "observation", "page_pdf": 97, "unit_id": "p097.05", "quote": "При использовании методов пористости требуется иметь корреляционные связи вида ΔJнт = f (kн)", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.permeability_threshold_on_logs#c2"}, {"page_print": null, "text": "При использовании методов глинистости требуется связь kпр = f (kгл или ηгл).", "kind": "observation", "page_pdf": 97, "unit_id": "p097.05", "quote": "методов глинистости - kпр = f (kгл или ηгл)", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.permeability_threshold_on_logs#c3"}, {"page_print": null, "text": "По этим связям находят значения kн* либо ηгл* (kгл*), соответствующие критической проницаемости kпр*.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.05", "quote": "по которым находятся значения kн* либо ηгл* (kгл*), соответствующие kпр*", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.permeability_threshold_on_logs#c4"}, {"page_print": null, "text": "Ранее упоминавшиеся связи ΔJнт = f (kн), ΔТ = f (kн), αСП = (ηгл) и другие используются на следующем шаге.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.06", "quote": "используя упоминавшиеся ранее связи вида ΔJнт = f (kн), ΔТ = f (kн), αСП = (ηгл) и др.", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.permeability_threshold_on_logs#c5"}, {"page_print": null, "text": "По величине kн находят критические значения ΔJнт*, ΔТ*, αСП* и т.д.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.06", "quote": "по величине kн находят ΔJнт*, ΔТ*, αСП* и т.д.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.permeability_threshold_on_logs#c6"}, {"page_print": null, "text": "Значения ΔJнт*, ΔТ*, αСП* откладывают на диаграммах соответствующих методов, и получают уровень критических значений параметра.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.07", "quote": "Отложив на диаграммах соответствующих методов ΔJнт*, ΔТ*, αСП*, получают уровень критических значений параметра", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.permeability_threshold_on_logs#c7"}, {"page_print": null, "text": "Этот уровень разделяет распознаваемые пласты в разрезе на классы «коллектор» и «неколлектор».", "kind": "inference", "page_pdf": 97, "unit_id": "p097.07", "quote": "который разделяет распознаваемые пласты в разрезе на классы \"коллектор\" и \"неколлектор\"", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.permeability_threshold_on_logs#c8"}], "id": "latyshova.permeability_threshold_on_logs", "order": 18, "minutes": 2, "essence": "Критическая проницаемость k*пр через корреляционные связи пересчитывается в критическое значение пористости или глинистости. Затем она пересчитывается в критические значения показаний методов. Откладываем их на диаграммах и получаем уровень, который делит пласты на «коллектор» и «неколлектор».", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Для определения эффективной толщины возможны два пути: методы пористости или методы глинистости. Для методов пористости нужны связи вида ΔJнт = f(kн). Для методов глинистости нужна связь kпр = f(kгл или ηгл).", "pages": [97]}, {"text": "Корреляционная связь — это статистическая зависимость одной величины от другой, по которой одну находят через другую. По связи с проницаемостью находят значения kн* либо ηгл* (kгл*), которые соответствуют k*пр. Далее по связям ΔJнт = f(kн), ΔТ = f(kн), αСП = (ηгл) и другим по величине kн получают ΔJнт*, ΔТ*, αСП* и так далее.", "pages": [97]}, {"text": "Критическое значение геофизического параметра — это показание метода, соответствующее критической проницаемости. Относительная амплитуда СП αСП — параметр метода СП, который здесь связан с относительной глинистостью ηгл.", "pages": [97]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок такой. Выбираем путь: пористость или глинистость. Берём заранее построенную корреляционную связь и находим критическое kн* или ηгл*, соответствующее k*пр.", "pages": [97]}, {"text": "Пересчитываем его в критические значения ΔJнт*, ΔТ*, αСП*. Откладываем эти значения на диаграммах соответствующих методов. Полученный уровень делит пласты разреза на коллекторы и неколлекторы.", "pages": [97]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Шаг описывает последние шаги цепочки, нумерованные 3–5. Шаги 1–2 лежат вне выданных единиц. Расшифровка обозначений ΔJнт и ΔТ в этой части главы не дана.", "pages": [97]}, {"text": "Точность уровня зависит от качества корреляционных связей, но в единицах об этом не сказано.", "pages": [97]}]}], "deeper": [], "glossary": [{"term": "корреляционная связь", "definition": "Статистическая зависимость одной величины от другой, по которой по одной величине находят другую, например kпр = f(kгл) или ΔJнт = f(kн)."}, {"term": "критическое значение геофизического параметра", "definition": "Значение показания метода (ΔJнт*, ΔТ*, αСП*), соответствующее критической проницаемости. Оно задаёт на диаграмме уровень между коллектором и неколлектором."}, {"term": "относительная амплитуда СП αСП", "definition": "Параметр метода СП, который в единицах связан с относительной глинистостью ηгл связью αСП = (ηгл). Его критическое значение αСП* находят по этой связи."}], "format": "практикум на данных", "tasks": [{"id": "latyshova.permeability_threshold_on_logs.t1", "type": "single", "step_id": "latyshova.permeability_threshold_on_logs", "claim_ids": ["latyshova.permeability_threshold_on_logs#c4", "latyshova.permeability_threshold_on_logs#c6", "latyshova.permeability_threshold_on_logs#c7", "latyshova.permeability_threshold_on_logs#c8"], "prompt": "Для критической проницаемости по корреляционной связи найдено критическое значение пористости kн*. Как из него получить уровень, разделяющий «коллектор» и «неколлектор» на диаграммах?", "options": [{"id": "a", "text": "По связям вида ΔJнт = f(kн), ΔТ = f(kн) найти ΔJнт*, ΔТ* и т.д. и отложить их на диаграммах методов", "misconception": null}, {"id": "b", "text": "Отложить само значение kн* на диаграмме любого метода без пересчёта", "misconception": "misc.skip_conversion"}, {"id": "c", "text": "Вернуться к рентабельному дебиту и пересчитать его для каждого пласта", "misconception": null}, {"id": "d", "text": "Принять за уровень среднее показание метода по всему разрезу", "misconception": "misc.mean_as_threshold"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Критическое kн* переводят связями в критические показания методов и откладывают их на диаграммах как уровень.", "kind": "understanding"}, {"id": "latyshova.permeability_threshold_on_logs.t2", "type": "gap", "step_id": "latyshova.permeability_threshold_on_logs", "claim_ids": ["latyshova.permeability_threshold_on_logs#c1", "latyshova.permeability_threshold_on_logs#c4"], "prompt": "Критическую проницаемость по {{1}} связям пересчитывают в критическое значение {{2}} или глинистости.", "options": [], "answer": ["корреляционным", "пористости"], "tolerance": null, "unit": null, "explanation": "Эффективную толщину определяют двумя путями — по методам пористости или по методам глинистости, — а k*пр переводят в соответствующее критическое значение через корреляционные связи.", "kind": "recall"}], "pictures": [{"id": "latyshova.permeability_threshold_on_logs.i1", "step_id": "latyshova.permeability_threshold_on_logs", "node_id": "latyshova.permeability_threshold_on_logs", "file": "pictures/permeability_threshold_on_logs_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Цепочка пересчёта: от kпр* к критическим показаниям методов, которые делят пласты на два класса.", "alt": "Схема из пяти блоков. Критическая проницаемость пересчитывается в критическую пористость или глинистость, затем в критические показания методов. Их откладывают на диаграммах, и уровень делит пласты на коллекторы и неколлекторы.", "source": "построено кодом по утверждениям главы, стр. 97", "claim_ids": ["latyshova.permeability_threshold_on_logs#c4", "latyshova.permeability_threshold_on_logs#c6", "latyshova.permeability_threshold_on_logs#c7", "latyshova.permeability_threshold_on_logs#c8"], "prompt": null}]}, {"title": "Какие методы использовать для эффективной толщины и как ЯМР выделяет коллектор по эффективной пористости", "short_title": "ЯМР и выбор метода для толщины", "why_here": {"text": "Опирается на пороговые значения и типы разрезов; практика с диаграммой ЯМР закрепляет эффективную пористость.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "Пр"}, "threshold": false, "pages": [90, 97], "misconception": {"ref": "misc.log_is_rock", "text": "Кривая ЯМ не является самой породой: это косвенное измерение, а эффективную пористость принимают по нему приближённо (k_п,эф = I_сф,в), и значения ниже 1 % могут быть помехами.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход — диаграмма ЯМ (график I_сф). Выход — интервалы залегания коллекторов и значения эффективной пористости k_п,эф = I_сф,в в пластах выше 1 %. Для толщины в терригенном разрезе входами служат α_СП*, ΔJ*, а при неактивном цементе — ΔJнт*, ΔТ*, δн*.", "by_model": false}, "breaks": {"text": "Значения k_п,эф ниже 1 % могут быть аппаратурными помехами и не дают надёжного признака коллектора. СП и ГМ одни не подходят при неактивном силикатном или карбонатном цементе.", "by_model": false}, "hypotheses": []}, "it_analogy": {"text": "Порог 1 % похож на порог шума в мониторинге: значения ниже него считают шумом датчика, а не реальным событием.", "breaks_where": "Порог 1 % задан главой для конкретного прибора и пористости, а не подбирается по статистике шума; сам сигнал ниже порога не обязательно шум.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["значение I_сф,в (k_п,эф) в пласте на диаграмме ЯМ", "тип разреза (терригенный с зависимостью от глинистости)", "наличие неактивного силикатного или карбонатного цемента"], "rule": "Пласт считают коллектором, если k_п,эф = I_сф,в больше 1 %. Для hэф в терригенном разрезе берут СП и ГМ, при неактивном цементе — методы пористости, а ЯМР по I_сф выше 1 % добавляют для однозначности.", "conclusion": "Пласты с k_п,эф выше 1 % выделяют как коллекторы, а их толщину уточняют методом, подходящим типу разреза.", "counterexample": "Значение ниже 1 % может быть помехой аппаратуры, а не отсутствием коллектора или его наличием; по одному такому значению решать нельзя."}, "worked_examples": [], "book_tasks": [{"number": "85", "page_pdf": 90, "text": "Выделить коллекторы по диаграмме ядерно-магнитного метода (рис.67). Определить интервалы их залегания и значения эффективной пористости.", "figure": "рис. 67, стр. 90"}], "terms_introduced": ["эффективная пористость", "индекс свободного флюида Iсф", "неактивный цемент"], "links": [{"type": "prerequisite", "target": "latyshova.permeability_threshold_on_logs"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "refutes_misconception", "target": "misc.log_is_rock"}], "needs_scan": [{"page": 90, "what": "Рис. 67 — диаграмма ЯМ для задачи 85"}], "claims": [{"page_print": null, "text": "Величина I_сф,в близка к значению эффективной пористости коллектора k_п,эф.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.01", "quote": "Величина $I_{сф,в}$ близка к значению эффективной пористости коллектора $k_{п,эф}$", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.nmr_and_method_choice#c1"}, {"page_print": null, "text": "График I_сф рассматривают как диаграмму параметра k_п,эф и определяют его, полагая k_п,эф = I_сф,в.", "kind": "inference", "page_pdf": 90, "unit_id": "p090.01", "quote": "поэтому график $I_{сф}$ рассматривают как диаграмму параметра $k_{п,эф}$ и определяют его, полагая $k_{п,эф} = I_{сф,в}$", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.nmr_and_method_choice#c2"}, {"page_print": null, "text": "Коллекторами считают пласты, в которых k_п,эф больше 1 %.", "kind": "assumption", "page_pdf": 90, "unit_id": "p090.01", "quote": "Коллекторами считают пласты, в которых $k_{п,эф} > 1\\%$", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.nmr_and_method_choice#c3"}, {"page_print": null, "text": "Значения k_п,эф меньше 1 % могут соответствовать отклонениям кривых U, обусловленным аппаратурными помехами.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.01", "quote": "учитывая, что значения $k_{п,эф} < 1\\%$ могут соответствовать отклонениям кривых U, обусловленным аппаратурными помехами", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.nmr_and_method_choice#c4"}, {"page_print": null, "text": "Задача 85 требует выделить коллекторы по диаграмме ЯМ (рис. 67), определить интервалы залегания и значения эффективной пористости.", "kind": "observation", "page_pdf": 90, "unit_id": "p090.03", "quote": "Выделить коллекторы по диаграмме ядерно-магнитного метода (рис.67). Определить интервалы их залегания и значения эффективной пористости.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nmr_and_method_choice#c5"}, {"page_print": null, "text": "В терригенном разрезе, где пористость и проницаемость коллекторов зависят от глинистости, для определения hэф используют данные методов СП и ГМ (αСП* и ΔJ*).", "kind": "observation", "page_pdf": 97, "unit_id": "p097.08", "quote": "В терригенном разрезе, где пористость и проницаемость коллекторов зависят от глинистости, для определения hэф используют данные методов СП и ГМ (αСП* и ΔJ*).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.nmr_and_method_choice#c6"}, {"page_print": null, "text": "Если в таком разрезе есть пласты с неактивным силикатным или карбонатным цементом, для hэф необходимо использовать методы пористости (ΔJнт*, ΔТ*, δн*).", "kind": "observation", "page_pdf": 97, "unit_id": "p097.08", "quote": "Если в таком разрезе имеются пласты, содержащие неактивный силикатный или карбонатный цемент, для определения hэф необходимо использовать методы пористости (ΔJнт*, ΔТ*, δн*).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.nmr_and_method_choice#c7"}, {"page_print": null, "text": "Для однозначного выделения эффективной мощности целесообразно также применять метод ЯМР по значениям ИСФ более 1 %.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.08", "quote": "Для однозначного выделения эффективной мощности целесообразно также применять метод ЯМР по величине значений ИСФ более 1 %.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.nmr_and_method_choice#c8"}], "id": "latyshova.nmr_and_method_choice", "order": 19, "minutes": 3, "essence": "По ЯМ строят график индекса свободного флюида Iсф, и его принимают за диаграмму эффективной пористости: k_п,эф = I_сф,в. Коллекторами считают пласты с k_п,эф больше 1 %. В терригенном разрезе для эффективной толщины используют СП и ГМ, а при неактивном цементе — методы пористости; ЯМР помогает выделить толщину однозначно.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Эффективная пористость — это доля объёма породы, занятая подвижным (свободным) флюидом, в отличие от связанной воды. По главе величина I_сф,в, индекс свободного флюида, близка к эффективной пористости коллектора. Поэтому график I_сф рассматривают как диаграмму k_п,эф и принимают k_п,эф = I_сф,в.", "pages": [90]}, {"text": "Прибор измеряет отклик ядерно-магнитного метода, а свойство пласта выводят из него косвенно. Порог 1 % нужен потому, что значения ниже 1 % могут быть отклонением кривых из-за аппаратурных помех, а не признаком коллектора.", "pages": [90]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок работы по ЯМ: взять диаграмму I_сф, считать её диаграммой k_п,эф и отметить пласты со значением выше 1 %. Границы этих пластов дают интервалы залегания коллекторов, а значения I_сф,в в них — эффективную пористость. Так построена задача 85 по рис.", "pages": [90]}, {"text": "67. В терригенном разрезе, где пористость и проницаемость зависят от глинистости, эффективную толщину определяют по СП и ГМ (α_СП* и ΔJ*). Если в пластах есть неактивный силикатный или карбонатный цемент, применяют методы пористости (ΔJнт*, ΔТ*, δн*).", "pages": [97]}, {"text": "ЯМР по I_сф выше 1 % добавляют для однозначности выделения толщины.", "pages": [97]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Неактивный цемент — силикатный или карбонатный цемент, который не меняет по-разному отклик СП и ГМ, поэтому одних этих методов для толщины в таком пласте недостаточно. Значения k_п,эф ниже 1 % глава не относит к надёжным признакам: они могут быть аппаратурными помехами. Равенство k_п,эф = I_сф,в в главе дано как приближение, так как I_сф,в лишь близко к эффективной пористости.", "pages": [97]}, {"text": "Выбор метода зависит от типа разреза и наличия цемента. Глава не поясняет в этой части главы, как именно устроено измерение ЯМ и что означает индекс «в» у I_сф,в.", "pages": [97]}]}], "deeper": [], "glossary": [{"term": "эффективная пористость", "definition": "Доля объёма породы, занятая подвижным (свободным) флюидом; в главе её принимают равной индексу свободного флюида: k_п,эф = I_сф,в."}, {"term": "индекс свободного флюида Iсф", "definition": "Величина, получаемая по ядерно-магнитному методу и близкая к эффективной пористости; график I_сф рассматривают как диаграмму k_п,эф."}, {"term": "неактивный цемент", "definition": "Силикатный или карбонатный цемент в терригенном пласте, из-за которого для определения эффективной толщины нельзя полагаться только на СП и ГМ и нужны методы пористости."}], "format": "интерактив", "tasks": [{"id": "latyshova.nmr_and_method_choice.t1", "type": "single", "step_id": "latyshova.nmr_and_method_choice", "claim_ids": ["latyshova.nmr_and_method_choice#c3", "latyshova.nmr_and_method_choice#c4"], "prompt": "На диаграмме ЯМ, пересчитанной в эффективную пористость, пласт даёт значение 0,6 %. Как правильно к нему отнестись?", "options": [{"id": "a", "text": "Это значение в пределах возможной аппаратурной помехи, поэтому по нему одному коллектор надёжно не выделяют", "misconception": null}, {"id": "b", "text": "Это коллектор с очень плохими свойствами, его нужно включить в эффективную толщину", "misconception": "misc.log_is_rock"}, {"id": "c", "text": "Это однозначный неколлектор, так как пористость ниже 1 %", "misconception": "misc.log_is_rock"}, {"id": "d", "text": "Значение нужно умножить на 1 %, чтобы получить истинную пористость", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Значения ниже 1 % могут быть отклонением кривой из-за помех, поэтому порог коллектора — выше 1 %.", "kind": "transfer"}, {"id": "latyshova.nmr_and_method_choice.t2", "type": "multiple", "step_id": "latyshova.nmr_and_method_choice", "claim_ids": ["latyshova.nmr_and_method_choice#c6", "latyshova.nmr_and_method_choice#c7", "latyshova.nmr_and_method_choice#c8"], "prompt": "Какие утверждения о выборе методов для эффективной толщины верны? Выберите все верные.", "options": [{"id": "a", "text": "В терригенном разрезе с зависимостью свойств от глинистости используют СП и ГМ", "misconception": null}, {"id": "b", "text": "При неактивном силикатном или карбонатном цементе применяют методы пористости", "misconception": null}, {"id": "c", "text": "ЯМР при ИСФ выше 1 % добавляют для однозначного выделения толщины", "misconception": null}, {"id": "d", "text": "ЯМР полностью заменяет СП, ГМ и методы пористости", "misconception": "misc.nmr_replaces_all"}], "answer": ["a", "b", "c"], "tolerance": null, "unit": null, "explanation": "Метод зависит от типа разреза и наличия цемента, а ЯМР лишь дополняет их.", "kind": "understanding"}], "pictures": [{"id": "latyshova.nmr_and_method_choice.i1", "step_id": "latyshova.nmr_and_method_choice", "node_id": "latyshova.nmr_and_method_choice", "file": "pictures/nmr_and_method_choice_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Iсф принимают за эффективную пористость; порог 1 % отделяет коллектор от возможных помех.", "alt": "Схема: график Iсф по ЯМ принимают за эффективную пористость. Если она больше одного процента, пласт считают коллектором, иначе это не коллектор, возможна помеха.", "source": "построено кодом по утверждениям главы, стр. 90", "claim_ids": ["latyshova.nmr_and_method_choice#c1", "latyshova.nmr_and_method_choice#c2", "latyshova.nmr_and_method_choice#c3", "latyshova.nmr_and_method_choice#c4"], "prompt": null}]}, {"title": "Оценка характера насыщения по сопротивлению и пористости", "short_title": "Характер насыщения по Pн", "why_here": {"text": "Опирается на параметр насыщения: показывает, какие измерения нужны для вывода о нефти, газе и воде.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "И"}, "threshold": true, "pages": [97], "misconception": {"ref": "misc.high_res_oil", "text": "Высокое сопротивление само по себе не доказывает нефть. Его сравнивают с сопротивлением водонасыщенного пласта, которое зависит от пористости и воды. Упрощённая оценка по одному сопротивлению допустима лишь в чистых однородных коллекторах с одинаковой водой.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: сопротивление неизменённой части пласта ρн (или кажущееся сопротивление оптимальных зондов), пористость и сведения о качестве пластовой воды ρв. Выход: Pн, из него коэффициент водонасыщения или качественный вывод о характере насыщения.", "by_model": true}, "breaks": {"text": "Упрощённая оценка по кажущемуся сопротивлению ломается, если пористость меняется в широких пределах. Она ломается и при разных пластовых водах в разрезе. Тогда ρвн нельзя считать почти постоянным.", "by_model": true}, "hypotheses": [{"text": "Если ρвн не определено, высокое сопротивление может объясняться низкой пористостью или солёностью воды, а не нефтью.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это сравнение измеренного значения с расчётным эталоном. Эталон считают по другим входам, как ожидаемое время отклика сервиса по нагрузке, и аномалией считают отклонение от него.", "breaks_where": "Эталон ρвн здесь получают косвенно, по пористости и свойствам воды, поэтому у него есть собственная погрешность.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["удельное сопротивление неизменённой части пласта ρн или кажущееся сопротивление оптимальных зондов", "пористость, переведённая в параметр пористости", "качество (сопротивление) пластовой воды ρв"], "rule": "Если пористость меняется в нешироких пределах, вода одинакова по разрезу и ρн > ρвн, характер насыщения оценивают по кажущемуся сопротивлению по табл. 21.", "conclusion": "Пласт с высоким сопротивлением относительно водонасыщенного состояния оценивают как нефте- или газонасыщенный.", "counterexample": "Если пористость или вода в разрезе заметно меняются, ρвн нужно считать по пористости и качеству воды, а не принимать почти постоянным."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["параметр пористости", "коэффициент водонасыщения"], "links": [{"type": "prerequisite", "target": "latyshova.productivity_pn"}, {"type": "prerequisite", "target": "latyshova.four_method_groups"}, {"type": "prerequisite", "target": "latyshova.methods_overlap"}, {"type": "prerequisite", "target": "latyshova.table21_clays_sands_gas"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [{"page": 97, "what": "Формулы в тексте записаны с совпадающими обозначениями (Pн, ρн/ρвн, ρвн > ρвн, ρн = const). Нужно сверить символы по скану: различие Pн и Pп, ρн и ρв."}], "claims": [{"page_print": null, "text": "Для определения характера насыщения коллектора используют параметр насыщения Pн, связанный с коэффициентом водонасыщения пор, или показания метода, который показывает изменение этой величины в коллекторах.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "используют параметр насыщения Pн, связанный с коэффициентом водонасыщения пор", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c1"}, {"page_print": null, "text": "Из формул (10) и (11) следует, что Pн = ρн/ρвн = ρн/Pнρв; в числителе стоит удельное сопротивление неизменённой части пласта.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "Из формул (10) и (11) следует, что Pн = ρн/ρвн = ρн/Pнρв, где в числителе стоит значение удельного сопротивления неизмененной части пласта", "source_kind": "formula", "by_model": false, "needs_scan": true, "id": "latyshova.saturation_from_resistivity#c2"}, {"page_print": null, "text": "В знаменателе стоит удельное сопротивление того же пласта в водонасыщенном состоянии.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "в знаменателе — удельное сопротивление того же пласта в водонасыщенном состоянии", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c3"}, {"page_print": null, "text": "Сопротивление пласта в водонасыщенном состоянии получают косвенным путём по известной пористости, переведённой по выражению (3) в параметр пористости.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "Последнее получают косвенным путем по известной пористости, переведенной в соответствии с выражением (3) в параметр пористости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c4"}, {"page_print": null, "text": "Параметр пористости затем переводят в сопротивление водонасыщенного пласта по соотношению ρвн = Pнρв, где ρв — сопротивление воды.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "переведенной в соответствии с выражением (3) в параметр пористости и затем - в ρвн = Pнρв", "source_kind": "formula", "by_model": false, "needs_scan": true, "id": "latyshova.saturation_from_resistivity#c5"}, {"page_print": null, "text": "В общем случае для оценки характера насыщения нужен комплекс, включающий метод сопротивления, который даёт ρн неизменённой части пласта.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "требуется комплекс, включающий метод сопротивления, который дает информацию об удельном сопротивлении неизмененной части пласта ρн", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c6"}, {"page_print": null, "text": "В комплекс входят также метод пористости, оценивающий величину Pн, и метод, дающий информацию о качестве воды, насыщающей пласт.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "метод пористости, позволяющий оценивать величину Pн, и метод, который давал бы информацию о качестве воды, насыщающей пласт", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c7"}, {"page_print": null, "text": "Соотношение (10) объединяет все методы комплекса в одно уравнение, которое решают количественно, получая коэффициент водонасыщения коллектора.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "Соотношение (10) связывает все методы геофизического комплекса в единое уравнение, разрешаемое количественно для получения коэффициента водонасыщения коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c8"}, {"page_print": null, "text": "То же уравнение можно решать качественно, чтобы установить характер насыщения коллекторов в разрезе скважины.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.09", "quote": "либо качественно для установления характера насыщения коллекторов в разрезе скважины", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c9"}, {"page_print": null, "text": "Чистые высокопористые межзерновые коллекторы характеризуются высокими значениями коэффициентов нефте- и газонасыщения.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.10", "quote": "Чистые, высокопористые межзерновые коллекторы характеризуются высокими значениями коэффициентов нефте-, газонасыщения.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c10"}, {"page_print": null, "text": "В таких коллекторах характер насыщения можно оценить по удельному сопротивлению неизменённой части пласта и даже по кажущемуся сопротивлению, зарегистрированному оптимальными зондами.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.10", "quote": "характер насыщения можно оценить по величине удельного сопротивления неизмененной части пласта и даже значениям кажущегося сопротивления, зарегистрированным оптимальными зондами", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c11"}, {"page_print": null, "text": "Условие: коэффициент пористости, а значит и Pн, меняются в нешироких пределах, а пластовые воды одинаковы во всём изучаемом разрезе.", "kind": "assumption", "page_pdf": 97, "unit_id": "p097.10", "quote": "если коэффициент пористости, а следовательно, и Pн изменяются в нешироких пределах, а пластовые воды одинаковы для всего изучаемого разреза (ρн = const)", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.saturation_from_resistivity#c12"}, {"page_print": null, "text": "При этих условиях сопротивление водонасыщенного пласта имеет малый диапазон изменения.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.10", "quote": "При этом ρвн = Pнρв имеет малый диапазон изменения", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_from_resistivity#c13"}, {"page_print": null, "text": "Из-за высокого нефте- или газонасыщения сопротивление пласта значительно отличается от сопротивления водонасыщенных коллекторов.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.10", "quote": "из-за высокого коэффициента нефте- или газонасыщения значительно отличается от ρвн водонасыщенных коллекторов", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.saturation_from_resistivity#c14"}, {"page_print": null, "text": "При ρн > ρвн характер насыщения оценивают по табл. 21 просто по величине кажущегося сопротивления.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.10", "quote": "При условии ρвн > ρвн оценка характера насыщения коллекторов возможна в соответствии с табл. 21 просто по величине кажущегося сопротивления.", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.saturation_from_resistivity#c15"}], "id": "latyshova.saturation_from_resistivity", "order": 20, "minutes": 3, "essence": "Характер насыщения определяют, сравнивая сопротивление пласта в естественном состоянии с сопротивлением того же пласта, если бы он был полностью водонасыщенным. Второе значение получают косвенно: из пористости и свойств пластовой воды. Поэтому нужен комплекс методов: сопротивление, пористость и данные о воде. В чистых высокопористых коллекторах хватает и кажущегося сопротивления.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Параметр насыщения Pн — это отношение сопротивления неизменённой части пласта ρн к сопротивлению того же пласта в водонасыщенном состоянии ρвн. Знаменатель нельзя измерить: пласт насыщен не только водой. Его получают косвенно, по известной пористости.", "pages": [97]}, {"text": "Пористость переводят в параметр пористости, то есть множитель, связывающий сопротивление воды ρв с сопротивлением водонасыщенного пласта: ρвн = Pнρв. Сопротивление ρн даёт метод сопротивления. Пористость даёт метод пористости.", "pages": [97]}, {"text": "Качество, то есть минерализацию воды, даёт третий метод. Все три метода входят в одно соотношение (10). Его решают количественно, получая коэффициент водонасыщения (долю пор, занятую водой).", "pages": [97]}, {"text": "Либо качественно, определяя только характер насыщения.", "pages": [97]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "В чистых высокопористых межзерновых коллекторах насыщение нефтью или газом высокое. Тогда характер насыщения оценивают прямо по ρн или даже по кажущемуся сопротивлению оптимальных зондов. Это допустимо, если пористость, а значит и Pн, меняется в нешироких пределах.", "pages": [97]}, {"text": "Ещё нужно, чтобы пластовые воды были одинаковыми по всему разрезу. Тогда ρвн меняется мало, а ρн у нефте- и газонасыщенных пластов заметно выше. При ρн > ρвн вывод делают по табл.", "pages": [97]}, {"text": "21 просто по кажущемуся сопротивлению.", "pages": [97]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Простое правило по сопротивлению работает только при узком разбросе пористости и одинаковой воде. Если пористость или вода в разрезе меняются, значение ρвн нужно считать по пористости. Само по себе высокое сопротивление ещё не доказывает нефть.", "pages": [97]}, {"text": "В тексте сказано, что в общем случае нужен полный комплекс методов. Сокращённая оценка по кажущемуся сопротивлению — частный случай для чистых коллекторов.", "pages": [97]}]}], "deeper": [], "glossary": [{"term": "параметр пористости", "definition": "Величина, в которую переводят известную пористость; умножением на сопротивление пластовой воды ρв она даёт сопротивление водонасыщенного пласта: ρвн = Pнρв (обозначение в тексте книги)."}, {"term": "коэффициент водонасыщения", "definition": "Доля объёма пор, занятая водой; связан с параметром насыщения Pн и определяется из соотношения (10) количественно."}], "format": "интерактив", "tasks": [{"id": "latyshova.saturation_from_resistivity.t1", "type": "single", "step_id": "latyshova.saturation_from_resistivity", "claim_ids": ["latyshova.saturation_from_resistivity#c2", "latyshova.saturation_from_resistivity#c3", "latyshova.saturation_from_resistivity#c4", "latyshova.saturation_from_resistivity#c12"], "prompt": "Два пласта в разрезе имеют одинаковое высокое сопротивление ρн, но пористость и пластовая вода у них заметно различаются. Почему по одному ρн нельзя сразу назвать оба пласта нефтенасыщенными?", "options": [{"id": "a", "text": "Нужно сравнивать ρн с сопротивлением водонасыщенного пласта, а оно зависит от пористости и воды", "misconception": null}, {"id": "b", "text": "Сопротивление пласта вообще не зависит от насыщения", "misconception": "misc.high_res_oil"}, {"id": "c", "text": "Высокое сопротивление означает только газ, а не нефть", "misconception": "misc.high_res_oil"}, {"id": "d", "text": "Сопротивление можно сравнивать лишь между пластами с одинаковой толщиной", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Параметр насыщения — это ρн/ρвн, а ρвн разное при разной пористости и воде.", "kind": "understanding"}, {"id": "latyshova.saturation_from_resistivity.t2", "type": "gap", "step_id": "latyshova.saturation_from_resistivity", "claim_ids": ["latyshova.saturation_from_resistivity#c4", "latyshova.saturation_from_resistivity#c5"], "prompt": "Сопротивление водонасыщенного пласта получают косвенно: известную пористость переводят в {{1}} пористости, а затем умножают его на сопротивление {{2}}.", "options": [], "answer": ["параметр", "воды"], "tolerance": null, "unit": null, "explanation": "По соотношению ρвн = Pнρв параметр пористости умножают на сопротивление пластовой воды.", "kind": "recall"}], "pictures": [{"id": "latyshova.saturation_from_resistivity.i1", "step_id": "latyshova.saturation_from_resistivity", "node_id": "latyshova.saturation_from_resistivity", "file": "pictures/saturation_from_resistivity_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Сопротивление водонасыщенного пласта получают косвенно из пористости и воды, затем сравнивают с ρн.", "alt": "Схема: пористость и сопротивление воды дают сопротивление водонасыщенного пласта. Его сравнивают с сопротивлением неизменённой части пласта, и так определяют характер насыщения.", "source": "построено кодом по утверждениям главы, стр. 97", "claim_ids": ["latyshova.saturation_from_resistivity#c2", "latyshova.saturation_from_resistivity#c3", "latyshova.saturation_from_resistivity#c4", "latyshova.saturation_from_resistivity#c5", "latyshova.saturation_from_resistivity#c6", "latyshova.saturation_from_resistivity#c7", "latyshova.saturation_from_resistivity#c9"], "prompt": null}]}, {"title": "Сопоставление сопротивления и пористости тремя способами", "short_title": "Сопоставление ρп и пористости", "why_here": {"text": "Когда одного сопротивления мало, нужно сравнивать его с пористостью; подготавливает палетку и нормализацию.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "И"}, "threshold": false, "pages": [97], "misconception": {"ref": "misc.high_res_oil", "text": "Высокое сопротивление само по себе не означает нефть. Сопротивление пласта нужно сравнить с сопротивлением ρвн, ожидаемым при данной пористости. Только превышение над ρвн (Pн > 1) указывает на насыщение углеводородами.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "На входе диаграммы сопротивления (ρн, ρв) и диаграммы методов пористости (kн, ΔJнт, ΔТ, δн, ρвн). На выходе пласты с ρн > ρвн, у которых Pн > 1 и kн < 1.", "by_model": false}, "breaks": {"text": "Правило ломается, когда диапазоны сопротивления перекрываются: пористость сильно меняется, а насыщение невысокое или колеблется. Тогда по одному сопротивлению характер насыщения не определить. Диаграммы разного масштаба нельзя наложить без трансформации.", "by_model": false}, "hypotheses": [{"text": "При нормализации кривые, вероятно, сравнивают визуально: расхождение между кривыми показывает пласты с ρн > ρвн.", "by_model": true, "hypothesis": true}, {"text": "Качество вывода, вероятно, зависит от точности пересчёта показаний метода пористости в ρвн.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на сравнение фактической метрики с базовой линией (baseline). Метрика тоже зависит от нагрузки, поэтому аномалию ищут как отклонение от ожидаемого значения при этой нагрузке, а не как абсолютную величину.", "breaks_where": "Базовая линия в ИТ строится по истории, а здесь ρвн получают физически из метода пористости. Кроме того, наложение диаграмм требует приведения к единому масштабу.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы методов сопротивления и методов пористости по интервалу.", "manual_steps": "Трансформировать диаграммы к единому масштабу, наложить их, построить зависимости ρн = f(kн) или ρн = f(ΔJнт) и выделить пласты с ρн > ρвн.", "judgment_points": "Выбор способа сопоставления и выбор метода пористости. Выделение пластов, у которых ρн превышает ρвн.", "time": "в главе не указано", "typical_errors": "В главе не указаны. Из текста следует лишь риск перекрытия диапазонов сопротивления при оценке без пористости.", "by_model": true}, "decision_on_data": {"features": ["ρн пласта", "ρвн по методу пористости", "Pн = ρн/ρвн"], "rule": "Если ρн > ρвн, то Pн > 1 и kн < 1 (kн > 0): пласт выделяют как возможно насыщенный нефтью или газом.", "conclusion": "Пласты с ρн > ρвн выделяют в разрезе как несущие нефте- или газонасыщение.", "counterexample": "Если диапазоны ρн и ρвн перекрываются из-за изменения пористости, по одному сопротивлению вывод невозможен. Нужно сопоставление с пористостью."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["нормализация (наложение диаграмм)"], "links": [{"type": "prerequisite", "target": "latyshova.productivity_pn"}, {"type": "prerequisite", "target": "latyshova.saturation_from_resistivity"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [], "claims": [{"page_print": null, "text": "В межзерновых коллекторах пористость может сильно меняться, а вместе с ней меняется и сопротивление ρвн.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "В межзерновых коллекторах при больших изменениях пористости, а следовательно, и значений ρвн", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c1"}, {"page_print": null, "text": "Если нефте- или газонасыщение невысокое или сильно колеблется, диапазоны изменения сопротивления могут в значительной степени перекрываться.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "при невысоких или сильно колеблющихся значениях коэффициента нефте-, газонасыщения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c2"}, {"page_print": null, "text": "Диапазоны изменения ρвн и ρвн (так в тексте) могут в значительной степени перекрываться.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "диапазоны изменения ρвн и ρвн могут в значительной степени перекрываться", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c3"}, {"page_print": null, "text": "Из-за перекрытия диапазонов для оценки характера насыщения таких коллекторов требуется использовать величину параметра насыщения.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.11", "quote": "для оценки характера насыщения таких коллекторов требуется использовать величину параметра насыщения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c4"}, {"page_print": null, "text": "Процедура определения характера насыщения базируется на сопоставлении диаграмм методов сопротивления и пористости, которое проводят разными способами.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "процедура определения характера насыщения базируется на сопоставлении диаграмм методов сопротивления и пористости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c5"}, {"page_print": null, "text": "Первый способ: сопоставление значений ρн и kн в координатах ρн = f (kн).", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "1) сопоставлением значений ρн и kн в координатах ρн = f (kн)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c6"}, {"page_print": null, "text": "Второй способ: сопоставление значений ρв с показаниями методов пористости в координатах ρн = f (ΔJнт), где вместо ΔJнт могут быть ΔТ, δн, ρвн.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "2) либо значений ρв и показаний методов пористости в координатах ρн = f (ΔJнт) (ΔТ, δн, ρвн)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c7"}, {"page_print": null, "text": "Третий способ: совмещение диаграмм ρв ≈ ρн с диаграммами методов пористости.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "3) совмещением диаграмм ρв ≈ ρн с диаграммами методов пористости.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c8"}, {"page_print": null, "text": "Третья методика называется нормализацией, или наложением диаграмм.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "Последняя методика носит название нормализации, или наложения диаграмм", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c9"}, {"page_print": null, "text": "Для нормализации диаграммы предварительно трансформируют, приводя их к единому масштабу.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.11", "quote": "для чего требуется предварительная их трансформация с целью приведения к единому масштабу", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c10"}, {"page_print": null, "text": "Все три операции основаны на сравнении удельного сопротивления пласта с ρвн, информацию о котором дает метод пористости.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.12", "quote": "Все три операции основаны на сравнении значений удельного сопротивления пласта с ρвн, информацию о котором дает метод пористости.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c11"}, {"page_print": null, "text": "В разрезе выделяют пласты, у которых ρн больше ρвн.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.12", "quote": "При этом в разрезе выделяют пласты, имеющие ρн > ρвн", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c12"}, {"page_print": null, "text": "Условие ρн > ρвн означает, что ρн/ρвн = Pн > 1.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.12", "quote": "что свидетельствует о величине ρн/ρвн = Pн > 1", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c13"}, {"page_print": null, "text": "Из Pн > 1 следует условие kн < 1 (kн > 0) для таких пластов.", "kind": "inference", "page_pdf": 97, "unit_id": "p097.12", "quote": "и, следовательно, о существовании для них условия kн < 1 (kн > 0)", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.compare_resistivity_porosity#c14"}], "id": "latyshova.compare_resistivity_porosity", "order": 21, "minutes": 2, "essence": "Когда пористость сильно меняется, одного сопротивления для оценки насыщения недостаточно. Диапазоны сопротивления разных пластов перекрываются. Поэтому сопротивление пласта сравнивают с сопротивлением, ожидаемым для него при полном водонасыщении, и это сравнение даёт параметр насыщения.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "В межзерновых коллекторах пористость меняется сильно, а нефте- и газонасыщение невысокое или колеблется. Из-за этого диапазоны сопротивления перекрываются, и по одному сопротивлению насыщение не определить. Метод пористости (например, нейтронный, акустический или плотностной) показывает, каким было бы сопротивление ρвн при полном водонасыщении.", "pages": [97]}, {"text": "Пласт сравнивают с этим значением. Если ρн больше ρвн, то Pн = ρн/ρвн больше 1, а коэффициент насыщения kн меньше 1 (но больше 0). Сравнивать можно тремя способами.", "pages": [97]}, {"text": "Первый: в координатах ρн = f(kн). Второй: в координатах ρн = f(ΔJнт), где вместо ΔJнт могут быть ΔТ, δн, ρвн. Третий: совместить диаграммы.", "pages": [97]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Сначала в разрезе выделяют пласты с ρн > ρвн. Для третьего способа диаграммы сопротивления и пористости сначала трансформируют к единому масштабу, а затем накладывают друг на друга. Это называется нормализацией, или наложением диаграмм.", "pages": [97]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Нормализация требует предварительной трансформации диаграмм, иначе их нельзя сравнивать. Все три способа дают один и тот же вывод: Pн больше 1. Обозначения в тексте (ρвн, ρв, ρн) местами записаны неоднозначно, поэтому сверяйте их по оригиналу.", "pages": [97]}]}], "deeper": [], "glossary": [{"term": "нормализация (наложение диаграмм)", "definition": "Совмещение диаграмм сопротивления ρв ≈ ρн с диаграммами методов пористости после их трансформации к единому масштабу."}], "format": "практикум на данных", "tasks": [{"id": "latyshova.compare_resistivity_porosity.t1", "type": "single", "step_id": "latyshova.compare_resistivity_porosity", "claim_ids": ["latyshova.compare_resistivity_porosity#c1", "latyshova.compare_resistivity_porosity#c2", "latyshova.compare_resistivity_porosity#c4"], "prompt": "В межзерновом коллекторе пористость сильно меняется, а нефтенасыщение невысокое или колеблется. Почему по одному значению сопротивления пласта нельзя определить характер насыщения?", "options": [{"id": "a", "text": "Диапазоны сопротивления перекрываются, поэтому пласт сравнивают с ρвн", "misconception": null}, {"id": "b", "text": "Сопротивление в таких коллекторах вообще не зависит от насыщения, его определяет только глинистость породы", "misconception": null}, {"id": "c", "text": "Высокое сопротивление всегда означает нефть, поэтому метод пористости нужен лишь для контроля глубины залегания пласта", "misconception": "misc.high_res_oil"}, {"id": "d", "text": "Приборы метода сопротивления не работают в породах, у которых пористость выше критической", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Из-за изменения пористости меняется ρвн и диапазоны сопротивления перекрываются, поэтому нужно сравнение ρн с ρвн, то есть параметр насыщения.", "kind": "understanding"}, {"id": "latyshova.compare_resistivity_porosity.t2", "type": "calc", "step_id": "latyshova.compare_resistivity_porosity", "claim_ids": ["latyshova.compare_resistivity_porosity#c13"], "prompt": "Сопротивление пласта ρн = 24 Ом·м. По методу пористости ожидаемое сопротивление при полном водонасыщении ρвн = 6 Ом·м. Чему равен параметр насыщения Pн = ρн/ρвн?", "options": [], "answer": 4, "tolerance": 0.01, "unit": "безразм.", "explanation": "Pн = 24/6 = 4, это больше 1, значит kн < 1 и пласт может быть насыщен нефтью или газом.", "kind": "data"}], "pictures": [{"id": "latyshova.compare_resistivity_porosity.i1", "step_id": "latyshova.compare_resistivity_porosity", "node_id": "latyshova.compare_resistivity_porosity", "file": "pictures/compare_resistivity_porosity_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Все способы сводятся к сравнению сопротивления пласта с ρвн, которое даёт метод пористости. Смотрите, как из ρн > ρвн следует kн < 1.", "alt": "Схема: сопротивление пласта и значение ρвн из метода пористости сравниваются, отсюда получается параметр насыщения больше 1 и коэффициент насыщения меньше 1.", "source": "построено кодом по утверждениям главы, стр. 97", "claim_ids": ["latyshova.compare_resistivity_porosity#c11", "latyshova.compare_resistivity_porosity#c12", "latyshova.compare_resistivity_porosity#c13", "latyshova.compare_resistivity_porosity#c14"], "prompt": null}]}, {"title": "Палетка ρп = f(kп): области неколлектора, коллектора и характера притока", "short_title": "Палетка ρп от пористости", "why_here": {"text": "Строит наглядный инструмент из предыдущего сопоставления; затем по нему определяют насыщение.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "Р"}, "threshold": false, "pages": [97, 98], "misconception": {"ref": "misc.high_res_oil", "text": "Высокое сопротивление само по себе не означает нефть. На палетке область определяется парой ρп и kп. Одно и то же ρп при разной пористости может попасть в область воды, двухфазную область или область безводной нефти.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: пары ρп (сопротивление неизменённой части пласта) и kп (пористость) по пласту. Выход: область палетки (неколлектор А; коллекторы Б с областями I, II, III) и тем самым характер насыщения. Кривые семейства подписаны относительным водонасыщением от 0 до 1; кривые 1, 2, 3 — границы областей. Критическая пористость в примере 17%.", "by_model": false}, "breaks": {"text": "Палетка построена для конкретного геологического объекта и по статистике петрофизических данных. Для другого объекта и других классов коллекторов кривые будут иными. Влияние глинистости показано отдельным семейством IV.", "by_model": false}, "hypotheses": [{"text": "Пласты, чьи точки лежат вблизи границ областей, дают неоднозначный ответ, так как кривые построены статистически.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Палетка похожа на классификатор по двум признакам, где пространство признаков разделено границами на области-классы.", "breaks_where": "Границы здесь не обучены автоматически, а получены статистикой для конкретного объекта; в главе также нет оценки вероятности ошибки у границы.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["ρп пласта", "kп пласта", "положение точки относительно критической пористости и кривых ρп,max, ρп*, ρп**, ρп0"], "rule": "Нанести точку (ρп, kп) на рис. 69; область, в которую она попала, определяет характер насыщения.", "conclusion": "Область I — безводная нефть (газ), II — нефть (газ) с водой, III — вода, А — неколлектор; непродуктивные коллекторы лежат у границы с водоносными.", "counterexample": "В главе не указан."}, "worked_examples": [{"page_pdf": 97, "condition": "Сопоставление ρп с kп для пласта, разобрано на рис. 69: поле зависимостей ρп = f(kп) делится на области неколлекторов и коллекторов.", "steps": ["Строится поле зависимостей ρп = f(kп).", "Задаётся критическая пористость kп* = 17%.", "Левее границы — область неколлекторов (А), правее — область коллекторов (Б)."], "result": "Поле разделено на области А (неколлекторы) и Б (коллекторы) при kп* = 17%.", "figure": "рис. 69, стр. 98"}], "book_tasks": [], "terms_introduced": ["относительное водонасыщение", "предельно нефтегазонасыщенный коллектор", "область двухфазного течения"], "links": [{"type": "prerequisite", "target": "latyshova.compare_resistivity_porosity"}, {"type": "prerequisite", "target": "latyshova.productivity_pn"}, {"type": "prerequisite", "target": "latyshova.permeability_threshold_on_logs"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [{"page": 98, "what": "Формула относительного водонасыщения: символы слева и справа одинаковы, неясно, какое именно водонасыщение и какая связанная вода обозначены."}, {"page": 98, "what": "Подписи дополнительных осей рис. 69 и значение букв А, Б, В, Г не прочитаны программой распознавания."}, {"page": 98, "what": "Граница непродуктивных коллекторов: в тексте названа пара ρп* и ρп0; проверить по рисунку, не ρп** ли имелась в виду."}], "claims": [{"page_print": null, "text": "Пример сопоставления первых двух способов (сопротивление с пористостью) приведён автором на рис. 69.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.13", "quote": "Пример сопоставлений первых двух способов приведен на рис.69 [3].", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c1"}, {"page_print": null, "text": "Поле зависимостей ρп = f(kп) на примере разделено на область неколлекторов (А) и область коллекторов (Б) при критической пористости 17%.", "kind": "observation", "page_pdf": 97, "unit_id": "p097.13", "quote": "разделяется здесь на области неколлекторов (А) и коллекторов (Б) при kн* = 17%.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c2"}, {"page_print": null, "text": "Рис. 69 показывает кривые ρп = f(kп) для оценки продуктивности коллекторов; шифр кривых — относительное водонасыщение.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.02", "quote": "Рис.69. Кривые зависимости ρn = f(kn), используемые для оценки продуктивности коллекторов.", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c3"}, {"page_print": null, "text": "Кривая 1 на рисунке — ρп,max = f(kп), кривая 2 — ρп0 = f(kп).", "kind": "observation", "page_pdf": 98, "unit_id": "p098.02", "quote": "Шифр кривых – kn; цифры в кружках: 1 – ρnmax = f(kn); 2 – ρno = f(kn);", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c4"}, {"page_print": null, "text": "Кривые 3 — это ρп* = f(kп) и ρп** = f(kп); кривая 4 — граница «коллектор – неколлектор», соответствующая критической пористости.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.02", "quote": "3 – ρn* = f(kn) и ρn** = f(kn); 4 – граница «коллектор - неколлектор», соответствующая kn,cp;", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c5"}, {"page_print": null, "text": "Области на рис. 69: I — безводная нефть, II — двухфазная область нефти с водой, III — вода, IV — кривые для коллекторов с разной глинистостью.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.02", "quote": "I – область безводной нефти; II – двухфазная область нефти с водой; III – область воды; IV – кривые ρn = f(kn) для коллекторов с разной глинистостью.", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c6"}, {"page_print": null, "text": "В области коллекторов расположено семейство графиков ρп = f(kп) для разных значений относительного водонасыщения пор.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.03", "quote": "В области коллекторов расположено семейство графиков ρn = f(kn) для различных значений относительного водонасыщения пор", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c7"}, {"page_print": null, "text": "Относительное водонасыщение определяется формулой: из водонасыщения вычитается значение для связанной воды, результат делится на единицу минус это значение (обозначения в тексте искажены распознаванием).", "kind": "assumption", "page_pdf": 98, "unit_id": "p098.04", "quote": "k_n = (k_n - k_{n,ca}) / (1 - k_{n,ca})", "source_kind": "formula", "by_model": false, "needs_scan": true, "id": "latyshova.rho_kp_palette#c8"}, {"page_print": null, "text": "Относительное водонасыщение изменяется от 0 до 1; значение 0 соответствует предельно нефтегазонасыщенному коллектору, значение 1 — водоносному.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "изменяющегося от 0 до 1. Значение kn* = 0 соответствует предельно нефтегазонасыщенному коллектору (kn = kn,ca), а kn = 1 - водоносному (kn = 1).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c9"}, {"page_print": null, "text": "Промежуточные кривые для постоянного относительного водонасыщения получены статистической обработкой результатов петрофизических исследований.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "Промежуточные кривые для kn = const получены путем статистической обработки результатов петрофизических исследований.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c10"}, {"page_print": null, "text": "График 1 — зависимость ρп,max от kп для предельно нефтегазонасыщенных коллекторов, содержащих только связанную воду.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "График 1 является зависимостью ρnmax = f(kn) предельно нефтегазонасыщенных коллекторов, содержащих только связанную воду.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c11"}, {"page_print": null, "text": "График 2 — зависимость ρп0 от kп для полностью водоносных коллекторов; она продолжается в область А неколлекторов.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "График 2 представляет зависимость ρno = f(kn) для полностью водоносных коллекторов, которая продолжается и в области А для неколлекторов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c12"}, {"page_print": null, "text": "С уменьшением пористости графики 1 и 2 сближаются и в области неколлекторов сливаются в единый график ρп0 = f(kп).", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "С уменьшением kn графики 1 и 2 сближаются и сливаются в единый ρno = f(kn) в области неколлекторов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c13"}, {"page_print": null, "text": "В области Б приведены кривые 3 — ρп* и ρп**, соответствующие значениям Pн*, kв* и Pн**, kв** на рис. 7, б.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "В области Б приведены еще кривые 3 зависимостей ρn* = f(kn) и ρn** = f(kn), соответствующие значениям Pn*, kn* и Pn**, kn** на рис. 7, б.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c14"}, {"page_print": null, "text": "Кривые 3 ограничивают область двухфазного течения жидкости в порах коллекторов.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "Эти графики ограничивают область двухфазного течения жидкости в порах коллекторов (см. рис. 7, б).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c15"}, {"page_print": null, "text": "Область коллекторов, дающих приток чистой нефти (газа), ограничена кривыми ρп,max и ρп*.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "область коллекторов, дающих приток чистой нефти (газа), ограничена кривыми ρnmax и ρn*", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c16"}, {"page_print": null, "text": "Область коллекторов, из которых может быть получена нефть (газ) с водой, ограничена кривыми ρп* и ρп**.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "область коллекторов, из которых может быть получена нефть (газ) с водой, - кривыми ρn* и ρn**", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c17"}, {"page_print": null, "text": "Область непродуктивных коллекторов, по тексту автора, ограничена кривыми ρп* и ρп0.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "область непродуктивных коллекторов - кривыми ρn* и ρno", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.rho_kp_palette#c18"}, {"page_print": null, "text": "Кривые ρп* и ρп** построены по совместному анализу кривых Pн = f(kп) для разных классов коллекторов, выделенных по интервалам пористости.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "Зависимости ρn* = f(kn) и ρn** = f(kn) построены на основе совместного анализа кривых Pn = f(kn) для разных классов коллекторов, характеризуемых интервалами значений kn,", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c19"}, {"page_print": null, "text": "При построении кривых использованы также зависимости фазовых проницаемостей по воде и нефти для тех же классов коллекторов.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "зависимостями фазовых проницаемостей по воде и нефти (см. рис. 7, б) для тех же классов коллекторов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c20"}, {"page_print": null, "text": "Кроме того, использована зависимость связанной воды от пористости для исследуемого объекта, объединяющего все классы коллекторов и неколлекторы.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "зависимостью kn,cb = f(kn) для исследуемого геологического объекта, представленного совокупностью всех классов коллекторов и неколлекторами.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c21"}, {"page_print": null, "text": "Характер насыщения коллектора определяют, нанося точку с координатами ρп и kп на графики рис. 69.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.05", "quote": "Характер насыщения коллектора может быть определен нанесением точки с координатами ρn и kn на систему графиков, представленных на рис. 69", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c22"}, {"page_print": null, "text": "Область, в которую попала точка, определяет характер насыщения распознаваемого пласта.", "kind": "inference", "page_pdf": 98, "unit_id": "p098.05", "quote": "при этом область, в которой окажется точка, определяет характер насыщения распознаваемого пласта.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.rho_kp_palette#c23"}, {"page_print": null, "text": "По описанию программы распознавания, ось ρп логарифмическая, подписаны деления 1 и 10 Ом·м.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.01", "quote": "ρп, Ом·м — логарифмический масштаб, диапазон от 1 до 10", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.rho_kp_palette#c24"}, {"page_print": null, "text": "По описанию программы распознавания, ось Кп линейная, в процентах, подписаны значения 10, 20, 30, 40.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.01", "quote": "Кп, % — линейный масштаб, подписаны значения 10, 20, 30, 40.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.rho_kp_palette#c25"}, {"page_print": null, "text": "По описанию программы распознавания, назначение дополнительных шкал (второй ряд под Кп и правая ось) и значение букв А, Б, В, Г не прочитаны.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.01", "quote": "Из-за низкого разрешения и мелкого шрифта часть подписей (правая ось, вторая шкала под Кп, буквенные точки А/Б/В/Г) не может быть прочитана уверенно", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.rho_kp_palette#c26"}, {"page_print": null, "text": "По описанию программы распознавания, палетка, судя по построению, предназначена для графического определения ρп по известному Кп или для обратной задачи.", "kind": "inference", "page_pdf": 98, "unit_id": "p098.01", "quote": "палетка предназначена для графического определения ρп по известному Кп (или обратной задачи)", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.rho_kp_palette#c27"}], "id": "latyshova.rho_kp_palette", "order": 22, "minutes": 4, "essence": "Палетка делит поле ρп = f(kп) на неколлекторы и коллекторы. Внутри коллекторов она задаёт кривые для разных значений относительного водонасыщения. Точка (ρп, kп) пласта попадает в одну из областей, и это определяет характер насыщения.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Область неколлекторов (А) отделена от коллекторов (Б) границей по критической пористости. В примере автора она равна 17%. В области коллекторов построено семейство кривых для разных значений относительного водонасыщения.", "pages": [97, 98]}, {"text": "Относительное водонасыщение — это водонасыщение, пересчитанное так, чтобы оно менялось от 0 до 1. Значение 0 — предельно нефтегазонасыщенный коллектор, когда в порах остаётся только связанная вода. Значение 1 — полностью водоносный коллектор.", "pages": [98]}, {"text": "Кривая 1 даёт ρп,max для предельно нефтегазонасыщенных коллекторов. Кривая 2 даёт ρп0 для водоносных коллекторов и продолжается в область неколлекторов. С уменьшением пористости кривые 1 и 2 сближаются и сливаются в одну в области неколлекторов.", "pages": [98]}, {"text": "Кривые 3, ρп* и ρп**, ограничивают область двухфазного течения: это область, где в порах одновременно движутся нефть (газ) и вода. Между ρп,max и ρп* лежит безводная нефть (газ). Между ρп* и ρп** возможен приток нефти (газа) с водой.", "pages": [98]}, {"text": "Кривые 3 построены по трём источникам: по кривым Pн = f(kп) для классов коллекторов, по фазовым проницаемостям и по связи связанной воды с пористостью для объекта.", "pages": [98]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Чтобы определить характер насыщения, берут пару значений ρп и kп для пласта. Их наносят точкой на палетку рис. 69.", "pages": [98]}, {"text": "Область, в которую попала точка, и есть ответ для распознаваемого пласта. Область I — безводная нефть, II — нефть с водой, III — вода. Кривые IV на рисунке показывают, как положение зависит от глинистости коллектора.", "pages": [98]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Промежуточные кривые для постоянного относительного водонасыщения получены статистической обработкой петрофизических данных, а не выведены строго. Палетка построена для конкретного геологического объекта, то есть для всей совокупности его классов коллекторов и неколлекторов. В тексте автора непродуктивные коллекторы ограничены кривыми ρп* и ρп0, хотя по логике соседних областей ожидалась бы ρп**.", "pages": [98]}, {"text": "Это стоит проверить по рисунку. Для рис. 69 в слое есть только описание программы распознавания, подписи которого частично нечитаемы.", "pages": [98]}]}], "deeper": [{"text": "Рис. 7, б, на который ссылается автор, содержит зависимости Pн и фазовых проницаемостей. Эти зависимости дали значения Pн*, kв* и Pн**, kв**. Они переносятся в плоскость ρп–kп в виде кривых ρп* и ρп**. В формуле относительного водонасыщения в тексте символы слева и справа одинаковы из-за распознавания. Смысл формулы: из водонасыщения вычитают значение для связанной воды и делят на единицу минус это значение.", "pages": [98]}], "glossary": [{"term": "относительное водонасыщение", "definition": "Водонасыщение, пересчитанное так, чтобы оно менялось от 0 (только связанная вода) до 1 (полностью водоносный коллектор); по нему подписаны кривые палетки."}, {"term": "предельно нефтегазонасыщенный коллектор", "definition": "Коллектор, в порах которого остаётся только связанная вода; относительное водонасыщение равно 0, кривая ρп,max."}, {"term": "область двухфазного течения", "definition": "Область палетки между кривыми ρп* и ρп**, где в порах коллектора одновременно движутся нефть (газ) и вода, поэтому возможен приток нефти (газа) с водой."}], "format": "интерактив", "tasks": [{"id": "latyshova.rho_kp_palette.t1", "type": "multiple", "step_id": "latyshova.rho_kp_palette", "claim_ids": ["latyshova.rho_kp_palette#c11", "latyshova.rho_kp_palette#c12", "latyshova.rho_kp_palette#c13"], "prompt": "Палетка ρп = f(kп) содержит кривые 1 и 2. Выберите верные утверждения о них.", "options": [{"id": "a", "text": "Кривая 1 даёт ρп,max для коллекторов, содержащих только связанную воду", "misconception": null}, {"id": "b", "text": "Кривая 2 даёт ρп0 водоносных коллекторов и продолжается в область неколлекторов", "misconception": null}, {"id": "c", "text": "Кривая 1 описывает полностью водоносные коллекторы, а кривая 2 — предельно нефтегазонасыщенные", "misconception": null}, {"id": "d", "text": "С ростом пористости кривые 1 и 2 сближаются и сливаются в одну кривую", "misconception": null}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "Кривая 1 относится к предельно нефтегазонасыщенным коллекторам, кривая 2 — к водоносным, а сливаются они при уменьшении пористости.", "kind": "recall"}, {"id": "latyshova.rho_kp_palette.t2", "type": "gap", "step_id": "latyshova.rho_kp_palette", "claim_ids": ["latyshova.rho_kp_palette#c13"], "prompt": "С уменьшением пористости графики предельно нефтегазонасыщенных и водоносных коллекторов {{1}}, а в области неколлекторов {{2}} в единый график ρп0 = f(kп).", "options": [], "answer": ["сближаются", "сливаются"], "tolerance": null, "unit": null, "explanation": "При малой пористости разница между насыщением нефтью и водой в сопротивлении исчезает, и кривые 1 и 2 в области неколлекторов совпадают.", "kind": "recall"}], "pictures": [{"id": "latyshova.rho_kp_palette.i1", "step_id": "latyshova.rho_kp_palette", "node_id": "latyshova.rho_kp_palette", "file": "pictures/rho_kp_palette_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "симуляция", "caption": "Кривые 1 и 2 сливаются в области неколлекторов, а в коллекторах расходятся; кривые 3 ограничивают двухфазную область между ними.", "alt": "Качественный график сопротивления от пористости. Слева, в области неколлекторов, кривые сливаются. Правее границы критической пористости они расходятся: сверху максимальное сопротивление, внизу водоносные коллекторы, между ними две промежуточные кривые.", "source": "построено кодом по утверждениям главы, стр. 97, 98", "claim_ids": ["latyshova.rho_kp_palette#c2", "latyshova.rho_kp_palette#c4", "latyshova.rho_kp_palette#c5", "latyshova.rho_kp_palette#c12", "latyshova.rho_kp_palette#c13", "latyshova.rho_kp_palette#c15"], "prompt": null}]}, {"title": "Как читать палетку: точка с координатами ρп и kп определяет характер насыщения", "short_title": "Чтение палетки", "why_here": {"text": "Использует построенную палетку и показывает, что высокое сопротивление само по себе не решает вопрос.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Н"}, "threshold": false, "pages": [98], "misconception": {"ref": "misc.high_res_oil", "text": "Высокое сопротивление не означает нефть само по себе. При ρп = 10 Ом·м порода может быть неколлектором, нефтеносным коллектором или коллектором с нефтью и водой, в зависимости от kп.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: пара значений ρп (Ом·м) и kп (%). Выход: заключение о породе — неколлектор, нефтеносный коллектор, коллектор с безводной нефтью или коллектор с нефтью и водой. Вместо шкалы пористости можно использовать шкалы ΔJm, ΔT, δn, ΔJno или ρno.", "by_model": false}, "breaks": {"text": "Из единиц не следует, где именно проходят границы областей: они на рис. 69, которого в этой части главы нет. Нормализация (наложение диаграмм) обходится без графика ρп = f(kп).", "by_model": true}, "hypotheses": [{"text": "Вероятно, при ρп и kп возле границы областей вывод ненадёжен, потому что небольшая погрешность одного из измерений переносит точку в соседнюю область. В главе это не обсуждается.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Палетка похожа на таблицу решений с двумя входными признаками: комбинация значений даёт класс. Это как правила маршрутизации по паре полей запроса.", "breaks_where": "Границы областей в палетке получены из петрофизических связей и опыта, а не заданы логикой. Точка вблизи границы даёт вероятностный, а не строго определённый ответ.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Значения ρп и kп по интервалу, палетка ρп = f(kп) (рис. 69).", "manual_steps": "Вручную нанести точку на палетку и по области определить характер насыщения. Для ускорения пользоваться шкалами ΔJm, ΔT, δn, ΔJno или ρno вместо пористости.", "judgment_points": "Выбор шкалы вместо пористости и интерпретация положения точки относительно областей.", "time": "в главе не указано", "typical_errors": "Судить о нефти по одному высокому сопротивлению без учёта kп (по примеру 47). Другие ошибки в главе не названы.", "by_model": true}, "decision_on_data": {"features": ["ρп, Ом·м", "kп, %", "область палетки ρп = f(kп) (рис. 69), в которую попала точка"], "rule": "Нанести точку (kп, ρп) на палетку и прочитать область: неколлектор, нефтеносный коллектор, коллектор с нефтью и водой, безводная нефть.", "conclusion": "При ρп = 20 Ом·м и kп = 25 % ожидается безводная нефть. При ρп = 10 Ом·м и kп = 20 % — нефтеносный коллектор.", "counterexample": "При тех же ρп = 10 Ом·м: kп = 15 % — неколлектор, kп = 25 % — коллектор с нефтью и водой. Одно сопротивление не определяет вывод."}, "worked_examples": [{"page_pdf": 98, "condition": "Пример 46. Разрез нефтяного месторождения, ρп = 20 Ом·м, kп = 25 %. Определить характер насыщения коллектора.", "steps": ["Построить на палетке точку с координатами ρп = 20 Ом·м и kп = 25 %.", "По положению точки определить характер насыщения."], "result": "Коллектор при испытании даст безводную нефть.", "figure": "рис. 69, стр. 98"}, {"page_pdf": 98, "condition": "Пример 47. Порода с ρп = 10 Ом·м при kп: а) 15 %; б) 20 %; в) 25 %. Установить, чем представлена порода.", "steps": ["Для каждого kп нанести на палетку точку при ρп = 10 Ом·м.", "Определить область, в которую попала точка."], "result": "а) неколлектор; б) нефтеносный коллектор; в) коллектор, который при испытании даст нефть с водой.", "figure": "рис. 69, стр. 98"}], "book_tasks": [], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.rho_kp_palette"}, {"type": "prerequisite", "target": "latyshova.saturation_from_resistivity"}, {"type": "prerequisite", "target": "latyshova.compare_resistivity_porosity"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [{"page": 98, "what": "Рис. 69: палетка ρп = f(kп) с границами областей, на которой строятся точки примеров 46 и 47."}], "claims": [{"page_print": null, "text": "В примере 46 для разреза нефтяного месторождения заданы ρп = 20 Ом·м и kп = 25 %, и нужно определить характер насыщения коллектора.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.06", "quote": "Определить характер насыщения коллектора в разрезе нефтяного месторождения, для которого ρn = 20 Ом·м, kn = 25 %.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c1"}, {"page_print": null, "text": "Точку с координатами ρп и kп строят на палетке, и по её положению определяют характер насыщения.", "kind": "inference", "page_pdf": 98, "unit_id": "p098.06", "quote": "Построив точку с указанными координатами, определяем, что коллектор даст при испытании безводную нефть.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c2"}, {"page_print": null, "text": "По точке с ρп = 20 Ом·м и kп = 25 % коллектор при испытании даст безводную нефть.", "kind": "inference", "page_pdf": 98, "unit_id": "p098.06", "quote": "определяем, что коллектор даст при испытании безводную нефть.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c3"}, {"page_print": null, "text": "В примере 47 задана порода с ρп = 10 Ом·м и три значения kп: 15 %, 20 % и 25 %, нужно установить, чем представлена порода.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.07", "quote": "Установить, чем представлена порода, имеющая ρn = 10 Ом·м, при значениях kn: а) 15%; б) 20%; в) 25 %.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c4"}, {"page_print": null, "text": "При ρп = 10 Ом·м и kп = 15 % порода — неколлектор.", "kind": "inference", "page_pdf": 98, "unit_id": "p098.07", "quote": "Ответ: а) неколлектор;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c5"}, {"page_print": null, "text": "При ρп = 10 Ом·м и kп = 20 % порода — нефтеносный коллектор.", "kind": "inference", "page_pdf": 98, "unit_id": "p098.07", "quote": "б) коллектор нефтеносный;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c6"}, {"page_print": null, "text": "При ρп = 10 Ом·м и kп = 25 % порода — коллектор, который при испытании даст нефть с водой.", "kind": "inference", "page_pdf": 98, "unit_id": "p098.07", "quote": "в) коллектор, который при испытании даст нефть с водой.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c7"}, {"page_print": null, "text": "При одном и том же ρп характер породы меняется в зависимости от kп. Это вывод по ответам примера 47, а не прямая формулировка автора.", "kind": "inference", "page_pdf": 98, "unit_id": "p098.07", "quote": "Ответ: а) неколлектор; б) коллектор нефтеносный; в) коллектор, который при испытании даст нефть с водой.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c8"}, {"page_print": null, "text": "Для ускорения оценки характера насыщения графики рис. 69 можно использовать со шкалами ΔJm, ΔT, δn или ΔJno, а также ρno вместо шкалы пористости.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.08", "quote": "Для ускорения процесса оценки характера насыщения графики рис. 69 могут быть использованы со шкалами ΔJm, ΔT, δn или ΔJno, а также ρno вместо шкалы пористости.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c9"}, {"page_print": null, "text": "Методы нормализации (наложения диаграмм) основаны на обнаружении тех же эффектов, но без построения графиков ρп = f(kп).", "kind": "observation", "page_pdf": 98, "unit_id": "p098.09", "quote": "Методы нормализации или наложения диаграмм, которые основаны на обнаружении тех же эффектов, но без построения графиков ρn = f(kn)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c10"}, {"page_print": null, "text": "Методы нормализации разбираются ниже в разделе о карбонатных коллекторах.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.09", "quote": "разбираются ниже в разделе, посвященном карбонатным коллекторам.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.reading_palette#c11"}], "id": "latyshova.reading_palette", "order": 23, "minutes": 2, "essence": "Чтобы оценить характер насыщения, на палетке ρп = f(kп) наносят точку по измеренным ρп и kп. Область, в которую она попала, даёт ответ: неколлектор, нефть, нефть с водой и т. д. Одного значения сопротивления для вывода недостаточно, нужна пара ρп и kп.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Палетка устроена как карта областей на плоскости «пористость — сопротивление». Точка попадает в одну из областей, и это определяет заключение. В примере 47 при одном ρп = 10 Ом·м меняется только kп, и вывод меняется трижды: от неколлектора до коллектора с нефтью и водой.", "pages": [98]}, {"text": "Значит, сопротивление читается только вместе с пористостью.", "pages": [98]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок такой: взять ρп и kп, построить точку на палетке, определить область и записать ожидаемый приток. В примере 46 при ρп = 20 Ом·м и kп = 25 % получена безводная нефть. Для ускорения вместо шкалы пористости можно взять шкалы ΔJm, ΔT, δn, ΔJno или ρno.", "pages": [98]}, {"text": "Тогда не нужно отдельно пересчитывать пористость.", "pages": [98]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "В главе нет точных границ областей, они на рис. 69, которого в этой части главы нет. Результат — прогноз притока при испытании, а не измерение.", "pages": [98]}, {"text": "Методы нормализации, или наложения диаграмм, ищут те же эффекты без построения графика ρп = f(kп). Их глава разбирает позже, в разделе о карбонатных коллекторах.", "pages": [98]}]}], "deeper": [], "glossary": [], "format": "практикум на данных", "tasks": [{"id": "latyshova.reading_palette.t1", "type": "order", "step_id": "latyshova.reading_palette", "claim_ids": ["latyshova.reading_palette#c1", "latyshova.reading_palette#c2", "latyshova.reading_palette#c3"], "prompt": "Расположите шаги определения характера насыщения пласта по палетке ρп = f(kп) в правильном порядке.", "options": [{"id": "a", "text": "Определить область палетки, в которую попала точка", "misconception": null}, {"id": "b", "text": "Взять измеренные значения ρп и kп пласта", "misconception": null}, {"id": "c", "text": "Записать ожидаемый приток при испытании", "misconception": null}, {"id": "d", "text": "Нанести на палетку точку с координатами ρп и kп", "misconception": null}], "answer": ["b", "d", "a", "c"], "tolerance": null, "unit": null, "explanation": "Сначала берут пару ρп и kп, наносят точку, по области определяют характер насыщения и фиксируют ожидаемый приток.", "kind": "recall"}, {"id": "latyshova.reading_palette.t2", "type": "single", "step_id": "latyshova.reading_palette", "claim_ids": ["latyshova.reading_palette#c5", "latyshova.reading_palette#c7", "latyshova.reading_palette#c8"], "prompt": "Два пласта имеют одинаковое сопротивление ρп = 10 Ом·м, но разную пористость: пласт А — kп = 15 %, пласт Б — kп = 25 %. Какой вывод по палетке ρп = f(kп) верен?", "options": [{"id": "a", "text": "А — неколлектор, Б — коллектор, который даст нефть с водой", "misconception": null}, {"id": "b", "text": "Оба пласта — нефтеносные коллекторы, потому что их сопротивление одинаково", "misconception": "misc.high_res_oil"}, {"id": "c", "text": "А — нефтеносный коллектор, а Б — неколлектор, так как пористость выше", "misconception": null}, {"id": "d", "text": "Оба пласта — неколлекторы, потому что 10 Ом·м — низкое сопротивление", "misconception": "misc.high_res_oil"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "При ρп = 10 Ом·м точка при kп = 15 % попадает в область неколлекторов, а при kп = 25 % — в область нефти с водой.", "kind": "data"}], "pictures": [{"id": "latyshova.reading_palette.i1", "step_id": "latyshova.reading_palette", "node_id": "latyshova.reading_palette", "file": "pictures/reading_palette_1.svg", "frame_class": "A", "origin": "code_from_data", "label": "симуляция", "caption": "При одном ρп = 10 Ом·м меняется только kп, и вывод по палетке меняется три раза.", "alt": "Горизонтальная линия при сопротивлении 10 Ом·м и три точки по пористости 15, 20 и 25 процентов. Подписи: неколлектор, нефть, нефть с водой.", "source": "построено кодом по утверждениям главы, стр. 98", "claim_ids": ["latyshova.reading_palette#c4", "latyshova.reading_palette#c5", "latyshova.reading_palette#c6", "latyshova.reading_palette#c7"], "prompt": null}]}, {"title": "Критические значения Pн и kв и два способа их установить", "short_title": "Критические Pн и kв", "why_here": {"text": "Переходит от графика к числовым порогам; опирается на понятие продуктивного и непродуктивного коллектора.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "Ф"}, "threshold": false, "pages": [98, 99], "misconception": null, "data_meaning": {"from_chapter": {"text": "Входные данные: Pн пласта и kв, связанные зависимостью Pн = f(kв) для данного коллектора. Их сравнивают с порогами Pн,кр и kв,кр. Для установления порогов нужны либо результаты опробования многих интервалов (распределения Pн продуктивных и непродуктивных объектов), либо лабораторные кривые на керне. Это связь Pн = f(kв) и относительные фазовые проницаемости по нефти, воде и газу в зависимости от kв. Выход: вывод «продуктивный» или «непродуктивный».", "by_model": true}, "breaks": {"text": "Статистический способ не работает в начале разведки, пока мало испытанных интервалов. Петрофизический способ требует представительного керна и порогов для изучаемого класса коллекторов.", "by_model": true}, "hypotheses": []}, "it_analogy": {"text": "Критическое значение похоже на порог классификатора. Статистический способ подбирает его по накопленной размеченной выборке. Петрофизический способ задаёт его из физической модели, снятой в лаборатории.", "breaks_where": "У классификатора порог можно пересчитать в любой момент. Здесь пороги привязаны к классу коллекторов и к данным испытаний или керна.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["Pн пласта", "kв пласта", "критические значения Pн,кр и kв,кр"], "rule": "Если Pн > Pн,кр и kв < kв,кр, коллектор считают продуктивным. Если Pн < Pн,кр и kв > kв,кр, коллектор считают непродуктивным.", "conclusion": "По положению Pн и kв относительно порогов определяют, будет ли приток промышленным.", "counterexample": "Порог Pн* отделяет коллекторы с чистой нефтью (газом). Коллектор между Pн* и Pн,кр может дать нефть с некоторым количеством воды и всё же считаться промышленным."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["критические значения Pн*, kв*", "критерий промышленного притока Pн,кр", "статистический способ", "петрофизический способ"], "links": [{"type": "prerequisite", "target": "latyshova.productivity_pn"}, {"type": "prerequisite", "target": "latyshova.critical_permeability"}, {"type": "prerequisite", "target": "latyshova.saturation_from_resistivity"}], "needs_scan": [{"page": 98, "what": "Рис. 7: графическое определение Pн и kв (в этой части главы не описан)"}, {"page": 99, "what": "Рис. 70: связь Pн = f(kв) и относительные фазовые проницаемости по нефти, воде и газу от kв (в этой части главы не описан)"}], "claims": [{"page_print": null, "text": "Для определения характера насыщения кроме ранее рассмотренного способа можно использовать значения параметра насыщения и коэффициента водонасыщения.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.10", "quote": "для определения характера насыщения можно использовать значения параметра насыщения и коэффициента водонасыщения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c1"}, {"page_print": null, "text": "Эти значения рассчитывают по формулам (10) и (11) или находят графически по данным рис. 7.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.10", "quote": "рассчитываемые по формулам (10) и (11) или графически по данным рис. 7", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_pn_kv#c2"}, {"page_print": null, "text": "Вычисленное для пласта значение Pн или соответствующее ему kв, найденное по зависимости Pн = f(kв) для изучаемого коллектора, сравнивают с критическими значениями этих параметров.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.10", "quote": "Вычисленное для данного пласта значение Pn или соответствующее ему значение kn, установленное по зависимости Pn = f(kn) для изучаемого коллектора, сравнивают с критическими значениями", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c3"}, {"page_print": null, "text": "Если Pн больше критического и kв меньше критического, коллектор считают продуктивным.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.10", "quote": "Если Pn > Pn,xp и kn < kn,xp, коллектор считают продуктивным", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c4"}, {"page_print": null, "text": "Если Pн меньше критического и kв больше критического, коллектор считают непродуктивным.", "kind": "observation", "page_pdf": 98, "unit_id": "p098.10", "quote": "при Pn < Pn,xp, kn > kn,xp - непродуктивным", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c5"}, {"page_print": null, "text": "Различают две разновидности критических значений Pн и kв.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.01", "quote": "Различают две разновидности критических значений  \\( P_{n} \\)  и  \\( k_{n} \\) :", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c6"}, {"page_print": null, "text": "Значения Pн*, kв* соответствуют границе между коллекторами, дающими при испытании чистую нефть (газ), и прочими коллекторами.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.01", "quote": "значения  \\( P_{n}^{*} \\) ,  \\( k_{n}^{*} \\) , соответствующие границе между коллекторами, дающими при испытании чистую нефть (газ)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c7"}, {"page_print": null, "text": "К прочим коллекторам относятся те, из которых при испытании получают нефть (газ) с водой или чистую воду.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.01", "quote": "из которых при испытании получают нефть (газ) с водой или чистую воду", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c8"}, {"page_print": null, "text": "Значения Pн,кр, kв,кр разделяют коллекторы с промышленным притоком нефти (газа), в том числе с некоторым количеством воды, и коллекторы с непромышленным притоком.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.01", "quote": "разделяющие области коллекторов, дающих при испытании промышленный приток нефти (газа), в том числе с некоторым количеством воды", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c9"}, {"page_print": null, "text": "Непромышленный приток — это чистая вода или вода с небольшим содержанием углеводородов.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.01", "quote": "и коллекторов с непромышленным притоком (чистая вода или вода с небольшим содержанием углеводородов)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c10"}, {"page_print": null, "text": "При подсчёте запасов чаще используют критерии Pн,кр и kв,кр.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.01", "quote": "При подсчете запасов чаще используют критерии  \\( P_{n,кр} \\)  и  \\( k_{n,кр} \\) .", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c11"}, {"page_print": null, "text": "Существуют два способа установления критических значений Pн и kв.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.02", "quote": "Существуют два способа установления критических значений  \\( P_{n} \\) ,  \\( k_{n} \\) :", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c12"}, {"page_print": null, "text": "В статистическом способе критические значения находят по пересечению распределений Pн для продуктивных и непродуктивных объектов по данным опробования.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.02", "quote": "а) статистический [3], в котором эти значения находят по пересечению распределений параметров  \\( P_{n} \\)  для продуктивных и непродуктивных объектов по данным опробования", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c13"}, {"page_print": null, "text": "В петрофизическом способе в лаборатории получают и сопоставляют связь Pн = f(kв).", "kind": "observation", "page_pdf": 99, "unit_id": "p099.02", "quote": "б) петрофизический [4], в котором критические значения  \\( P_{n} \\) ,  \\( k_{n} \\)  находят, получая в лаборатории и сопоставляя связь  \\( P_{n} = f(k_{n}) \\)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c14"}, {"page_print": null, "text": "С этой связью сопоставляют зависимость относительной фазовой проницаемости по нефти, воде и газу от kв для изучаемого класса коллекторов (рис. 70).", "kind": "observation", "page_pdf": 99, "unit_id": "p099.02", "quote": "зависимость относительной фазовой проницаемости по нефти, воде и газу [3] от коэффициента водонасыщения  \\( k_{n} \\)  для изучаемого класса коллекторов (рис. 70)", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_pn_kv#c15"}, {"page_print": null, "text": "Статистический способ применим на стадии завершения разведки, когда имеется большое число испытанных интервалов.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.02", "quote": "Первый способ применим на стадии завершения разведки месторождения, когда имеется большое число испытанных интервалов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c16"}, {"page_print": null, "text": "Недостаток статистического способа: полученные значения устанавливаются с опозданием и не обслуживают начало и процесс разведки, когда они особенно нужны.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.02", "quote": "полученные статистически критические значения устанавливаются с опозданием и не могут обслуживать начало и процесс разведки, когда они особенно нужны", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c17"}, {"page_print": null, "text": "Петрофизический способ требует отбора представительного керна из первых разведочных скважин на данном месторождении.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.02", "quote": "Второй способ требует отбора представительного керна из первых разведочных скважин на данном месторождении", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c18"}, {"page_print": null, "text": "Петрофизический способ позволяет получать критические значения в лабораториях в начале разведки и использовать их на всех стадиях вплоть до подсчёта запасов и проектирования разработки.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.02", "quote": "в петрофизических лабораториях в начале разведки и использовать их на всех стадиях вплоть до подсчета запасов и проектирования разработки.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.critical_pn_kv#c19"}], "id": "latyshova.critical_pn_kv", "order": 24, "minutes": 4, "essence": "Характер насыщения можно определить, сравнив Pн коллектора и соответствующий ему kв с критическими значениями. Если Pн больше критического и kв меньше критического, коллектор продуктивный. Критические значения бывают двух видов: Pн*, kв* (граница чистого притока нефти или газа) и Pн,кр, kв,кр (граница промышленного притока). Установить их можно двумя способами: статистическим и петрофизическим.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Для пласта вычисляют параметр насыщения Pн по формуле (10) и коэффициент водонасыщения kв по формуле (11), либо находят их графически. Параметр Pн связан с kв зависимостью Pн = f(kв) для данного класса коллекторов. Поэтому значению Pн соответствует определённое kв.", "pages": [98]}, {"text": "Это значение сравнивают с порогом. Чем выше Pн и ниже kв, тем больше в породе нефти или газа и тем меньше воды. Порогов два вида.", "pages": [99]}, {"text": "Pн*, kв* отделяют коллекторы с чистой нефтью (газом) при испытании от остальных, дающих нефть с водой или чистую воду. Pн,кр, kв,кр отделяют коллекторы с промышленным притоком, возможно с некоторой водой, от коллекторов с непромышленным притоком. Непромышленный приток — это чистая вода или вода с малым содержанием углеводородов.", "pages": [99]}, {"text": "Статистический способ ищет порог по пересечению распределений Pн для продуктивных и непродуктивных объектов по данным опробования. Петрофизический способ строит в лаборатории связь Pн = f(kв) и зависимость относительной фазовой проницаемости по нефти, воде и газу от kв. Относительная фазовая проницаемость показывает, какую долю своей проницаемости сохраняет каждая фаза (нефть, вода, газ) при совместном течении.", "pages": [99]}, {"text": "Обе зависимости строят для изучаемого класса коллекторов (рис. 70).", "pages": [98, 99]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "При подсчёте запасов чаще используют критерии Pн,кр и kв,кр. Статистический способ применяют на стадии завершения разведки, когда накоплено много испытанных интервалов. Петрофизический способ требует представительного керна из первых разведочных скважин месторождения.", "pages": [99]}, {"text": "Его пороги получают в лаборатории уже в начале разведки. Их используют на всех стадиях вплоть до подсчёта запасов и проектирования разработки.", "pages": [99]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Недостаток статистического способа в том, что пороги появляются с опозданием. Они не обслуживают начало и ход разведки, когда особенно нужны. Петрофизический способ зависит от того, насколько керн представителен.", "pages": [99]}, {"text": "Пороги относятся к изучаемому классу коллекторов, поэтому переносить их на другой класс без проверки нельзя. В тексте символы Pн и kв записаны как Pn и kn (kn здесь — коэффициент водонасыщения), а Pн,кр записано как Pn,xp. Это особенности распознавания текста.", "pages": [98, 99]}, {"text": "Рисунки 7 и 70 в предоставленных единицах не описаны.", "pages": [98, 99]}]}], "deeper": [], "glossary": [{"term": "критические значения Pн*, kв*", "definition": "Значения параметра насыщения и коэффициента водонасыщения на границе между коллекторами, дающими при испытании чистую нефть (газ), и прочими коллекторами. Прочие дают нефть (газ) с водой или чистую воду."}, {"term": "критерий промышленного притока Pн,кр", "definition": "Критические значения Pн,кр и kв,кр разделяют коллекторы с промышленным притоком нефти (газа), возможно с некоторой водой, и коллекторы с непромышленным притоком. Именно их чаще используют при подсчёте запасов."}, {"term": "статистический способ", "definition": "Способ установления критических Pн и kв по пересечению распределений Pн для продуктивных и непродуктивных объектов по данным опробования. Применим при завершении разведки, когда испытано много интервалов."}, {"term": "петрофизический способ", "definition": "Способ установления критических Pн и kв по лабораторным данным на керне. Сопоставляют связь Pн = f(kв) и зависимость относительной фазовой проницаемости по нефти, воде и газу от kв. Применим с начала разведки."}], "format": "карточки", "tasks": [{"id": "latyshova.critical_pn_kv.t1", "type": "single", "step_id": "latyshova.critical_pn_kv", "claim_ids": ["latyshova.critical_pn_kv#c7", "latyshova.critical_pn_kv#c8", "latyshova.critical_pn_kv#c9", "latyshova.critical_pn_kv#c10"], "prompt": "Чем различаются критические значения Pн*, kв* и Pн,кр, kв,кр?", "options": [{"id": "a", "text": "Pн* отделяет коллекторы с чистой нефтью (газом), Pн,кр — промышленный приток от непромышленного", "misconception": null}, {"id": "b", "text": "Pн* отделяет коллекторы от неколлекторов по пористости, а Pн,кр — нефтеносные от газоносных", "misconception": null}, {"id": "c", "text": "Pн* получают только статистически, а Pн,кр только петрофизически, других различий между ними нет", "misconception": null}, {"id": "d", "text": "Pн* относится к водоносным пластам, а Pн,кр — к пластам с любым количеством углеводородов", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Pн* — граница чистого притока нефти (газа), а Pн,кр — граница промышленного притока, который может содержать воду.", "kind": "understanding"}, {"id": "latyshova.critical_pn_kv.t2", "type": "multiple", "step_id": "latyshova.critical_pn_kv", "claim_ids": ["latyshova.critical_pn_kv#c16", "latyshova.critical_pn_kv#c17", "latyshova.critical_pn_kv#c18", "latyshova.critical_pn_kv#c19"], "prompt": "На месторождении только началась разведка: есть представительный керн из первых скважин, но испытанных интервалов мало. Какие утверждения о выборе способа получения критических значений Pн и kв верны?", "options": [{"id": "a", "text": "Пороги можно получить петрофизическим способом в лаборатории по керну", "misconception": null}, {"id": "b", "text": "Статистический способ пока малоприменим: для него нужно много испытанных интервалов", "misconception": null}, {"id": "c", "text": "Статистический способ предпочтительнее, так как даёт пороги на любой стадии разведки без опоздания", "misconception": null}, {"id": "d", "text": "Лабораторные пороги можно использовать только после подсчёта запасов и при проектировании разработки", "misconception": null}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "Петрофизический способ даёт пороги по керну уже в начале разведки, а статистический срабатывает с опозданием, когда накоплено много испытаний.", "kind": "transfer"}], "pictures": [{"id": "latyshova.critical_pn_kv.i1", "step_id": "latyshova.critical_pn_kv", "node_id": "latyshova.critical_pn_kv", "file": "pictures/critical_pn_kv_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Pн и kв пласта сравнивают с критическими значениями: больший Pн и меньший kв означают продуктивный коллектор.", "alt": "Схема: по Pн и kв пласта, рассчитанным по формулам, сравнивают их с критическими значениями. Если Pн больше, а kв меньше критических, коллектор продуктивный, в обратном случае непродуктивный.", "source": "построено кодом по утверждениям главы, стр. 98", "claim_ids": ["latyshova.critical_pn_kv#c2", "latyshova.critical_pn_kv#c3", "latyshova.critical_pn_kv#c4", "latyshova.critical_pn_kv#c5"], "prompt": null}]}, {"title": "Относительные фазовые проницаемости делят пласт на зоны нефти, смеси и воды", "short_title": "Фазовые проницаемости и зоны притока", "why_here": {"text": "Объясняет физический смысл порогов kв* и kв** и зоны неоднозначной оценки.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "Н"}, "threshold": false, "pages": [99], "misconception": {"ref": null, "text": "Заблуждение: если в пласте есть нефть, из него пойдёт чистая нефть. На деле между Pн* и Pн** характер насыщения неопределённый, возможна смесь нефти и воды.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: зависимость Pн от водонасыщения и две кривые относительной фазовой проницаемости (нефть и вода, либо газ и вода) для коллектора с мало меняющейся глинистостью. Выход: три интервала водонасыщения (нефть, смесь, вода), критические kв*, kв** и соответствующие Pн*, Pн**.", "by_model": true}, "breaks": {"text": "В интервале между Pн* и Pн** характер насыщения неоднозначен. Кривые на рис. 70 даны для чистого песчаного коллектора; процедура рассчитана на мало меняющуюся глинистость.", "by_model": true}, "hypotheses": [{"text": "Для сильно глинистых или неоднородных коллекторов одна пара кривых, вероятно, не подойдёт и пороги придётся определять отдельно.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Светофор с тремя состояниями: зелёный — чистая нефть, жёлтый — смесь и неопределённость, красный — вода. Пороги Pн* и Pн** играют роль границ между цветами.", "breaks_where": "У светофора жёлтая зона узкая и по времени. У пласта её ширина задана свойствами породы и флюидов, и внутри неё приток может быть любой смесью.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["Параметр насыщения Pн пласта", "Критические значения Pн* и Pн**", "Предельное Pн max для коллектора"], "rule": "Pн max > Pн > Pн* — чистая нефть; Pн* > Pн > Pн** — неопределённый характер; Pн** > Pн ≥ 1 — чистая вода.", "conclusion": "По Pн пласт относят к нефтяной, неопределённой или водяной зоне; в средней зоне однозначного вывода нет.", "counterexample": "Если Pн попал между Pн* и Pн**, по порогам нельзя сказать, нефть пойдёт, вода или смесь."}, "worked_examples": [{"page_pdf": 99, "condition": "Пример 48. Установить критические параметры для выделения продуктивных коллекторов межзернового типа с мало изменяющейся глинистостью.", "steps": ["Взять одну зависимость Pн = f(kв) и две зависимости относительной фазовой проницаемости от kв для системы нефть – вода (либо газ – вода).", "По кривым рис. 70 выделить три интервала kв: однофазное течение нефти, двухфазное течение нефти и воды (между kв* и kв**), однофазное течение воды (от kв** до 1).", "Найти Pн*, Pн** по kв*, kв** и предельное Pн max по минимальному водонасыщению kв,со.", "Для критерия второго рода взять заданное отношение проницаемостей (например, равное 1); kв,кр и Pн,кр соответствуют точке пересечения кривых."], "result": "Pн max > Pн > Pн* — чистая нефть; Pн* > Pн > Pн** — неопределённый характер; Pн** > Pн ≥ 1 — чистая вода. Автор числовых значений не приводит.", "figure": "рис. 70, стр. 99"}], "book_tasks": [], "terms_introduced": ["относительная фазовая проницаемость", "однофазное течение", "двухфазное течение"], "links": [{"type": "prerequisite", "target": "latyshova.productivity_pn"}, {"type": "prerequisite", "target": "latyshova.critical_pn_kv"}], "needs_scan": [{"page": 99, "what": "Рис. 70: форма кривых относительных фазовых проницаемостей, подписи осей, положения kв*, kв**, kв,со, точка пересечения кривых и расшифровка штриховки"}], "claims": [{"page_print": null, "text": "Пример 48 ставит задачу: установить критические параметры для выделения продуктивных коллекторов межзернового типа с мало изменяющейся глинистостью.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.03", "quote": "Установить критические параметры для выделения продуктивных коллекторов межзерно-вого типа", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c1"}, {"page_print": null, "text": "Для коллекторов с мало изменяющейся глинистостью нужна одна зависимость Pн от пористости/водонасыщения и две зависимости относительной фазовой проницаемости от той же величины.", "kind": "assumption", "page_pdf": 99, "unit_id": "p099.04", "quote": "В этом случае необходимо иметь одну зависимость", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c2"}, {"page_print": null, "text": "Две зависимости относительной фазовой проницаемости строят для системы нефть – вода либо для системы газ – вода.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.04", "quote": "для системы нефть – вода (либо системы газ - вода)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c3"}, {"page_print": null, "text": "Такие зависимости приведены на рис. 70 для чистого песчаного коллектора.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.04", "quote": "На рис.70 приведены такие зависимости для чистого песчаного коллектора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c4"}, {"page_print": null, "text": "По кривым выделяются три интервала значений водонасыщения.", "kind": "inference", "page_pdf": 99, "unit_id": "p099.04", "quote": "По кривым выделятся три интервала значений", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c5"}, {"page_print": null, "text": "Первый интервал — однофазное течение нефти, от минимального водонасыщения kв,со; верхняя граница в тексте записана как kв**.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.04", "quote": "однофазного течения нефти  \\( k_{n,ca} < k_{n} < k_{n}^{**} \\)", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c6"}, {"page_print": null, "text": "Второй интервал — двухфазное течение нефти и воды, между kв* и kв**.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.04", "quote": "двухфазного течения нефти и воды", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c7"}, {"page_print": null, "text": "Третий интервал — однофазное течение воды, от kв** до единицы (включительно).", "kind": "observation", "page_pdf": 99, "unit_id": "p099.04", "quote": "однофазного течения воды  \\( k_{n}^{**} < k_{n} \\leq 1 \\)  (см. рис. 70, а)", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c8"}, {"page_print": null, "text": "На рис. 70 цифрами 1, 2, 3 обозначены области течения нефти, нефти с водой и воды соответственно.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.05", "quote": "1, 2, 3 – области течения нефти, нефти с водой и воды соответственно.", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c9"}, {"page_print": null, "text": "Рис. 70 содержит два графика: (а) зависимости относительных фазовых проницаемостей и (б) зависимость Pн от водонасыщения.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.05", "quote": "Зависимости  \\( k_{\\mathrm{op,n}} = f(k_n) \\)  и  \\( k_{\\mathrm{op,n}} = f(k_n)(a) \\) ;  \\( P_n = f(k_n)(b) \\)", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c10"}, {"page_print": null, "text": "По описанию программы распознавания, нижняя панель имеет ось Y со шкалой от 0 до 1 с отметками 0,5 и 1.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.06", "quote": "Ось Y (вертикальная): шкала от 0 до 1, с отметками 0,5 и 1.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.phase_permeability_zones#c11"}, {"page_print": null, "text": "По описанию программы распознавания, на нижней панели две кривые идут от значений около 1 к минимуму и затем снова к 1; форма приблизительная.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.06", "quote": "Обе кривые снижаются от высоких значений (близких к 1) к минимуму и затем возрастают снова к 1 у правого края", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.phase_permeability_zones#c12"}, {"page_print": null, "text": "По описанию программы распознавания, левая и правая ветви нижней панели различаются штриховкой: косой и крапчатой.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.06", "quote": "Правая ветвь кривой (от минимума к x_нз) обозначена крапчатой", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.phase_permeability_zones#c13"}, {"page_print": null, "text": "По описанию программы распознавания, на рисунке два условных знака (косая штриховка и крапчатый узор), подписи к ним не читаются.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.07", "quote": "Литология/физический смысл штриховок не определяется без полной легенды.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.phase_permeability_zones#c14"}, {"page_print": null, "text": "Критические значения kв* и kв** ограничивают область двухфазного насыщения.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.08", "quote": "ограничивают область двухфазного насыщения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c15"}, {"page_print": null, "text": "С точки зрения промысловой геофизики эта область — область неоднозначной оценки характера насыщения.", "kind": "inference", "page_pdf": 99, "unit_id": "p099.08", "quote": "с точки зрения промысловой геофизики, область неоднозначной оценки его характера.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c16"}, {"page_print": null, "text": "Критическим значениям kв*, kв** соответствуют критические значения Pн*, Pн**.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.09", "quote": "соответствуют критические значения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c17"}, {"page_print": null, "text": "Минимальному водонасыщению коллектора kв,со соответствует предельное для данного коллектора значение Pн max.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.09", "quote": "а минимальному водонасыщению коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c18"}, {"page_print": null, "text": "Если Pн max > Pн > Pн*, коллектор даёт чистую нефть.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.09", "quote": "коллектор дает чистую нефть", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c19"}, {"page_print": null, "text": "Если Pн* > Pн > Pн**, характер насыщения неопределённый.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.09", "quote": "характер насыщения неопределенный", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c20"}, {"page_print": null, "text": "Если Pн** > Pн ≥ 1, коллектор даёт чистую воду.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.09", "quote": "коллектор дает чистую воду.", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c21"}, {"page_print": null, "text": "Критерием второго рода можно считать значения Pн и kв в интервалах Pн*–Pн** и kв*–kв**, отвечающие заданному отношению относительных проницаемостей.", "kind": "assumption", "page_pdf": 99, "unit_id": "p099.09", "quote": "В качестве критерия второго рода можно использовать определенные значения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c22"}, {"page_print": null, "text": "Заданное отношение проницаемостей означает заданное соотношение нефти и воды в притоке; пример — отношение, равное единице.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.09", "quote": "заданному соотношению нефти и воды в притоке жидкости, например, величине", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c23"}, {"page_print": null, "text": "При отношении, равном единице, kв,кр и Pн,кр соответствуют точке пересечения двух кривых относительной проницаемости (рис. 70).", "kind": "inference", "page_pdf": 99, "unit_id": "p099.09", "quote": "соответствуют точке пересечения кривых", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.phase_permeability_zones#c24"}], "id": "latyshova.phase_permeability_zones", "order": 25, "minutes": 4, "essence": "Относительная фазовая проницаемость показывает, какую долю полной проницаемости получает каждая фаза (нефть или вода), когда в порах две фазы сразу. По двум таким кривым и зависимости Pн от kв выделяют три интервала водонасыщения: однофазная нефть, смесь нефти и воды, однофазная вода. Границы смеси kв* и kв** (и Pн*, Pн**) задают область неоднозначной оценки характера насыщения.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Относительная фазовая проницаемость фазы зависит от водонасыщения kв. Для системы нефть – вода строят две кривые: для нефти и для воды. Для системы газ – вода строят такие же две кривые.", "pages": [99]}, {"text": "Однофазное течение — в порах движется только одна фаза: либо нефть, либо вода. Двухфазное течение — одновременно движутся нефть и вода. На рис.", "pages": [99]}, {"text": "70 для чистого песчаного коллектора выделены три интервала kв. Первый интервал — однофазное течение нефти, от минимального водонасыщения kв,со. Второй интервал — двухфазное течение, между kв* и kв**.", "pages": [99]}, {"text": "Третий интервал — однофазное течение воды, от kв** до единицы. Каждому критическому kв соответствует критическое значение параметра насыщения Pн. Минимальному водонасыщению kв,со соответствует предельное для данного коллектора Pн max.", "pages": [99]}, {"text": "Параметр Pн растёт при снижении водонасыщения. Поэтому нефть соответствует большим Pн, вода — малым, а смесь лежит между Pн* и Pн**.", "pages": [99]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Для коллекторов межзернового типа с мало меняющейся глинистостью нужны три зависимости: одна Pн = f(kв) и две кривые относительной проницаемости, для нефти и для воды. По значению Pн в пласте определяют характер насыщения. Pн между Pн max и Pн* — пласт даёт чистую нефть.", "pages": [99]}, {"text": "Pн между Pн* и Pн** — характер насыщения неопределённый. Pн между Pн** и 1 — чистая вода. Если нужен более строгий критерий, берут заданное отношение проницаемостей по нефти и воды, например равное единице.", "pages": [99]}, {"text": "Тогда kв,кр и Pн,кр находят в точке пересечения двух кривых.", "pages": [99]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Зона между kв* и kв** — это область двухфазного насыщения. Для промысловой геофизики это область неоднозначной оценки: по Pн нельзя уверенно сказать, что пойдёт. Приведённые на рис.", "pages": [99]}, {"text": "70 зависимости относятся к чистому песчаному коллектору. Для другого коллектора кривые будут иными. В тексте интервал однофазной нефти записан с верхней границей kв**; по смыслу это, вероятно, опечатка и должно быть kв*.", "pages": [99]}, {"text": "Описание рис. 70, сделанное программой распознавания, плохо читается: обозначения осей и легенда неразборчивы. Поэтому форму кривых нужно сверять со сканом.", "pages": [99]}]}], "deeper": [], "glossary": [{"term": "относительная фазовая проницаемость", "definition": "Доля проницаемости породы, которую получает данная фаза (нефть, вода или газ), когда в порах присутствуют две фазы. Зависит от водонасыщения."}, {"term": "однофазное течение", "definition": "Течение, при котором в порах движется только одна фаза: нефть или вода."}, {"term": "двухфазное течение", "definition": "Течение, при котором в порах одновременно движутся две фазы, например нефть и вода."}], "format": "интерактив", "tasks": [{"id": "latyshova.phase_permeability_zones.t1", "type": "single", "step_id": "latyshova.phase_permeability_zones", "claim_ids": ["latyshova.phase_permeability_zones#c20", "latyshova.phase_permeability_zones#c16"], "prompt": "Для чистого песчаного коллектора известны критические значения параметра насыщения Pн* и Pн** (Pн* > Pн**). Измеренный в пласте Pн оказался между ними. Какой вывод о характере насыщения правомерен?", "options": [{"id": "a", "text": "Пласт даёт чистую нефть, потому что Pн заметно больше единицы", "misconception": "misc.high_res_oil"}, {"id": "b", "text": "Пласт даёт чистую воду, потому что Pн меньше предельного Pн max", "misconception": null}, {"id": "c", "text": "Характер насыщения неопределённый: возможна смесь нефти и воды", "misconception": null}, {"id": "d", "text": "Пласт непродуктивен, потому что значение Pн лежит ниже Pн max", "misconception": null}], "answer": "c", "tolerance": null, "unit": null, "explanation": "Между Pн* и Pн** лежит область двухфазного течения, где по Pн нельзя однозначно оценить характер насыщения.", "kind": "understanding"}, {"id": "latyshova.phase_permeability_zones.t2", "type": "order", "step_id": "latyshova.phase_permeability_zones", "claim_ids": ["latyshova.phase_permeability_zones#c2", "latyshova.phase_permeability_zones#c5", "latyshova.phase_permeability_zones#c17", "latyshova.phase_permeability_zones#c24"], "prompt": "Расположите действия при установлении критических параметров для коллектора межзернового типа с мало меняющейся глинистостью в порядке выполнения.", "options": [{"id": "a", "text": "Найти Pн*, Pн** по kв*, kв** и Pн max по kв,со"}, {"id": "b", "text": "Взять зависимость Pн = f(kв) и две кривые относительной фазовой проницаемости"}, {"id": "c", "text": "Для критерия второго рода взять заданное отношение проницаемостей и найти точку пересечения кривых"}, {"id": "d", "text": "По кривым выделить три интервала водонасыщения"}], "answer": ["b", "d", "a", "c"], "tolerance": null, "unit": null, "explanation": "Сначала берут кривые, по ним выделяют интервалы, затем переводят границы kв в Pн и только потом применяют дополнительный критерий.", "kind": "recall"}], "pictures": [{"id": "latyshova.phase_permeability_zones.i1", "step_id": "latyshova.phase_permeability_zones", "node_id": "latyshova.phase_permeability_zones", "file": "pictures/phase_permeability_zones_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "симуляция", "caption": "Две кривые фазовых проницаемостей. Границы kв* и kв** делят ось на нефть, смесь нефти с водой и воду.", "alt": "График: проницаемость для нефти падает, а для воды растёт с ростом водонасыщения. Отметки kв* и kв** ограничивают область двухфазного течения.", "source": "построено кодом по утверждениям главы, стр. 99", "claim_ids": ["latyshova.phase_permeability_zones#c5", "latyshova.phase_permeability_zones#c6", "latyshova.phase_permeability_zones#c7", "latyshova.phase_permeability_zones#c8", "latyshova.phase_permeability_zones#c15"], "prompt": null}]}, {"title": "Примеры определения критических Pн и kв и характера насыщения чистого коллектора", "short_title": "Примеры критических значений", "why_here": {"text": "Закрепляет предыдущий шаг числами: от кривых фазовых проницаемостей к Pн.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Н"}, "threshold": false, "pages": [99, 100], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход примера 49: кривые относительной фазовой проницаемости (рис. 70, б) и зависимость Pн = f(kв) (рис. 70, а). Выход: насыщения 30, 56, 80 % и Pн 10, 3, 1,5. Вход примера 50: Pн 35, 7, 2, 1,3 и кривая с модулем αСП = 1. Выход: ожидаемый характер притока.", "by_model": true}, "breaks": {"text": "Пример 50 рассмотрен только для чистого коллектора (αСП = 1); для других αСП в этой части главы правила нет. Значения Pн и kв считаны с рис. 70 и относятся к конкретному коллектору.", "by_model": true}, "hypotheses": [{"text": "Pн,кр = 3 из примера 49, возможно, объясняет разницу между Pн = 7 (нефть с небольшим количеством воды) и Pн = 2 (вода с признаками нефти). Автор эту связь прямо не проводит.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Две кривые похожи на цепочку таблиц подстановки. Первая выдаёт значение насыщения, вторая переводит его в Pн. Затем Pн сравнивают с порогами, как значение метрики с уровнями алерта.", "breaks_where": "Таблицы подстановки точные и универсальные, а кривые рис. 70 свои для каждого коллектора и считываются графически с погрешностью.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Графики относительных фазовых проницаемостей и зависимость Pн = f(kв) для данного коллектора; измеренные значения Pн; значение αСП.", "manual_steps": "Считать по кривым рис. 70, б значения насыщения, перенести их на рис. 70, а и прочитать Pн. Для каждого измеренного Pн найти точку на кривой αСП = 1 и определить характер притока.", "judgment_points": "Выбор кривой по αСП и интерпретация попадания точки в зону нефти, смеси или воды.", "time": "в главе не указано", "typical_errors": "В главе не указано; возможны неточное считывание значений с графиков и выбор кривой, не соответствующей αСП.", "by_model": true}, "decision_on_data": {"features": ["Pн коллектора", "αСП = 1 (чистый коллектор)", "зависимость на рис. 70, а"], "rule": "Для чистого коллектора по кривой с αСП = 1 соотнести Pн с характером притока: Pн = 35 даёт чистую нефть, 7 — нефть с небольшим количеством воды, 2 — воду с признаками нефти, 1,3 — чистую воду.", "conclusion": "Чем ниже Pн, тем больше воды ожидается в притоке: от чистой нефти при Pн = 35 до чистой воды при Pн = 1,3.", "counterexample": "Для коллектора с αСП ≠ 1 использовать кривую αСП = 1 нельзя; в этой части главы для такого случая правил нет."}, "worked_examples": [{"page_pdf": 99, "condition": "Определить критические значения kв и Pн для коллектора, характеризуемого зависимостями на рис. 70.", "steps": ["По кривым относительной фазовой проницаемости (рис. 70, б) найти насыщения: 30 %, 56 % (критическое), 80 %.", "По зависимости Pн = f(kв) (рис. 70, а) найти Pн, соответствующие каждому из этих насыщений."], "result": "Pн* = 10, Pн,кр = 3, Pн** = 1,5.", "figure": "рис. 70, стр. 99"}, {"page_pdf": 100, "condition": "Оценить характер насыщения чистого коллектора (αСП = 1) по зависимости на рис. 70, а для Pн = 35; 7; 2; 1,3.", "steps": ["Взять на рис. 70, а кривую с модулем αСП = 1.", "Для каждого значения Pн определить по кривой ожидаемый характер притока при испытании."], "result": "Pн = 35 — чистая нефть; 7 — нефть с небольшим количеством воды; 2 — вода с признаками нефти; 1,3 — чистая вода.", "figure": "рис. 70, стр. 99"}], "book_tasks": [], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.critical_pn_kv"}, {"type": "prerequisite", "target": "latyshova.phase_permeability_zones"}, {"type": "prerequisite", "target": "latyshova.productivity_pn"}], "needs_scan": [{"page": 99, "what": "Рис. 70, а и б: зависимость Pн = f(kв) и кривые относительной фазовой проницаемости; нужно проверить считанные значения и смысл обозначений k*, k**, P*, P**."}], "claims": [{"page_print": null, "text": "Пример 49 ставит задачу определить критические значения kв и Pн для коллектора, который характеризуется зависимостями на рис. 70.", "kind": "assumption", "page_pdf": 99, "unit_id": "p099.10", "quote": "Определить критические значения параметров  \\( k_{n} \\)  и  \\( P_{n} \\)  для коллектора, характеризуемого зависимостями на рис. 70.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.critical_values_examples#c1"}, {"page_print": null, "text": "По кривым относительной фазовой проницаемости (рис. 70, б) находят три значения насыщения: 30 %, 56 % (критическое) и 80 %.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.10", "quote": "По кривым относительной фазовой проницаемости на рис. 70, б находим  \\( k_{n}^{*} = 30\\% \\) ;  \\( k_{n,кр} = 56\\% \\) ;  \\( k_{n}^{**} = 80\\% \\) .", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_values_examples#c2"}, {"page_print": null, "text": "Pн определяют по зависимости Pн = f(kв) (рис. 70, а) соответственно каждому из ранее установленных значений насыщения.", "kind": "inference", "page_pdf": 99, "unit_id": "p099.10", "quote": "По зависимости  \\( P_{n} = f(k_{n}) \\)  (см. рис. 70, а) находим соответственно установленным", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_values_examples#c3"}, {"page_print": null, "text": "Для найденных значений насыщения получены величины Pн* = 10, Pн,кр = 3 и Pн** = 1,5.", "kind": "observation", "page_pdf": 99, "unit_id": "p099.10", "quote": "величины  \\( P_{n}^{*} = 10 \\) ,  \\( P_{n,кр} = 3 \\) ,  \\( P_{n}^{**} = 1,5 \\) .", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_values_examples#c4"}, {"page_print": null, "text": "Пример 50 ставит задачу оценить характер насыщения чистого коллектора (αСП = 1) по зависимости на рис. 70, а для Pн = 35; 7; 2; 1,3.", "kind": "assumption", "page_pdf": 100, "unit_id": "p100.01", "quote": "Оценить характер насыщения чистого коллектора ( \\( \\alpha_{СП} = 1 \\) ), используя зависимость на рис. 70, а для значений  \\( P_{n} = 35 \\) ; 7; 2; 1,3.", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.critical_values_examples#c5"}, {"page_print": null, "text": "Характер насыщения определяют по кривой с модулем αСП = 1, то есть для чистого коллектора.", "kind": "inference", "page_pdf": 100, "unit_id": "p100.01", "quote": "По кривой с модулем  \\( \\alpha_{СП} = 1 \\)  устанавливаем, что коллектор при испытании даст соответственно:", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_values_examples#c6"}, {"page_print": null, "text": "Для Pн = 35; 7; 2; 1,3 коллектор при испытании даст соответственно чистую нефть; нефть с небольшим количеством воды; воду с признаками нефти; чистую воду.", "kind": "inference", "page_pdf": 100, "unit_id": "p100.01", "quote": "чистую нефть; нефть с небольшим количеством воды; воду с признаками нефти; чистую воду.", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.critical_values_examples#c7"}], "id": "latyshova.critical_values_examples", "order": 26, "minutes": 3, "essence": "Сначала по кривым относительной фазовой проницаемости (рис. 70, б) читают характерные значения насыщения: 30, 56 и 80 %. Затем по зависимости Pн = f(kв) (рис. 70, а) находят им соответствующие Pн: 10, 3 и 1,5. Полученная зависимость позволяет по измеренному Pн предсказать, что даст чистый коллектор при испытании: чистую нефть, смесь или воду.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Связь двух рисунков работает как цепочка. Кривые относительной фазовой проницаемости (рис. 70, б) показывают, при каком насыщении меняется характер течения.", "pages": [99]}, {"text": "Отсюда берутся характерные значения насыщения: 30, 56 и 80 %. Зависимость Pн = f(kв) (рис. 70, а) переводит каждое такое насыщение в параметр насыщения Pн.", "pages": [99, 100]}, {"text": "Параметр насыщения Pн — это отношение сопротивления пласта к сопротивлению того же пласта, полностью насыщенного водой. Так насыщение, которое нельзя измерить по каротажу напрямую, превращается в Pн, который можно найти по сопротивлению. Во втором примере действие обратное: известный Pн откладывают на зависимости и читают ожидаемый характер притока.", "pages": [99, 100]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок в примере 49 такой. Берут кривые относительной фазовой проницаемости и считывают три значения насыщения. Для каждого по зависимости Pн = f(kв) находят Pн.", "pages": [99]}, {"text": "Результат — три критических параметра: Pн* = 10, Pн,кр = 3, Pн** = 1,5. В примере 50 берут измеренные Pн: 35, 7, 2 и 1,3. Для чистого коллектора (αСП = 1) используют кривую с модулем αСП = 1 и по ней определяют ожидаемый приток.", "pages": [99, 100]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "В единицах значения kв записаны как k_n (так распознан текст). По смыслу главы это, вероятно, коэффициент водонасыщения kв. Что именно означают одна и две звёздочки (k*, k**), в этой части главы не пояснено.", "pages": [99, 100]}, {"text": "Пример 50 решён только для чистого коллектора с αСП = 1. Числа в обоих примерах считаны с графиков рис. 70, самих кривых в этой части главы нет.", "pages": [100]}]}], "deeper": [], "glossary": [], "format": "практикум на данных", "tasks": [{"id": "latyshova.critical_values_examples.t1", "type": "gap", "step_id": "latyshova.critical_values_examples", "claim_ids": ["latyshova.critical_values_examples#c2", "latyshova.critical_values_examples#c4"], "prompt": "В примере 49 по кривым относительной фазовой проницаемости найдены насыщения 30, 56 и 80 %. По зависимости Pн = f(kв) насыщению 30 % отвечает Pн* = {{1}}, а насыщению 80 % — Pн** = {{2}}.", "options": [], "answer": ["10", "1,5"], "tolerance": null, "unit": null, "explanation": "Из примера 49: Pн* = 10, Pн,кр = 3, Pн** = 1,5, то есть чем выше водонасыщение, тем меньше Pн.", "kind": "data"}, {"id": "latyshova.critical_values_examples.t2", "type": "multiple", "step_id": "latyshova.critical_values_examples", "claim_ids": ["latyshova.critical_values_examples#c6", "latyshova.critical_values_examples#c7"], "prompt": "Для чистого коллектора (αСП = 1) измерены значения Pн: 35; 7; 2; 1,3. Какие из них по кривой αСП = 1 соответствуют притоку, содержащему воду (пусть даже с примесью нефти)?", "options": [{"id": "a", "text": "Pн = 35", "misconception": null}, {"id": "b", "text": "Pн = 7", "misconception": null}, {"id": "c", "text": "Pн = 2", "misconception": null}, {"id": "d", "text": "Pн = 1,3", "misconception": null}], "answer": ["b", "c", "d"], "tolerance": null, "unit": null, "explanation": "Pн = 35 даёт чистую нефть, а 7, 2 и 1,3 — нефть с небольшим количеством воды, воду с признаками нефти и чистую воду.", "kind": "data"}], "pictures": [{"id": "latyshova.critical_values_examples.i1", "step_id": "latyshova.critical_values_examples", "node_id": "latyshova.critical_values_examples", "file": "pictures/critical_values_examples_1.svg", "frame_class": "A", "origin": "code_from_data", "label": "симуляция", "caption": "Каждому характерному водонасыщению соответствует свой Pн. Чем выше kв, тем меньше Pн.", "alt": "График: по оси x водонасыщение 30, 56 и 80 процентов, по оси y параметр насыщения 10, 3 и 1,5. Значение Pн убывает с ростом водонасыщения.", "source": "построено кодом по утверждениям главы, стр. 99", "claim_ids": ["latyshova.critical_values_examples#c2", "latyshova.critical_values_examples#c4"], "prompt": null}]}, {"title": "Критические значения для коллекторов разной глинистости", "short_title": "Критерии для разных классов", "why_here": {"text": "Обобщает критические значения на семейство коллекторов с разной глинистостью (αСП).", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "Ф"}, "threshold": false, "pages": [100], "misconception": {"ref": null, "text": "Заблуждение: критические значения Pн и kв — одни и те же для любого терригенного коллектора. Шаг показывает, что они зависят от класса (глинистости, αСП): в табл. 22 они меняются от 1,0 к 0,7.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: для каждого класса коллектора (αСП=const) зависимость Pн = f(kв) и кривые относительных фазовых проницаемостей по нефти и воде. Для глинистого коллектора нужны также ρп, kп и αСП. Выход: критические значения kв*, kв**, kв,sp и соответствующие Pн*, Pн**, Pн,sp, а также кривые Pн*, Pн**, Pн,sp, разделяющие области нефти, нефти с водой, воды, продуктивных и непродуктивных коллекторов. В табл. 22 столбцы: αСП, kв* %, Pн*, kв** %, Pн**, kв,sp %, Pн,sp; строки — αСП 1,0; 0,9; 0,8; 0,7.", "by_model": true}, "breaks": {"text": "Данные относятся к межзерновым терригенным коллекторам. Значения kв,sp и Pн,sp установлены для условия 50 % нефти и 50 % воды. Без значения αСП или другого параметра глинистости критерии для глинистого коллектора определить нельзя. Числа табл. 22 заданы лишь для четырёх значений αСП.", "by_model": true}, "hypotheses": [{"text": "Вероятно, αСП=1,0 соответствует наименее глинистому (чистому) классу, а уменьшение αСП означает рост глинистости.", "by_model": true, "hypothesis": true}, {"text": "Для промежуточных значений αСП критические значения, вероятно, можно получать интерполяцией между кривыми семейства; в главе это не сказано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это как набор калибровочных таблиц, по одной на каждый тип датчика: порог срабатывания берётся из таблицы, соответствующей классу устройства, а не единый для всех.", "breaks_where": "Классы здесь задаются физическим параметром (глинистостью по αСП), а кривые следуют из фазовых проницаемостей, а не из произвольной настройки. Поэтому значения меняются закономерно, и классов может быть больше четырёх.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["класс коллектора по αСП", "пористость и сопротивление (ρп, kп)", "параметр насыщения Pн и коэффициент водонасыщения kв", "кривые Pн*, Pн**, Pн,sp для данного αСП"], "rule": "Взять семейство для нужного αСП, найти точку (Pн, kв) относительно кривых Pн* и Pн** и кривой Pн,sp и по области определить, даёт ли коллектор нефть, нефть с водой, воду, промышленно нефтеносен ли он.", "conclusion": "Область между разделяющими кривыми показывает ожидаемый результат испытания: нефть, нефть с водой, вода; кривая Pн,sp отделяет промышленно нефтеносные коллекторы от непродуктивных.", "counterexample": "Для глинистого коллектора критерий чистого коллектора не годится: по табл. 22 при αСП=1,0 kв*=30 %, Pн*=10, а при αСП=0,7 kв*=50 %, Pн*=2,1. Один набор порогов даст неверный вывод."}, "worked_examples": [{"page_pdf": 100, "condition": "Пример 51. Оценить критические значения Pн и kв и критерии для оценки характера насыщения межзерновых терригенных коллекторов с различной пористостью, проницаемостью, глинистостью.", "steps": ["Иметь для каждого класса коллекторов зависимость Pн = f(kв) и кривые фазовых проницаемостей по нефти и воде типа рис. 70.", "Получить семейство зависимостей Pн = f(kв) при различной глинистости (пример — рис. 7, б).", "На каждом графике найти характерные значения kв,сп, kв*, kв**.", "Точки (Pн*, kв*) и (Pн**, kв**) для разных αСП=const образуют кривые Pн* и Pн**, разделяющие области коллекторов с нефтью, нефтью с водой и водой.", "Соединить точки (Pн,sp, kв,sp) и получить кривую, разделяющую промышленно нефтеносные и непродуктивные коллекторы."], "result": "Получены кривые Pн*, Pн** и Pн,sp для семейства классов коллекторов; для глинистого коллектора дополнительно нужен параметр глинистости, например αСП.", "figure": "рис. 7, б и рис. 70 (страницы в этой части главы не указаны)"}, {"page_pdf": 100, "condition": "Пример 52. Определить критические значения kв и Pн для разных классов терригенного коллектора с зависимостями Pн = f(kв) для αСП равного 1; 0,9; 0,8; 0,7 (см. рис. 7, б).", "steps": ["Взять значения kв*, kв,sp* и kв**, установленные по кривым относительной фазовой проницаемости для каждого класса коллекторов.", "По графикам Pн = f(kв) для разных αСП=const найти пары Pн и kв для каждой характерной границы.", "Записать пары в табл. 22 (значения kв,sp и Pн установлены для коллекторов с 50 % нефти и 50 % воды)."], "result": "Табл. 22 (αСП: kв*/Pн*; kв**/Pн**; kв,sp/Pн,sp): 1,0: 30 %/10; 80 %/1,6; 58 %/2,9. 0,9: 37 %/5; 77 %/1,6; 58 %/2,5. 0,8: 42 %/3,1; 74 %/1,55; 59 %/2,1. 0,7: 50 %/2,1; 68 %/1,5; 59 %/1,8.", "figure": "рис. 7, б (страница в этой части главы не указана)"}], "book_tasks": [], "terms_introduced": ["класс коллектора", "семейство зависимостей Pн = f(kв)"], "links": [{"type": "prerequisite", "target": "latyshova.critical_pn_kv"}, {"type": "prerequisite", "target": "latyshova.phase_permeability_zones"}, {"type": "prerequisite", "target": "latyshova.critical_values_examples"}, {"type": "prerequisite", "target": "latyshova.productivity_pn"}], "needs_scan": [{"page": 100, "what": "Рис. 7, б — семейство зависимостей Pн = f(kв) для αСП 1; 0,9; 0,8; 0,7: нужно видеть расположение областей нефти, нефти с водой и воды."}, {"page": 100, "what": "Рис. 70 — кривые фазовых проницаемостей по нефти и воде, из которых берут kв*, kв** и kв,sp."}, {"page": 100, "what": "Обозначения в тексте и шапке табл. 22 (k_n вместо kв, индекс sp, условие kв,sp = kв,sp) — проверить по скану."}], "claims": [{"page_print": null, "text": "Пример 51 ставит задачу оценить критические значения Pн и kв и критерии характера насыщения для межзерновых терригенных коллекторов с различной пористостью, проницаемостью и глинистостью.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.02", "quote": "критерии для оценки характера насыщения межзерновых терригенных коллекторов с различной пористостью, проницаемостью, глинистостью.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c1"}, {"page_print": null, "text": "Для каждого класса коллекторов необходимо иметь свою зависимость Pн = f(kв) и свои кривые фазовых проницаемостей по нефти и воде типа рис. 70.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.03", "quote": "необходимо иметь для каждого класса коллекторов, в результате чего будет получено семейство зависимостей", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c2"}, {"page_print": null, "text": "В результате получается семейство зависимостей Pн = f(kв) при различной глинистости; пример такого семейства приведён на рис. 7, б.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.03", "quote": "Пример такого семейства приведен на рис. 7, б.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c3"}, {"page_print": null, "text": "Каждому графику Pн = f(kв) семейства соответствуют свои характерные значения kв,сп, kв* и kв**.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.03", "quote": "Каждому графику  \\( P_{n}=f(k_{n}) \\)  этого семейства соответствуют характерные для них значения  \\( k_{n,cn}, k_{n}^{*}, k_{n}^{**} \\) .", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c4"}, {"page_print": null, "text": "Точки (Pн*, kв*) и (Pн**, kв**) на графиках для различных αСП=const образуют геометрические места точек.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.03", "quote": "Точки с координатами  \\( P_{n}^{*}, k_{n}^{*} \\)  и  \\( P_{n}^{**}, k_{n}^{**} \\)  на графиках", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c5"}, {"page_print": null, "text": "Геометрические места этих точек — кривые Pн* и Pн** как функции kв.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.03", "quote": "образуют геометрические места точек, т.е. кривые", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c6"}, {"page_print": null, "text": "Кривые Pн* и Pн** разделяют области коллекторов, дающих при испытании нефть, нефть с водой и воду.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.03", "quote": "разделяющие области коллекторов, дающих при испытании нефть, нефть с водой и воду", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c7"}, {"page_print": null, "text": "Если соединить на графиках Pн = f(kв) точки с координатами (Pн,sp, kв,sp), получается кривая Pн,sp = f(kв,sp).", "kind": "observation", "page_pdf": 100, "unit_id": "p100.03", "quote": "Соединяя на графиках  \\( P_{n}=f(k_{n}) \\)  точки с координатами  \\( P_{n,sp} \\)  и  \\( k_{n,sp} \\) , получают кривую", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c8"}, {"page_print": null, "text": "Кривая Pн,sp = f(kв,sp) разделяет области промышленно нефтеносных и непродуктивных коллекторов.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.03", "quote": "разделяющую области промышленно нефтеносных и непродуктивных коллекторов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c9"}, {"page_print": null, "text": "Для оценки характера насыщения чистого коллектора достаточно знать ρп и kп (или второй параметр, обозначенный в тексте ρ_m).", "kind": "observation", "page_pdf": 100, "unit_id": "p100.04", "quote": "Если для оценки характера насыщения чистого коллектора достаточно знать величины", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c10"}, {"page_print": null, "text": "Для определения продуктивности глинистого коллектора дополнительно необходимо значение геофизического параметра глинистости, например αСП.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.04", "quote": "для определения продуктивности глинистого коллектора необходимо располагать еще значением геофизического параметра глинистости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c11"}, {"page_print": null, "text": "Пример 52 ставит задачу определить критические значения kв и Pн для разных классов терригенного коллектора с αСП 1; 0,9; 0,8; 0,7 по зависимостям Pн = f(kв) (рис. 7, б).", "kind": "observation", "page_pdf": 100, "unit_id": "p100.08", "quote": "характеризуемого зависимостями  \\( P_{n} = f(k_{n}) \\)  для  \\( \\alpha_{СП} \\)  равного 1; 0,9; 0,8; 0,7 (см. рис. 7, б)", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c12"}, {"page_print": null, "text": "Значения kв*, kв,sp* и kв** берут по кривым относительной фазовой проницаемости рассматриваемых классов, а по графикам Pн = f(kв) для разных αСП=const находят пары Pн и kв для каждой характерной границы и записывают их в табл. 22.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.08", "quote": "находим пары значений  \\( P_{n} \\)  и  \\( k_{n} \\)  для каждой характерной границы, записывая их в табл. 22.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c13"}, {"page_print": null, "text": "Табл. 22, αСП=1,0: kв*=30 %, Pн*=10, kв**=80 %, Pн**=1,6, kв,sp=58 %, Pн,sp=2,9.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.07", "quote": "|  1,0 | 30 | 10 | 80 | 1,6 | 58 | 2,9  |", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c14"}, {"page_print": null, "text": "Табл. 22, αСП=0,9: kв*=37 %, Pн*=5, kв**=77 %, Pн**=1,6, kв,sp=58 %, Pн,sp=2,5.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.07", "quote": "|  0,9 | 37 | 5 | 77 | 1,6 | 58 | 2,5  |", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c15"}, {"page_print": null, "text": "Табл. 22, αСП=0,8: kв*=42 %, Pн*=3,1, kв**=74 %, Pн**=1,55, kв,sp=59 %, Pн,sp=2,1.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.07", "quote": "|  0,8 | 42 | 3,1 | 74 | 1,55 | 59 | 2,1  |", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c16"}, {"page_print": null, "text": "Табл. 22, αСП=0,7: kв*=50 %, Pн*=2,1, kв**=68 %, Pн**=1,5, kв,sp=59 %, Pн,sp=1,8.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.07", "quote": "|  0,7 | 50 | 2,1 | 68 | 1,5 | 59 | 1,8  |", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c17"}, {"page_print": null, "text": "Значения kв,sp и Pн в примере 52 установлены для условия равенства kв,sp самому себе (запись в единице так и выглядит), то есть для коллекторов, дающих при испытании 50 % нефти и 50 % воды.", "kind": "assumption", "page_pdf": 100, "unit_id": "p100.09", "quote": "установлены для условия  \\( k_{n,sp} = k_{n,sp} \\) ,", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c18"}, {"page_print": null, "text": "Условие для kв,sp и Pн — коллекторы, дающие при испытании 50 % нефти, 50 % воды.", "kind": "assumption", "page_pdf": 100, "unit_id": "p100.09", "quote": "т.е. для коллекторов, дающих при испытании 50 % нефти, 50 % воды.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.clay_classes_critical#c19"}], "id": "latyshova.clay_classes_critical", "order": 27, "minutes": 4, "essence": "Для межзерновых терригенных коллекторов с разной глинистостью критические значения Pн и kв нельзя взять одним набором. Их определяют для каждого класса коллектора. Получается семейство зависимостей Pн = f(kв) при разных αСП, а критические точки на них образуют разделяющие кривые.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Класс коллектора — группа пластов с одним значением глинистости, заданным αСП. Для каждого класса нужны своя зависимость Pн = f(kв) и свои кривые фазовых проницаемостей по нефти и воде (типа рис. 70).", "pages": [100]}, {"text": "Совокупность зависимостей для разных αСП — семейство. На каждом графике семейства есть характерные значения kв,сп, kв* и kв**. Точки (Pн*, kв*) и (Pн**, kв**) для разных αСП=const образуют геометрические места точек, то есть кривые Pн* и Pн**.", "pages": [100]}, {"text": "Эти кривые разделяют области коллекторов, дающих при испытании нефть, нефть с водой и воду. Соединив точки (Pн,sp, kв,sp), получают кривую, которая разделяет промышленно нефтеносные и непродуктивные коллекторы.", "pages": [100]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "В примере 52 берут четыре класса с αСП 1; 0,9; 0,8; 0,7. Значения kв*, kв,sp и kв** берут по кривым относительной фазовой проницаемости каждого класса. По графикам Pн = f(kв) для каждого αСП=const находят парные значения Pн и kв и заносят их в табл.", "pages": [100]}, {"text": "22. Для чистого коллектора достаточно знать ρп и kп. Для глинистого коллектора дополнительно нужен геофизический параметр глинистости, например αСП.", "pages": [100]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Значения kв,sp и Pн,sp в примере 52 установлены для коллекторов, дающих при испытании 50 % нефти и 50 % воды. По табл. 22 при переходе от αСП=1,0 к 0,7 меняются все критические значения. kв* растёт с 30 до 50 %, а Pн* падает с 10 до 2,1. kв** уменьшается с 80 до 68 %, Pн** с 1,6 до 1,5.", "pages": [100]}, {"text": "Pн,sp падает с 2,9 до 1,8, а kв,sp почти не меняется (58–59 %). В тексте единиц обозначения kв и индексов (k_n, sp) выглядят нестрого: возможны ошибки распознавания. Роль точки (Pн,sp, kв,sp) описана двояко: как граница продуктивных и непродуктивных коллекторов и как условие 50 % нефти и 50 % воды.", "pages": [100]}]}], "deeper": [{"text": "Сами графики семейства (рис. 7, б) и кривые фазовых проницаемостей (рис. 70) не входят в текст шага, поэтому по ним нельзя сказать, какая из границ kв* и kв** лежит выше. Из таблицы видно только изменение чисел с глинистостью. Пример 51 задаёт общую постановку, пример 52 даёт числа для четырёх классов.", "pages": [100]}], "glossary": [{"term": "класс коллектора", "definition": "Группа коллекторов с одинаковой глинистостью (одним значением αСП), для которой строят свою зависимость Pн = f(kв) и свои кривые фазовых проницаемостей и находят свои критические значения."}, {"term": "семейство зависимостей Pн = f(kв)", "definition": "Набор графиков Pн = f(kв), построенных для разных классов коллекторов при различной глинистости (разных αСП=const); из характерных точек этих графиков получают разделяющие кривые Pн*, Pн**, Pн,sp."}], "format": "карточки", "tasks": [{"id": "latyshova.clay_classes_critical.t1", "type": "calc", "step_id": "latyshova.clay_classes_critical", "claim_ids": ["latyshova.clay_classes_critical#c17"], "prompt": "По табл. 22 для класса с αСП = 0,7 критические водонасыщения: kв* = 50 %, kв** = 68 %. Какова ширина зоны двухфазного насыщения по kв (в процентных пунктах)?", "options": [], "answer": 18, "tolerance": 0.5, "unit": "%", "explanation": "Зона двухфазного течения лежит между kв* и kв**: 68 − 50 = 18.", "kind": "data"}, {"id": "latyshova.clay_classes_critical.t2", "type": "single", "step_id": "latyshova.clay_classes_critical", "claim_ids": ["latyshova.clay_classes_critical#c2", "latyshova.clay_classes_critical#c14", "latyshova.clay_classes_critical#c17"], "prompt": "Почему для терригенных коллекторов разной глинистости нельзя использовать один набор критических Pн и kв?", "options": [{"id": "a", "text": "Критические значения зависят от класса: при αСП = 1,0 Pн* = 10, при αСП = 0,7 уже 2,1", "misconception": null}, {"id": "b", "text": "Критические значения одинаковы, но разные классы различаются только по Pн max", "misconception": "misc.same_critical"}, {"id": "c", "text": "Глинистость влияет лишь на kв,sp, остальные критические значения остаются прежними", "misconception": "misc.same_critical"}, {"id": "d", "text": "Глинистость меняет только единицы измерения kв и Pн, но не их числовые пороги", "misconception": "misc.same_critical"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Для каждого класса своя зависимость Pн = f(kв), поэтому при переходе от αСП = 1,0 к 0,7 меняются kв*, Pн*, kв** и Pн**.", "kind": "understanding"}], "pictures": [{"id": "latyshova.clay_classes_critical.i1", "step_id": "latyshova.clay_classes_critical", "node_id": "latyshova.clay_classes_critical", "file": "pictures/clay_classes_critical_1.svg", "frame_class": "A", "origin": "code_from_data", "label": "симуляция", "caption": "Критические точки для разной глинистости (αСП) образуют две разделяющие кривые Pн* и Pн**.", "alt": "График с двумя кривыми критических точек. Pн* сильно падает при переходе от αСП 1,0 к 0,7, а Pн** почти не меняется и держится около 1,5–1,6.", "source": "построено кодом по утверждениям главы, стр. 100", "claim_ids": ["latyshova.clay_classes_critical#c14", "latyshova.clay_classes_critical#c15", "latyshova.clay_classes_critical#c16", "latyshova.clay_classes_critical#c17", "latyshova.clay_classes_critical#c6"], "prompt": null}]}, {"title": "Практика: оценка характера насыщения по Pн, αСП и диаграммам", "short_title": "Практика по характеру насыщения", "why_here": {"text": "Применяет все критерии насыщения, включая глинистые и тонкослоистые коллекторы.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Н"}, "threshold": false, "pages": [100], "misconception": {"ref": "misc.high_res_oil", "text": "Высокое сопротивление не означает нефть автоматически. В примере 53 пары с Pн = 5 дают разные ответы при αСП 0,8 и 0,95: нефтеносный коллектор или нефть с водой. Вывод делают по двум параметрам сразу.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: пара значений Pн и αСП (в примере 53 шесть пар) либо комплексы диаграмм. Выход: характер насыщения — нефть, нефть с водой, вода с признаками нефти или предельно нефтенасыщенный коллектор. Для пар используется рис. 7, б с областями I, II и III.", "by_model": true}, "breaks": {"text": "Заключение по диаграммам может быть неоднозначным (задача 93). В тонкослоистом коллекторе трудно определить положение продуктивных и водоносных пластов (задача 95). Причины в этой части главы не раскрыты.", "by_model": true}, "hypotheses": [{"text": "Вероятно, граница между областями на рис. 7, б зависит от класса коллектора по глинистости. Это предположение, в единицах оно не подтверждено.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на классификатор с двумя входными признаками. Точка (Pн, αСП) попадает в одну из областей решающей карты, и область задаёт ответ.", "breaks_where": "Области на рис. 7, б построены по петрофизическим зависимостям, а не обучены на данных. Ответы вроде «нефть с небольшим количеством воды» описывают ожидаемый результат испытания, а не вероятность класса.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Значения Pн и αСП, снятые с диаграмм, график рис. 7, б и комплексы диаграмм из задач.", "manual_steps": "Для каждой пары значений вручную ставят точку на графике рис. 7, б и определяют, в какую область она попала.", "judgment_points": "Какой области принадлежит точка. Как устранить неоднозначность заключения (задача 93). Как отличить продуктивные пласты от водоносных в тонкослоистом коллекторе (задача 95).", "time": "в главе не указано", "typical_errors": "В этой части главы не указаны.", "by_model": true}, "decision_on_data": {"features": ["параметр насыщения Pн", "относительная амплитуда СП αСП"], "rule": "Для пары (Pн, αСП) ставят точку на рис. 7, б. Принадлежность точки к области I, II или III определяет характер насыщения.", "conclusion": "Например, Pн = 10 и αСП = 0,9 дают нефтеносный коллектор, а Pн = 2 и αСП = 0,9 дают воду с признаками нефти.", "counterexample": "При одинаковом Pн = 5 значение αСП = 0,8 даёт нефтеносный коллектор, а αСП = 0,95 даёт нефть с небольшим количеством воды. При Pн = 3 значение αСП = 0,7 даёт предельно нефтенасыщенный коллектор, а αСП = 0,9 даёт нефть с водой."}, "worked_examples": [{"page_pdf": 100, "condition": "Пример 53. Установить характер насыщения коллектора по зависимостям рис. 7, б для пар значений: а) Pн = 10, αСП = 0,9; б) Pн = 5, αСП = 0,8; в) Pн = 5, αСП = 0,95; г) Pн = 3, αСП = 0,7; д) Pн = 3, αСП = 0,9; е) Pн = 2, αСП = 0,9.", "steps": ["Для каждой пары значений Pн и αСП находят точку на рис. 7, б.", "Определяют, к какой области — I, II или III — принадлежит точка.", "По области получают ответ."], "result": "а) коллектор нефтеносный; б) коллектор нефтеносный; в) при испытании даст нефть с небольшим количеством воды; г) предельно нефтенасыщенный; д) при испытании даст нефть с водой; е) даст воду с признаками нефти.", "figure": "рис. 7, б"}], "book_tasks": [{"number": "92", "page_pdf": 100, "text": "Определить характер насыщения коллекторов, выделяемых на основании комплекса диаграмм, приведенных на рис. 67 и 76.", "figure": "рис. 67 и 76"}, {"number": "93", "page_pdf": 100, "text": "Определить характер насыщения коллекторов по диаграммам, представленным на рис. 14 и 68. Объяснить причины неоднозначностей сделанного заключения и способа их устранения.", "figure": "рис. 14 и 68"}, {"number": "94", "page_pdf": 100, "text": "Определить характер насыщения коллекторов, выделяемых на основании диаграмм рис. 58 и 46. Объяснить, какими методами устанавливается характеристика удельного сопротивления пластовых вод и какую роль она играет при решении поставленной задачи.", "figure": "рис. 58 и 46"}, {"number": "95", "page_pdf": 100, "text": "Установить характер насыщения тонкослоистого коллектора, выделяемого на основании диаграмм, приведенных на рис. 73. Объяснить, в чем трудность определения положения продуктивных и водоносных коллекторов в разрезе исследуемой скважины.", "figure": "рис. 73"}], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.critical_values_examples"}, {"type": "prerequisite", "target": "latyshova.clay_classes_critical"}, {"type": "prerequisite", "target": "latyshova.critical_pn_kv"}, {"type": "prerequisite", "target": "latyshova.reading_palette"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [{"page": 100, "what": "Рис. 7, б: области I, II и III и их соответствие ответам примера 53"}, {"page": 100, "what": "Диаграммы рис. 67, 76, 14, 68, 58, 46 и 73 к задачам 92–95 (страницы рисунков в этой части главы не указаны)"}], "claims": [{"page_print": null, "text": "Пример 53 требует установить характер насыщения коллектора по зависимостям рис. 7, б для заданных значений параметров.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.10", "quote": "Установить характер насыщения коллектора, используя зависимости, приведенные на рис. 7, б для следующих значений параметров", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c1"}, {"page_print": null, "text": "Для каждой пары значений Pн и αСП на рис. 7, б находят точку.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.10", "quote": "Для каждой пары значений  \\( P_{n} \\)  и  \\( \\alpha_{CII} \\)  находим точку на рис. 7, б.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c2"}, {"page_print": null, "text": "Ответ определяется принадлежностью точки к области I, II или III. Для пар а) и б) коллектор нефтеносный.", "kind": "inference", "page_pdf": 100, "unit_id": "p100.10", "quote": "По принадлежности получаемой точки к области I, II и III получаем ответы: а) коллектор нефтеносный; б) коллектор нефтеносный;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c3"}, {"page_print": null, "text": "Для пары в) коллектор при испытании даст нефть с небольшим количеством воды. Для пары г) он предельно нефтенасыщенный.", "kind": "inference", "page_pdf": 100, "unit_id": "p100.10", "quote": "в) коллектор при испытании даст нефть с небольшим количеством воды; г) коллектор предельно нефтенасыщенный;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c4"}, {"page_print": null, "text": "Для пары д) коллектор при испытании даст нефть с водой. Для пары е) он даст воду с признаками нефти.", "kind": "inference", "page_pdf": 100, "unit_id": "p100.10", "quote": "д) коллектор при испытании даст нефть с водой; е) коллектор даст воду с признаками нефти.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c5"}, {"page_print": null, "text": "Задача 92: определить характер насыщения коллекторов, выделяемых по комплексу диаграмм на рис. 67 и 76.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.12", "quote": "Определить характер насыщения коллекторов, выделяемых на основании комплекса диаграмм, приведенных на рис. 67 и 76.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c6"}, {"page_print": null, "text": "Задача 93: определить характер насыщения по диаграммам рис. 14 и 68 и объяснить причины неоднозначности заключения и способ её устранения.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.13", "quote": "Определить характер насыщения коллекторов по диаграммам, представленным на рис. 14 и 68. Объяснить причины неоднозначностей сделанного заключения и способа их устранения.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c7"}, {"page_print": null, "text": "Задача 94 требует объяснить, какими методами устанавливается характеристика удельного сопротивления пластовых вод.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.14", "quote": "Объяснить, какими методами устанавливается характеристика удельного сопротивления пластовых", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c8"}, {"page_print": null, "text": "В задаче 94 также нужно объяснить, какую роль характеристика сопротивления пластовых вод играет при решении поставленной задачи.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.15", "quote": "вод и какую роль она играет при решении поставленной задачи.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c9"}, {"page_print": null, "text": "Задача 94 основана на диаграммах рис. 58 и 46.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.14", "quote": "Определить характер насыщения коллекторов, выделяемых на основании диаграмм рис. 58 и 46.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c10"}, {"page_print": null, "text": "Задача 95: установить характер насыщения тонкослоистого коллектора по диаграммам рис. 73.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.16", "quote": "Установить характер насыщения тонкослоистого коллектора, выделяемого на основании диаграмм, приведенных на рис. 73.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c11"}, {"page_print": null, "text": "В задаче 95 нужно объяснить трудность определения положения продуктивных и водоносных коллекторов в разрезе скважины.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.16", "quote": "Объяснить, в чем трудность определения положения продуктивных и водоносных коллекторов в разрезе исследуемой скважины.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.saturation_examples_tasks#c12"}], "id": "latyshova.saturation_examples_tasks", "order": 28, "minutes": 3, "essence": "В примере 53 для шести пар значений параметра насыщения Pн и относительной амплитуды СП αСП характер насыщения находят по точке на рис. 7, б. Область I, II или III, в которую попала точка, даёт ответ: от нефтеносного коллектора до воды с признаками нефти. Задачи 92–95 переносят это на реальные комплексы диаграмм, включая тонкослоистый коллектор.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Параметр насыщения Pн показывает, во сколько раз сопротивление пласта превышает сопротивление того же пласта, полностью насыщенного водой. Относительная амплитуда СП αСП характеризует глинистость коллектора. Для каждой пары значений на рис.", "pages": [100]}, {"text": "7, б ставится точка. Область I, II или III, в которую она попадает, определяет ответ. Какая область какому ответу соответствует, в этой части главы не сказано.", "pages": [100]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "В примере 53 при Pн = 10 и αСП = 0,9 коллектор нефтеносный. При Pн = 5 и αСП = 0,8 он тоже нефтеносный. При Pн = 5 и αСП = 0,95 даст нефть с небольшим количеством воды.", "pages": [100]}, {"text": "При Pн = 3 и αСП = 0,7 он предельно нефтенасыщенный. При Pн = 3 и αСП = 0,9 даст нефть с водой, при Pн = 2 и αСП = 0,9 — воду с признаками нефти. Задачи 92–95 требуют так же определить насыщение по комплексам диаграмм на рис.", "pages": [100]}, {"text": "67, 76, 14, 68, 58, 46 и 73.", "pages": [100]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "При одном Pн ответ зависит от αСП: при Pн = 5 значение 0,8 даёт нефтеносный коллектор, а 0,95 — нефть с водой. Задача 93 прямо требует объяснить неоднозначность заключения и способ её устранить. Задача 94 связывает ответ с удельным сопротивлением пластовых вод.", "pages": [100]}, {"text": "Задача 95 просит объяснить, почему в тонкослоистом коллекторе трудно отличить продуктивные пласты от водоносных. Самих объяснений в этой части главы нет.", "pages": [100]}]}], "deeper": [], "glossary": [], "format": "практикум на данных", "tasks": [{"id": "latyshova.saturation_examples_tasks.t1", "type": "single", "step_id": "latyshova.saturation_examples_tasks", "claim_ids": ["latyshova.saturation_examples_tasks#c4", "latyshova.saturation_examples_tasks#c3"], "prompt": "Два пласта имеют одинаковый параметр насыщения Pн = 5, но относительная амплитуда СП у первого αСП = 0,8, у второго αСП = 0,95. Что даст каждый пласт по результатам оценки на рис. 7, б?", "options": [{"id": "a", "text": "Первый — нефтеносный, второй — нефть с небольшим количеством воды", "misconception": null}, {"id": "b", "text": "Оба — нефтеносные, так как Pн одинаков", "misconception": "misc.high_res_oil"}, {"id": "c", "text": "Первый — нефть с водой, второй — предельно нефтенасыщенный", "misconception": null}, {"id": "d", "text": "Оба — вода с признаками нефти, так как Pн меньше 10", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "При одном Pн ответ зависит от αСП, и точки попадают в разные области рис. 7, б.", "kind": "transfer"}, {"id": "latyshova.saturation_examples_tasks.t2", "type": "multiple", "step_id": "latyshova.saturation_examples_tasks", "claim_ids": ["latyshova.saturation_examples_tasks#c3", "latyshova.saturation_examples_tasks#c4", "latyshova.saturation_examples_tasks#c5"], "prompt": "Для каких пар (Pн; αСП) в примере 53 коллектор признан нефтеносным?", "options": [{"id": "a", "text": "Pн = 10; αСП = 0,9", "misconception": null}, {"id": "b", "text": "Pн = 5; αСП = 0,8", "misconception": null}, {"id": "c", "text": "Pн = 3; αСП = 0,9", "misconception": null}, {"id": "d", "text": "Pн = 2; αСП = 0,9", "misconception": null}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "Пары а) и б) дают нефтеносный коллектор, пара д) — нефть с водой, пара е) — воду с признаками нефти.", "kind": "data"}], "pictures": [{"id": "latyshova.saturation_examples_tasks.i1", "step_id": "latyshova.saturation_examples_tasks", "node_id": "latyshova.saturation_examples_tasks", "file": "pictures/saturation_examples_tasks_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Как решают пример: пара Pн и αСП даёт точку на графике, а область, в которую она попала, даёт характер насыщения.", "alt": "Схема из четырёх блоков: пара значений Pн и αСП, поиск точки на графике, определение области I, II или III, вывод о характере насыщения.", "source": "построено кодом по утверждениям главы, стр. 100", "claim_ids": ["latyshova.saturation_examples_tasks#c2", "latyshova.saturation_examples_tasks#c3"], "prompt": null}]}, {"title": "Эффективная толщина однородного пласта и пласта у контакта", "short_title": "Эффективная толщина пласта", "why_here": {"text": "Опирается на характер насыщения; определяет, какая часть коллектора считается продуктивной.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "П"}, "threshold": false, "pages": [100, 101], "misconception": {"ref": "misc.owc_sharp", "text": "Шаг показывает, что чёткий контакт без переходной зоны — лишь частный случай, для которого дано простое правило. Резкую плоскую границу нельзя считать общим правилом.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Входом служат диаграммы геофизических методов и вывод о характере насыщения. На диаграмме сопротивления верхняя продуктивная часть коллектора выглядит как пласт высокого сопротивления. Его подошва даёт положение контакта при чёткой границе. Выходом служит значение h_ф в метрах глубины.", "by_model": true}, "breaks": {"text": "Правило подошвы пласта высокого сопротивления дано только для чёткой границы без переходной зоны. При переходной зоне в этой части главы правила нет.", "by_model": true}, "hypotheses": [{"text": "Для пласта с переходной зоной контакт, вероятно, нужно устанавливать по критическим значениям насыщения из других шагов.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Аналогия — выборка записей по условию: берётся лишь диапазон строк от начала таблицы до границы, где условие «продуктивно» перестаёт выполняться.", "breaks_where": "Граница в пласте не задана в данных явно, её выводят косвенно по диаграммам, а не читают как значение поля.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы геофизических методов, заключение о характере насыщения, положение кровли коллектора.", "manual_steps": "Специалист находит на диаграммах кровлю, определяет по характеру насыщения продуктивный интервал и положение контакта, затем вычисляет толщину.", "judgment_points": "Решение, где проходит контакт, и является ли граница чёткой без переходной зоны.", "time": "в главе не указано", "typical_errors": "Включить в эффективную толщину водоносную часть ниже контакта.", "by_model": true}, "decision_on_data": {"features": ["пласт однороден по коллекторским свойствам, но неоднороден по насыщению", "пласт расположен в зоне ВНК или ГВК", "граница воды и нефти чёткая, без переходной зоны"], "rule": "h_ф берут как интервал от кровли коллектора до уровня ВНК или ГВК. При чёткой границе контакт ставят на подошве пласта высокого сопротивления, то есть верхней продуктивной части.", "conclusion": "Эффективная толщина включает только часть пласта, насыщенную нефтью или газом, без водоносной части ниже контакта.", "counterexample": "При наличии переходной зоны это простое правило не подтверждено единицами: подошва пласта высокого сопротивления может не совпадать с контактом."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["продуктивная часть коллектора", "кровля коллектора"], "links": [{"type": "prerequisite", "target": "latyshova.saturation_from_resistivity"}, {"type": "prerequisite", "target": "latyshova.critical_pn_kv"}, {"type": "prerequisite", "target": "latyshova.build_litho_column"}, {"type": "refutes_misconception", "target": "misc.owc_sharp"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Раздел посвящён определению эффективной толщины h_ф продуктивного коллектора.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.17", "quote": "Определение эффективной толщины  \\( h_{\\phi} \\)  продуктивного коллектора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c1"}, {"page_print": null, "text": "Толщину однородного продуктивного пласта-коллектора определяют по диаграммам геофизических методов.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.18", "quote": "Толщину однородного продуктивного пласта-коллектора определяют по диаграммам геофизических методов", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c2"}, {"page_print": null, "text": "При определении толщины однородного продуктивного пласта учитывают правила определения границ пласта, изложенные в соответствующих разделах руководства.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.18", "quote": "с учетом правил определения границ пласта, изложенных в соответствующих разделах данного руководства.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c3"}, {"page_print": null, "text": "Для коллектора, однородного по коллекторским свойствам, но неоднородного по насыщению, толщину устанавливают для интервала, который по характеру насыщения отнесён к продуктивному.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.19", "quote": "Толщину однородного по коллекторским свойствам, но неоднородного по насыщению коллектора устанавливают для интервала, который по характеру насыщения отнесен к продуктивному.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c4"}, {"page_print": null, "text": "К такому типу (однородные по свойствам, неоднородные по насыщению) относят коллекторы в зоне водонефтяного или газоводяного контактов.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.19", "quote": "К такому типу относят коллекторы, расположенные в зоне водонефтяного или газоводяного контактов.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c5"}, {"page_print": null, "text": "В таком коллекторе продуктивна часть, насыщенная нефтью или газом.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.19", "quote": "продуктивной является часть коллектора, насыщенная нефтью или газом", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c6"}, {"page_print": null, "text": "Часть коллектора ниже контакта — водоносная или содержит непромышленную остаточную нефть или газ.", "kind": "observation", "page_pdf": 100, "unit_id": "p100.19", "quote": "а остальная часть, расположенная ниже контакта, представлена коллектором водоносным или содержащим непромышленную остаточную нефть или газ.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c7"}, {"page_print": null, "text": "Эффективная толщина таких объектов равна интервалу между кровлей коллектора и уровнем ВНК или ГВК.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.01", "quote": "Эффективная толщина таких объектов определяется интервалом между кровлей коллектора и уровнем ВНК или ГВК.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c8"}, {"page_print": null, "text": "При чёткой границе воды с нефтью без переходной зоны контакт определяют как подошву пласта высокого сопротивления.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.01", "quote": "В случае четкой границы воды с нефтью без переходной зоны контакт определяют как подошву пласта высокого сопротивления", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c9"}, {"page_print": null, "text": "Пласт высокого сопротивления в этом случае — верхняя продуктивная часть коллектора.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.01", "quote": "которой является верхняя продуктивная часть коллектора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.effective_thickness_basic#c10"}], "id": "latyshova.effective_thickness_basic", "order": 29, "minutes": 2, "essence": "Эффективная толщина h_ф — это толщина именно продуктивной части коллектора. Для однородного по насыщению пласта её берут по диаграммам по правилам определения границ. Если пласт однороден по свойствам, но неоднороден по насыщению (у ВНК или ГВК), считают только интервал от кровли до контакта.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Продуктивная часть коллектора — это часть, насыщенная нефтью или газом. Всё, что лежит ниже контакта, продуктивной не считается. Там либо вода, либо остаточная нефть или газ, которые нельзя добывать промышленно.", "pages": [100]}, {"text": "Кровля коллектора — его верхняя граница. Эффективная толщина у контакта равна расстоянию от кровли до уровня ВНК или ГВК. Если граница воды и нефти чёткая, без переходной зоны, контакт ставят на подошве пласта высокого сопротивления.", "pages": [101]}, {"text": "Этим пластом служит верхняя продуктивная часть коллектора.", "pages": [100, 101]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок действий такой. Сначала по характеру насыщения решают, какой интервал продуктивный. Затем границы находят по диаграммам геофизических методов по правилам из соответствующих разделов руководства.", "pages": [100]}, {"text": "Для пласта у контакта отсчитывают от кровли до уровня ВНК или ГВК. При чёткой границе без переходной зоны контакт берут по подошве пласта высокого сопротивления.", "pages": [101]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Руководство разбирает только случай чёткой границы без переходной зоны. Как определять контакт при наличии переходной зоны, в этой части главы не сказано. Общая толщина коллектора и эффективная толщина у контакта различаются: водоносная часть ниже контакта в h_ф не входит.", "pages": [100, 101]}, {"text": "Это относится к коллекторам, однородным по свойствам, но неоднородным по насыщению.", "pages": [100]}]}], "deeper": [], "glossary": [{"term": "продуктивная часть коллектора", "definition": "Часть коллектора, насыщенная нефтью или газом; ниже контакта лежит водоносная часть или часть с непромышленной остаточной нефтью или газом."}, {"term": "кровля коллектора", "definition": "Верхняя граница коллектора; от неё отсчитывают эффективную толщину до уровня ВНК или ГВК."}], "format": "практикум на данных", "tasks": [{"id": "latyshova.effective_thickness_basic.t1", "type": "single", "step_id": "latyshova.effective_thickness_basic", "claim_ids": ["latyshova.effective_thickness_basic#c4", "latyshova.effective_thickness_basic#c8"], "prompt": "Коллектор однороден по свойствам, его общая толщина 20 м, кровля на глубине 1500 м. Граница нефти и воды в нём чёткая, ВНК на глубине 1512 м. Чему равна эффективная толщина h_ф?", "options": [{"id": "a", "text": "12 м", "misconception": null}, {"id": "b", "text": "20 м", "misconception": "misc.total_thickness"}, {"id": "c", "text": "8 м", "misconception": "misc.water_part"}, {"id": "d", "text": "32 м", "misconception": "misc.sum_thickness"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Эффективная толщина равна интервалу от кровли до ВНК: 1512 − 1500 = 12 м.", "kind": "data"}, {"id": "latyshova.effective_thickness_basic.t2", "type": "multiple", "step_id": "latyshova.effective_thickness_basic", "claim_ids": ["latyshova.effective_thickness_basic#c7", "latyshova.effective_thickness_basic#c5"], "prompt": "Коллектор расположен в зоне ВНК или ГВК. Что может находиться в его части ниже контакта и поэтому не входит в эффективную толщину? Выберите все верные варианты.", "options": [{"id": "a", "text": "Вода", "misconception": null}, {"id": "b", "text": "Остаточная нефть или газ, не имеющие промышленного значения", "misconception": null}, {"id": "c", "text": "Нефть или газ, которые можно добывать в промышленных объёмах", "misconception": "misc.below_contact_productive"}, {"id": "d", "text": "Кровля продуктивной части коллектора", "misconception": "misc.roof_confusion"}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "Ниже контакта коллектор водоносный либо содержит непромышленную остаточную нефть или газ.", "kind": "recall"}], "pictures": [{"id": "latyshova.effective_thickness_basic.i1", "step_id": "latyshova.effective_thickness_basic", "node_id": "latyshova.effective_thickness_basic", "file": "pictures/effective_thickness_basic_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Коллектор у водонефтяного контакта: продуктивна только нефтенасыщенная часть выше контакта, ниже неё вода.", "alt": "Разрез: над пластом-коллектором лежит глинистая покрышка. В верхней части коллектора нефть, в нижней вода. Эффективная толщина равна интервалу от кровли до контакта.", "source": "построено кодом по утверждениям главы, стр. 100, 101", "claim_ids": ["latyshova.effective_thickness_basic#c5", "latyshova.effective_thickness_basic#c6", "latyshova.effective_thickness_basic#c7", "latyshova.effective_thickness_basic#c8"], "prompt": null}]}, {"title": "Проведение ВНК при наличии переходной зоны", "short_title": "ВНК в переходной зоне", "why_here": {"text": "Развивает расчёт толщины у контакта; использует критические значения ρп.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Н"}, "threshold": false, "pages": [101], "misconception": {"ref": "misc.owc_sharp", "text": "Шаг исправляет представление, что водонефтяной контакт всегда резкая плоская граница. Здесь между нефтью и водой есть переходная зона, а ВНК проводят условно по критерию.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: диаграммы больших зондов БЭЗ или индукционного зонда. По ним берут Нк, Нп, ρншах и ρвп, а также критические ρп* или ρп,пр. Выход: график ρп = f(Н) в переходной зоне и глубина ВНК.", "by_model": false}, "breaks": {"text": "Правило опирается на допущение о линейном изменении ρп в переходной зоне. Оно также требует заранее установленных ρп* и ρп,пр для данного объекта.", "by_model": true}, "hypotheses": [{"text": "Если реальное изменение ρп в зоне далеко от линейного, найденная глубина ВНК может заметно сместиться. В главе это не обсуждается.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это линейная интерполяция между двумя опорными точками. По прямой между ними находят, где значение пересекает заданный порог.", "breaks_where": "У интерполяции порог задан заранее. Здесь порог сам определяется по петрофизике объекта и зависит от выбранного критерия. Реальная зависимость может быть нелинейной.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы больших зондов БЭЗ или индукционного зонда. Критические значения ρп* или ρп,пр для объекта.", "manual_steps": "Найти кровлю и подошву переходной зоны, снять ρншах и ρвп, построить прямую ρп = f(Н), найти на ней точку с критическим ρп и провести ВНК.", "judgment_points": "Положение кровли и зеркала воды по диаграммам. Выбор критерия (ρп* или ρп,пр). Принятие линейного закона.", "time": "в главе не указано", "typical_errors": "В главе не указаны.", "by_model": true}, "decision_on_data": {"features": ["Нк и Нп по диаграммам больших зондов БЭЗ или индукционного зонда", "ρншах и ρвп", "критическое ρп* или ρп,пр"], "rule": "Провести прямую ρп = f(Н) между (ρншах, Нк) и (ρвп, Нп). ВНК проводят на глубине, где ρп равно ρп* или ρп,пр, в зависимости от принятого критерия.", "conclusion": "Глубина этой точки принимается за ВНК. При подсчёте запасов используют ρп,пр, и выше такого ВНК испытание даёт приток нефти с некоторым количеством воды.", "counterexample": "В главе не приведён. Правило держится на допущении линейности ρп в переходной зоне."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["переходная зона", "зеркало воды"], "links": [{"type": "prerequisite", "target": "latyshova.effective_thickness_basic"}, {"type": "prerequisite", "target": "latyshova.critical_pn_kv"}, {"type": "prerequisite", "target": "latyshova.critical_values_examples"}, {"type": "prerequisite", "target": "latyshova.rho_kp_palette"}, {"type": "refutes_misconception", "target": "misc.owc_sharp"}], "needs_scan": [], "claims": [{"page_print": null, "text": "При наличии переходной зоны ВНК выделяют по определённой последовательности из четырёх шагов.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "При наличии переходной зоны ВНК выделяют следующим образом:", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c1"}, {"page_print": null, "text": "Шаг 1: по диаграммам больших зондов БЭЗ или индукционного зонда определяют нижнюю границу зоны предельного нефтегазонасыщения, которая является кровлей переходной зоны.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "по диаграммам больших зондов БЭЗ или индукционного зонда определяют нижнюю границу зоны предельного нефтегазонасыщения (кровлю переходной зоны)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c2"}, {"page_print": null, "text": "Также по этим диаграммам определяют положение зеркала воды, которое является подошвой переходной зоны.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "и положение зеркала воды (подошву переходной зоны)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c3"}, {"page_print": null, "text": "Шаг 2: устанавливают удельное сопротивление зоны предельного нефтенасыщения ρншах и водоносной части коллектора ρвп.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "устанавливают удельные сопротивления зоны предельного нефтенасыщения ρншах и водоносной части коллектора ρвп", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c4"}, {"page_print": null, "text": "Шаг 3: закон изменения ρп в переходной зоне полагают линейным и проводят график ρп = f(Н).", "kind": "assumption", "page_pdf": 101, "unit_id": "p101.02", "quote": "полагая линейным закон изменения ρп в переходной зоне, проводят график ρп = f (Н)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c5"}, {"page_print": null, "text": "График соединяет точку (ρп = ρншах, Н = Нк) с точкой (ρп = ρвп, Н = Нп).", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "соединяющий точки с координатами ρп = ρншах, Н = Нк и ρп = ρвп, Н = Нп", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c6"}, {"page_print": null, "text": "Нк и Нп — глубины кровли и подошвы переходной зоны.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "где Нк, Нп – глубины кровли и подошвы переходной зоны", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c7"}, {"page_print": null, "text": "Шаг 4: на графике в переходной зоне находят точку, в которой ρп равно ρп* или ρп,пр.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "на графике ρп = f (Н) в переходной зоне находят точку, в которой ρп = ρп* или ρп = ρп,пр", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c8"}, {"page_print": null, "text": "Выбор между ρп* и ρп,пр зависит от критерия, принятого для определения ВНК. ВНК проводят через найденную точку.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "(в зависимости от того, какой критерий принят для определения ВНК), и через эту точку проводят ВНК", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c9"}, {"page_print": null, "text": "Значения ρп*, кк* и ρп,пр, кв,пр для изучаемого объекта должны быть установлены одним из рассмотренных ранее способов.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "Значения ρп*, кк* и ρп,пр, кв,пр для изучаемого объекта должны быть установлены одним из рассмотренных выше способов.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c10"}, {"page_print": null, "text": "При подсчёте запасов в качестве критерия ВНК принимают значение ρп,пр.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "При подсчете запасов в качестве критерия ВНК принимают значение ρп,пр;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c11"}, {"page_print": null, "text": "При таком критерии испытание выше ВНК даёт промышленный приток нефти с некоторым количеством воды.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.02", "quote": "в этом случае при испытании выше ВНК дает промышленный приток нефти с некоторым количеством воды.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.vnk_transition_zone#c12"}], "id": "latyshova.vnk_transition_zone", "order": 30, "minutes": 2, "essence": "Переходная зона — интервал между кровлей, где нефтенасыщение предельное, и подошвой, где начинается вода. Внутри неё сопротивление ρп принимают меняющимся по линейному закону. ВНК проводят на глубине, где график ρп = f(Н) достигает критического значения.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Сначала по диаграммам больших зондов БЭЗ или индукционного зонда находят две границы. Первая — нижняя граница зоны предельного нефтегазонасыщения, то есть кровля переходной зоны. Вторая — зеркало воды, то есть подошва переходной зоны.", "pages": [101]}, {"text": "Затем берут два сопротивления: в зоне предельного нефтенасыщения (ρншах) и в водоносной части (ρвп). Их ставят в точки с глубинами Нк (кровля) и Нп (подошва) и соединяют прямой. Так получается график ρп = f(Н).", "pages": [101]}, {"text": "На нём находят глубину, где ρп равно ρп* или ρп,пр, и через неё проводят ВНК. Выбор между ρп* и ρп,пр зависит от принятого критерия определения ВНК.", "pages": [101]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Перед построением нужно знать значения ρп*, кк* и ρп,пр, кв,пр для изучаемого объекта. Их устанавливают одним из способов, рассмотренных ранее. При подсчёте запасов критерием ВНК принимают ρп,пр.", "pages": [101]}, {"text": "Тогда при испытании выше такого ВНК получают промышленный приток нефти с некоторым количеством воды.", "pages": [101]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Линейный закон изменения ρп в переходной зоне — допущение автора, а не измеренный факт. Результат зависит от того, какой критерий выбран: ρп* или ρп,пр. Положение ВНК, принятое для подсчёта запасов, — это не граница чистой нефти.", "pages": [101]}, {"text": "Выше него ожидается приток нефти с водой.", "pages": [101]}]}], "deeper": [], "glossary": [{"term": "переходная зона", "definition": "Интервал между кровлей, где нефтегазонасыщение ещё предельное, и подошвой, то есть зеркалом воды. В нём сопротивление ρп меняется от значения нефтенасыщенной части к значению водоносной."}, {"term": "зеркало воды", "definition": "Нижняя граница переходной зоны (её подошва), с которой начинается водоносная часть коллектора."}], "format": "практикум на данных", "tasks": [{"id": "latyshova.vnk_transition_zone.t1", "type": "order", "step_id": "latyshova.vnk_transition_zone", "claim_ids": ["latyshova.vnk_transition_zone#c1", "latyshova.vnk_transition_zone#c2", "latyshova.vnk_transition_zone#c4", "latyshova.vnk_transition_zone#c5", "latyshova.vnk_transition_zone#c8"], "prompt": "Расставьте в правильном порядке шаги проведения ВНК при наличии переходной зоны.", "options": [{"id": "a", "text": "Провести прямую ρп = f(Н), соединив точки (ρншах, Нк) и (ρвп, Нп)", "misconception": null}, {"id": "b", "text": "Найти на графике глубину, где ρп равно ρп* или ρп,пр, и провести через неё ВНК", "misconception": null}, {"id": "c", "text": "По диаграммам больших зондов БЭЗ или индукционного зонда найти кровлю и подошву переходной зоны", "misconception": null}, {"id": "d", "text": "Установить сопротивление зоны предельного нефтенасыщения ρншах и водоносной части ρвп", "misconception": null}], "answer": ["c", "d", "a", "b"], "tolerance": null, "unit": null, "explanation": "Сначала находят границы зоны, затем два сопротивления, по ним строят прямую и на ней ищут критическое значение.", "kind": "recall"}, {"id": "latyshova.vnk_transition_zone.t2", "type": "gap", "step_id": "latyshova.vnk_transition_zone", "claim_ids": ["latyshova.vnk_transition_zone#c11", "latyshova.vnk_transition_zone#c12"], "prompt": "При подсчёте запасов критерием положения ВНК принимают значение {{1}}. Тогда при испытании выше такого ВНК получают промышленный приток нефти с некоторым количеством {{2}}.", "options": [], "answer": ["ρп,пр", "воды"], "tolerance": null, "unit": null, "explanation": "ВНК по ρп,пр лежит не на границе чистой нефти, поэтому выше него нефть идёт с водой.", "kind": "recall"}], "pictures": [{"id": "latyshova.vnk_transition_zone.i1", "step_id": "latyshova.vnk_transition_zone", "node_id": "latyshova.vnk_transition_zone", "file": "pictures/vnk_transition_zone_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "симуляция", "caption": "Прямая соединяет кровлю (Нк) и подошву (Нп) переходной зоны. ВНК проводят на глубине, где ρп достигает критического значения.", "alt": "График: по горизонтали глубина, по вертикали сопротивление. Прямая линия падает от ρншах на кровле переходной зоны до ρвп на её подошве. На линии отмечена точка ВНК.", "source": "построено кодом по утверждениям главы, стр. 101", "claim_ids": ["latyshova.vnk_transition_zone#c5", "latyshova.vnk_transition_zone#c6", "latyshova.vnk_transition_zone#c7", "latyshova.vnk_transition_zone#c8", "latyshova.vnk_transition_zone#c9"], "prompt": null}]}, {"title": "Положение газонефтяного контакта по повторным нейтронным замерам", "short_title": "ГНК по нейтронным замерам", "why_here": {"text": "Использует идею расформирования зоны проникновения для газового контакта.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "М"}, "threshold": false, "pages": [101], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход — диаграммы стационарных нейтронных методов: повторные замеры в обсаженной скважине или однократный замер в необсаженной на нефильтрующемся растворе. Допустим и импульсный метод. Выход — положение ГНК. На рис. 71 диаграммы НГМ даны вместе с другими методами; обозначены глины, коллекторы, нефть, газ. Признак готовности повторных замеров — стабилизация повышенных показаний НМ во времени.", "by_model": false}, "breaks": {"text": "Пока повышенные показания НМ меняются от замера к замеру, расформирование не завершено. Тогда диаграмме нельзя доверять для ГНК. Время расформирования растёт при малой проницаемости и большом радиусе зоны проникновения.", "by_model": true}, "hypotheses": [{"text": "Вероятно, повторные замеры нужны, чтобы увидеть, как показания НМ со временем выходят на устойчивый уровень после обсадки. Глава этого механизма прямо не описывает.", "by_model": true, "hypothesis": true}, {"text": "Вероятно, газ и нефть различаются по диаграмме НМ величиной показаний, и ГНК виден как смена уровня. В главе такое различие не описано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Повторные замеры похожи на ожидание, пока кэш или реплика придут в устойчивое состояние. Измерения повторяют, пока значения не перестанут меняться, и только тогда им доверяют.", "breaks_where": "Для сервиса ожидание устанавливается заранее по таймауту. Здесь срок зависит от проницаемости и радиуса зоны проникновения, а критерий — стабилизация самих показаний.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы стационарных нейтронных методов, полученные при повторных замерах в обсаженной скважине. Либо однократные диаграммы стационарных или импульсных НМ в необсаженной скважине на нефильтрующемся растворе.", "manual_steps": "Составить специальную программу повторных замеров. Выполнять замеры в обсаженной скважине, сравнивая диаграммы между замерами. Остановиться, когда повышенные показания НМ стабилизируются. По диаграммам, в комплексе с другими методами, определить положение ГНК.", "judgment_points": "Решить, что показания стабилизировались и расформирование зоны завершено. Выбрать, повторные замеры или однократный замер подходят в данной скважине.", "time": "в главе не указано", "typical_errors": "В главе ошибки не перечислены. Следует из текста: если замеры остановить до стабилизации показаний, зона проникновения ещё не расформирована.", "by_model": true}, "decision_on_data": {"features": ["Повторные замеры стационарными нейтронными методами в обсаженной скважине", "Повышенные показания НМ стабилизировались во времени", "Проницаемость коллектора и радиус зоны проникновения к спуску колонны"], "rule": "Повторные замеры ведут до стабилизации повышенных показаний НМ во времени. Стабилизация означает завершение расформирования зоны проникновения.", "conclusion": "После стабилизации показаний по диаграммам НМ в комплексе с другими методами устанавливают положение ГНК.", "counterexample": "Если показания ещё меняются между замерами, зона проникновения не расформирована полностью. Это вероятно при малой проницаемости или большом радиусе зоны проникновения."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["ГНК", "расформирование зоны проникновения"], "links": [{"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}, {"type": "prerequisite", "target": "latyshova.water_and_nonfiltering_muds"}, {"type": "prerequisite", "target": "latyshova.radial_gradient_and_dynamic"}, {"type": "prerequisite", "target": "latyshova.vnk_transition_zone"}], "needs_scan": [{"page": 101, "what": "Рис. 71: по скану проверить глубины, шкалы кривых КС, СП, НГМ-60 и отметку ГНК. Программа распознавания оценил подписи приблизительно, часть нечитаема."}, {"page": 101, "what": "Рис. 71: расшифровать неразборчивую пометку «ЮЖВ +» на диаграмме."}, {"page": 101, "what": "Рис. 71: сверить условные знаки на рисунке с легендой автора (глины, коллекторы, нефть, газ)."}], "claims": [{"page_print": null, "text": "Положение ГНК устанавливают по диаграммам стационарных нейтронных методов, полученным при повторных замерах в обсаженной скважине.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.03", "quote": "Положение ГНК устанавливают по диаграммам стационарных нейтронных методов, полученным при повторных замерах в обсаженной скважине (рис.71)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.gnk_by_neutron#c1"}, {"page_print": null, "text": "Положение ГНК можно установить и по данным однократных исследований стационарными или импульсными нейтронными методами в необсаженной скважине, пробуренной на нефильтрующемся растворе.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.03", "quote": "или по данным однократных исследований стационарными или импульсными нейтронными методами в необсаженной скважине, пробуренной на нефильтрующемся растворе.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.gnk_by_neutron#c2"}, {"page_print": null, "text": "Повторные замеры в обсаженной скважине проводят по специальной программе до стабилизации повышенных показаний НМ во времени.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.03", "quote": "Повторные замеры в обсаженной скважине проводят по специальной программе до стабилизации повышенных показаний НМ во времени", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.gnk_by_neutron#c3"}, {"page_print": null, "text": "Стабилизация повышенных показаний НМ во времени является признаком завершения расформирования зоны проникновения.", "kind": "inference", "page_pdf": 101, "unit_id": "p101.03", "quote": "что является признаком завершения расформирования зоны проникновения.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.gnk_by_neutron#c4"}, {"page_print": null, "text": "По описанию программы распознавания, на рисунке показан участок разреза глубиной 1444–1478 м, ось глубин направлена вниз.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.04", "quote": "Глубина: 1444–1478 м, ось глубин направлена вниз (возрастание вниз).", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.gnk_by_neutron#c5"}, {"page_print": null, "text": "По описанию программы распознавания, на диаграмме есть трек НГМ-60 с одной кривой; шкала подписана значениями 1, 2, 3, 4, Jгк, усл.ед.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.04", "quote": "Трек «НГМ-60»: одна кривая, шкала внизу подписана значениями 1, 2, 3, 4, Jгк, усл.ед", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.gnk_by_neutron#c6"}, {"page_print": null, "text": "По описанию программы распознавания, на интервале 1458–1466 м кривая КС снижается, а показания НГМ-60 растут.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.04", "quote": "КС — снижение значений, НГМ-60 — рост показаний", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.gnk_by_neutron#c7"}, {"page_print": null, "text": "По описанию программы распознавания, в интервале 1466–1478 м показания НГМ-60 высокие в нижней части.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.04", "quote": "НГМ-60 — высокие показания в нижней части", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.gnk_by_neutron#c8"}, {"page_print": null, "text": "По описанию программы распознавания, на диаграмме отмечена линия с неразборчивой подписью «ЮЖВ +»; её значение не расшифровано.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.04", "quote": "отмечена линия \"ЮЖВ +\"", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.gnk_by_neutron#c9"}, {"page_print": null, "text": "По описанию программы распознавания, расшифровка литологических знаков внутри изображения не приведена, поэтому литология по нему не определяется.", "kind": "observation", "page_pdf": 95, "unit_id": "p101.04", "quote": "Литология не определяется без легенды", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.gnk_by_neutron#c10"}, {"page_print": null, "text": "Рис. 71 — пример определения ГНК по диаграммам НГМ в комплексе с данными других геофизических методов.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.05", "quote": "Рис.71. Пример определения газонефтяного контакта по диаграммам НГМ в комплексе с данными других геофизических методов:", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.gnk_by_neutron#c11"}, {"page_print": null, "text": "Условные обозначения рис. 71: 1 — глины, 2 — коллекторы, 3 — нефть, 4 — газ.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.06", "quote": "1 – глины; 2 – коллекторы; 3 – нефть; 4 - газ", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.gnk_by_neutron#c12"}, {"page_print": null, "text": "Время полного расформирования зоны проникновения тем больше, чем меньше проницаемость коллектора.", "kind": "inference", "page_pdf": 101, "unit_id": "p101.07", "quote": "тем больше, чем меньше проницаемость коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.gnk_by_neutron#c13"}, {"page_print": null, "text": "Время полного расформирования зоны также тем больше, чем больше радиус зоны проникновения, сформировавшейся к моменту спуска колонны.", "kind": "inference", "page_pdf": 101, "unit_id": "p101.07", "quote": "больше радиус зоны проникновения, сформировавшейся к моменту спуска колонны", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.gnk_by_neutron#c14"}], "id": "latyshova.gnk_by_neutron", "order": 31, "minutes": 3, "essence": "Положение ГНК (газонефтяного контакта, границы между газонасыщенной и нефтенасыщенной частями пласта) устанавливают по диаграммам нейтронных методов. Берут повторные замеры в обсаженной скважине или однократный замер в необсаженной скважине на нефильтрующемся растворе. Повторные замеры продолжают до стабилизации повышенных показаний НМ: это признак завершённого расформирования зоны проникновения.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Расформирование зоны проникновения — это постепенное исчезновение зоны, которую создал в пласте фильтрат раствора при бурении. После обсадки эта зона со временем «рассасывается». Пока она рассасывается, показания нейтронных методов (НМ) во времени меняются.", "pages": [101]}, {"text": "Когда повышенные показания перестают меняться, расформирование считается завершённым. Время расформирования больше, если проницаемость коллектора ниже. Оно также больше, если радиус зоны проникновения к моменту спуска колонны был больше.", "pages": [101]}, {"text": "Нейтронные методы здесь выступают как косвенное измерение: прибор даёт отклик в условных единицах, а положение контакта выводят по диаграмме.", "pages": [101]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Повторные замеры в обсаженной скважине проводят по специальной программе. Замеры повторяют, пока повышенные показания НМ не перестанут меняться. Если скважина не обсажена, но пробурена на нефильтрующемся растворе, достаточно однократного замера.", "pages": [101]}, {"text": "Это может быть стационарный или импульсный нейтронный метод. На рис. 71 диаграммы НГМ рассматривают вместе с данными других методов.", "pages": [101]}, {"text": "Автор обозначает на рисунке глины, коллекторы, нефть и газ.", "pages": [101]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Нужны либо обсаженная скважина с повторными замерами, либо необсаженная на нефильтрующемся растворе. Для обсаженной скважины критерий — стабилизация повышенных показаний НМ. Время стабилизации заранее не одинаково: оно зависит от проницаемости и радиуса зоны проникновения.", "pages": [101]}, {"text": "Описание рисунка от программы распознавания неполное: подписи и шкалы частично нечитаемы. Расшифровку знаков надо брать из подписи автора под рисунком.", "pages": [95, 101]}]}], "deeper": [{"text": "Для рис. 71 программа распознавания называет кривые КС, СП и НГМ-60, глубины 1444–1478 м и пометку «ЮЖВ +». Эти данные приблизительные и требуют проверки по скану. В главе не сказано, как именно газ и нефть различаются по показаниям НМ. Нет и сроков, за которые наступает стабилизация.", "pages": [101]}], "glossary": [{"term": "ГНК", "definition": "Газонефтяной контакт — граница между газонасыщенной и нефтенасыщенной частями пласта. Её положение устанавливают по диаграммам нейтронных методов."}, {"term": "расформирование зоны проникновения", "definition": "Постепенное исчезновение зоны проникновения, созданной фильтратом при бурении, после обсадки скважины. Его завершение определяют по стабилизации повышенных показаний НМ во времени."}], "format": "шортс", "tasks": [{"id": "latyshova.gnk_by_neutron.t1", "type": "single", "step_id": "latyshova.gnk_by_neutron", "claim_ids": ["latyshova.gnk_by_neutron#c3", "latyshova.gnk_by_neutron#c4"], "prompt": "В обсаженной скважине для поиска ГНК сделали два повторных нейтронных замера с интервалом в несколько месяцев. Повышенные показания НМ во втором замере заметно отличаются от первого. Что из этого следует?", "options": [{"id": "a", "text": "Зона проникновения ещё не расформировалась полностью, замеры нужно продолжать", "misconception": null}, {"id": "b", "text": "Расформирование зоны проникновения завершено, можно определять ГНК", "misconception": "misc.change_means_done"}, {"id": "c", "text": "Скважина обсажена неправильно, и метод для ГНК не годится", "misconception": null}, {"id": "d", "text": "Положение ГНК сместилось вниз за это время", "misconception": "misc.gnk_moves"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Признак завершения расформирования — стабилизация повышенных показаний НМ, а здесь они ещё меняются.", "kind": "transfer"}, {"id": "latyshova.gnk_by_neutron.t2", "type": "multiple", "step_id": "latyshova.gnk_by_neutron", "claim_ids": ["latyshova.gnk_by_neutron#c13", "latyshova.gnk_by_neutron#c14"], "prompt": "Для каких условий время полного расформирования зоны проникновения будет больше? Выберите все верные варианты.", "options": [{"id": "a", "text": "Низкая проницаемость коллектора", "misconception": null}, {"id": "b", "text": "Большой радиус зоны проникновения к моменту спуска колонны", "misconception": null}, {"id": "c", "text": "Высокая проницаемость коллектора", "misconception": "misc.perm_direction"}, {"id": "d", "text": "Малый радиус зоны проникновения к моменту спуска колонны", "misconception": "misc.radius_direction"}], "answer": ["a", "b"], "tolerance": null, "unit": null, "explanation": "Время расформирования растёт с уменьшением проницаемости и с увеличением радиуса зоны проникновения.", "kind": "understanding"}], "pictures": [{"id": "latyshova.gnk_by_neutron.i1", "step_id": "latyshova.gnk_by_neutron", "node_id": "latyshova.gnk_by_neutron", "file": "pictures/gnk_by_neutron_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Повторные замеры нейтронными методами продолжают, пока повышенные показания не перестанут меняться со временем.", "alt": "Схема из четырёх блоков: повторные замеры НМ в обсаженной скважине, изменение показаний во времени, стабилизация повышенных показаний, завершение расформирования зоны проникновения.", "source": "построено кодом по утверждениям главы, стр. 101", "claim_ids": ["latyshova.gnk_by_neutron#c1", "latyshova.gnk_by_neutron#c3", "latyshova.gnk_by_neutron#c4"], "prompt": null}]}, {"title": "Прослои неколлектора внутри мощного пласта и вычитание их толщин", "short_title": "Прослои неколлектора", "why_here": {"text": "Переходит к неоднородным пластам; нужны признаки глин и плотных пород.", "by_model": true}, "difficulty": {"primary": "Р", "secondary": "Пр"}, "threshold": false, "pages": [101], "misconception": {"ref": "misc.high_res_oil", "text": "Высокие показания микрозондов не говорят о нефти. Против них такой же отклик дают плотные неколлекторы — алевролиты и песчаники с неактивным цементом. Такой интервал надо вычитать из эффективной толщины, а не считать продуктивным.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Входные данные — диаграммы микрозондов, нейтронных методов, СП и ГМ по мощному пласту и значения пористости kп. Выход — толщины прослоев неколлектора, их сумма Σhпл и эффективная толщина h,ф = h − Σhпл.", "by_model": false}, "breaks": {"text": "Вычитание не работает в пачке тонкого переслаивания коллектора и глины: прослои не разделяются даже микроэлектрическими методами. Там толщину считают по интегральным характеристикам. На СП и ГМ плотные прослои почти не видны, если нет глинистого цемента.", "by_model": false}, "hypotheses": [{"text": "Чем тоньше прослой неколлектора, тем вероятнее, что его пропустят или недооценят, и тем сильнее будет завышена h,ф.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это как подсчёт полезного объёма на диске: из общего размера вычитают размер служебных и зарезервированных блоков, которые видны как отдельные записи.", "breaks_where": "Если блоки перемешаны на уровне ниже разрешения инструмента, как слоистая глинистость, учесть каждый нельзя. Остаётся оценка по общей статистике.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы микрозондов, нейтронных методов, СП, ГМ и значения пористости по мощному пласту.", "manual_steps": "Найти на диаграммах каждый прослой неколлектора, определить его толщину, сложить и вычесть из толщины пласта.", "judgment_points": "Отличить плотный прослой от коллектора по сочетанию кривых. Решить, однороден ли пласт по насыщению. Понять, что тонкое переслаивание нужно считать другим способом.", "time": "в главе не указано", "typical_errors": "Принять плотный прослой за коллектор из-за слабых показаний СП и ГМ. Применить вычитание к слоистому глинистому коллектору.", "by_model": true}, "decision_on_data": {"features": ["повышенные показания микрозондов", "kп < kп* при показаниях ГМ", "высокие значения нейтронных методов", "отсутствие выделения на СП и ГМ"], "rule": "Интервал с признаками глины, плотного алевролита или песчаника с глинистым цементом считают прослоем неколлектора и вычитают его толщину из толщины однородного по насыщению пласта.", "conclusion": "Эффективная толщина h,ф = h − Σhпл.", "counterexample": "При тонком переслаивании коллектора и глины прослои не выделяются даже микрометодами. Вычитание невозможно, толщину h,ф2 находят расчётом по пачке в целом."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["плотные прослои", "песчаник с глинистым цементом"], "links": [{"type": "prerequisite", "target": "latyshova.effective_thickness_basic"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.build_litho_column"}, {"type": "prerequisite", "target": "latyshova.table21_clays_sands_gas"}, {"type": "prerequisite", "target": "latyshova.permeability_threshold_on_logs"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Правило относится к мощному пласту коллектора, однородному по характеру насыщения, в котором есть прослои неколлектора.", "kind": "assumption", "page_pdf": 101, "unit_id": "p101.08", "quote": "В мощном пласте коллектора, однородном по характеру насыщения, но содержащем прослои неколлектора", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c1"}, {"page_print": null, "text": "Эффективная толщина такого пласта равна разности толщины всего пласта и суммы толщин прослоев неколлектора.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "эффективная толщина h,ф определяется как разность толщин всего пласта h и суммы толщин прослоев неколлектора Σhпл", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c2"}, {"page_print": null, "text": "Формула эффективной толщины: h,ф = h − Σhпл.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "h,ф = h - Σhпл.", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c3"}, {"page_print": null, "text": "Для терригенного разреза наиболее характерны три типа прослоев неколлектора: глины, плотные алевролиты и песчаники с глинистым цементом.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "Для терригенного разреза наиболее характерны три типа прослоев неколлектора: глины, плотные алевролиты и песчаники с глинистым цементом", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c4"}, {"page_print": null, "text": "Эти прослои выделяются повышенными показаниями микрозондов и низкими значениями пористости kп < kп* при показаниях ГМ.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "выделяются повышенными показаниями микрозондов, низкими значениями kп < kп* при показаниях ГМ", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c5"}, {"page_print": null, "text": "Плотные алевролиты и песчаники — это неколлекторы с неактивным карбонатным или силикатным цементом.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "плотные алевролиты и песчаники (неколлекторы с неактивным карбонатным или силикатным цементом)", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c6"}, {"page_print": null, "text": "Плотные алевролиты и песчаники выделяются высокими значениями на диаграммах микрозондов и нейтронных методов.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "выделяются высокими значениями на диаграммах микрозондов и нейтронных методов", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c7"}, {"page_print": null, "text": "Плотные алевролиты и песчаники практически не прослеживаются на диаграммах СП и ГМ. Исключение — случай, когда наряду с неактивным цементом присутствует глинистый.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "практически не прослеживаются на диаграммах СП и ГМ, за исключением случаев, когда наряду с неактивным в породе присутствует глинистый цемент.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c8"}, {"page_print": null, "text": "Пачка из чередования тонких прослоев коллектора и глины — это глинистый коллектор со слоистой глинистостью.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "В пачке, представленной чередованием тонких прослоев коллектора и глины (глинистый коллектор со слоистой глинистостью)", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c9"}, {"page_print": null, "text": "В такой пачке отдельные прослои неколлекторов не выделяются даже методами с максимальной вертикальной разрешающей способностью — микроэлектрическими.", "kind": "observation", "page_pdf": 101, "unit_id": "p101.08", "quote": "отдельные прослои неколлекторов не выделяются даже по данным методов с максимальной разрешающей способностью по вертикали (микроэлектрические методы)", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c10"}, {"page_print": null, "text": "Поэтому суммарную эффективную толщину h,ф2 продуктивного коллектора в такой пачке находят расчётом по интегральным характеристикам пачки в целом, а не вычитанием прослоев.", "kind": "inference", "page_pdf": 101, "unit_id": "p101.08", "quote": "поэтому суммарную эффективную толщину h,ф2 продуктивного коллектора в этом случае находят расчетным путем по интегральным характеристикам пачки в целом.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.nonreservoir_interlayers#c11"}], "id": "latyshova.nonreservoir_interlayers", "order": 32, "minutes": 3, "essence": "Если мощный пласт однороден по насыщению, но содержит прослои неколлектора, их суммарную толщину вычитают из толщины всего пласта: h,ф = h − Σhпл. В терригенном разрезе чаще всего встречаются прослои глин, плотных алевролитов и песчаников с глинистым цементом. Если коллектор тонко переслаивается с глиной, прослои по отдельности не видны, и толщину считают по интегральным характеристикам пачки.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Эффективная толщина — это толщина той части пласта, которая отдаёт флюид. Если пласт однороден по насыщению, лишние прослои просто вычитают. Для этого сначала по диаграммам находят каждый прослой неколлектора и определяют его толщину.", "pages": [101]}, {"text": "Затем толщины суммируют и вычитают из толщины пласта. Прослои опознают по комбинации методов. Глины, плотные алевролиты и глинистые песчаники дают повышенные показания микрозондов (приборов с малой глубиной исследования) и низкую пористость kп < kп*.", "pages": [101]}, {"text": "Здесь kп* — критическое значение пористости, ниже которого порода считается неколлектором. Плотные алевролиты и песчаники с неактивным карбонатным или силикатным цементом дают высокие значения на микрозондах и нейтронных методах. На диаграммах СП и ГМ они почти не видны.", "pages": [101]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "На диаграммах мощного пласта выделяют интервалы с признаками неколлектора. Для плотных пород главные признаки — высокие значения микрозондов и нейтронных методов. Для глин и глинистых песчаников — показания микрозондов и низкая пористость при показаниях ГМ.", "pages": [101]}, {"text": "Толщины найденных прослоев суммируют и вычитают из h. Если коллектор слоистый и тонкие прослои не разделяются даже микроэлектрическими методами, вычитание невозможно. Тогда h,ф2 находят расчётом по интегральным характеристикам пачки в целом.", "pages": [101]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Плотные прослои с неактивным цементом на СП и ГМ почти не заметны. Поэтому по одним этим кривым их легко принять за коллектор. Исключение — случай, когда в породе кроме неактивного цемента есть и глинистый.", "pages": [101]}, {"text": "Тогда прослой заметен и на этих кривых. Правило вычитания применимо только к пласту, однородному по характеру насыщения. В формулировке автора группировка признаков по трём типам прослоев неоднозначна: часть признаков отнесена сразу к глинам, плотным алевролитам и глинистым песчаникам.", "pages": [101]}, {"text": "Здесь она передана как в книге. Глинистый коллектор со слоистой глинистостью вычитанием не обрабатывается.", "pages": [101]}]}], "deeper": [], "glossary": [{"term": "плотные прослои", "definition": "Прослои плотных алевролитов и песчаников — неколлекторы с неактивным карбонатным или силикатным цементом. Они дают высокие значения на микрозондах и нейтронных методах и почти не видны на СП и ГМ."}, {"term": "песчаник с глинистым цементом", "definition": "Песчаник, поры которого заполнены глинистым цементом. В терригенном разрезе это один из трёх характерных типов прослоев неколлектора наряду с глинами и плотными алевролитами."}], "format": "карточки", "tasks": [{"id": "latyshova.nonreservoir_interlayers.t1", "type": "calc", "step_id": "latyshova.nonreservoir_interlayers", "claim_ids": ["latyshova.nonreservoir_interlayers#c2", "latyshova.nonreservoir_interlayers#c3"], "prompt": "Мощный пласт толщиной 24 м однороден по насыщению. По диаграммам в нём выделены три прослоя неколлектора толщиной 3,0 м, 2,5 м и 1,5 м. Найдите эффективную толщину по формуле h,ф = h − Σhпл.", "options": [], "answer": 17, "tolerance": 0.1, "unit": "м", "explanation": "Сумма прослоёв 7 м, и 24 − 7 = 17 м.", "kind": "data"}, {"id": "latyshova.nonreservoir_interlayers.t2", "type": "single", "step_id": "latyshova.nonreservoir_interlayers", "claim_ids": ["latyshova.nonreservoir_interlayers#c6", "latyshova.nonreservoir_interlayers#c7", "latyshova.nonreservoir_interlayers#c8"], "prompt": "В мощном пласте есть интервал с высокими показаниями микрозондов и нейтронных методов. На диаграммах СП и ГМ он практически не выделяется. Как его следует трактовать?", "options": [{"id": "a", "text": "Как плотный алевролит или песчаник с неактивным цементом, то есть прослой неколлектора, который вычитают", "misconception": null}, {"id": "b", "text": "Как нефтенасыщенную часть коллектора, потому что сопротивление высокое", "misconception": "misc.high_res_oil"}, {"id": "c", "text": "Как глинистый коллектор, потому что СП и ГМ его не выделяют", "misconception": "misc.no_sp_gm_clean"}, {"id": "d", "text": "Как водоносную часть пласта, которую нужно вычесть по контакту", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Такую комбинацию признаков дают плотные неколлекторы с неактивным цементом, а не нефтенасыщенный коллектор.", "kind": "understanding"}], "pictures": [{"id": "latyshova.nonreservoir_interlayers.i1", "step_id": "latyshova.nonreservoir_interlayers", "node_id": "latyshova.nonreservoir_interlayers", "file": "pictures/nonreservoir_interlayers_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Эффективная толщина равна толщине всего пласта за вычетом суммы толщин прослоев неколлектора.", "alt": "Схема из четырёх блоков: пласт с прослоями неколлектора, поиск прослоев и их толщин, суммирование толщин, вычитание суммы из толщины пласта по формуле h,ф = h − Σhпл.", "source": "построено кодом по утверждениям главы, стр. 101", "claim_ids": ["latyshova.nonreservoir_interlayers#c1", "latyshova.nonreservoir_interlayers#c2", "latyshova.nonreservoir_interlayers#c3"], "prompt": null}]}, {"title": "Тонкослоистая пачка: глинистость и эффективная толщина по сопротивлению", "short_title": "Тонкослоистый коллектор по ρп", "why_here": {"text": "Когда прослои не различимы, их долю считают по среднему сопротивлению (параллельные проводимости).", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "И"}, "threshold": false, "pages": [102], "misconception": {"ref": "misc.high_res_oil", "text": "Сопротивление пачки ρп зависит от доли глины и от сопротивлений прослоев, поэтому по одному ρп нельзя судить о нефти. Сначала нужно учесть глинистость.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "На входе — ρп пачки по БЭЗ или фокусированным методам, а также заданные ρпм и ρсп. На выходе — χсп и эффективная толщина пачки h·(1 − χсп).", "by_model": true}, "breaks": {"text": "Результат зависит от выбранных ρсп и ρпм, которые задают, а не измеряют по самой пачке. Другие ограничения в этой части главы не указаны.", "by_model": true}, "hypotheses": [{"text": "Если взять ρпм слишком низким или ρсп слишком высоким, χсп и эффективная толщина получатся смещёнными.", "by_model": true, "hypothesis": true}, {"text": "Из (63) можно явно выразить χсп = (1/ρп − 1/ρпм) / (1/ρсп − 1/ρпм); это алгебраический шаг модели.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на оценку доли медленных запросов в смеси по среднему времени отклика: известны средние значения двух классов и общее среднее, из них находится доля.", "breaks_where": "В аналогии усредняются времена, а в уравнении (63) усредняются обратные величины, проводимости. Реальные прослои ещё и не вполне однородны.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы БЭЗ или комплекса фокусированных методов, данные керна или значения сопротивления чистых коллекторов и вмещающих глин.", "manual_steps": "Снять ρп пачки, выбрать ρсп и ρпм, решить (63) для χсп, вычислить эффективную толщину по (64).", "judgment_points": "Выбор ρсп (вмещающие глины) и ρпм (керн или наиболее чистый коллектор разреза).", "time": "в главе не указано", "typical_errors": "В главе не указаны.", "by_model": true}, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["относительная глинистость пачки χгл", "эффективная толщина пачки"], "links": [{"type": "prerequisite", "target": "latyshova.effective_thickness_basic"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.nonreservoir_interlayers"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [{"page": 102, "what": "Проверить по скану обозначения в формулах (63) и (64): индексы ρп, ρпм, ρсп, χсп, hэф (в распознанном тексте «sp», «cn», «nm»)."}], "claims": [{"page_print": null, "text": "Удельное сопротивление пачки ρп определяют по диаграммам БЭЗ или комплекса фокусированных методов.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.01", "quote": "по диаграммам БЭЗ или комплекса фокусированных методов, задают удельные сопротивления прослоев продуктивного коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c1"}, {"page_print": null, "text": "Задают удельные сопротивления прослоев продуктивного коллектора ρпм и глины ρсп.", "kind": "assumption", "page_pdf": 102, "unit_id": "p102.01", "quote": "задают удельные сопротивления прослоев продуктивного коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c2"}, {"page_print": null, "text": "Относительную по толщине глинистость пачки χсп рассчитывают, решая уравнение (63) относительно χсп.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.01", "quote": "рассчитывают относительную по толщине глинистость", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c3"}, {"page_print": null, "text": "Уравнение (63): обратное сопротивление пачки равно сумме обратных сопротивлений глины и коллектора, взятых с весами χсп и (1 − χсп).", "kind": "observation", "page_pdf": 102, "unit_id": "p102.02", "quote": "1 / \\rho_ {\\mathrm{n}} = \\chi_ {\\mathrm{cn}} / \\rho_ {\\mathrm{cn}} + (1 - \\chi_ {\\mathrm{cn}}) / \\rho_ {\\mathrm{nm}}", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c4"}, {"page_print": null, "text": "Уравнение (63) эквивалентно сложению проводимостей прослоев, пропорциональных их толщинам.", "kind": "inference", "page_pdf": 102, "unit_id": "p102.02", "quote": "1 / \\rho_ {\\mathrm{n}} = \\chi_ {\\mathrm{cn}} / \\rho_ {\\mathrm{cn}} + (1 - \\chi_ {\\mathrm{cn}}) / \\rho_ {\\mathrm{nm}}", "source_kind": "formula", "by_model": true, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c5"}, {"page_print": null, "text": "После нахождения χсп вычисляют эффективную толщину пачки.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.03", "quote": "Далее вычисляют эффективную толщину пачки", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c6"}, {"page_print": null, "text": "Формула (64): эффективная толщина пачки равна толщине пачки, умноженной на (1 − χсп).", "kind": "observation", "page_pdf": 102, "unit_id": "p102.04", "quote": "\\mathrm{h} _ {\\mathrm{sp}} \\Sigma = \\mathrm{h} _ {\\mathrm{n}} (1 - \\chi_ {\\mathrm{cn}}) (6 4)", "source_kind": "formula", "by_model": false, "needs_scan": true, "id": "latyshova.thin_layers_resistivity#c7"}, {"page_print": null, "text": "В качестве ρсп обычно берут удельное сопротивление глин, вмещающих пачку.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.05", "quote": "берут обычно удельное сопротивление глин, вмещающих пачку", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c8"}, {"page_print": null, "text": "Величину ρпм рассчитывают по значениям параметров, измеренных по керну.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.05", "quote": "рассчитывают по значениям параметров, измеренных по керну", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c9"}, {"page_print": null, "text": "Вместо расчёта по керну в качестве ρпм принимают удельное сопротивление наиболее чистых продуктивных коллекторов в разрезе.", "kind": "assumption", "page_pdf": 102, "unit_id": "p102.05", "quote": "или принимают в качестве нее удельное сопротивление наиболее чистых продуктивных коллекторов в разрезе", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_resistivity#c10"}], "id": "latyshova.thin_layers_resistivity", "order": 33, "minutes": 2, "essence": "Когда прослои пачки по отдельности не различимы, берут её общее сопротивление ρп. Уравнение (63) связывает ρп с сопротивлениями глины и коллектора и долей глины χсп. Решив его, получают относительную глинистость χсп и по формуле (64) эффективную толщину пачки.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Пачка состоит из чередующихся прослоев глины и продуктивного коллектора. Относительная глинистость пачки χсп — доля её толщины, занятая глиной. Уравнение (63) складывает проводимости, то есть величины, обратные сопротивлению.", "pages": [102]}, {"text": "Проводимость глины берётся с весом χсп, проводимость коллектора — с весом (1 − χсп). Сумма равна проводимости пачки 1/ρп. Известны три сопротивления: ρп, ρсп и ρпм.", "pages": [102]}, {"text": "Поэтому уравнение решают относительно единственной неизвестной χсп.", "pages": [102]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Сначала ρп определяют по диаграммам БЭЗ или комплекса фокусированных методов. Затем задают сопротивление прослоев коллектора ρпм и глины ρсп. После этого из (63) находят χсп.", "pages": [102]}, {"text": "Далее по (64) вычисляют эффективную толщину пачки: толщину пачки умножают на (1 − χсп). Сопротивление глины ρсп берут обычно по глинам, вмещающим пачку. Сопротивление ρпм рассчитывают по параметрам, измеренным на керне, или принимают равным сопротивлению наиболее чистых продуктивных коллекторов разреза.", "pages": [102]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Результат зависит от выбранных ρсп и ρпм: их задают, а не измеряют по самой пачке. В главе указаны два способа получить ρпм: по керну или по чистым коллекторам разреза. В рассмотренных единицах нет оценки погрешности и границ применимости метода.", "pages": [102]}, {"text": "Не расшифровано и обозначение толщины пачки в (64): по смыслу это полная толщина пачки.", "pages": [102]}]}], "deeper": [], "glossary": [{"term": "относительная глинистость пачки χгл", "definition": "Доля толщины тонкослоистой пачки, занятая глинистыми прослоями. В тексте обозначена χсп и находится из уравнения (63) по сопротивлению пачки."}, {"term": "эффективная толщина пачки", "definition": "Толщина коллекторской части пачки: полная толщина пачки, умноженная на (1 − χсп), формула (64)."}], "format": "интерактив", "tasks": [{"id": "latyshova.thin_layers_resistivity.t1", "type": "order", "step_id": "latyshova.thin_layers_resistivity", "claim_ids": ["latyshova.thin_layers_resistivity#c1", "latyshova.thin_layers_resistivity#c2", "latyshova.thin_layers_resistivity#c3", "latyshova.thin_layers_resistivity#c7"], "prompt": "Расставьте в верном порядке шаги определения эффективной толщины тонкослоистой пачки по её среднему сопротивлению.", "options": [{"id": "a", "text": "Вычислить эффективную толщину как толщину пачки, умноженную на (1 − χсп)", "misconception": null}, {"id": "b", "text": "Решить уравнение (63) относительно относительной глинистости χсп", "misconception": null}, {"id": "c", "text": "Определить сопротивление пачки ρп по диаграммам БЭЗ или фокусированных методов", "misconception": null}, {"id": "d", "text": "Задать сопротивления прослоев коллектора ρпм и глины ρсп", "misconception": null}], "answer": ["c", "d", "b", "a"], "tolerance": null, "unit": null, "explanation": "Сначала нужны все три сопротивления, затем из (63) находят χсп, и только после этого по (64) считают эффективную толщину.", "kind": "recall"}, {"id": "latyshova.thin_layers_resistivity.t2", "type": "calc", "step_id": "latyshova.thin_layers_resistivity", "claim_ids": ["latyshova.thin_layers_resistivity#c7"], "prompt": "Из уравнения для сопротивления тонкослоистой пачки найдена относительная глинистость χсп = 0,35. Полная толщина пачки 20 м. Эффективная толщина равна толщине пачки, умноженной на (1 − χсп). Чему она равна?", "options": [], "answer": 13, "tolerance": 0.1, "unit": "м", "explanation": "Эффективная толщина = 20 · (1 − 0,35) = 13 м.", "kind": "transfer"}], "pictures": [{"id": "latyshova.thin_layers_resistivity.i1", "step_id": "latyshova.thin_layers_resistivity", "node_id": "latyshova.thin_layers_resistivity", "file": "pictures/thin_layers_resistivity_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Порядок расчёта: три сопротивления дают χсп, а по нему находят эффективную толщину тонкослоистой пачки.", "alt": "Схема: сопротивление пачки и заданные сопротивления коллектора и глин подставляют в уравнение сложения проводимостей, находят глинистость χсп, затем эффективную толщину.", "source": "построено кодом по утверждениям главы, стр. 102", "claim_ids": ["latyshova.thin_layers_resistivity#c1", "latyshova.thin_layers_resistivity#c2", "latyshova.thin_layers_resistivity#c3", "latyshova.thin_layers_resistivity#c4", "latyshova.thin_layers_resistivity#c6", "latyshova.thin_layers_resistivity#c7"], "prompt": null}]}, {"title": "Глинистость слоистой пачки по амплитуде СП и палетке Долля; учёт плотных прослоев", "short_title": "Тонкослоистый коллектор по СП", "why_here": {"text": "Альтернатива расчёту по сопротивлению; использует αСП и палетку; затем добавляет плотные прослои.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "Пр"}, "threshold": false, "pages": [102], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход: αСП пачки, ρ глин, ρ чистого коллектора и ρ его зоны проникновения. Выход: глинистость χ, а затем суммарная толщина h_spΣ по формуле (64). На палетке по оси абсцисс отложена глинистость, по оси ординат — αСП, кривые различаются шифром.", "by_model": true}, "breaks": {"text": "СП и ГМ не видят плотные прослои с неактивным цементом, поэтому по ним глинистость плотных прослоев не оценить. Описание палетки сделано программой распознавания, и параметр кривых на ней не подписан.", "by_model": true}, "hypotheses": [{"text": "Шифры кривых на палетке вероятно соответствуют отношению ρ_nm/ρ_sn, как на рис. 72, но это нужно проверить по скану.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Формула (65) похожа на параллельное соединение резисторов: проводимости слоёв складываются с весами по долям толщины. Палетка при этом работает как таблица обратного поиска по готовой функции.", "breaks_where": "Аналогия верна для тока вдоль слоёв. Поперёк слоёв сопротивления складывались бы иначе, но глава этого не разбирает.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграмма СП, значения ρ глин, чистого коллектора и его зоны проникновения, палетки Долля, при необходимости данные микрометодов и керна.", "manual_steps": "Определить αСП по диаграмме, выбрать палетку по ρ_nm/ρ_cn, найти χ по кривой нужного шифра, затем рассчитать h_spΣ.", "judgment_points": "Выбор интервалов чистого коллектора и глин, выбор способа учёта плотных прослоев.", "time": "в главе не указано", "typical_errors": "Не учесть плотные прослои, которые невидимы на СП и ГМ. Взять ρ_max вместо ρ_sn, как допущено в задаче 98 из-за трудоёмкости БЭЗ.", "by_model": true}, "decision_on_data": {"features": ["αСП пачки", "ρ_nm/ρ_cn", "ρ_nm/ρ_sn"], "rule": "Выбрать палетку по ρ_nm/ρ_cn, на кривой нужного ρ_nm/ρ_sn найти χ по αСП, затем рассчитать h_spΣ по формуле (64).", "conclusion": "Получаем глинистость слоистой пачки и суммарную толщину прослоев по СП без использования сопротивления пачки.", "counterexample": "Если в пачке есть плотные прослои с неактивным цементом, СП и ГМ их не отражают, и χ по СП относится только к глинистым прослоям."}, "worked_examples": [], "book_tasks": [{"number": "96", "page_pdf": 102, "text": "Привести примеры сложных продуктивных пластов с прослоями неколлекторов всех типов, пользуясь рисунками, приведенными в настоящем руководстве.", "figure": null}, {"number": "97", "page_pdf": 102, "text": "Определить эффективную толщину продуктивного коллектора с учетом прослоев неколлектора; дать характеристику прослоев неколлектора и признаков, по которым они выделяются на примере рис. 68, 73, 76.", "figure": "рис. 68, 73, 76"}, {"number": "98", "page_pdf": 102, "text": "Определить эффективную толщину тонкослоистого газоносного коллектора по диаграммам БЭЗ и СП (рис. 73). Выбрать интервалы для определения удельного сопротивления глин и чистого коллектора, максимальной статической амплитуды СП в данном разрезе. В связи с трудоемкостью обработки данных БЭЗ в слоистом коллекторе считать ρ_max ≡ ρ_sn.", "figure": "рис. 73"}, {"number": "99", "page_pdf": 102, "text": "Рассчитать глинистость χ_cn глинистого слоистого продуктивного коллектора, если ρ_cn = 2 Ом·м, среднее удельное сопротивление пачки 4,4 Ом·м, пористость наиболее чистых прослоев песчаника 26%, удельное сопротивление вод в пластовых условиях 0,03 Ом·м, коэффициент газонасыщения достигает 88%. Определить (текст обрывается в выданной единице).", "figure": null}], "terms_introduced": ["формулы Долля", "среднее сопротивление пачки"], "links": [{"type": "prerequisite", "target": "latyshova.thin_layers_resistivity"}, {"type": "prerequisite", "target": "latyshova.nonreservoir_interlayers"}, {"type": "prerequisite", "target": "latyshova.effective_thickness_basic"}], "needs_scan": [{"page": 102, "what": "Палетка на стр. 102: подпись оси абсцисс («хтл»), смысл шифров кривых и их значения."}, {"page": 102, "what": "Формула (65): повторяющиеся обозначения χ_cn и ρ_ns; проверить индексы."}, {"page": 102, "what": "Задача 99: обрыв текста («Определить»), единицы сопротивления и ρ_cn искажены распознаванием."}], "claims": [{"page_print": null, "text": "Содержание глинистых прослоев χ_cn в слоистой пачке определяют по кривым αСП = f(χ_cn), которые построены по формулам Долля.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.06", "quote": "построенным по формулам Долля для фиксированных значений", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c1"}, {"page_print": null, "text": "Кривые построены для фиксированных значений отношений ρ_nm/ρ_cn и ρ_nm/ρ_sn.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.06", "quote": "построенным по формулам Долля для фиксированных значений", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c2"}, {"page_print": null, "text": "ρ_sn — удельное сопротивление зоны проникновения в прослоях продуктивного коллектора; примеры кривых даны на рис. 72.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.06", "quote": "удельное сопротивление зоны проникновения в прослоях продуктивного коллектора (рис.72).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c3"}, {"page_print": null, "text": "Рис. 72 показывает кривые зависимости αСП = f(χ_cn).", "kind": "observation", "page_pdf": 102, "unit_id": "p102.07", "quote": "Рис.72. Кривые зависимости", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c4"}, {"page_print": null, "text": "Кривые на рис. 72 построены при отношении ρ_n/ρ_cn = 10, а шифром кривых служит отношение ρ_n/ρ_sn.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.07", "quote": "\\( \\rho_{n}/\\rho_{cn} = 10 \\) . Шифр кривых –", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c5"}, {"page_print": null, "text": "Название палетки на изображении не подписано, виден только номер страницы «165».", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "Название палетки не подписано (кроме номера страницы «165»).", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thin_layers_sp#c6"}, {"page_print": null, "text": "Физический смысл параметра семейства (20, 10, 5, 2, 1, 0,5, 0,2) на изображении не указан, легенды нет.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "Физический смысл параметра на изображении не указан (нет легенды).", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thin_layers_sp#c7"}, {"page_print": null, "text": "Все кривые палетки начинаются на оси ординат при x=0 (около 0,8–0,85) и монотонно убывают к нулю при x_гл→1.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "Все кривые исходят из точки на оси ординат при x=0 (значение около 0,8–0,85) и монотонно убывают к оси абсцисс, сходясь к нулю при x_гл→1.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thin_layers_sp#c8"}, {"page_print": null, "text": "Кривые с большими значениями параметра (20, 10) убывают быстрее, чем кривые с малыми (0,5; 0,2).", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "Кривые с большими значениями параметра (20, 10) убывают быстрее", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thin_layers_sp#c9"}, {"page_print": null, "text": "Считывание с палетки: задают x_гл по оси абсцисс и по кривой нужного параметра снимают α_сп на оси ординат.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "Порядок процедуры считывания: по оси абсцисс задаётся значение x_гл", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thin_layers_sp#c10"}, {"page_print": null, "text": "Ориентировочные точки кривой «20»: при x_гл≈0,2 α_сп≈0,35, при x_гл≈0,4 α_сп≈0,15.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "(x_гл≈0,2; α_сп≈0,35), (x_гл≈0,4; α_сп≈0,15)", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thin_layers_sp#c11"}, {"page_print": null, "text": "В качестве αСП берут отношение среднего значения аномалии СП в пачке ΔU_СП к максимальной величине ΔE_max в близлежащем чистом коллекторе.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "берут отношение среднего значения аномалии СП в пачке", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c12"}, {"page_print": null, "text": "Максимальная аномалия ΔE_max берётся в близлежащем чистом коллекторе.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "в близлежащем чистом коллекторе. Как и в предыдущем случае, в качестве", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c13"}, {"page_print": null, "text": "В качестве ρ_cn используют удельное сопротивление вмещающих глин.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "используют удельное сопротивление вмещающих глин, а в качестве", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c14"}, {"page_print": null, "text": "В качестве ρ_nm и ρ_sn берут соответствующие значения параметров чистого коллектора.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "соответствующие значения параметров чистого коллектора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c15"}, {"page_print": null, "text": "Для определения χ_cn выбирают палетку расчётных кривых, шифр которой соответствует заданному ρ_nm/ρ_cn.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "шифр которой соответствует заданному", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c16"}, {"page_print": null, "text": "Палетка — набор расчётных кривых αСП = f(χ_cn); по ней находят χ_cn для заданных ρ_nm/ρ_sn и αСП.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "выбирают палетку расчетных кривых", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c17"}, {"page_print": null, "text": "После нахождения χ_cn суммарную толщину h_spΣ определяют по формуле (64).", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "После вычислений  \\( \\chi_{cn} \\)  определяют  \\( h_{sp\\Sigma} \\)  по формуле (64).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c18"}, {"page_print": null, "text": "Пачка может содержать тонкие прослои неколлектора двух типов: глинистые и плотные с неактивным цементом.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "в. В пачке, где присутствуют тонкие прослои неколлектора двух типов (глинистые и плотные с неактивным цементом), связь между средним удельным сопротивлением пачки", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c19"}, {"page_print": null, "text": "Формула (65) связывает обратное среднее сопротивление пачки с долями и сопротивлениями глинистых, плотных прослоев и коллектора: слагаемые глин и плотных прослоев плюс слагаемое коллектора с долей (1 − χ_cn − χ_ns).", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "1 / \\rho_ {\\mathrm{nav}} ^ {\\mathrm{sp}} = \\chi_ {\\mathrm{cn}} / \\rho_ {\\mathrm{cn}} + \\chi_ {\\mathrm{cn}} / \\rho_ {\\mathrm{ns}}", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c20"}, {"page_print": null, "text": "Слагаемое коллектора в формуле (65) имеет долю (1 − χ_cn − χ_ns) и сопротивление ρ_nm.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "+ (1 - \\chi_ {\\mathrm{cn}} - \\chi_ {\\mathrm{ns}}) / \\rho_ {\\mathrm{nm}}, \\tag {65}", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c21"}, {"page_print": null, "text": "В формуле (65) величина χ в слагаемом плотных прослоев — относительное содержание по толщине плотных прослоев в пачке.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "относительное содержание по толщине плотных прослоев в пачке.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c22"}, {"page_print": null, "text": "Сопротивление плотной породы обычно соизмеримо с ρ_nm, поэтому плотные прослои в отличие от глинистых слабо влияют на ρ_nm.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "присутствие плотных прослоев, в отличие от глинистых, на величину", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c23"}, {"page_print": null, "text": "На показания СП и ГМ плотные прослои с неактивным цементом также не влияют.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "На показания методов СП и ГМ плотные прослои с неактивным цементом также не влияют.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c24"}, {"page_print": null, "text": "Путь учёта плотных прослоев при расчёте h_spΣ: выделить и рассчитать их суммарную толщину микроэлектрическими методами.", "kind": "inference", "page_pdf": 102, "unit_id": "p102.08", "quote": "плотных прослоев микроэлектрическими методами;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c25"}, {"page_print": null, "text": "Путь учёта плотных прослоев: комплексировать методы сопротивления и СП с методами пористости.", "kind": "inference", "page_pdf": 102, "unit_id": "p102.08", "quote": "комплексирование методов сопротивления и потенциалов собственной поляризации с методами пористости;", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c26"}, {"page_print": null, "text": "Путь учёта плотных прослоев: взять их содержание в пачке по данным изучения представительного керна.", "kind": "inference", "page_pdf": 102, "unit_id": "p102.08", "quote": "учет содержания плотных прослоев в пачке по данным изучения представительного керна.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c27"}, {"page_print": null, "text": "Это три возможных пути учёта плотных неглинистых прослоев при расчёте h_spΣ.", "kind": "inference", "page_pdf": 102, "unit_id": "p102.08", "quote": "возможными путями учета плотных неглинистых прослоев при расчете", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c28"}, {"page_print": null, "text": "Задача 96: привести примеры сложных продуктивных пластов с прослоями неколлекторов всех типов по рисункам руководства.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "Привести примеры сложных продуктивных пластов с прослоями неколлекторов всех типов", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c29"}, {"page_print": null, "text": "Задача 97: определить эффективную толщину продуктивного коллектора с учётом прослоев неколлектора (рис. 68, 73, 76).", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "Определить эффективную толщину продуктивного коллектора с учетом прослоев неколлектора", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c30"}, {"page_print": null, "text": "Задача 98: определить эффективную толщину тонкослоистого газоносного коллектора по БЭЗ и СП (рис. 73).", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "Определить эффективную толщину тонкослоистого газоносного коллектора по диаграммам БЭЗ и СП (рис. 73).", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c31"}, {"page_print": null, "text": "В задаче 98 из-за трудоёмкости обработки данных БЭЗ в слоистом коллекторе принимают ρ_max ≡ ρ_sn.", "kind": "assumption", "page_pdf": 102, "unit_id": "p102.08", "quote": "В связи с трудоемкостью обработки данных БЭЗ в слоистом коллекторе считать", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.thin_layers_sp#c32"}, {"page_print": null, "text": "Задача 99: рассчитать глинистость слоистого продуктивного коллектора с заданными ρ_cn, средним сопротивлением пачки, пористостью, сопротивлением вод и газонасыщением.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "глинистого слоистого продуктивного коллектора, если", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.thin_layers_sp#c33"}, {"page_print": null, "text": "Условия задачи 99: пористость наиболее чистых прослоев песчаника 26%, сопротивление вод в пластовых условиях 0,03.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "пористость наиболее чистых прослоев песчаника 26%, удельное сопротивление вод в пластовых условиях 0,03", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.thin_layers_sp#c34"}, {"page_print": null, "text": "Условие задачи 99: коэффициент газонасыщения достигает 88%.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "коэффициент газонасыщения достигает 88%.", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.thin_layers_sp#c35"}, {"page_print": null, "text": "Условие задачи 99: среднее удельное сопротивление пачки 4,4.", "kind": "observation", "page_pdf": 102, "unit_id": "p102.08", "quote": "среднее удельное сопротивление пачки 4,4", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.thin_layers_sp#c36"}], "id": "latyshova.thin_layers_sp", "order": 34, "minutes": 5, "essence": "Глинистость слоистой пачки χ (в тексте χ_cn) можно найти по амплитуде СП, не используя сопротивление пачки. Для этого относительную амплитуду αСП сравнивают с расчётными кривыми, построенными по формулам Долля. Плотные прослои с неактивным цементом сопротивление пачки почти не меняют и на СП не влияют, поэтому их учитывают отдельно.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Палетка — семейство кривых αСП = f(χ). Каждая кривая построена по формулам Долля для фиксированных отношений сопротивлений. Формулы Долля — это расчётные соотношения, по которым построены кривые.", "pages": [102]}, {"text": "Сами формулы в выданных единицах не приведены. Шифр палетки задаёт отношение сопротивления чистого коллектора к сопротивлению вмещающих глин, а шифр кривой — отношение его к сопротивлению зоны проникновения в прослоях. αСП берут как отношение средней аномалии СП в пачке к максимальной аномалии в близлежащем чистом коллекторе. Из палетки по αСП и шифру кривой снимают χ.", "pages": [102]}, {"text": "После этого суммарную толщину считают по формуле (64), которой в этой части главы нет. Если в пачке есть и глинистые, и плотные прослои, среднее сопротивление пачки связывает формула (65). Среднее сопротивление пачки — это эффективное сопротивление всей слоистой пачки.", "pages": [102]}, {"text": "Его обратная величина равна сумме долей толщины прослоёв, делённых на их сопротивления.", "pages": [102]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок такой. Берут ρ вмещающих глин и значения ρ чистого коллектора и его зоны проникновения. Из них составляют отношения и выбирают палетку с нужным шифром.", "pages": [102]}, {"text": "Определяют αСП по диаграмме СП. Находят χ на кривой, соответствующей отношению ρ чистого коллектора к ρ зоны проникновения. Затем считают толщину по формуле (64).", "pages": [102]}, {"text": "Для плотных прослоёв глава называет три пути. Первый — выделить и просуммировать их толщину микроэлектрическими методами. Второй — комплексировать методы сопротивления и СП с методами пористости.", "pages": [102]}, {"text": "Третий — взять их долю по представительному керну.", "pages": [102]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Плотные прослои с неактивным цементом не влияют на СП и ГМ. Сопротивление таких прослоёв обычно близко к сопротивлению коллектора, поэтому на сопротивление пачки они действуют слабо. Поэтому по СП и по сопротивлению их не отделить от коллектора, и нужны отдельные пути учёта.", "pages": [102]}, {"text": "В формуле (65) в тексте главы обозначения повторяются: χ_cn стоит и при глинах, и при плотных прослоях. Видимо, это искажение распознавания; это стоит проверить по скану. Описание палетки дано программой распознавания, у него нет легенды параметра и подпись оси неразборчива.", "pages": [102]}]}], "deeper": [], "glossary": [{"term": "формулы Долля", "definition": "Расчётные соотношения, по которым строят кривые αСП = f(χ) для фиксированных отношений сопротивлений; сами формулы в выданных единицах не приведены."}, {"term": "среднее сопротивление пачки", "definition": "Эффективное удельное сопротивление слоистой пачки. По формуле (65) его обратная величина складывается из долей толщины прослоёв, делённых на их сопротивления."}], "format": "интерактив", "tasks": [{"id": "latyshova.thin_layers_sp.t1", "type": "single", "step_id": "latyshova.thin_layers_sp", "claim_ids": ["latyshova.thin_layers_sp#c23", "latyshova.thin_layers_sp#c24"], "prompt": "Тонкослоистую пачку оценивают по СП и по сопротивлению, но в ней есть плотные прослои с неактивным цементом. Почему этих двух методов недостаточно, чтобы учесть такие прослои?", "options": [{"id": "a", "text": "Их сопротивление близко к сопротивлению коллектора, а на СП они не влияют, поэтому от коллектора они не отличаются", "misconception": null}, {"id": "b", "text": "Их сопротивление намного ниже, чем у глин, и оно искажает показания СП", "misconception": "misc.dense_like_clay"}, {"id": "c", "text": "Их толщина всегда меньше разрешающей способности любого метода", "misconception": "misc.dense_too_thin"}, {"id": "d", "text": "Они дают на СП аномалию, как у глин, и их путают с глинистыми прослоями", "misconception": "misc.dense_like_clay"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Плотные прослои мало меняют сопротивление пачки и не влияют на СП и ГМ, поэтому их отделяют другими путями.", "kind": "understanding"}, {"id": "latyshova.thin_layers_sp.t2", "type": "multiple", "step_id": "latyshova.thin_layers_sp", "claim_ids": ["latyshova.thin_layers_sp#c25", "latyshova.thin_layers_sp#c26", "latyshova.thin_layers_sp#c27", "latyshova.thin_layers_sp#c28"], "prompt": "Какие пути учёта плотных неглинистых прослоев при расчёте суммарной толщины слоистой пачки названы в тексте? Выберите все верные.", "options": [{"id": "a", "text": "Выделить и просуммировать их толщину микроэлектрическими методами", "misconception": null}, {"id": "b", "text": "Комплексировать методы сопротивления и СП с методами пористости", "misconception": null}, {"id": "c", "text": "Взять их долю по данным изучения представительного керна", "misconception": null}, {"id": "d", "text": "Найти их долю по относительной амплитуде αСП на палетке Долля", "misconception": "misc.sp_sees_dense"}], "answer": ["a", "b", "c"], "tolerance": null, "unit": null, "explanation": "Три пути — микроэлектрические методы, комплекс с пористостью и керн; СП плотные прослои не отражает.", "kind": "recall"}], "pictures": [{"id": "latyshova.thin_layers_sp.i1", "step_id": "latyshova.thin_layers_sp", "node_id": "latyshova.thin_layers_sp", "file": "pictures/thin_layers_sp_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Глинистость пачки снимают с палетки кривых Долля по относительной амплитуде СП и выбранным отношениям сопротивлений.", "alt": "Схема: относительная амплитуда СП и шифры палетки и кривой определяют глинистость χсп, по ней находят суммарную толщину пачки.", "source": "построено кодом по утверждениям главы, стр. 102", "claim_ids": ["latyshova.thin_layers_sp#c1", "latyshova.thin_layers_sp#c2", "latyshova.thin_layers_sp#c12", "latyshova.thin_layers_sp#c16", "latyshova.thin_layers_sp#c17", "latyshova.thin_layers_sp#c18"], "prompt": null}]}, {"title": "Практика: расчёт эффективной толщины слоистых пластов с глинами и плотными прослоями", "short_title": "Практика: толщина слоистого пласта", "why_here": {"text": "Закрепляет формулы слоистых пачек на диаграммах и числовых задачах, включая оценку ошибки при использовании среднего сопротивления без учёта прослоев (задача 101).", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Ф"}, "threshold": false, "pages": [103, 104], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход: общая толщина пачки (28 м или 18 м), сопротивления плотных пород, глин и коллектора, среднее сопротивление пачки 7,3 Ом·м, доля плотных прослоёв не более 20% по керну. Выход: эффективная толщина и ошибка её определения. Для рис. 73 в единицах есть только подпись и линия глин.", "by_model": true}, "breaks": {"text": "Если считать пачку по среднему сопротивлению и не учитывать плотные прослои, эффективная толщина получается с ошибкой. Задача 101 просит её оценить, число в этой части главы не дано. Описание рис. 73 без легенды не позволяет прочитать числа справа от фрагментов.", "by_model": true}, "hypotheses": []}, "it_analogy": {"text": "Среднее сопротивление пачки похоже на среднюю загрузку кластера. Одно число скрывает, что часть шагов простаивает, а часть перегружена, и по нему нельзя сказать, сколько шагов реально полезны.", "breaks_where": "Среднее сопротивление слоистой пачки зависит от схемы протекания тока через слои, а не простое арифметическое среднее. Полезные слои определяются по порогам коллектора.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы сопротивления по пачке, сопротивления компонентов, среднее сопротивление пачки, керновые данные о доле плотных прослоёв.", "manual_steps": "Задача требует вручную отделить толщины глин, плотных прослоёв и коллектора и посчитать эффективную толщину. Затем нужно сравнить результат с расчётом по среднему сопротивлению.", "judgment_points": "Решение зависит от выбора модели пачки и от того, учитывать ли плотные прослои.", "time": "в главе не указано", "typical_errors": "Ошибка: считать пачку по среднему сопротивлению и не учитывать плотные прослои (задача 101).", "by_model": true}, "decision_on_data": null, "worked_examples": [], "book_tasks": [{"number": "без номера (фрагмент)", "page_pdf": 103, "text": "…эффективную толщину пласта, если общая толщина пачки 28 м. Начало условия на этой странице отсутствует.", "figure": null}, {"number": "100", "page_pdf": 104, "text": "Определить эффективную толщину 18-метровой толщи продуктивного коллектора, содержащего прослои глин и плотных пород с неактивным цементом, если удельные сопротивления плотных разностей 38 Ом·м, глин 2,2 Ом·м, продуктивных коллекторов 25 Ом·м.", "figure": null}, {"number": "101", "page_pdf": 104, "text": "Реконструкция по искажённому тексту: на основании результатов решения предыдущей задачи вычислить, какая ошибка в определении эффективной толщины пачки будет допущена, если при расчёте по величине среднего сопротивления и при использовании модели слоистого глинистого коллектора не учитывать плотные прослои. Данные в единице p104.06: среднее сопротивление пачки 7,3 Ом·м, плотные прослои не более 20% по керну.", "figure": null}, {"number": "102", "page_pdf": 104, "text": "Реконструкция по искажённому тексту: в терригенном разрезе по материалам ГИС (рис. 74) выделить коллекторы, используя комплекс ВК-МВК и диаграмму коэффициента эффективной проницаемости из гидродинамических исследований. Определить граничное значение ΔT_гр по акустическому методу и соответствующее граничное значение kп, используя константы уравнения среднего времени 170 мкс/м и 580 мкс/м.", "figure": "рис. 74"}], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.effective_thickness_basic"}, {"type": "prerequisite", "target": "latyshova.nonreservoir_interlayers"}, {"type": "prerequisite", "target": "latyshova.thin_layers_resistivity"}, {"type": "prerequisite", "target": "latyshova.thin_layers_sp"}], "needs_scan": [{"page": 104, "what": "Текст задач 101 и 102 распознан с искажениями: нужен скан для точных формулировок и обозначений констант (170 и 580 мкс/м)."}, {"page": 104, "what": "Рис. 73: описание получено моделью, числа справа от фрагментов, шкалы и литология не подтверждены."}, {"page": 104, "what": "Единицы p104.04 и p104.05 в шаг не вошли. Нужно проверить, к какой задаче относятся данные 7,3 Ом·м и не более 20%."}, {"page": 103, "what": "Начало условия, оканчивающегося словами «общая толщина пачки 28 м», и номер задачи."}], "claims": [{"page_print": null, "text": "Одна из задач просит найти эффективную толщину пласта при общей толщине пачки 28 м. Это конец условия, начало и номер на этой странице не даны.", "kind": "assumption", "page_pdf": 103, "unit_id": "p103.01", "quote": "эффективную толщину пласта, если общая толщина пачки 28м.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.thickness_practice#c1"}, {"page_print": null, "text": "Рис. 73 показывает диаграммы комплекса геофизических методов по участку разреза хадумского газоносного горизонта.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.01", "quote": "Диаграммы комплекса геофизических методов по участку разреза хадумского газоносного горизонта", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.thickness_practice#c2"}, {"page_print": null, "text": "На рис. 73 линия глин обозначена 00'.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.01", "quote": "00' – линия глин.", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.thickness_practice#c3"}, {"page_print": null, "text": "По описанию программы распознавания, рисунок — планшет каротажной диаграммы из четырёх сближенных фрагментов разреза одной скважины.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.02", "quote": "Общий вид: планшет каротажной диаграммы, разбитый на 4 сближенных фрагмента разреза (внутри одной скважины)", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thickness_practice#c4"}, {"page_print": null, "text": "По описанию программы распознавания, справа от фрагментов стоят числа без подписи. Их физический смысл без легенды определить нельзя.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.02", "quote": "Физический смысл этих чисел (Кп, Кнг, УЭС или иной параметр) не подписан явно и не может быть однозначно определён без легенды.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thickness_practice#c5"}, {"page_print": null, "text": "По описанию программы распознавания, на изображении не подписаны и не показаны отбивки пластов, границы, ВНК/ГНК и интервалы перфорации.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.02", "quote": "Отбивки пластов, границы, ВНК/ГНК, интервалы перфорации на изображении не подписаны и не показаны.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.thickness_practice#c6"}, {"page_print": null, "text": "Задача 100: найти эффективную толщину 18-метровой толщи продуктивного коллектора с прослоями глин и плотных пород с неактивным цементом.", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.03", "quote": "Определить эффективную толщину 18-метровой толщи продуктивного коллектора, содержащего прослои глин и плотных пород с неактивным цементом", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.thickness_practice#c7"}, {"page_print": null, "text": "В задаче 100 удельные сопротивления: плотные разности 38 Ом·м, глины 2,2 Ом·м, продуктивные коллекторы 25 Ом·м.", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.03", "quote": "удельные сопротивления плотных разностей 38 Ом·м, глин 2,2 Ом·м, продуктивных коллекторов 25 Ом·м.", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.thickness_practice#c8"}, {"page_print": null, "text": "Среднее удельное сопротивление пачки равно 7,3 Ом·м. Единица стоит между задачами 100 и 101, и по этой странице не ясно, к какой из них она относится.", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.06", "quote": "Среднее удельное сопротивление пачки 7,3 Ом·м.", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.thickness_practice#c9"}, {"page_print": null, "text": "По данным керновых определений плотные прослои составляют не более 20% от общей толщины пачки.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.06", "quote": "По данным керновых определений плотные прослои составляют не более 20% от общей толщины.", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.thickness_practice#c10"}, {"page_print": null, "text": "Задача 101 (реконструкция по искажённому тексту): по результатам предыдущей задачи вычислить ошибку в определении эффективной толщины пачки. Ошибка возникает при расчёте по среднему сопротивлению и модели слоистого глинистого коллектора без учёта плотных прослоёв.", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.07", "quote": "BbUHcJIHTb, KaKa OIIb6a B OIIpeJIeHHN 3ΦΦeKTHBHO TOnIIHHb NaKH 6yIeT dOnyIeHa", "source_kind": "task", "by_model": true, "needs_scan": true, "id": "latyshova.thickness_practice#c11"}, {"page_print": null, "text": "В задаче 101 упомянуты величина среднего сопротивления, модель слоистого глинистого коллектора и плотные прослои, которые она не учитывает (реконструкция).", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.07", "quote": "cpeIHeRo COIIpOTHBJIeHHN II pH IcIOJIb3OBaHHN MoJIeN CIOHCTOrO rJIHHCTOrO KOJIeKTopa", "source_kind": "task", "by_model": true, "needs_scan": true, "id": "latyshova.thickness_practice#c12"}, {"page_print": null, "text": "Задача 102 (реконструкция): в терригенном разрезе по материалам ГИС с рис. 74 выделить коллекторы по комплексу ВК-МВК и диаграмме коэффициента эффективной проницаемости из гидродинамических исследований.", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.07", "quote": "B TeppHReHHOM pa3pe3e IIO MaTePhaJIaM ΓHC, IIpHBeIeHHbIM Ha pHc. 74, BbIeJIHTb KOJIeKTopbI", "source_kind": "task", "by_model": true, "needs_scan": true, "id": "latyshova.thickness_practice#c13"}, {"page_print": null, "text": "В задаче 102 по акустическому методу нужно найти граничное значение ΔT_гр для выделения коллекторов и соответствующее граничное значение kп (реконструкция).", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.07", "quote": "OIIpeJIeHTb rpaHHUHO 3NaueHHe \\(\\Delta T_{\\mathrm{rp}}\\) IJIa BbIeJIeHHN KOJIeKTOPOB", "source_kind": "task", "by_model": true, "needs_scan": true, "id": "latyshova.thickness_practice#c14"}, {"page_print": null, "text": "Константы уравнения среднего времени в задаче 102: 170 мкс/м и 580 мкс/м (обозначения констант в тексте искажены).", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.07", "quote": "\\Delta T_{\\mathrm{ex}} = 170\\mathrm{MKC / M}; \\Delta T_{\\phi \\mathrm{II}} = 580\\) MKC/M.", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.thickness_practice#c15"}], "id": "latyshova.thickness_practice", "order": 35, "minutes": 3, "essence": "Шаг состоит из условий задач 100–102 и рисунка 73. Разобранных решений в нём нет. Задача 100 задаёт общую толщину 18 м и три сопротивления: плотных пород, глин и продуктивного коллектора. Задача 101 просит оценить ошибку в эффективной толщине, если пачку считать по среднему сопротивлению и не учитывать плотные прослои.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Формулы в этой части главы не приведены, поэтому механизм расчёта здесь не раскрывается. Он опирается на формулы Долля и вычитание прослоёв из соседних шагов. Идея задач: слоистая пачка состоит из продуктивного коллектора, глин и плотных прослоёв с неактивным цементом.", "pages": [104]}, {"text": "Они сильно различаются по сопротивлению. Среднее сопротивление пачки смешивает их вклады.", "pages": [104]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Для задачи 100 известны общая толщина 18 м и сопротивления трёх компонентов: плотные 38 Ом·м, глины 2,2 Ом·м, коллектор 25 Ом·м. Для задачи 101 даны среднее сопротивление пачки 7,3 Ом·м и доля плотных прослоёв по керну: не более 20% общей толщины. Связь этих данных с конкретной задачей в тексте не прослеживается: единицы между задачами 100 и 101 отсутствуют.", "pages": [104]}, {"text": "В задаче 102 по данным ВК-МВК и диаграмме коэффициента эффективной проницаемости выделяют коллекторы и находят граничные значения по акустике.", "pages": [104]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Текст задачи 101 в единице распознан с искажениями. Его смысл восстановлен по контексту и требует проверки по скану. Диаграмма на рис.", "pages": [104]}, {"text": "73 описана программой распознавания: числа справа от фрагментов не подписаны, литологии без легенды не видно. Читать из этого описания значения нельзя.", "pages": [104]}]}], "deeper": [], "glossary": [], "format": "карточки", "tasks": [{"id": "latyshova.thickness_practice.t1", "type": "calc", "step_id": "latyshova.thickness_practice", "claim_ids": ["latyshova.thickness_practice#c7", "latyshova.thickness_practice#c10"], "prompt": "Общая толщина слоистой пачки 18 м. По данным керна плотные прослои составляют не более 20 % общей толщины. Какова максимальная суммарная толщина плотных прослоев?", "options": [], "answer": 3.6, "tolerance": 0.05, "unit": "м", "explanation": "20 % от 18 м даёт 18 · 0,2 = 3,6 м.", "kind": "data"}], "pictures": [{"id": "latyshova.thickness_practice.i1", "step_id": "latyshova.thickness_practice", "node_id": "latyshova.thickness_practice", "file": "pictures/thickness_practice_1.svg", "frame_class": "A", "origin": "code_from_data", "label": "схема", "caption": "Удельные сопротивления компонентов 18-метровой пачки в задаче 100: глины на порядок слабее проводят отличие от плотных пород и коллекторов.", "alt": "Столбчатая диаграмма сопротивлений: плотные породы 38, продуктивные коллекторы 25, глины 2,2 Ом·м, шкала логарифмическая.", "source": "построено кодом по утверждениям главы, стр. 104", "claim_ids": ["latyshova.thickness_practice#c7", "latyshova.thickness_practice#c8"], "prompt": null}]}, {"title": "Выделение коллекторов по ГГМ и АК с граничной пористостью", "short_title": "Коллекторы по ГГМ и АК", "why_here": {"text": "Применяет метод пористости и граничное значение; готовит карбонатный раздел. Задача 102 просит выделить коллекторы по комплексу и найти граничное ΔT для заданных констант.", "by_model": true}, "difficulty": {"primary": "И", "secondary": "Пр"}, "threshold": false, "pages": [104, 105], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход задачи 103: диаграмма плотности δп (ГГМ, шкала 2,4–2,0 г/см³), диаграмма ΔТ (АК, шкала 200–280 мкс/м), константы скелета и флюида и kп,гр = 9 %. Выход: интервалы коллекторов. Для рис. 74: кривые БМК, БК-3, ГМ, НГМ, ΔТ и гистограмма проницаемости.", "by_model": true}, "breaks": {"text": "Описания рисунков машинные, отметок пластов и результатов нет, поэтому по ним нельзя выделить интервалы. Формула пересчёта в этой части главы не дана. Текст задачи 101 искажён.", "by_model": true}, "hypotheses": [{"text": "Пересчёт δп и ΔТ в пористость по линейным уравнениям даёт значения, которые сравнивают с kп,гр.", "by_model": true, "hypothesis": true}, {"text": "В газоносных коллекторах газ может смещать показания ГГМ и АК относительно водо- и нефтенасыщенных, поэтому константа флюида на рис. 75 важна.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Граничная пористость похожа на порог классификации. Кривую пересчитывают в оценку, затем сравнивают с порогом и получают метку «коллектор» или «неколлектор».", "breaks_where": "Порог для скважины выбирают из физики и проницаемости, а не по метрике качества. На самой кривой пласты не размечены.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [{"number": "101", "page_pdf": 104, "text": "Опираясь на результаты предыдущей задачи, вычислить ошибку в определении эффективной толщины пачки, если при расчёте не учитывать плотные прослои по величине среднего сопротивления и при использовании модели слоистого глинистого коллектора. Формулировка восстановлена из искажённого текста, нужна сверка по скану.", "figure": null}, {"number": "102", "page_pdf": 104, "text": "В терригенном разрезе по материалам ГИС рис. 74 выделить коллекторы, используя основные методы комплекс БК–МБК и диаграмму коэффициента эффективной проницаемости из гидродинамических исследований. Определить граничное значение ΔТгр для выделения коллекторов по АК и соответствующее граничное значение kп, используя в уравнении среднего времени ΔТск = 170 мкс/м и ΔТфл = 580 мкс/м.", "figure": "рис. 74, стр. 104"}, {"number": "103", "page_pdf": 105, "text": "При граничном значении kп,гр = 9 % выделить в терригенном разрезе (рис. 75) коллекторы по диаграммам ГГМ и АК. Константы: для ГГМ δск = 2,65 г/см³, δфл = 0,9; для АК ΔТск = 170 мкс/м, ΔТф = 600 мкс/м.", "figure": "рис. 75, стр. 105"}], "terms_introduced": ["гамма-гамма-метод (ГГМ)", "акустический метод (АК)", "граничное значение пористости kп,гр"], "links": [{"type": "prerequisite", "target": "latyshova.permeability_threshold_on_logs"}, {"type": "prerequisite", "target": "latyshova.critical_permeability"}, {"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.nmr_and_method_choice"}, {"type": "prerequisite", "target": "latyshova.thickness_practice"}, {"type": "prerequisite", "target": "latyshova.thin_layers_resistivity"}], "needs_scan": [{"page": 104, "what": "Рис. 74: кривые БМК, БК-3, ГМ, НГМ, ΔТ и гистограмма проницаемости; описание программы распознавания числовых значений не даёт"}, {"page": 104, "what": "Текст задач 101 и 102 искажён при распознавании, нужна сверка формулировок"}, {"page": 105, "what": "Рис. 75: кривые δп и ΔТ, литологическая колонка без легенды; нужны значения по глубинам"}], "claims": [{"page_print": null, "text": "Рис. 74 показывает материалы ГИС и ГДК для выделения продуктивных коллекторов в терригенном разрезе.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.05", "quote": "Материалы ГИС и ГДК для выделения в терригенном разрезе продуктивных коллекторов", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c1"}, {"page_print": null, "text": "Для рис. 74 заданы плотность раствора δр = 1,16–1,18 г/см³, сопротивление раствора ρр = 0,049 Ом·м и диаметр скважины dс = 0,19 м.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.05", "quote": "δp = 1,16 – 1,18 г/см³; ρp = 0,049 Ом·м; dc = 0,19м.", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c2"}, {"page_print": null, "text": "Среднее удельное сопротивление пачки равно 7,3 Ом·м.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.06", "quote": "Среднее удельное сопротивление пачки 7,3 Ом·м.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c3"}, {"page_print": null, "text": "По керновым определениям плотные прослои составляют не более 20 % от общей толщины.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.06", "quote": "По данным керновых определений плотные прослои составляют не более 20% от общей толщины.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c4"}, {"page_print": null, "text": "Задача 101 опирается на результаты предыдущей задачи и касается ошибки в определении эффективной толщины пачки. По искажённому тексту это ошибка при неучёте плотных прослоев по среднему сопротивлению и модели слоистого глинистого коллектора. Формулировка восстановлена приблизительно.", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.07", "quote": "101. OchoBbAcb Ha pe3yIbTaTax peHHeHH npeIbIyIeH 3aJaH", "source_kind": "task", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c5"}, {"page_print": null, "text": "Задача 102: в терригенном разрезе по материалам ГИС рис. 74 выделить коллекторы.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.07", "quote": "102. B TeppHReHHOM pa3pe3e IIO MaTePhaJIaM ΓHC, IIpHBeIeHHbIM Ha pHc. 74", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c6"}, {"page_print": null, "text": "В задаче 102 основными методами названы комплекс БК–МБК и диаграмма коэффициента эффективной проницаемости из гидродинамических исследований. Текст восстановлен из искажённого.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.07", "quote": "BbIeJIHTb KOJIeKTopbI, HcIIIOJIyB KaueCTBe OCHOBHbIX MeTOIOB KOMIIIEKC BK-MBK", "source_kind": "task", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c7"}, {"page_print": null, "text": "В задаче 102 нужно определить граничное ΔТ для выделения коллекторов по акустическому методу и соответствующее граничное kп.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.07", "quote": "OIIpeJIeHTb rpaHHUHO 3NaueHHe \\(\\Delta T_{\\mathrm{rp}}\\) IJIa BbIeJIeHHN KOJIeKTOPOB IIO DaHHbIM akyCTHueCKoro MeToDA", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c8"}, {"page_print": null, "text": "В задаче 102 константы уравнения среднего времени: ΔТск = 170 мкс/м и ΔТфл = 580 мкс/м.", "kind": "assumption", "page_pdf": 104, "unit_id": "p104.07", "quote": "\\(\\Delta T_{\\mathrm{ex}} = 170\\mathrm{MKC / M}; \\Delta T_{\\phi \\mathrm{II}} = 580\\) MKC/M.", "source_kind": "task", "by_model": false, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c9"}, {"page_print": null, "text": "Задача 103: при граничной пористости kп,гр = 9 % выделить коллекторы в терригенном разрезе рис. 75 по диаграммам ГГМ и АК.", "kind": "assumption", "page_pdf": 105, "unit_id": "p105.01", "quote": "При граничном значении  \\( k_{n,гр} = 9 \\% \\) , выделить в терригенном разрезе (рис. 75) коллекторы по диаграммам ГГМ и АК", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c10"}, {"page_print": null, "text": "Для ГГМ в задаче 103 принято δск = 2,65 г/см³ и δфл = 0,9.", "kind": "assumption", "page_pdf": 105, "unit_id": "p105.01", "quote": "\\( \\delta_{ск} = 2,65 \\, г/см^{3} \\)", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c11"}, {"page_print": null, "text": "Для АК в задаче 103 принято ΔТф = 600 мкс/м; ΔТск = 170 мкс/м.", "kind": "assumption", "page_pdf": 105, "unit_id": "p105.01", "quote": "\\( \\Delta T_{ф} = 600 \\, мкс/м \\)", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c12"}, {"page_print": null, "text": "На рис. 74 показаны кривые БМК и БК-3 в логарифмической шкале сопротивления 10–100–1000 Ом·м.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.04", "quote": "Кривая БМК (сплошная линия) — шкала ρк, Ом·м: 10 – 100 – 1000 (логарифмическая шкала)", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c13"}, {"page_print": null, "text": "На рис. 74 кривая ΔТ акустического метода имеет шкалу 160–220 мкс/м.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.04", "quote": "Кривая ΔТ, мкс/м — шкала: 160, 180, 200, 220 мкс/м (подписаны деления 160 180 | 200 220)", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c14"}, {"page_print": null, "text": "На рис. 74 есть гистограмма гидродинамических исследований: проницаемость в логарифмической шкале от 1 до 1000.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.04", "quote": "Гистограмма (столбчатая диаграмма), шкала Кпр·10⁻³ мкм²: 1, 10, 100, 1000 (логарифмическая шкала)", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c15"}, {"page_print": null, "text": "На рис. 74 кривая ГМ колеблется волнообразно по всему интервалу.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.04", "quote": "Кривая ГМ показывает волнообразные колебания по всему интервалу.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c16"}, {"page_print": null, "text": "Результаты интерпретации (Кп, Кн, Кпр, эффективная толщина) на рис. 74 не приведены.", "kind": "observation", "page_pdf": 104, "unit_id": "p104.04", "quote": "Результаты интерпретации (Кп, Кн, Кпр, эфф. толщина) на изображении не приведены.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c17"}, {"page_print": null, "text": "На рис. 75 кривая АМ (ΔТ) имеет шкалу 200–240–280 мкс/м.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.02", "quote": "Кривая ΔТ, мкс/м: шкала 200–240–280", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c18"}, {"page_print": null, "text": "На рис. 75 кривая плотности δп ГГМ имеет шкалу 2,4–2,0 г/см³, значения убывают слева направо.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.02", "quote": "Кривая δп, г/см³: шкала 2,4–2,3–2,2–2,1–2,0", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c19"}, {"page_print": null, "text": "На рис. 75 литологическая колонка не снабжена легендой, поэтому литология неизвестна.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.02", "quote": "Литологическая колонка справа не подписана легендой внутри изображения", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c20"}, {"page_print": null, "text": "На рис. 75 результаты интерпретации (Кп, Кн, Кпр, толщина) не приведены.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.02", "quote": "Результаты интерпретации (Кп, Кн, Кпр, эффективная толщина) на изображении не приведены.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.ggm_ak_collectors#c21"}, {"page_print": null, "text": "Рис. 75 показывает диаграммы ГИС для выделения газоносных коллекторов в терригенном разрезе.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.03", "quote": "Диаграммы ГИС для выделения в терригенном разрезе газоносных коллекторов", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c22"}, {"page_print": null, "text": "В подписи рис. 75 указано ΔТп = 600 мкс/м.", "kind": "assumption", "page_pdf": 105, "unit_id": "p105.03", "quote": "\\( \\Delta T_{n} = 600 \\)", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c23"}, {"page_print": null, "text": "В подписи рис. 75 указано δп = 1,1 г/см³.", "kind": "assumption", "page_pdf": 105, "unit_id": "p105.03", "quote": "\\( \\delta_{n} = 1,1 \\)", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.ggm_ak_collectors#c24"}], "id": "latyshova.ggm_ak_collectors", "order": 36, "minutes": 4, "essence": "В этом фрагменте главы нет теории, только рис. 74 и 75 и задачи 101–103. Задача 103 требует выделить коллекторы в терригенном разрезе по ГГМ и АК, если граничная пористость kп,гр равна 9 %. Задача 102 просит найти граничное ΔT для акустики и соответствующее граничное kп по заданным константам.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Гамма-гамма-метод (ГГМ) даёт кривую плотности породы δп в г/см³. Акустический метод (АК) даёт интервальное время пробега волны ΔТ в мкс/м. Для перевода показаний в пористость задачи дают константы скелета и флюида: δск и δфл для ГГМ, ΔТск и ΔТф для АК.", "pages": [104, 105]}, {"text": "В задаче 102 названо «уравнение среднего времени», но сама формула в этой части главы не приведена. Граничное значение пористости kп,гр делит породы на коллектор и неколлектор. Пласт с kп выше kп,гр относят к коллектору.", "pages": [104, 105]}, {"text": "Это общее объяснение модели, в тексте единиц его нет. Граничное ΔТ для АК получают подстановкой kп,гр в то же уравнение.", "pages": [104, 105]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Для задачи 103 берут диаграммы δп и ΔТ рис. 75 и константы из условия. По константам пересчитывают показания в пористость и сравнивают её с 9 %.", "pages": [105]}, {"text": "Интервалы, где пористость не ниже граничной, выделяют как коллекторы. Для задачи 102 по рис. 74 коллекторы выделяют по комплексу БК–МБК и по диаграмме эффективной проницаемости из гидродинамических исследований.", "pages": [104]}, {"text": "Затем по константам ΔТск и ΔТф находят граничное ΔТ и соответствующее граничное kп. Рис. 74 относится к продуктивным коллекторам, рис.", "pages": [104]}, {"text": "75 к газоносным. Для задачи 101 сведений мало: среднее удельное сопротивление пачки 7,3 Ом·м, плотные прослои не более 20 % толщины.", "pages": [104]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Текст задачи 101 в этой части главы искажён при распознавании, поэтому её формулировка восстановлена приблизительно и требует сверки со сканом. Описания рисунков машинные: числовых отметок пластов и результатов интерпретации в них нет. Литологическая колонка на рис.", "pages": [104]}, {"text": "75 без легенды. В подписи рис. 75 константы названы ΔТп = 600 и δп = 1,1, а в условии 103 ΔТф = 600 и δфл = 0,9.", "pages": [104, 105]}, {"text": "Для газоносных коллекторов это стоит помнить: газ может искажать показания ГГМ и АК, в единицах этого нет. Шкала δп на рис. 75 идёт от 2,4 к 2,0 г/см³, то есть плотность убывает вправо.", "pages": [105]}]}], "deeper": [{"text": "Единицы не содержат решений задач и значений граничных ΔТ и δп. Эти числа в слой не вносятся. Рис. 74 даёт параметры раствора: δр = 1,16–1,18 г/см³, ρр = 0,049 Ом·м, dс = 0,19 м. Они нужны для поправок и интерпретации БК–МБК, но как именно, в этой части главы не сказано.", "pages": [104, 105]}], "glossary": [{"term": "гамма-гамма-метод (ГГМ)", "definition": "Метод каротажа с источником гамма-излучения. Рассеянное излучение регистрируют, и по нему оценивают плотность породы δп в г/см³."}, {"term": "акустический метод (АК)", "definition": "Метод каротажа, измеряющий интервальное время ΔТ пробега упругой волны по породе, в мкс/м. По нему оценивают пористость."}, {"term": "граничное значение пористости kп,гр", "definition": "Пористость, по которой породу делят на коллектор и неколлектор. Пласт с kп выше граничной относят к коллекторам. В задаче 103 kп,гр = 9 %."}], "format": "карточки", "tasks": [{"id": "latyshova.ggm_ak_collectors.t1", "type": "gap", "step_id": "latyshova.ggm_ak_collectors", "claim_ids": ["latyshova.ggm_ak_collectors#c10", "latyshova.ggm_ak_collectors#c11", "latyshova.ggm_ak_collectors#c12"], "prompt": "Гамма-гамма-метод даёт кривую {{1}} породы в г/см³, а акустический метод — интервальное {{2}} пробега волны ΔТ в мкс/м.", "options": [], "answer": ["плотности", "время"], "tolerance": null, "unit": null, "explanation": "ГГМ измеряет плотность породы δп, а АК — интервальное время ΔТ.", "kind": "recall"}, {"id": "latyshova.ggm_ak_collectors.t2", "type": "single", "step_id": "latyshova.ggm_ak_collectors", "claim_ids": ["latyshova.ggm_ak_collectors#c19", "latyshova.ggm_ak_collectors#c11", "latyshova.ggm_ak_collectors#c10"], "prompt": "На диаграмме ГГМ шкала плотности δп идёт от 2,4 к 2,0 г/см³ слева направо. Скелет породы имеет плотность 2,65 г/см³, флюид — 0,9 г/см³. Как понимать смещение кривой вправо в терригенном разрезе?", "options": [{"id": "a", "text": "Плотность породы падает, то есть пористость растёт, и пласт ближе к коллектору", "misconception": null}, {"id": "b", "text": "Плотность породы растёт, то есть пористость падает", "misconception": "misc.density_scale_direction"}, {"id": "c", "text": "Растёт плотность скелета, а пористость не меняется", "misconception": "misc.density_skeleton"}, {"id": "d", "text": "Кривая вправо всегда означает рост глинистости, а не пористости", "misconception": "misc.density_clay"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Плотность δп лежит между плотностью флюида и скелета, и чем она меньше, тем больше пористость.", "kind": "understanding"}], "pictures": [{"id": "latyshova.ggm_ak_collectors.i1", "step_id": "latyshova.ggm_ak_collectors", "node_id": "latyshova.ggm_ak_collectors", "file": "pictures/ggm_ak_collectors_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "схема", "caption": "Параметры задачи 103: у каждого метода свои кривая, константы скелета и флюида; граничная пористость для обоих одна, kп,гр = 9 %.", "alt": "Таблица сравнения ГГМ и АК: измеряемая кривая, константы скелета и флюида, шкала кривой. Граничная пористость 9 процентов задана для обоих методов.", "source": "построено кодом по утверждениям главы, стр. 105", "claim_ids": ["latyshova.ggm_ak_collectors#c10", "latyshova.ggm_ak_collectors#c11", "latyshova.ggm_ak_collectors#c12", "latyshova.ggm_ak_collectors#c18", "latyshova.ggm_ak_collectors#c19"], "prompt": null}]}, {"title": "Особенности карбонатных коллекторов, затрудняющие оценку насыщения", "short_title": "Особенности карбонатных коллекторов", "why_here": {"text": "Те же принципы, что в терригенном разрезе, но другое строение пор и слабая связь с глинистостью.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "М"}, "threshold": false, "pages": [105, 107], "misconception": {"ref": "misc.high_res_oil", "text": "В карбонатах значения ρп продуктивного коллектора и неколлектора соизмеримы. Поэтому высокое сопротивление само по себе не доказывает, что пласт продуктивен.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Входные данные — диаграммы ГИС по межзерновому карбонатному разрезу: ρп, пористость kп, СП и ГМ. В главе сказано, что ρп продуктивного коллектора и неколлектора соизмеримы, а kп и нижний предел пористости коллектора меняются в широком диапазоне. СП и ГМ дают мало, потому что глинистость не связана с коллекторскими свойствами. Выходные данные: выделение коллектора и характер его насыщения.", "by_model": false}, "breaks": {"text": "Правила терригенного разреза ломаются в карбонатах по четырём причинам. Единой границы пористости для коллектора нет. Значения ρп коллектора и неколлектора близки. Глинистость не отражает коллекторские свойства. СП и ГМ теряют эффективность.", "by_model": false}, "hypotheses": [{"text": "Вероятно, для надёжного вывода в карбонатах нужно сопоставлять несколько методов, а не один параметр. В этой части главы это не сказано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на мониторинг, где косвенная метрика (например, загрузка процессора) раньше хорошо предсказывала задержку, а в новой архитектуре перестала. Привычный индикатор остаётся в панели, но больше не помогает отличить здоровый сервис от больного. Глинистость в терригенном разрезе была таким индикатором, в карбонатах она им не является.", "breaks_where": "У метрики можно заменить способ сбора. Свойства породы поменять нельзя: меняется только набор методов и способ интерпретации. Кроме того, в карбонатах сложность создаёт разброс самих параметров, а не только пропавшая корреляция.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["низкопористые разности", "нижний предел пористости коллектора"], "links": [{"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.water_loss_and_mud_density"}, {"type": "prerequisite", "target": "latyshova.table21_carbonates_salts"}, {"type": "prerequisite", "target": "latyshova.saturation_from_resistivity"}, {"type": "refutes_misconception", "target": "misc.high_res_oil"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Основные принципы выделения коллекторов и оценки характера насыщения в межзерновых карбонатных коллекторах те же, что и в терригенном разрезе.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.05", "quote": "Основные принципы выделения и оценки характера насыщения межзерновых карбонатных коллекторов те же, что и для терригенного разреза.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c1"}, {"page_print": null, "text": "У карбонатных коллекторов есть особенности, которые существенно влияют на геофизические способы их изучения.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.05", "quote": "Особенностями карбонатных коллекторов, существенно влияющими на геофизические способы их изучения, являются", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c2"}, {"page_print": null, "text": "В карбонатных коллекторах преобладают низкопористые разности.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.05", "quote": "преобладание низкопористых разностей, широкий диапазон изменения пористости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c3"}, {"page_print": null, "text": "В одном и том же горизонте карбонатов пористость и структура порового пространства меняются в широком диапазоне.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.05", "quote": "широкий диапазон изменения пористости и структуры порового пространства в одном и том же горизонте", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c4"}, {"page_print": null, "text": "Нижний предел пористости коллектора в карбонатах меняется в широком диапазоне.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.05", "quote": "широкий диапазон изменения нижнего предела пористости коллектора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c5"}, {"page_print": null, "text": "Коллекторские свойства карбонатов слабо связаны с содержанием глинистого материала (нерастворимого остатка), при этом глинистость мала.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.05", "quote": "слабая связь коллекторских свойств с содержанием глинистого материала (нерастворимого остатка) при малой глинистости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c6"}, {"page_print": null, "text": "Преобладание низкопористых разностей приводит к более глубокому проникновению фильтрата промывочной жидкости в карбонатные межзерновые коллекторы по сравнению с терригенными.", "kind": "inference", "page_pdf": 105, "unit_id": "p105.06", "quote": "Первая особенность карбонатного разреза обусловливает формирование в карбонатных межзерновых коллекторах более глубокого по сравнению с терригенными проникновения фильтрата промывочной жидкости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c7"}, {"page_print": null, "text": "С уменьшением пористости (до некоторого предела) глубина проникновения в коллекторы при прочих равных условиях растёт.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.06", "quote": "поскольку с уменьшением пористости (до некоторого предела) глубина проникновения в коллекторы при прочих равных условиях растет.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c8"}, {"page_print": null, "text": "Та же особенность (преобладание низкопористых разностей) — причина соизмеримости значений ρп в продуктивном коллекторе и в неколлекторе.", "kind": "inference", "page_pdf": 105, "unit_id": "p105.06", "quote": "Эта же особенность — причина соизмеримости значений  \\( \\rho_{n} \\)  в продуктивном коллекторе и неколлекторе.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c9"}, {"page_print": null, "text": "Перечисленные обстоятельства, влияние структуры порового пространства и широкий диапазон изменения kп существенно затрудняют оценку характера насыщения коллектора.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.01", "quote": "Эти обстоятельства и влияние структуры порового пространства, а также широкий диапазон изменений  \\( k_{n} \\)  существенно затрудняют оценку характера насыщения коллектора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c10"}, {"page_print": null, "text": "Отсутствие корреляции коллекторских свойств с глинистостью снижает эффективность методов СП и ГМ при изучении межзерновых коллекторов в карбонатном разрезе.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.01", "quote": "Отсутствие корреляции коллекторских свойств с глинистостью снижает эффективность методов СП и ГМ при изучении межзерновых коллекторов в карбонатном разрезе.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.carbonate_features#c11"}], "id": "latyshova.carbonate_features", "order": 37, "minutes": 2, "essence": "Принципы выделения коллекторов и оценки насыщения в карбонатах те же, что в терригенном разрезе. Но у карбонатов есть особенности, которые осложняют работу с каротажем. Это преобладание низкопористых разностей, широкий разброс пористости и структуры пор, широкий разброс нижнего предела пористости коллектора и слабая связь свойств с глинистостью.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Низкопористых разностей в карбонатах много. Поэтому фильтрат (жидкость из раствора, уходящая в пласт) проникает глубже, чем в терригенных коллекторах. Глубина проникновения растёт с уменьшением пористости, но лишь до некоторого предела.", "pages": [105]}, {"text": "Из-за этого значения сопротивления неизменённой части пласта ρп в продуктивном коллекторе и в неколлекторе становятся соизмеримыми. Коллекторские свойства карбонатов почти не связаны с содержанием нерастворимого остатка, то есть глинистого материала, которого здесь мало. Поэтому методы СП и ГМ теряют эффективность.", "pages": [105]}, {"text": "СП — метод потенциалов самопроизвольной поляризации, ГМ — гамма-метод.", "pages": [105, 107]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Для практики глава делает такой вывод: оценка характера насыщения карбонатного коллектора существенно сложнее, чем терригенного. Нельзя опираться на СП и ГМ как на главные признаки коллектора. Конкретные приёмы в этой части главы не описаны.", "pages": [105, 107]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Низкопористые разности — это части карбонатного разреза с малой пористостью. Нижний предел пористости коллектора — значение пористости, ниже которого порода уже не коллектор. В карбонатах он меняется в широком диапазоне, поэтому единой границы нет.", "pages": [105]}, {"text": "К трудностям добавляются структура порового пространства и широкий диапазон kп. Все эти обстоятельства вместе затрудняют оценку насыщения.", "pages": [107]}]}], "deeper": [{"text": "Единицы не приводят числовых значений пределов пористости, глубины проникновения или ρп. Они не описывают способов преодоления перечисленных трудностей.", "pages": [105]}], "glossary": [{"term": "низкопористые разности", "definition": "Части карбонатного разреза с малой пористостью; в карбонатных коллекторах они преобладают."}, {"term": "нижний предел пористости коллектора", "definition": "Значение пористости, ниже которого порода перестаёт быть коллектором; в карбонатах оно меняется в широком диапазоне."}], "format": "карточки", "tasks": [{"id": "latyshova.carbonate_features.t1", "type": "single", "step_id": "latyshova.carbonate_features", "claim_ids": ["latyshova.carbonate_features#c6", "latyshova.carbonate_features#c11"], "prompt": "В межзерновых карбонатных коллекторах методы СП и гамма-метод (ГМ) работают хуже, чем в терригенном разрезе. Почему?", "options": [{"id": "a", "text": "Свойства коллектора почти не связаны с глинистостью, а глинистого материала мало", "misconception": null}, {"id": "b", "text": "Фильтрат бурового раствора в карбонатах вообще не проникает в пласт", "misconception": "misc.no_invasion"}, {"id": "c", "text": "В карбонатах нет пористых разностей, пригодных для записи", "misconception": "misc.no_porosity"}, {"id": "d", "text": "Эти методы реагируют только на сопротивление, а оно в карбонатах постоянно", "misconception": "misc.method_confusion"}], "answer": "a", "tolerance": null, "unit": null, "explanation": "СП и ГМ выделяют коллектор по глинистости, а в карбонатах такой связи нет.", "kind": "understanding"}, {"id": "latyshova.carbonate_features.t2", "type": "multiple", "step_id": "latyshova.carbonate_features", "claim_ids": ["latyshova.carbonate_features#c3", "latyshova.carbonate_features#c5", "latyshova.carbonate_features#c9"], "prompt": "Какие особенности карбонатных коллекторов затрудняют оценку характера насыщения по каротажу? Выберите все верные.", "options": [{"id": "a", "text": "Преобладают низкопористые разности", "misconception": null}, {"id": "b", "text": "Нижний предел пористости коллектора меняется в широком диапазоне", "misconception": null}, {"id": "c", "text": "Сопротивление ρп продуктивного коллектора и неколлектора соизмеримо", "misconception": null}, {"id": "d", "text": "Высокая глинистость, по которой легко отличить коллектор", "misconception": "misc.clay_in_carbonates"}], "answer": ["a", "b", "c"], "tolerance": null, "unit": null, "explanation": "Низкопористые разности, широкий разброс нижнего предела и соизмеримость ρп затрудняют оценку, а глинистость в карбонатах мала.", "kind": "recall"}], "pictures": [{"id": "latyshova.carbonate_features.i1", "step_id": "latyshova.carbonate_features", "node_id": "latyshova.carbonate_features", "file": "pictures/carbonate_features_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Одна причина — много низкопористых пород — ведёт к глубокому проникновению фильтрата и близким ρп, из-за чего труднее оценить насыщение.", "alt": "Схема: из преобладания низкопористых пород следуют более глубокое проникновение фильтрата и близкие значения ρп коллектора и неколлектора, что затрудняет оценку насыщения.", "source": "построено кодом по утверждениям главы, стр. 105, 107", "claim_ids": ["latyshova.carbonate_features#c3", "latyshova.carbonate_features#c7", "latyshova.carbonate_features#c9", "latyshova.carbonate_features#c10"], "prompt": null}]}, {"title": "Нормализация диаграмм: совмещение кривой ρп и метода пористости", "short_title": "Нормализация диаграмм", "why_here": {"text": "Опирается на сопоставление ρп и пористости и показывает его в карбонатном разрезе (рис. 76).", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "И"}, "threshold": false, "pages": [105, 106, 107], "misconception": {"ref": null, "text": "Расхождение кривых ρп и метода пористости не означает автоматически нефть. По главе это признак продуктивного коллектора, а при пресном фильтрате — просто коллектора.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Вход: кривая ρп глубинного фокусированного электрического метода и кривая метода пористости (НМ, акустический или ГГМ) по одному интервалу. Одну из шкал преобразуют, например в логарифмическую с модулем. Выход: интервалы совпадения (неколлекторы, водоносные коллекторы) и интервалы расхождения (коллектор или продуктивный коллектор).", "by_model": true}, "breaks": {"text": "Совпадение в водоносных пластах требует достаточной глубинности электрического метода. Результат наиболее чёткий при однородном минеральном составе пород. При пресном фильтрате расхождение говорит о коллекторе, а не обязательно о продуктивности.", "by_model": true}, "hypotheses": []}, "it_analogy": {"text": "Нормализация похожа на наложение двух графиков метрик с подбором масштаба по «здоровому» участку. Затем расхождение показывает аномалию, как при сравнении с базовой линией.", "breaks_where": "Здесь базовая линия задана физикой породы (водоносный пласт, однородная минералогия), а не историей данных. Смена минерального состава ломает базу.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы ρп и метода пористости по интервалу, шкалы, участки неколлекторов и водоносных коллекторов.", "manual_steps": "Выбрать пару методов, преобразовать шкалу одной диаграммы, подобрать модуль, совместить кривые в опорных интервалах, выделить участки расхождения.", "judgment_points": "Подбор модуля масштаба; выбор опорных интервалов; оценка достаточной глубинности электрического метода; решение, продуктивный это коллектор или просто коллектор.", "time": "в главе не указано", "typical_errors": "В главе не описаны; из условий: недостаточная глубинность метода, неоднородный минеральный состав.", "by_model": true}, "decision_on_data": {"features": ["совпадение или расхождение кривой ρп и кривой метода пористости после преобразования шкалы", "тип промывочной жидкости: пресный фильтрат или нет", "однородность минерального состава"], "rule": "Кривые совпадают в неколлекторах и водоносных коллекторах. Расхождение — признак продуктивного коллектора, а при проникновении пресного фильтрата — коллектора.", "conclusion": "Интервал расхождения кривых относят к коллектору, а при отсутствии пресного фильтрата — к продуктивному коллектору.", "counterexample": "Если глубинность электрического метода недостаточна для захвата неизменённой части водоносного коллектора, условие совпадения в воде не выполняется. Если состав пород неоднороден, результат менее чёткий."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["совмещение кривых"], "links": [{"type": "prerequisite", "target": "latyshova.compare_resistivity_porosity"}, {"type": "prerequisite", "target": "latyshova.ggm_ak_collectors"}, {"type": "prerequisite", "target": "latyshova.nmr_and_method_choice"}, {"type": "prerequisite", "target": "latyshova.mud_effects_on_borehole"}], "needs_scan": [{"page": 105, "what": "Рис. 76: подписи кривых, шкалы, литологическая колонка и положение интервалов расхождения плохо читаются в описаниях программы распознавания"}, {"page": 106, "what": "Формула под рис. 76: расшифровка обозначений (ρп, ρр, δр) и их смысл не раскрыты в единицах"}], "claims": [{"page_print": null, "text": "Помимо ранее рассмотренных методов выделения коллекторов, которые применимы и к карбонатному, и к терригенному разрезу, используется способ нормализации (наложения диаграмм).", "kind": "observation", "page_pdf": 107, "unit_id": "p107.02", "quote": "В дополнение к рассмотренным методам выделения и изучения коллекторов, которые применимы к карбонатному разрезу так же, как и к терригенному, используется способ нормализации или наложения диаграмм.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c1"}, {"page_print": null, "text": "Сущность способа — графическое сопоставление кривой ρп одного из фокусированных электрических методов большой глубинности с кривой одного из методов пористости: НМ, акустического или ГГМ.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.02", "quote": "с кривой одного из методов пористости — НМ, акустического или ГГМ (рис. 76).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c2"}, {"page_print": null, "text": "Кривые ρп и метода пористости совпадают в интервалах неколлекторов и водоносных коллекторов при условии, что глубинность электрического метода достаточна, чтобы захватить неизменённую часть водоносного коллектора.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.02", "quote": "совпадают в интервалах не-коллекторов и водоносных коллекторов, если глубинность электрического метода достаточна, чтобы захватить исследованием неизмененную часть водоносного коллектора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c3"}, {"page_print": null, "text": "Для совпадения кривых преобразуют шкалу одной из совмещаемых диаграмм.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.02", "quote": "Для этого преобразуют шкалу одной из совмещаемых диаграмм.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c4"}, {"page_print": null, "text": "При совмещении кривой ρп экранированного зонда с кривой НГМ или НМ линейный масштаб переводят в логарифмический с модулем, обеспечивающим совмещение кривых в неколлекторах и водоносных коллекторах.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.02", "quote": "экранированного зонда с кривой НГМ или НМ преобразуют линейный масштаб в логарифмический с модулем, обеспечивающим совмещение кривых в неколлекторах и водоносных коллекторах (см. рис. 76).", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c5"}, {"page_print": null, "text": "Расхождение кривых ρп и метода пористости — признак продуктивного коллектора, а при проникновении пресного фильтрата глинистого раствора — признак коллектора.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.02", "quote": "является признаком продуктивного коллектора или, при наличии проникновения пресного фильтрата глинистого раствора, - коллектора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c6"}, {"page_print": null, "text": "С петрофизической точки зрения нормализация — это сопоставление значений ρп или близких к ним значений с расчётным значением ρm.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.03", "quote": "С петрофизической точки зрения способ нормализации есть сопоставление значений", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c7"}, {"page_print": null, "text": "Сопоставление выполняется непрерывно по всему исследуемому интервалу разреза.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.03", "quote": "непрерывно по исследуемому интервалу разреза.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c8"}, {"page_print": null, "text": "Преимущества способа — простота и наглядность.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.03", "quote": "Преимуществами способа являются простота и наглядность", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c9"}, {"page_print": null, "text": "Способ позволяет выделять коллекторы при бурении на любом типе раствора.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.03", "quote": "возможность выделения коллекторов при бурении на любом типе раствора", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c10"}, {"page_print": null, "text": "Продуктивность способом устанавливают при бурении на глинистом и нефильтрующемся растворе.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.03", "quote": "установлении продуктивности при бурении на глинистом и нефильтрующемся растворе.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c11"}, {"page_print": null, "text": "Способ даёт примерно одинаковую эффективность при различном граничном значении kп*.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.03", "quote": "Способ также дает примерно одинаковую эффективность при различном граничном значении", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c12"}, {"page_print": null, "text": "Эффективность сохраняется и при наличии в разрезе коллекторов, у которых пористость и значение kп* существенно отличаются.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.03", "quote": "и при наличии в исследуемом интервале разреза коллекторов, пористость и значение", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c13"}, {"page_print": null, "text": "Наиболее чёткие результаты нормализация даёт при однородном минеральном составе пород в исследуемом разрезе.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.04", "quote": "Наиболее четкие результаты способ нормализации дает при однородном минеральном составе пород в исследуемом разрезе.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c14"}, {"page_print": null, "text": "Рис. 76 — комплекс диаграмм ГИС по участку скважины карбонатного разреза; на нём показан способ нормализации.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.09", "quote": "Рис.76. Комплекс диаграмм ГИС по участку скважины карбонатного разреза:", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.normalization_overlay#c15"}, {"page_print": null, "text": "Под рис. 76 приведены параметры: 0,05 Ом·м и t° = 20 °C (обозначение левой части в записи OCR — ρп, смысл в тексте не раскрыт).", "kind": "observation", "page_pdf": 106, "unit_id": "p106.01", "quote": "\\rho_{\\mathrm{n}} = 0,05 \\mathrm{OM} \\cdot \\mathrm{M}; t^{0} = 20^{\\circ} \\mathrm{C}", "source_kind": "formula", "by_model": false, "needs_scan": true, "id": "latyshova.normalization_overlay#c16"}, {"page_print": null, "text": "Под рис. 76 приведены также значения 1,2÷1,3 Ом·м (обозначено ρр) и 1,2 т/см³ (обозначено δр); расшифровка символов в этой части главы отсутствует.", "kind": "observation", "page_pdf": 106, "unit_id": "p106.01", "quote": "\\rho_{\\mathrm{p}} = 1,2 \\div 1,3 \\mathrm{OM} \\cdot \\mathrm{M}; \\delta_{\\mathrm{p}} = 1,2 \\mathrm{t} / \\mathrm{cm}^{3}", "source_kind": "formula", "by_model": false, "needs_scan": true, "id": "latyshova.normalization_overlay#c17"}, {"page_print": null, "text": "По описанию программы распознавания, одна из панелей рисунка — планшет с двумя треками каротажных кривых, глубинной и литологической колонкой.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.07", "quote": "Общий вид: планшет с двумя треками каротажных кривых", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.normalization_overlay#c18"}, {"page_print": null, "text": "По описанию программы распознавания, на левом треке одна из кривых имеет пик у отметки 2740.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.07", "quote": "Отметка \"2740\" подписана у одного из пиков кривой.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.normalization_overlay#c19"}, {"page_print": null, "text": "По описанию программы распознавания, правый трек содержит кривую с частыми высокоамплитудными зубцами.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.07", "quote": "Кривая с высокоамплитудными частыми зубцами (типичное поведение кривой типа ПС или КС с сильной изрезанностью).", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.normalization_overlay#c20"}, {"page_print": null, "text": "По описанию программы распознавания, названия кривых, единицы и числовые отметки шкал на панели в большинстве случаев не читаются.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.07", "quote": "точные названия кривых, единицы измерения и числовые отметки шкал в большинстве случаев не читаются.", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.normalization_overlay#c21"}, {"page_print": null, "text": "По описанию программы распознавания, на второй панели несколько треков (ГК, НМ, ЯМ) с частично неразборчивыми подписями.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.08", "quote": "Заголовки над треками (слева направо), частично неразборчивы из-за качества скана:", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.normalization_overlay#c22"}, {"page_print": null, "text": "По описанию программы распознавания, кривые второй панели — непрерывные записи по глубине без отбивок пластов и интервалов перфорации.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.08", "quote": "Кривые представляют собой непрерывные каротажные записи по глубине (глубина увеличивается вниз)", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.normalization_overlay#c23"}, {"page_print": null, "text": "По описанию программы распознавания, литологическая колонка второй панели не имеет легенды.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.08", "quote": "Литологическая колонка слева от первого трека не имеет легенды в данном изображении", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.normalization_overlay#c24"}, {"page_print": null, "text": "По описанию программы распознавания, на второй панели все четыре кривые плавно колеблются без резких аномалий.", "kind": "observation", "page_pdf": 105, "unit_id": "p105.08", "quote": "плавные волнообразные колебания всех четырёх кривых без резких аномалий", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.normalization_overlay#c25"}], "id": "latyshova.normalization_overlay", "order": 38, "minutes": 4, "essence": "Нормализация — это графическое совмещение кривой ρп глубинного фокусированного электрического метода с кривой метода пористости (НМ, акустический метод или ГГМ). Масштаб одной кривой подбирают так, чтобы они совпали в неколлекторах и водоносных коллекторах. Расхождение кривых указывает на продуктивный коллектор или, при пресном фильтрате, просто на коллектор.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Совмещение кривых — это наложение двух диаграмм на один планшет с общей глубиной. Масштаб одной из них преобразуют так, чтобы кривые лежали друг на друге в опорных интервалах. Опорные интервалы — неколлекторы и водоносные коллекторы.", "pages": [107]}, {"text": "Электрический метод должен быть достаточно глубинным, чтобы захватить неизменённую часть водоносного коллектора. Тогда в опорных интервалах оба метода отражают одну и ту же пористость. Пример из главы: кривую ρп экранированного зонда совмещают с кривой НГМ или НМ.", "pages": [107]}, {"text": "Для этого линейный масштаб переводят в логарифмический с подобранным модулем. С петрофизической точки зрения это сопоставление ρп или близких к нему значений с расчётным значением ρm непрерывно по всему интервалу разреза. Если кривые разошлись, в этом интервале сопротивление отличается от ожидаемого для водоносной породы такой пористости.", "pages": [107]}, {"text": "Это признак продуктивного коллектора. При проникновении пресного фильтрата глинистого раствора расхождение указывает на коллектор.", "pages": [107]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок действий по главе такой. Берут кривую ρп фокусированного глубинного метода и кривую одного из методов пористости: НМ, акустического или ГГМ. Преобразуют шкалу одной из диаграмм, например линейную в логарифмическую с подходящим модулем.", "pages": [107]}, {"text": "Модуль подбирают так, чтобы кривые совпали в неколлекторах и водоносных коллекторах. Затем ищут интервалы, где кривые расходятся. Для рис.", "pages": [107]}, {"text": "76 (карбонатный разрез) в главе приведены условия записи: 0,05; t° = 20 °C; 1,2÷1,3 Ом·м; 1,2 т/см³. Смысл обозначений в тексте формулы не раскрыт.", "pages": [106]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Способ применим и к карбонатному, и к терригенному разрезу. Он позволяет выделять коллекторы при бурении на любом растворе. Продуктивность по нему устанавливают только при бурении на глинистом и нефильтрующемся растворе.", "pages": [107]}, {"text": "Эффективность примерно одинакова при разных граничных значениях пористости kп*. Она сохраняется и тогда, когда коллекторы в разрезе заметно различаются по пористости. Наиболее чёткие результаты получаются при однородном минеральном составе пород.", "pages": [107]}, {"text": "Если глубинности метода не хватает, чтобы захватить неизменённую часть водоносного коллектора, совпадение в водоносных пластах не гарантировано. При пресном фильтрате расхождение говорит лишь о коллекторе, а не о нефти.", "pages": [107]}]}], "deeper": [], "glossary": [{"term": "совмещение кривых", "definition": "Наложение двух диаграмм на один планшет с преобразованием шкалы одной из них, чтобы кривые совпали в опорных интервалах (неколлекторы и водоносные коллекторы); расхождение выявляет коллекторы."}], "format": "практикум на данных", "tasks": [{"id": "latyshova.normalization_overlay.t1", "type": "order", "step_id": "latyshova.normalization_overlay", "claim_ids": ["latyshova.normalization_overlay#c2", "latyshova.normalization_overlay#c4", "latyshova.normalization_overlay#c5", "latyshova.normalization_overlay#c6"], "prompt": "Расставьте шаги способа нормализации диаграмм в порядке выполнения.", "options": [{"id": "a", "text": "Подобрать модуль так, чтобы кривые совпали в неколлекторах и водоносных коллекторах", "misconception": null}, {"id": "b", "text": "Найти интервалы, где кривые расходятся", "misconception": null}, {"id": "c", "text": "Взять кривую ρп глубинного фокусированного метода и кривую метода пористости", "misconception": null}, {"id": "d", "text": "Преобразовать шкалу одной из диаграмм, например линейную в логарифмическую", "misconception": null}], "answer": ["c", "d", "a", "b"], "tolerance": null, "unit": null, "explanation": "Сначала берут две кривые, затем меняют масштаб одной до совпадения в опорных интервалах и только потом ищут расхождения.", "kind": "recall"}, {"id": "latyshova.normalization_overlay.t2", "type": "single", "step_id": "latyshova.normalization_overlay", "claim_ids": ["latyshova.normalization_overlay#c6", "latyshova.normalization_overlay#c11"], "prompt": "После нормализации кривая ρп глубинного фокусированного метода расходится с кривой нейтронного метода в интервале карбонатного разреза. Скважина пробурена на глинистом растворе, фильтрат которого пресный. Какой вывод корректен?", "options": [{"id": "a", "text": "Интервал нефтенасыщен, потому что расхождение всегда означает нефть", "misconception": "misc.divergence_is_oil"}, {"id": "b", "text": "Интервал водоносный, потому что в воде кривые должны расходиться", "misconception": "misc.water_diverges"}, {"id": "c", "text": "Интервал является коллектором, но нефтеносность по одному расхождению не доказана", "misconception": null}, {"id": "d", "text": "Интервал является неколлектором, так как кривые не совпали", "misconception": "misc.divergence_is_noncollector"}], "answer": "c", "tolerance": null, "unit": null, "explanation": "При проникновении пресного фильтрата расхождение кривых указывает лишь на коллектор.", "kind": "transfer"}], "pictures": [{"id": "latyshova.normalization_overlay.i1", "step_id": "latyshova.normalization_overlay", "node_id": "latyshova.normalization_overlay", "file": "pictures/normalization_overlay_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Две кривые совмещают по шкале в опорных интервалах; там, где они расходятся, смотрите на признак продуктивного коллектора.", "alt": "Схема: кривые ρп и метода пористости совмещают подбором шкалы в неколлекторах и водоносных коллекторах; расхождение кривых указывает на продуктивный коллектор.", "source": "построено кодом по утверждениям главы, стр. 107", "claim_ids": ["latyshova.normalization_overlay#c2", "latyshova.normalization_overlay#c3", "latyshova.normalization_overlay#c4", "latyshova.normalization_overlay#c6"], "prompt": null}]}, {"title": "Пример 54: нефтеносный карбонатный коллектор, ВНК и эффективная толщина", "short_title": "Пример: ВНК и толщина в карбонате", "why_here": {"text": "Сводит нормализацию, ВНК и вычитание прослоев в одну процедуру.", "by_model": true}, "difficulty": {"primary": "Пр", "secondary": "Н"}, "threshold": false, "pages": [107], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход: кривые ρп зонда БК-3, ρпНМ индукционного метода и НГМ в едином масштабе пористости, а также диаграмма микрозондов. Выход: положение ВНК (1083 м), Pн,кр ≈ 2,5 и эффективная толщина 9 м из общей 13,5 м.", "by_model": true}, "breaks": {"text": "Значение Pн,кр ≈ 2,5 верно при допущении ρпНМ ≈ ρп. Если оно не выполняется, привязка Pн,кр к глубине ВНК меняется. Глубина кровли в тексте не дана.", "by_model": true}, "hypotheses": [{"text": "Расхождение нормализованных кривых по глубине, вероятно, служит признаком смены насыщения, а сближение — признаком плотного прослоя.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Нормализация похожа на приведение двух метрик к одной шкале на общем графике. Тогда расхождение линий ищется по одной оси, а точка пересечения даёт границу. Вычитание прослоев похоже на фильтрацию строк таблицы перед суммированием.", "breaks_where": "У метрик шкала задана произвольно, а у кривых масштаб привязан к пористости и физике пласта. Граница ВНК требует критического Pн, а не просто пересечения линий.", "by_model": true}, "now_practice": null, "inefficiency_lens": {"inputs": "Диаграммы БК-3, индукционного метода, НГМ и микрозондов по интервалу разреза.", "manual_steps": "Привести кривые к единому масштабу пористости, сравнить их, провести ВНК, выделить плотные прослои по микрозондам или сближению кривых, вычесть их суммарную толщину из общей.", "judgment_points": "Выбор глубины ВНК по расхождению кривых. Признание ρпНМ ≈ ρп. Решение, какие прослои считать неколлектором.", "time": "в главе не указано", "typical_errors": "В главе не указаны.", "by_model": true}, "decision_on_data": {"features": ["Нормализованные кривые ρп (БК-3, индукционный метод) и НГМ в едином масштабе пористости", "Диаграмма микрозондов для выделения плотных прослоев"], "rule": "Часть разреза, где нормализованные кривые показывают продуктивность, считается нефтеносной, где нет — водоносной. Границу между ними принимают за ВНК, ей соответствует Pн,кр ≈ 2,5. Из общей толщины продуктивной части вычитают толщину плотных прослоев-неколлекторов.", "conclusion": "ВНК на глубине 1083 м; общая толщина 13,5 м, эффективная толщина 9 м.", "counterexample": "В главе не приведён."}, "worked_examples": [{"page_pdf": 107, "condition": "Выделить интервалы нефтеносного межзернового коллектора в карбонатных отложениях, определить положение ВНК и величину h_φ продуктивных коллекторов.", "steps": ["Применить нормализацию: сравнить кривые ρп зонда БК-3 и НГМ, ρпНМ индукционного метода и НГМ в едином масштабе пористости.", "Установить, что верхняя часть разреза продуктивна, нижняя водоносна.", "Провести ВНК на глубине 1083 м, которой соответствует Pн,кр ≈ 2,5 при ρпНМ ≈ ρп.", "В интервале 1069,5 - 1083 м учесть прослои плотных пород-неколлекторов по микрозондам, а в отдельных случаях по сближению нормализованных кривых НГМ и БК-3.", "Из общей толщины продуктивных отложений 13,5 м исключить суммарную толщину прослоев неколлектора."], "result": "ВНК на 1083 м; Pн,кр ≈ 2,5; h_φ = 13,5 − 4,5 = 9 м.", "figure": "рис. 76, стр. 107"}], "book_tasks": [], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.normalization_overlay"}, {"type": "prerequisite", "target": "latyshova.carbonate_features"}, {"type": "prerequisite", "target": "latyshova.vnk_transition_zone"}, {"type": "prerequisite", "target": "latyshova.nonreservoir_interlayers"}, {"type": "prerequisite", "target": "latyshova.effective_thickness_basic"}, {"type": "prerequisite", "target": "latyshova.critical_pn_kv"}], "needs_scan": [{"page": 107, "what": "Рис. 76: диаграммы БК-3, индукционного метода, НГМ, микрозондов, положение ВНК и плотных прослоев."}, {"page": 107, "what": "Глубина кровли продуктивных отложений: в тексте предложение обрывается."}], "claims": [{"page_print": null, "text": "Задача примера 54: выделить интервалы нефтеносного межзернового коллектора в карбонатных отложениях.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.05", "quote": "Выделить интервалы нефтеносного межзернового коллектора в карбонатных отложениях", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c1"}, {"page_print": null, "text": "Нужно также определить положение ВНК и величину h_φ продуктивных коллекторов; пример опирается на рис. 76.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.05", "quote": "определить положение ВНК и величину", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c2"}, {"page_print": null, "text": "Используется способ нормализации: сравниваются кривые ρп зонда БК-3 и НГМ, а также ρпНМ индукционного метода и НГМ, приведённые к единому масштабу пористости.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.06", "quote": "Используем способ нормализации, сравнивая кривые", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c3"}, {"page_print": null, "text": "Кривые сравниваются после приведения к единому масштабу пористости.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.06", "quote": "приведенные к единому масштабу пористости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c4"}, {"page_print": null, "text": "По нормализации установлено: продуктивна верхняя часть разреза, нижняя — водоносная.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.06", "quote": "Устанавливаем, что продуктивна верхняя часть разреза, а нижняя является водоносной.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c5"}, {"page_print": null, "text": "ВНК проведён на глубине 1083 м.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.06", "quote": "Границу ВНК проводим на глубине 1083м, которой соответствует", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c6"}, {"page_print": null, "text": "Этой глубине соответствует Pн,кр ≈ 2,5 при допущении ρпНМ ≈ ρп.", "kind": "assumption", "page_pdf": 107, "unit_id": "p107.06", "quote": "если принять  \\( \\rho_{nHM} \\approx \\rho_{n} \\)", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c7"}, {"page_print": null, "text": "Глубина кровли продуктивных отложений в тексте не указана: предложение обрывается.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.06", "quote": "Кровля продуктивных отложений расположена на глубине.", "source_kind": "text", "by_model": false, "needs_scan": true, "id": "latyshova.example_54#c8"}, {"page_print": null, "text": "Общая толщина продуктивных отложений составляет 13,5 м.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.10", "quote": "Общая толщина продуктивных отложений составляет 13,5 м.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c9"}, {"page_print": null, "text": "В интервале 1069,5 - 1083 м учитываются прослои плотных пород-неколлекторов, выделяемые по диаграмме микрозондов.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.10", "quote": "Учитывая в интервале 1069,5 - 1083м прослои плотных пород неколлекторов, выделяемых по диаграмме микрозондов", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c10"}, {"page_print": null, "text": "В отдельных случаях прослои неколлектора выделяют по сближению нормализованных кривых НГМ и БК-3.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.10", "quote": "а в отдельных случаях сближением нормализованных кривых НГМ и БК-3", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c11"}, {"page_print": null, "text": "Из общей толщины исключают суммарную толщину прослоев неколлектора; получается h_φ = 13,5 − 4,5 = 9 м.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.10", "quote": "\\( h_{\\varphi} = 13,5 - 4,5 = 9м \\)", "source_kind": "formula", "by_model": false, "needs_scan": false, "id": "latyshova.example_54#c12"}], "id": "latyshova.example_54", "order": 39, "minutes": 2, "essence": "Пример сводит три действия в одну процедуру. Сначала кривые сопротивления и пористости приводят к единому масштабу, затем по ним проводят ВНК, затем из общей толщины вычитают прослои неколлектора. В примере ВНК стоит на глубине 1083 м, а эффективная толщина равна 9 м.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Нормализация — это сравнение кривых ρп и метода пористости (НГМ), приведённых к единому масштабу пористости. В примере берут ρп зонда БК-3 и ρпНМ индукционного метода и сравнивают каждую с НГМ. Так верхняя часть разреза оказывается продуктивной, а нижняя — водоносной.", "pages": [107]}, {"text": "Границу между ними принимают за ВНК. Ей соответствует критическое значение параметра насыщения Pн,кр ≈ 2,5, если принять ρпНМ ≈ ρп.", "pages": [107]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порядок действий такой. Выделяют интервалы нефтеносного межзернового коллектора в карбонатных отложениях. Нормализацией разделяют нефтеносную и водоносную части.", "pages": [107]}, {"text": "Проводят ВНК и находят толщину продуктивных отложений. Внутри продуктивного интервала выделяют прослои плотных пород-неколлекторов по микрозондам. В отдельных случаях их выделяют по сближению нормализованных кривых НГМ и БК-3.", "pages": [107]}, {"text": "Суммарную толщину этих прослоев вычитают из общей толщины. Получается 13,5 − 4,5 = 9 м.", "pages": [107]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Равенство ρпНМ ≈ ρп принято как допущение. Значение Pн,кр ≈ 2,5 привязано именно к этому допущению. Прослои неколлектора выделяют двумя способами: надёжнее по микрозондам, в отдельных случаях по сближению кривых.", "pages": [107]}, {"text": "В тексте единиц глубина кровли продуктивных отложений не указана: фраза обрывается. Нужен скан страницы с этим примером.", "pages": [107]}]}], "deeper": [{"text": "В примере только интервал 1069,5 - 1083м прямо назван интервалом, где учтены плотные прослои. Число 4,5 м автор приводит как суммарную толщину прослоев неколлектора, отдельные прослои в этой части главы не перечислены. Они, вероятно, показаны на рис. 76, которого в этой части главы нет.", "pages": [107]}], "glossary": [], "format": "практикум на данных", "tasks": [{"id": "latyshova.example_54.t1", "type": "calc", "step_id": "latyshova.example_54", "claim_ids": ["latyshova.example_54#c9", "latyshova.example_54#c12"], "prompt": "Общая толщина продуктивных отложений над ВНК равна 13,5 м. Суммарная толщина плотных прослоев-неколлекторов в этом интервале — 4,5 м. Чему равна эффективная толщина h_φ?", "options": [], "answer": 9, "tolerance": 0.01, "unit": "м", "explanation": "Из общей толщины вычитают суммарную толщину прослоев неколлектора: 13,5 − 4,5 = 9 м.", "kind": "data"}, {"id": "latyshova.example_54.t2", "type": "gap", "step_id": "latyshova.example_54", "claim_ids": ["latyshova.example_54#c10", "latyshova.example_54#c11", "latyshova.example_54#c12"], "prompt": "Эффективную толщину получают, вычитая из общей толщины суммарную толщину прослоев {{1}}. Их выделяют по диаграммам {{2}}, а в отдельных случаях — по сближению нормализованных кривых НГМ и БК-3.", "options": [], "answer": ["неколлектора", "микрозондов"], "tolerance": null, "unit": null, "explanation": "Плотные прослои-неколлекторы не входят в эффективную толщину и выделяются в первую очередь по микрозондам.", "kind": "recall"}], "pictures": [{"id": "latyshova.example_54.i1", "step_id": "latyshova.example_54", "node_id": "latyshova.example_54", "file": "pictures/example_54_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Три шага примера: нормализация кривых, положение ВНК, вычитание неколлектора из общей толщины 13,5 м.", "alt": "Схема: после нормализации кривых определён ВНК на глубине 1083 м, из общей толщины 13,5 м вычтены 4,5 м неколлектора, получена эффективная толщина 9 м.", "source": "построено кодом по утверждениям главы, стр. 107", "claim_ids": ["latyshova.example_54#c3", "latyshova.example_54#c5", "latyshova.example_54#c6", "latyshova.example_54#c9", "latyshova.example_54#c12"], "prompt": null}]}, {"title": "Критическая пористость карбонатов по связи остаточной воды и пористости", "short_title": "Критическая пористость карбонатов", "why_here": {"text": "Продолжает тему порога пористости; зависимость kв.св = f(kп) задаёт kп*.", "by_model": true}, "difficulty": {"primary": "Ф", "secondary": "Н"}, "threshold": false, "pages": [107], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход — пористость kп (%) и тип карбонатного коллектора. Выход — остаточная водонасыщенность kв.св (%). Рис. 77 даёт пять кривых kв.св = f(kп) для разных районов. По ним снимают kп* при заданном kв.св.", "by_model": true}, "breaks": {"text": "kп* меняется в широких пределах из-за структуры порового пространства, поэтому один порог для всех типов неприменим. Уровень 70% принят условием примера.", "by_model": true}, "hypotheses": [{"text": "Вероятно, обозначение k_{n,cn} в формулах — это kв.св, как на осях рисунка; в тексте единиц это не расшифровано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это похоже на порог срабатывания, подбираемый по кривой для каждого класса данных. Для каждого типа коллектора своя кривая, и порог снимают с неё.", "breaks_where": "Порог в IT обычно выбирают произвольно или по метрике. Здесь он зависит от физической структуры пор, а 70% задано условием примера.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["тип межзернового карбонатного коллектора (кривая 1–5 рис. 77)", "зависимость kв.св = f(kп)", "принятый уровень kв.св = 70%"], "rule": "Найти на кривой данного типа коллектора пористость kп, при которой kв.св = 70%; принять её за kп*.", "conclusion": "Полученное kп* используют как критическое значение при выделении межзерновых карбонатных коллекторов по диаграммам методов пористости.", "counterexample": "Значение kп*, найденное для одного типа коллектора, нельзя переносить на другой: в главе сказано, что kп* меняется в широких пределах."}, "worked_examples": [{"page_pdf": 107, "condition": "Определить kп* для различных межзерновых карбонатных коллекторов, характеризуемых графиками kв.св = f(kп) на рис. 77, принимая за kп* значение kп, соответствующее kв.св = 70%.", "steps": ["Для каждой из кривых 1–5 рис. 77 найти точку, где kв.св = 70%.", "Снять с оси пористости значение kп в этой точке.", "Оформить результаты в табл. 23."], "result": "Числовые значения kп* даны в табл. 23, которой нет в выданных единицах.", "figure": "рис. 77, стр. 107"}], "book_tasks": [], "terms_introduced": ["остаточная (связанная) водонасыщенность kв.св", "критическая пористость kп*"], "links": [{"type": "prerequisite", "target": "latyshova.critical_pn_kv"}, {"type": "prerequisite", "target": "latyshova.carbonate_features"}, {"type": "prerequisite", "target": "latyshova.ggm_ak_collectors"}, {"type": "prerequisite", "target": "latyshova.critical_values_examples"}], "needs_scan": [{"page": 107, "what": "Рис. 77: точные кривые 1–5, оси, символы точек; описание программы распознавания приблизительное."}, {"page": 107, "what": "Табл. 23: значения kп* для типов коллекторов."}], "claims": [{"page_print": null, "text": "Рис. 77 показывает кривые зависимости остаточной водонасыщенности от пористости для карбонатных коллекторов разных районов.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.07", "quote": "для карбонатных коллекторов разных районов:", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c1"}, {"page_print": null, "text": "Кривая 1 на рис. 77 относится к крупнопористым рифовым отложениям (Башкирия).", "kind": "observation", "page_pdf": 107, "unit_id": "p107.08", "quote": "1 – крупнопористые рифовые отложения (Башкирия);", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c2"}, {"page_print": null, "text": "Кривая 2 относится к крупнопористым коллекторам карбона (Башкирия).", "kind": "observation", "page_pdf": 107, "unit_id": "p107.08", "quote": "2 – крупнопористые коллекторы карбона (Башкирия);", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c3"}, {"page_print": null, "text": "Кривая 3 относится к известнякам карбона (Вуктыл), кривая 4 — к доломитам межсолевых отложений девона (Белоруссия).", "kind": "observation", "page_pdf": 107, "unit_id": "p107.08", "quote": "3 – известняки карбона (Вуктыл); 4 – доломиты межсолевых отложений девона (Белоруссия);", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c4"}, {"page_print": null, "text": "Кривая 5 относится к поровым коллекторам перми (Оренбург).", "kind": "observation", "page_pdf": 107, "unit_id": "p107.08", "quote": "5 – поровые коллекторы перми (Оренбург)", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c5"}, {"page_print": null, "text": "По описанию программы распознавания, на графике по горизонтали отложена пористость Кп (%), по вертикали — Кв.св (%).", "kind": "observation", "page_pdf": 107, "unit_id": "p107.09", "quote": "Оси: горизонтальная — Кп, % (линейная шкала, диапазон примерно 0–25%); вертикальная — Кв.св, % (линейная шкала, диапазон примерно 0–90%).", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.kp_star_graph#c6"}, {"page_print": null, "text": "По описанию программы распознавания, пять кривых убывают: Кв.св высокая при малых Кп и низкая при больших Кп.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.09", "quote": "убывающих от высоких значений Кв.св при малых Кп к низким значениям Кв.св при больших Кп", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.kp_star_graph#c7"}, {"page_print": null, "text": "По описанию программы распознавания, точки данных (разные символы) разбросаны в области выше и между кривых.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.09", "quote": "Точки данных разбросаны в области выше и между кривых", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.kp_star_graph#c8"}, {"page_print": null, "text": "По описанию программы распознавания, кривая 5 расположена выше остальных, а кривая 1 — самая нижняя и крутая.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.09", "quote": "самая нижняя и крутая кривая, ограничивает область малых Кв.св", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.kp_star_graph#c9"}, {"page_print": null, "text": "По описанию программы распознавания, чем выше номер кривой, тем выше Кв.св при одинаковой пористости; это интерпретация программы распознавания.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.09", "quote": "чем выше номер кривой, тем выше уровень Кв.св при одинаковой пористости", "source_kind": "figure_description_model", "by_model": true, "needs_scan": true, "id": "latyshova.kp_star_graph#c10"}, {"page_print": null, "text": "При выделении межзерновых карбонатных коллекторов по диаграммам методов пористости используют критическое значение kп*.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.11", "quote": "При выделении межзерновых карбонатных коллекторов по диаграммам методов пористости с использованием критического значения", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c11"}, {"page_print": null, "text": "В зависимости от структуры порового пространства kп* изменяется в широких пределах.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.11", "quote": "учитывают, что в зависимости от структуры порового пространства", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c12"}, {"page_print": null, "text": "Это иллюстрируют обобщённые зависимости остаточной водонасыщенности от пористости.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.11", "quote": "Это наглядно иллюстрируют обобщенные зависимости между параметрами", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c13"}, {"page_print": null, "text": "Зависимости построены для разных типов межзерновых карбонатных коллекторов известных нефтяных и газовых месторождений СССР (рис. 77).", "kind": "observation", "page_pdf": 107, "unit_id": "p107.11", "quote": "для различных типов межзерновых карбонатных коллекторов известных нефтяных и газовых месторождений СССР (рис. 77)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c14"}, {"page_print": null, "text": "По зависимости остаточной водонасыщенности от пористости можно оценить критическое значение kп*.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.11", "quote": "можно оценить критическое значение", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c15"}, {"page_print": null, "text": "Пример 55 ставит задачу определить kп* для разных межзерновых карбонатных коллекторов по графикам рис. 77.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.12", "quote": "для различных межзерновых карбонатных коллекторов, характеризуемых графиками", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c16"}, {"page_print": null, "text": "В примере 55 в качестве kп* принимается kп, при котором остаточная водонасыщенность равна 70%.", "kind": "assumption", "page_pdf": 107, "unit_id": "p107.12", "quote": "значение \\( k_n \\), соответствующее \\( k_{n,cn} = 70\\% \\)", "source_kind": "task", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c17"}, {"page_print": null, "text": "Результаты определения kп* оформляются в табл. 23.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.13", "quote": "Результаты определений оформляем в виде табл. 23.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_graph#c18"}], "id": "latyshova.kp_star_graph", "order": 40, "minutes": 2, "essence": "Для межзерновых карбонатных коллекторов критическая пористость kп* сильно зависит от структуры порового пространства. Поэтому единого значения нет. Её оценивают по зависимости остаточной воды от пористости, которая на рис. 77 дана для пяти типов коллекторов. В примере 55 kп* принято там, где остаточная водонасыщенность равна 70%.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Остаточная (связанная) вода — это вода, которая остаётся в порах и не вытесняется. Её долю от объёма пор обозначают kв.св. Чем выше пористость kп, тем ниже kв.св: кривые на рис.", "pages": [107]}, {"text": "77 убывают. Для каждого типа коллектора кривая своя. Критическую пористость kп* снимают с кривой в точке, где kв.св достигает принятого значения.", "pages": [107]}, {"text": "В примере 55 это 70%.", "pages": [107]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Сначала берут график kв.св = f(kп) для нужного типа карбонатного коллектора. Затем на уровне kв.св = 70% находят соответствующий kп. Результаты для всех кривых рис.", "pages": [107]}, {"text": "77 сводят в табл. 23. Полученное kп* используют при выделении межзерновых коллекторов по диаграммам методов пористости.", "pages": [107]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Значение kп* меняется в широких пределах, поэтому переносить его с одного типа коллектора на другой нельзя. Рис. 77 обобщает известные месторождения СССР.", "pages": [107]}, {"text": "Уровень 70% принят условием примера, а не общим законом. Числовые результаты табл. 23 в выданных единицах отсутствуют.", "pages": [107]}]}], "deeper": [], "glossary": [{"term": "остаточная (связанная) водонасыщенность kв.св", "definition": "Доля объёма пор, занятая водой, которая остаётся в породе и не вытесняется; на рис. 77 убывает с ростом пористости."}, {"term": "критическая пористость kп*", "definition": "Пороговое значение пористости, по которому выделяют межзерновые карбонатные коллекторы; оценивается по зависимости kв.св от kп и меняется в широких пределах."}], "format": "интерактив", "tasks": [{"id": "latyshova.kp_star_graph.t1", "type": "single", "step_id": "latyshova.kp_star_graph", "claim_ids": ["latyshova.kp_star_graph#c12", "latyshova.kp_star_graph#c13"], "prompt": "Для одного типа межзернового карбонатного коллектора по графику kв.св = f(kп) найдено kп*. Можно ли использовать это значение для коллектора другого типа?", "options": [{"id": "a", "text": "Можно, потому что kп* — константа для всех карбонатов", "misconception": "misc.kp_star_constant"}, {"id": "b", "text": "Можно, если оба коллектора карбонатные и находятся в одной стране", "misconception": "misc.region_equals_type"}, {"id": "c", "text": "Нельзя, так как у каждого типа своя структура пор и свой kп*", "misconception": null}, {"id": "d", "text": "Нельзя, так как kп* определяют только по глинистости", "misconception": "misc.kp_star_clay"}], "answer": "c", "tolerance": null, "unit": null, "explanation": "kп* сильно зависит от структуры порового пространства и меняется в широких пределах.", "kind": "understanding"}, {"id": "latyshova.kp_star_graph.t2", "type": "order", "step_id": "latyshova.kp_star_graph", "claim_ids": ["latyshova.kp_star_graph#c11", "latyshova.kp_star_graph#c15", "latyshova.kp_star_graph#c17"], "prompt": "Расставьте действия при определении критической пористости kп* по графику остаточной воды (условие примера 55).", "options": [{"id": "a", "text": "Найти на кривой пористость, при которой kв.св = 70%", "misconception": null}, {"id": "b", "text": "Принять снятое значение за kп*", "misconception": null}, {"id": "c", "text": "Взять график kв.св = f(kп) для нужного типа коллектора", "misconception": null}, {"id": "d", "text": "Использовать kп* при выделении коллекторов по методам пористости", "misconception": null}], "answer": ["c", "a", "b", "d"], "tolerance": null, "unit": null, "explanation": "Сначала выбирают кривую своего типа, затем снимают kп при 70%, принимают его за kп* и применяют.", "kind": "recall"}], "pictures": [{"id": "latyshova.kp_star_graph.i1", "step_id": "latyshova.kp_star_graph", "node_id": "latyshova.kp_star_graph", "file": "pictures/kp_star_graph_1.svg", "frame_class": "A", "origin": "code_from_model", "label": "симуляция", "caption": "Остаточная вода убывает с ростом пористости, у каждого типа коллектора своя кривая; kп* снимают там, где kв.св = 70%.", "alt": "График: три убывающие кривые остаточной водонасыщенности от пористости для разных карбонатных коллекторов; отмечена точка, где остаточная вода равна 70% и берётся критическая пористость.", "source": "построено кодом по утверждениям главы, стр. 107", "claim_ids": ["latyshova.kp_star_graph#c1", "latyshova.kp_star_graph#c2", "latyshova.kp_star_graph#c4", "latyshova.kp_star_graph#c5", "latyshova.kp_star_graph#c7", "latyshova.kp_star_graph#c17"], "prompt": null}]}, {"title": "Значения kп* для разных карбонатов и последствия неверного выбора порога", "short_title": "Таблица kп* и ошибки порога", "why_here": {"text": "Обобщает результаты примера 55; показывает, как ошибка порога искажает эффективную толщину.", "by_model": true}, "difficulty": {"primary": "Н", "secondary": "Пр"}, "threshold": false, "pages": [107, 108], "misconception": null, "data_meaning": {"from_chapter": {"text": "Вход — тип карбонатного межзернового коллектора. По таблице 23 из него получают kп* в процентах. Выход — эффективная толщина, определяемая с этим порогом. В таблице два столбца: коллектор и kп*, %.", "by_model": true}, "breaks": {"text": "Порог ломается, если взять kп* от отложений другого типа: тогда эффективная толщина определяется с серьёзными погрешностями. Таблица 23 охватывает только карбонатные межзерновые коллекторы.", "by_model": true}, "hypotheses": [{"text": "Если для разреза нет аналога в таблице 23, kп* придётся устанавливать отдельно, например по связи остаточной воды и пористости (см. шаг kp_star_graph).", "by_model": true, "hypothesis": true}, {"text": "Заниженный порог, скорее всего, завышает эффективную толщину, а завышенный — занижает. В главе направление ошибки не указано.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Порог в классификаторе: значение, подобранное на одной выборке, нельзя без проверки переносить на другую, иначе число ошибок резко растёт.", "breaks_where": "kп* — физическая величина, связанная со строением пор породы, а не параметр, подбираемый по метрике качества. Для нового типа отложений его нельзя просто перенастроить на данных.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["Тип карбонатного межзернового коллектора (размер зёрен и пор, регион, возраст)", "Пористость пласта kп по диаграммам комплекса"], "rule": "Выбрать kп* из таблицы 23 по типу коллектора (для большинства межзерновых карбонатных коллекторов типично 6–8 %) и применять его как порог выделения коллектора. Это следует из определения kп* как критической пористости; направление сравнения в этой части главы не описано.", "conclusion": "Эффективная толщина карбонатного разреза определяется надёжно, если порог соответствует изучаемым отложениям.", "counterexample": "Для мелоподобных известняков kп* равна 13 %, а для рифтовых отложений 1 %. Типичные 6–8 % для них не подходят и дадут серьёзные погрешности в эффективной толщине."}, "worked_examples": [], "book_tasks": [{"number": "104", "page_pdf": 108, "text": "Выделить коллекторы с межзерновой пористостью по диаграммам комплекса методов, приведенным на рис. 63.", "figure": "рис. 63 (страница в этой части главы не указана)"}, {"number": "105", "page_pdf": 108, "text": "Дать заключение об эффективной толщине коллекторов, выделяемых на основании комплекса диаграмм, приведенных на рис. 63, 58. Оценить характер насыщения этих коллекторов.", "figure": "рис. 63, 58 (страницы в этой части главы не указаны)"}, {"number": "106", "page_pdf": 108, "text": "Дать заключение о наличии карбонатных коллекторов в разрезах скважин, приведенных на диаграммах рис. 14, 53, 68.", "figure": "рис. 14, 53, 68 (страницы в этой части главы не указаны)"}, {"number": "107", "page_pdf": 108, "text": "На основании диаграмм, приведенных на рис. 76, определить эффективную толщину коллекторов в карбонатном разрезе.", "figure": "рис. 76 (страница в этой части главы не указана)"}, {"number": "108", "page_pdf": 108, "text": "Дать заключение, в каком диапазоне меняется нижний предел пористости карбонатных коллекторов, рассмотренных в задачах 104-107. Сравнить полученные результаты с данными табл. 23.", "figure": null}], "terms_introduced": [], "links": [{"type": "prerequisite", "target": "latyshova.kp_star_graph"}, {"type": "prerequisite", "target": "latyshova.example_54"}, {"type": "prerequisite", "target": "latyshova.normalization_overlay"}, {"type": "prerequisite", "target": "latyshova.carbonate_features"}, {"type": "prerequisite", "target": "latyshova.effective_thickness_basic"}], "needs_scan": [], "claims": [{"page_print": null, "text": "По данным таблицы 23 граничное значение kп* растёт при переходе от крупнозернистых коллекторов с большими порами к тонкозернистым с малыми порами.", "kind": "inference", "page_pdf": 107, "unit_id": "p107.14", "quote": "граничное значение \\( k_n^* \\) растет при переходе от крупнозернистых коллекторов с большими порами к тонкозернистым с малыми порами.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c1"}, {"page_print": null, "text": "Типичное значение kп* заключено в пределах 6–8 %.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.14", "quote": "типичное значение \\( k_n^* \\) заключено в пределах 6-8 %.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c2"}, {"page_print": null, "text": "Это типичное значение относится к большинству межзерновых карбонатных коллекторов, характерных для крупнейших нефтяных и газовых месторождений СССР.", "kind": "observation", "page_pdf": 107, "unit_id": "p107.14", "quote": "Для большинства межзерновых карбонатных коллекторов, характерных для крупнейших нефтяных и газовых месторождений СССР", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c3"}, {"page_print": null, "text": "Правильный выбор kп* обеспечивает надёжное определение эффективной толщины в карбонатном разрезе.", "kind": "inference", "page_pdf": 108, "unit_id": "p108.01", "quote": "правильный выбор $k_n^*$ обеспечивает надежное определение $h_{\\text{эф}}$ в карбонатном разрезе", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c4"}, {"page_print": null, "text": "Использование kп*, не соответствующего изучаемым отложениям, приводит к серьёзным погрешностям в установлении эффективной толщины.", "kind": "inference", "page_pdf": 108, "unit_id": "p108.01", "quote": "использование значения $k_n^*$, не соответствующего изучаемым отложениям, приводит к серьезным погрешностям в установлении $h_{\\text{эф}}$", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c5"}, {"page_print": null, "text": "Способы нормализации для выделения продуктивных межзерновых коллекторов и критический kп* для выделения коллекторов эффективны не только в карбонатном, но и в низкопористом слабоглинистом терригенном разрезе.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.02", "quote": "эффективны не только в карбонатном, но и в низкопористом слабоглинистом терригенном разрезе.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c6"}, {"page_print": null, "text": "Таблица 23 содержит значения kп* для карбонатных межзерновых коллекторов.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.04", "quote": "Значения $k_n^*$ для карбонатных межзерновых коллекторов.", "source_kind": "figure_caption", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c7"}, {"page_print": null, "text": "Для рифтовых отложений (Башкирия, пермь) в таблице 23 указано значение 1 %.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.05", "quote": "Рифтовые отложения (Башкирия, пермь) | 1", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c8"}, {"page_print": null, "text": "Для крупнозернистых известняков (Башкирия, карбон) в таблице 23 указано значение 3 %.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.05", "quote": "Крупнозернистые известняки (Башкирия, Карбон) | 3", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c9"}, {"page_print": null, "text": "Для крупнозернистых доломитов (Белоруссия, девон) в таблице 23 указано значение 3 %.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.05", "quote": "Крупнозернистые доломиты (Белоруссия, девон) | 3", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c10"}, {"page_print": null, "text": "Для коллекторов Оренбургского газового месторождения (пермь) в таблице 23 указано значение 7 %.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.05", "quote": "Коллекторы Оренбургского газового месторождения (пермь) | 7", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c11"}, {"page_print": null, "text": "Для мелоподобных известняков (АССР, верхний мел) в таблице 23 указано значение 13 %.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.05", "quote": "Мелоподобные известняки (АССР, верхний мел) | 13", "source_kind": "table", "by_model": false, "needs_scan": false, "id": "latyshova.kp_star_table#c12"}], "id": "latyshova.kp_star_table", "order": 41, "minutes": 2, "essence": "Граничная пористость kп* — порог, по которому пласт относят к коллекторам. Она растёт от крупнозернистых коллекторов с крупными порами к тонкозернистым с мелкими. Если взять kп*, не подходящий к отложениям, эффективная толщина определяется с серьёзными погрешностями.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Порог kп* зависит от строения порового пространства. У крупнозернистых пород с большими порами он низкий: в таблице 23 это 1–3 %. У тонкозернистых пород с малыми порами он выше: у мелоподобных известняков 13 %.", "pages": [107]}, {"text": "Для большинства межзерновых карбонатных коллекторов крупнейших месторождений СССР типичное значение 6–8 %. Эффективная толщина считается по этому порогу, поэтому ошибка порога переходит в ошибку толщины.", "pages": [107]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "Порог берут из таблицы 23 по типу коллектора, а не одно значение на все разрезы. Нормализация (наложение диаграмм) вместе с критическим kп* работает и в низкопористом слабоглинистом терригенном разрезе. В конце параграфа даны задачи 104–108.", "pages": [108]}, {"text": "В них нужно выделить коллекторы, оценить эффективную толщину и насыщение, а затем найти диапазон нижнего предела пористости и сравнить его с таблицей 23.", "pages": [107, 108]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Таблица 23 даёт значения только для карбонатных межзерновых коллекторов. Значения сильно различаются: от 1 до 13 %. Значение 7 % для Оренбургского месторождения попадает в диапазон 6–8 %, а 13 % у мелоподобных известняков выходит за него.", "pages": [107, 108]}, {"text": "Поэтому «типичное» значение нельзя применять ко всем разрезам без проверки. В главе не сказано, как именно ошибка порога меняет толщину: сообщается лишь, что погрешности серьёзны.", "pages": [108]}]}], "deeper": [], "glossary": [], "format": "карточки", "tasks": [{"id": "latyshova.kp_star_table.t1", "type": "single", "step_id": "latyshova.kp_star_table", "claim_ids": ["latyshova.kp_star_table#c4", "latyshova.kp_star_table#c5"], "prompt": "Для разреза мелоподобных известняков взяли типичный порог граничной пористости 6–8 %, подходящий для большинства межзерновых карбонатных коллекторов. Что произойдёт с оценкой эффективной толщины?", "options": [{"id": "a", "text": "Она получится с серьёзной погрешностью, потому что порог не соответствует отложениям", "misconception": null}, {"id": "b", "text": "Она не изменится, поскольку порог влияет только на оценку проницаемости", "misconception": "misc.threshold_irrelevant"}, {"id": "c", "text": "Она будет надёжной, так как 6–8 % подходит для любых карбонатов", "misconception": "misc.universal_threshold"}, {"id": "d", "text": "Она будет верной, если дополнительно наложить диаграммы", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Эффективная толщина считается по порогу kп*, поэтому неподходящий порог напрямую искажает её.", "kind": "understanding"}, {"id": "latyshova.kp_star_table.t2", "type": "calc", "step_id": "latyshova.kp_star_table", "claim_ids": ["latyshova.kp_star_table#c8", "latyshova.kp_star_table#c12"], "prompt": "По таблице 23 для рифтовых отложений (Башкирия, пермь) kп* = 1 %, а для мелоподобных известняков (верхний мел) kп* = 13 %. На сколько процентных пунктов отличаются эти пороги?", "options": [], "answer": 12, "tolerance": 0, "unit": "п.п.", "explanation": "Разность значений 13 % и 1 % составляет 12 процентных пунктов.", "kind": "data"}], "pictures": [{"id": "latyshova.kp_star_table.i1", "step_id": "latyshova.kp_star_table", "node_id": "latyshova.kp_star_table", "file": "pictures/kp_star_table_1.svg", "frame_class": "A", "origin": "code_from_data", "label": "схема", "caption": "Граничная пористость kп* для разных коллекторов: от крупнозернистых к тонкозернистым порог растёт.", "alt": "Столбчатая диаграмма граничной пористости: рифтовые отложения 1 процент, крупнозернистые известняки и доломиты по 3, Оренбургское месторождение 7, мелоподобные известняки 13 процентов.", "source": "построено кодом по утверждениям главы, стр. 108", "claim_ids": ["latyshova.kp_star_table#c8", "latyshova.kp_star_table#c9", "latyshova.kp_star_table#c10", "latyshova.kp_star_table#c11", "latyshova.kp_star_table#c12"], "prompt": null}]}, {"title": "Сложные коллекторы: что их отличает от межзерновых", "short_title": "Что такое сложный коллектор", "why_here": {"text": "Переход от простых коллекторов к тем, у которых признаки межзернового коллектора не работают.", "by_model": true}, "difficulty": {"primary": "Р", "secondary": "П"}, "threshold": false, "pages": [108], "misconception": {"ref": "misc.reservoir_void", "text": "Пласт — не пустота: даже сложный коллектор остаётся породой. В нём есть межзерновые поры, а также трещины и каверны, но скелет породы сохраняется.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Глава говорит только, что сложные коллекторы не выделяются по признакам межзернового коллектора. Данные, кривые и столбцы в этой части главы не названы.", "by_model": false}, "breaks": {"text": "Признаки межзернового коллектора не работают для сложных коллекторов: те не выделяются по ним в разрезе.", "by_model": false}, "hypotheses": []}, "it_analogy": {"text": "Это как система, где проверки написаны под один формат данных: входы другого формата не проходят проверку и не распознаются.", "breaks_where": "У коллектора нет формата, заданного заранее: сложное строение пустот и состав скелета меняют саму породу, а не её запись.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["сложный коллектор", "трещины и каверны"], "links": [{"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.direct_signs_of_collector"}, {"type": "refutes_misconception", "target": "misc.reservoir_void"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Сложными называют коллекторы, которые не выделяются в разрезах скважин по признакам, соответствующим межзерновым коллекторам.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.13", "quote": "К сложным относят коллекторы, которые не выделяются в разрезах скважин по признакам, соответствующим межзерновым коллекторам.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.complex_collectors#c1"}, {"page_print": null, "text": "Для сложных коллекторов характерно сложное строение порового пространства.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.13", "quote": "Для них характерны: сложное строение порового пространства, наличие, кроме межзерновых пор, трещин и каверн.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.complex_collectors#c2"}, {"page_print": null, "text": "Кроме межзерновых пор, в сложных коллекторах есть трещины и каверны.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.13", "quote": "наличие, кроме межзерновых пор, трещин и каверн.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.complex_collectors#c3"}, {"page_print": null, "text": "К сложным относят также коллекторы со сложным минеральным составом скелета.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.13", "quote": "К сложным относят также коллекторы со сложным минеральным составом скелета.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.complex_collectors#c4"}, {"page_print": null, "text": "Существует множество классов сложных коллекторов: карбонатные, терригенные, эффузивные, смешанного состава.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.14", "quote": "Существует множество классов сложных коллекторов - карбонатные, терригенные, эффузивные, смешанного состава.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.complex_collectors#c5"}, {"page_print": null, "text": "Автор рассмотрит наиболее типичные классы, играющие важную роль в нефтяной и газовой промышленности.", "kind": "assumption", "page_pdf": 108, "unit_id": "p108.14", "quote": "Рассмотрим наиболее типичные, играющие важную роль в нефтяной и газовой промышленности.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.complex_collectors#c6"}], "id": "latyshova.complex_collectors", "order": 42, "minutes": 2, "essence": "Сложным называют коллектор, который нельзя выделить в разрезе скважины по признакам межзернового коллектора. Его отличают сложное строение пустот и сложный минеральный состав скелета. Классов таких коллекторов много, и книга разбирает самые типичные для нефтегазовой отрасли.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Признаки межзернового коллектора опираются на то, что флюид заполняет поры между зёрнами. У сложного коллектора, кроме межзерновых пор, есть трещины и каверны. Каверны — полости в породе, трещины — узкие разломы.", "pages": [108]}, {"text": "Из-за такого строения привычные признаки перестают работать, и коллектор не выделяется. Сложный минеральный состав скелета, то есть твёрдой основы породы, тоже относит коллектор к сложным.", "pages": [108]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "В этом фрагменте нет порядка действий. Он задаёт только критерий отнесения: если коллектор нельзя выделить по признакам межзернового, его считают сложным. Дальше книга обещает рассмотреть наиболее типичные классы.", "pages": [108]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Сложными называют два случая: сложное строение порового пространства и сложный минеральный состав скелета. Классов много: карбонатные, терригенные, эффузивные, смешанного состава. Эффузивные — коллекторы в породах вулканического излияния.", "pages": [108]}, {"text": "Книга рассматривает только типичные классы, которые важны для нефтяной и газовой промышленности.", "pages": [108]}]}], "deeper": [], "glossary": [{"term": "сложный коллектор", "definition": "Коллектор, который не выделяется в разрезах скважин по признакам межзернового коллектора. Он имеет сложное строение порового пространства или сложный минеральный состав скелета."}, {"term": "трещины и каверны", "definition": "Пустоты в породе помимо межзерновых пор: трещины — узкие разломы, каверны — полости. Их наличие отличает сложные коллекторы от межзерновых."}], "format": "карточки", "tasks": [{"id": "latyshova.complex_collectors.t1", "type": "multiple", "step_id": "latyshova.complex_collectors", "claim_ids": ["latyshova.complex_collectors#c1", "latyshova.complex_collectors#c2", "latyshova.complex_collectors#c3", "latyshova.complex_collectors#c4"], "prompt": "Какие особенности отличают сложные коллекторы от межзерновых? Выберите все верные.", "options": [{"id": "a", "text": "Сложное строение порового пространства", "misconception": null}, {"id": "b", "text": "Наличие трещин и каверн помимо межзерновых пор", "misconception": null}, {"id": "c", "text": "Сложный минеральный состав скелета", "misconception": null}, {"id": "d", "text": "Отсутствие твёрдого скелета: пласт представляет собой пустоту", "misconception": "misc.reservoir_void"}], "answer": ["a", "b", "c"], "tolerance": null, "unit": null, "explanation": "Сложными называют коллекторы со сложным строением пустот (трещины, каверны) и сложным составом скелета, но скелет породы сохраняется.", "kind": "recall"}], "pictures": [{"id": "latyshova.complex_collectors.i1", "step_id": "latyshova.complex_collectors", "node_id": "latyshova.complex_collectors", "file": "pictures/complex_collectors_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Две особенности сложного коллектора и общий итог: привычные признаки не позволяют его выделить.", "alt": "Схема: сложное строение пор с трещинами и кавернами и сложный минеральный состав скелета ведут к тому, что коллектор не выделяется по признакам межзернового коллектора.", "source": "построено кодом по утверждениям главы, стр. 108", "claim_ids": ["latyshova.complex_collectors#c1", "latyshova.complex_collectors#c2", "latyshova.complex_collectors#c3", "latyshova.complex_collectors#c4"], "prompt": null}]}, {"title": "Трещинный коллектор: плотные блоки, малая ёмкость трещин и высокая проницаемость", "short_title": "Устройство трещинного коллектора", "why_here": {"text": "Показывает, как малая пористость сочетается с высокой проницаемостью.", "by_model": true}, "difficulty": {"primary": "П", "secondary": "М"}, "threshold": true, "pages": [108], "misconception": {"ref": "misc.porosity_eq_perm", "text": "Шаг исправляет представление, что пористость и проницаемость — одно и то же. В трещинном коллекторе ёмкость трещин не больше 1%, а проницаемость может достигать сотен микрометров в квадрате.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Из этих страниц следуют только числовые ориентиры: межзерновая пористость блоков меньше 5–10%, kп,т обычно меньше 0,5%, раскрытость значительная — более 100 мкм. Столбцы и кривые на этих страницах не описаны.", "by_model": false}, "breaks": {"text": "Малая пористость сама по себе не значит «неколлектор»: трещинный коллектор при ней может быть высокопродуктивным. Других ограничений в главе здесь не указано.", "by_model": true}, "hypotheses": []}, "it_analogy": {"text": "Это как сеть с большой пропускной способностью, но почти без хранилища. Блоки — диски без доступа извне, трещины — магистральные каналы. Данных в каналах мало, но трафик через них идёт огромный.", "breaks_where": "У канала пропускная способность не растёт так резко от ширины, а раскрытость трещин определяет проницаемость очень сильно. К тому же в блоках флюида нет, а в диске данные есть.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": null, "worked_examples": [], "book_tasks": [], "terms_introduced": ["матрица (блоки)", "коэффициент трещиноватости kп,т", "раскрытость трещин"], "links": [{"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "refutes_misconception", "target": "misc.porosity_eq_perm"}], "needs_scan": [], "claims": [{"page_print": null, "text": "Трещинный коллектор наиболее типичен для карбонатных и гидрохимических отложений.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.16", "quote": "Наиболее типичен для карбонатных и гидрохимических отложений", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c1"}, {"page_print": null, "text": "Трещинный коллектор встречается также в вулканогенных, вулканогенно-обломочных и терригенных породах.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.16", "quote": "однако встречается также в вулканогенных, вулканогенно-обломочных и терригенных породах.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c2"}, {"page_print": null, "text": "Трещинный коллектор обычно приурочен к низкопористым, плотным породам.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.17", "quote": "Трещинный коллектор приурочен обычно к низкопористым, плотным породам.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c3"}, {"page_print": null, "text": "Коллектор состоит из блоков (матрицы) с низкой межзерновой пористостью (меньше 5–10%) и нулевой эффективной пористостью.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.17", "quote": "Он состоит из блоков (матрицы) с низкой межзерновой ($k_{n,мз} < 5-10\\%$) и нулевой эффективной ($k_{n,эф,мз} = 0$) пористостью", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c4"}, {"page_print": null, "text": "Блоки разделены трещинами значительной протяжённости, образующими одну, две и более систем с определённой ориентацией.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.17", "quote": "разделенных трещинами значительной протяженности, образующих одну, две и более системы с определенной ориентацией.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c5"}, {"page_print": null, "text": "Ёмкость трещин невелика и характеризуется коэффициентом трещиноватости kп,т, обычно меньше 0,5%, редко достигая 1%.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.17", "quote": "Емкость трещин невелика, характеризуется коэффициентом трещиноватости $k_{n,т}$, обычно $k_{n,т} < 0,5\\%$, редко достигая 1%.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c6"}, {"page_print": null, "text": "Трещины — идеальные пути фильтрации флюидов, они обеспечивают высокую проницаемость трещинного коллектора.", "kind": "inference", "page_pdf": 108, "unit_id": "p108.17", "quote": "В то же время трещины -идеальные пути фильтрации флюидов, которые обеспечивают высокую проницаемость трещинного коллектора.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c7"}, {"page_print": null, "text": "При нулевой проницаемости блоков коэффициент проницаемости трещинного коллектора составляет от долей до сотен микрометров в квадрате, нередко обеспечивая гигантскую продуктивность скважины.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.17", "quote": "трещинный коллектор имеет коэффициент проницаемости $k_{n,т}$ от долей до сотен микрометров в квадрате, обеспечивая нередко гигантскую продуктивность скважины.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c8"}, {"page_print": null, "text": "Проницаемость по трещинам тем больше, чем больше густота и, главное, раскрытость трещин.", "kind": "inference", "page_pdf": 108, "unit_id": "p108.17", "quote": "Величина $k_{n,т}$ тем больше, чем больше густота и, главное, раскрытость трещин.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c9"}, {"page_print": null, "text": "Раскрытость трещин играет основную роль среди факторов проницаемости.", "kind": "inference", "page_pdf": 108, "unit_id": "p108.17", "quote": "Последний фактор играет основную роль", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c10"}, {"page_print": null, "text": "Одна трещина значительной раскрытости (более 100 мкм) обеспечивает дебит нефти более 100 г/сут (единица как в тексте).", "kind": "observation", "page_pdf": 108, "unit_id": "p108.17", "quote": "одна трещина значительной раскрытости (более 100 мкм) обеспечивает дебит нефти более 100г/сут.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_matrix#c11"}], "id": "latyshova.fracture_matrix", "order": 43, "minutes": 2, "essence": "Трещинный коллектор состоит из плотных блоков (матрицы), разделённых трещинами. Ёмкость трещин мала: коэффициент трещиноватости обычно меньше 0,5%. Но трещины — идеальные пути фильтрации, поэтому проницаемость высока, от долей до сотен микрометров в квадрате. Поэтому малая пористость не мешает гигантской продуктивности скважины.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "Порода состоит из блоков с низкой межзерновой пористостью, меньше 5–10%. Эффективная пористость блоков, то есть доля пор, по которым течёт флюид, равна нулю. Блоки разделены протяжёнными трещинами.", "pages": [108]}, {"text": "Они образуют одну, две или больше систем с определённой ориентацией. Матрица (блоки) — это плотные участки породы между трещинами. Ёмкость трещин характеризуется коэффициентом трещиноватости kп,т.", "pages": [108]}, {"text": "Он обычно меньше 0,5% и редко достигает 1%. Флюид движется по трещинам, а не по порам блоков. Поэтому проницаемость определяется трещинами, а ёмкость остаётся малой.", "pages": [108]}, {"text": "Проницаемость растёт с густотой трещин и особенно с их раскрытостью. Раскрытость трещины — это размер её раскрытия, ширина щели. Она играет основную роль.", "pages": [108]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "В главе на этих страницах нет процедуры выделения трещинного коллектора по диаграммам. Есть только описание его устройства и количественные ориентиры по пористости, проницаемости и раскрытости.", "pages": [108]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Трещинный коллектор наиболее типичен для карбонатных и гидрохимических отложений. Он встречается также в вулканогенных, вулканогенно-обломочных и терригенных породах. Обычно он приурочен к низкопористым плотным породам.", "pages": [108]}, {"text": "Проницаемость трещинного коллектора может быть гигантской при малой ёмкости. Одна трещина раскрытостью более 100 мкм даёт дебит нефти более 100 г/сут, как сказано в тексте. Единица измерения дебита в тексте указана именно так.", "pages": [108]}]}], "deeper": [{"text": "В тексте проницаемость трещинного коллектора обозначена тем же символом kп,т, что и коэффициент трещиноватости. Для блоков написано «нулевая проницаемость (kп,мз = 0)», хотя kп,мз — это обозначение межзерновой пористости. Это неточности обозначений в источнике. Диапазон проницаемости от долей до сотен микрометров в квадрате дан без привязки к конкретному разрезу.", "pages": [108]}], "glossary": [{"term": "матрица (блоки)", "definition": "Плотные участки породы между трещинами. Межзерновая пористость блоков низкая (меньше 5–10%), эффективная пористость равна нулю."}, {"term": "коэффициент трещиноватости kп,т", "definition": "Показатель ёмкости трещин. Обычно меньше 0,5%, редко достигает 1%."}, {"term": "раскрытость трещин", "definition": "Размер раскрытия трещины, то есть ширина щели. Это главный фактор проницаемости: трещина более 100 мкм даёт дебит нефти более 100 г/сут."}], "format": "интерактив", "tasks": [{"id": "latyshova.fracture_matrix.t1", "type": "gap", "step_id": "latyshova.fracture_matrix", "claim_ids": ["latyshova.fracture_matrix#c6", "latyshova.fracture_matrix#c7"], "prompt": "Ёмкость трещин в трещинном коллекторе {{1}} (коэффициент трещиноватости обычно меньше 0,5 %), а проницаемость {{2}}, так как трещины служат идеальными путями фильтрации.", "options": [], "answer": ["мала", "высока"], "tolerance": null, "unit": null, "explanation": "Трещины занимают малый объём, но по ним флюид фильтруется легко.", "kind": "recall"}, {"id": "latyshova.fracture_matrix.t2", "type": "single", "step_id": "latyshova.fracture_matrix", "claim_ids": ["latyshova.fracture_matrix#c4", "latyshova.fracture_matrix#c8", "latyshova.fracture_matrix#c10"], "prompt": "Скважина вскрыла плотную карбонатную породу с межзерновой пористостью блоков около 3 % и дала очень высокий дебит. Как это объяснить?", "options": [{"id": "a", "text": "Блоки хорошо проницаемы, потому что пористость 3 % уже достаточна для фильтрации", "misconception": "misc.porosity_eq_perm"}, {"id": "b", "text": "Флюид идёт по раскрытым трещинам, а блоки в фильтрации не участвуют", "misconception": null}, {"id": "c", "text": "Высокий дебит возможен только при пористости выше 10 %", "misconception": "misc.porosity_eq_perm"}, {"id": "d", "text": "Дебит определяется суммарной ёмкостью трещин, а не их раскрытостью", "misconception": null}], "answer": "b", "tolerance": null, "unit": null, "explanation": "Эффективная пористость блоков равна нулю, а проницаемость обеспечивают трещины, прежде всего их раскрытость.", "kind": "transfer"}], "pictures": [{"id": "latyshova.fracture_matrix.i1", "step_id": "latyshova.fracture_matrix", "node_id": "latyshova.fracture_matrix", "file": "pictures/fracture_matrix_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Плотные блоки матрицы разделены трещинами: флюид идёт по трещинам, а не по порам блоков.", "alt": "Увеличенный срез плотной породы, разделённой трещинами на блоки. Трещины заполнены нефтью, а сами блоки плотные.", "source": "построено кодом по утверждениям главы, стр. 108", "claim_ids": ["latyshova.fracture_matrix#c4", "latyshova.fracture_matrix#c5", "latyshova.fracture_matrix#c7"], "prompt": null}]}, {"title": "Как обнаруживают трещинный коллектор: ГТИ и ограничения стандартного комплекса ГИС", "short_title": "Обнаружение трещинного коллектора", "why_here": {"text": "Опирается на признаки межзернового коллектора, которые здесь не работают.", "by_model": true}, "difficulty": {"primary": "Р", "secondary": "Н"}, "threshold": false, "pages": [108], "misconception": {"ref": null, "text": "Если признаки межзернового коллектора на диаграммах ГИС не видны, то коллектора нет. Для трещинного коллектора эти признаки не характерны, поэтому стандартный комплекс его не обнаруживает.", "by_model": true}, "data_meaning": {"from_chapter": {"text": "Входы: данные ГТИ при бурении (поглощение промывочной жидкости, продолжительность проходки) и диаграммы ГИС карбонатного разреза (методы пористости, кавернограмма или профилеграмма, разноглубинные зонды, СП, ГМ). Выход: отметка зоны трещиноватости. Для зоны трещиноватости в карбонатном разрезе: низкие kп, номинальный или слегка увеличенный диаметр, высокие показания зондов без радиального градиента, низкие СП и ГМ.", "by_model": false}, "breaks": {"text": "Признаки межзернового коллектора, используемые при выделении его по ГИС, для трещинного не характерны. Поэтому стандартный комплекс ГИС его не обнаруживает. Изменение показаний во времени иногда наблюдается, но в целом не характерно.", "by_model": false}, "hypotheses": [{"text": "Набор из низкой пористости и высоких показаний зондов похож на плотную непроницаемую породу, поэтому по одной диаграмме зону трещиноватости легко принять за неколлектор.", "by_model": true, "hypothesis": true}]}, "it_analogy": {"text": "Это как мониторинг сервиса, который ловит только отказы с ошибками в логах. Утечка без ошибок остаётся невидимой, пока не посмотришь метрики самой работы, например поглощение жидкости при бурении.", "breaks_where": "У сервиса можно добавить недостающую метрику после запуска. В скважине поглощение и скорость проходки фиксируются только во время бурения, и вернуться к ним потом нельзя.", "by_model": true}, "now_practice": null, "inefficiency_lens": null, "decision_on_data": {"features": ["аномалии поглощения промывочной жидкости при бурении", "снижение продолжительности проходки", "низкие kп по методам пористости", "номинальный или незначительно увеличенный диаметр скважины", "высокие показания разноглубинных зондов без радиального градиента", "низкие показания СП и ГМ"], "rule": "Зоны трещиноватости отмечают аномалиями поглощения жидкости и снижением продолжительности проходки (ГТИ). В карбонатном разрезе им соответствует перечисленный набор показаний ГИС.", "conclusion": "Трещинный коллектор нельзя выделять по признакам межзернового коллектора. Нужны данные ГТИ при бурении и особый набор признаков на диаграммах.", "counterexample": "В главе контрпример не приведён."}, "worked_examples": [], "book_tasks": [], "terms_introduced": ["геолого-технологические исследования (ГТИ)", "профилеграмма"], "links": [{"type": "prerequisite", "target": "latyshova.section_and_collector_types"}, {"type": "prerequisite", "target": "latyshova.direct_signs_of_collector"}, {"type": "prerequisite", "target": "latyshova.radial_gradient_and_dynamic"}, {"type": "prerequisite", "target": "latyshova.complex_collectors"}, {"type": "prerequisite", "target": "latyshova.fracture_matrix"}], "needs_scan": [], "claims": [{"page_print": null, "text": "ГТИ — комплекс геолого-технологических исследований, которые ведутся при проходке скважины, в процессе бурения.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.18", "quote": "При проходке скважины методы, входящие в комплекс геолого-технологических исследований в процессе бурения (ГТИ)", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c1"}, {"page_print": null, "text": "В комплекс ГТИ входят фильтрационный и детальный механический методы.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.18", "quote": "фильтрационный и детальный механический методы", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c2"}, {"page_print": null, "text": "Методы ГТИ отмечают зоны трещиноватости аномалиями поглощения промывочной жидкости.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.18", "quote": "отмечают зоны трещиноватости аномалиями поглощения промывочной жидкости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c3"}, {"page_print": null, "text": "Методы ГТИ отмечают зоны трещиноватости также снижением продолжительности проходки.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.18", "quote": "и снижением продолжительности проходки.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c4"}, {"page_print": null, "text": "Стандартный комплекс ГИС не позволяет обнаружить трещинный коллектор.", "kind": "inference", "page_pdf": 108, "unit_id": "p108.19", "quote": "Стандартный комплекс ГИС не позволяет обнаружить трещинный коллектор", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c5"}, {"page_print": null, "text": "Причина: признаки межзернового коллектора, используемые при выделении его по ГИС, не характерны для трещинного коллектора.", "kind": "inference", "page_pdf": 108, "unit_id": "p108.19", "quote": "поскольку признаки межзернового коллектора, используемые при выделении его по материалам ГИС, не характерны для коллектора трещинного", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c6"}, {"page_print": null, "text": "Трещинный коллектор был впервые обнаружен и исследован в карбонатном разрезе.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.19", "quote": "в карбонатном разрезе, где этот тип коллектора был впервые обнаружен и исследован", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c7"}, {"page_print": null, "text": "В карбонатном разрезе зонам трещиноватости соответствуют низкие значения kп на диаграммах методов пористости.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.19", "quote": "зонам трещиноватости соответствуют низкие значения $k_n$ на диаграммах методов пористости", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c8"}, {"page_print": null, "text": "Зонам трещиноватости соответствует номинальный или незначительно увеличенный диаметр скважины на кавернограмме или профилеграмме.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.19", "quote": "номинальный или незначительно увеличенный диаметр скважины на кавернограмме или профилеграмме", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c9"}, {"page_print": null, "text": "Зонам трещиноватости соответствуют высокие показания разноглубинных зондов при отсутствии признаков радиального градиента сопротивления.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.19", "quote": "высокие показания на диаграммах разноглубинных зондов при отсутствии признаков радиального градиента сопротивления", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c10"}, {"page_print": null, "text": "Зонам трещиноватости соответствуют низкие показания на диаграммах СП и ГМ.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.19", "quote": "низкие показания на диаграммах СП и ГМ", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c11"}, {"page_print": null, "text": "Изменение показаний разных методов во времени в трещинном коллекторе иногда наблюдается, но в целом не характерно.", "kind": "observation", "page_pdf": 108, "unit_id": "p108.19", "quote": "Изменение показаний на диаграммах разных методов во времени в трещинном коллекторе иногда наблюдается, но в целом не является характерным.", "source_kind": "text", "by_model": false, "needs_scan": false, "id": "latyshova.fracture_detection#c12"}], "id": "latyshova.fracture_detection", "order": 44, "minutes": 3, "essence": "Стандартный комплекс ГИС не позволяет обнаружить трещинный коллектор. Признаки межзернового коллектора, на которых он построен, для трещинного не характерны. Зоны трещиноватости отмечают методы ГТИ во время бурения: по поглощению промывочной жидкости и по снижению продолжительности проходки.", "how": [{"title": "Механизм", "by_model": true, "paragraphs": [{"text": "ГТИ — геолого-технологические исследования в процессе бурения. Они ведутся во время проходки скважины, а не после неё. В их комплекс входят фильтрационный и детальный механический методы.", "pages": [108]}, {"text": "Фильтрационный метод фиксирует аномалии поглощения промывочной жидкости: жидкость уходит в породу. Детальный механический метод фиксирует снижение продолжительности проходки: порода бурится быстрее. Оба признака отмечают зону трещиноватости.", "pages": [108]}, {"text": "Стандартный комплекс ГИС строят на признаках межзернового коллектора, а в трещинном они не проявляются. В карбонатном разрезе зонам трещиноватости соответствует особый набор показаний. Пористость по методам пористости низкая.", "pages": [108]}, {"text": "Диаметр скважины номинальный или лишь слегка увеличен. Разноглубинные зонды дают высокие показания, а радиального градиента сопротивления нет. СП и ГМ дают низкие показания.", "pages": [108]}]}, {"title": "Как работает специалист", "by_model": true, "paragraphs": [{"text": "В главе на этой странице нет пошаговой процедуры. Из текста следует лишь порядок рассуждения. Сначала при бурении смотрят аномалии поглощения жидкости и снижение продолжительности проходки по ГТИ.", "pages": [108]}, {"text": "Затем на диаграммах ГИС ищут описанный набор показаний. Он включает низкую пористость, номинальный диаметр, высокие показания зондов без радиального градиента и низкие СП и ГМ. Отдельные признаки межзернового коллектора здесь не применяют.", "pages": [108]}]}, {"title": "Нюансы", "by_model": true, "paragraphs": [{"text": "Трещинный коллектор впервые обнаружен и исследован именно в карбонатном разрезе. Набор признаков в главе описан для этого случая. Диаметр скважины может быть номинальным или чуть увеличенным.", "pages": [108]}, {"text": "Профилеграмма и кавернограмма в этом случае не показывают заметной каверны. Изменение показаний разных методов во времени в трещинном коллекторе иногда наблюдается. В целом оно для него не характерно, поэтому метод повторных замеров здесь ненадёжен.", "pages": [108]}, {"text": "Низкая пористость по ГИС не означает отсутствия коллектора: пористость описывает плотные блоки, а не трещины.", "pages": [108]}]}], "deeper": [], "glossary": [{"term": "геолого-технологические исследования (ГТИ)", "definition": "Комплекс исследований, который ведут в процессе бурения. Включает фильтрационный и детальный механический методы, отмечающие зоны трещиноватости по поглощению промывочной жидкости и снижению продолжительности проходки."}, {"term": "профилеграмма", "definition": "Диаграмма, показывающая диаметр скважины и форму её сечения; наряду с кавернограммой по ней видно, номинален диаметр скважины или увеличен."}], "format": "карточки", "tasks": [{"id": "latyshova.fracture_detection.t1", "type": "order", "step_id": "latyshova.fracture_detection", "claim_ids": ["latyshova.fracture_detection#c3", "latyshova.fracture_detection#c4", "latyshova.fracture_detection#c8", "latyshova.fracture_detection#c10"], "prompt": "Расположите шаги поиска трещинного коллектора в порядке рассуждения по тексту.", "options": [{"id": "a", "text": "На диаграммах ГИС ищут набор: низкая kп, номинальный диаметр, высокие показания зондов без радиального градиента", "misconception": null}, {"id": "b", "text": "При бурении по ГТИ отмечают аномалии поглощения жидкости и снижение продолжительности проходки", "misconception": null}, {"id": "c", "text": "Интервал относят к зоне трещиноватости, а не оценивают по признакам межзернового коллектора", "misconception": null}], "answer": ["b", "a", "c"], "tolerance": null, "unit": null, "explanation": "Сначала ГТИ при бурении указывают на зону, затем её проверяют набором признаков на диаграммах ГИС и делают вывод.", "kind": "understanding"}, {"id": "latyshova.fracture_detection.t2", "type": "single", "step_id": "latyshova.fracture_detection", "claim_ids": ["latyshova.fracture_detection#c5", "latyshova.fracture_detection#c8", "latyshova.fracture_detection#c9", "latyshova.fracture_detection#c10", "latyshova.fracture_detection#c11"], "prompt": "В карбонатном разрезе интервал имеет низкую kп по методам пористости, номинальный диаметр скважины, высокие показания разноглубинных зондов без радиального градиента, низкие СП и ГМ. При бурении здесь было поглощение промывочной жидкости. Какой вывод наиболее обоснован?", "options": [{"id": "a", "text": "Вероятна зона трещиноватости, несмотря на низкую пористость", "misconception": null}, {"id": "b", "text": "Это плотная порода без коллекторских свойств, поскольку kп низкая", "misconception": "misc.no_interzerno_no_reservoir"}, {"id": "c", "text": "Это межзерновой коллектор, так как показания зондов высокие", "misconception": null}, {"id": "d", "text": "Это глинистый пласт, так как СП и ГМ низкие", "misconception": null}], "answer": "a", "tolerance": null, "unit": null, "explanation": "Такой набор показаний вместе с поглощением жидкости соответствует зоне трещиноватости, а низкая kп описывает плотные блоки.", "kind": "data"}], "pictures": [{"id": "latyshova.fracture_detection.i1", "step_id": "latyshova.fracture_detection", "node_id": "latyshova.fracture_detection", "file": "pictures/fracture_detection_1.svg", "frame_class": "B", "origin": "code_from_model", "label": "схема", "caption": "Зону трещиноватости при бурении отмечают два метода ГТИ; стандартный комплекс ГИС её не обнаруживает.", "alt": "Схема: геолого-технологические исследования во время бурения включают фильтрационный и механический методы. Поглощение жидкости и снижение времени проходки указывают на зону трещиноватости.", "source": "построено кодом по утверждениям главы, стр. 108", "claim_ids": ["latyshova.fracture_detection#c1", "latyshova.fracture_detection#c2", "latyshova.fracture_detection#c3", "latyshova.fracture_detection#c4", "latyshova.fracture_detection#c5"], "prompt": null}]}]};
